const p0HttpTestMode = process.env.P0_HTTP_TEST_MODE === 'true';
if (p0HttpTestMode) {
  const databaseUrl = process.env.DATABASE_URL;
  if (process.env.NODE_ENV !== 'test' || !databaseUrl) {
    throw new Error('P0_HTTP_TEST_MODE_REQUIRES_NODE_TEST_AND_EXPLICIT_TEST_DATABASE');
  }
  const testDatabaseUrl = new URL(databaseUrl);
  const testDatabaseName = decodeURIComponent(testDatabaseUrl.pathname.replace(/^\//, '').split('/')[0] || '');
  if (!/(^|[-_])(test|e2e)([-_]|$)/i.test(testDatabaseName)
    || !['localhost', '127.0.0.1', '::1'].includes(testDatabaseUrl.hostname)) {
    throw new Error('P0_HTTP_TEST_MODE_REQUIRES_LOOPBACK_TEST_DATABASE');
  }
}
let cachedObjectStorageClient: { client: S3Client; signature: string } | null = null;
let cachedMediaObjectStorageClient: { client: S3Client; signature: string } | null = null;
let cachedDatabaseBackupStorageClient: { client: S3Client; signature: string } | null = null;
let cachedMediaBackupStorageClient: { client: S3Client; signature: string } | null = null;
function getObjectStorageConfig() {
  const stored = integrationConfig.objectStorage;
  const configuredViaAdmin = Boolean(stored.accessKeyIdEncrypted);
  return {
    endpoint: configuredIntegrationValue(stored.endpointEncrypted, process.env.OBJECT_STORAGE_ENDPOINT || ''),
    region: configuredIntegrationValue(stored.regionEncrypted, process.env.OBJECT_STORAGE_REGION || 'auto'),
    bucket: configuredIntegrationValue(stored.bucketEncrypted, process.env.OBJECT_STORAGE_BUCKET || ''),
    accessKeyId: configuredIntegrationValue(stored.accessKeyIdEncrypted, process.env.OBJECT_STORAGE_ACCESS_KEY_ID || ''),
    secretAccessKey: configuredIntegrationValue(stored.secretAccessKeyEncrypted, process.env.OBJECT_STORAGE_SECRET_ACCESS_KEY || ''),
    publicBaseUrl: configuredIntegrationValue(stored.publicBaseUrlEncrypted, process.env.OBJECT_STORAGE_PUBLIC_BASE_URL || '').replace(/\/+$/, ''),
    forcePathStyle: configuredViaAdmin ? stored.forcePathStyle : process.env.OBJECT_STORAGE_FORCE_PATH_STYLE === 'true'
  };
}
function getObjectStorageBucket() {
  return getObjectStorageConfig().bucket || undefined;
}
function designImageStorageKey(merchantId: string, designId: string) {
  return `merchants/${merchantId}/modagpt/designs/${designId}.webp`;
}
function getObjectStoragePublicBaseUrl() {
  return getObjectStorageConfig().publicBaseUrl || undefined;
}
function getObjectStorageClient(): S3Client | null {
  const config = getObjectStorageConfig();
  if (!config.endpoint || !config.accessKeyId || !config.secretAccessKey) return null;
  const signature = JSON.stringify(config);
  if (cachedObjectStorageClient && cachedObjectStorageClient.signature === signature) return cachedObjectStorageClient.client;
  const client = new S3Client({
    region: config.region,
    endpoint: config.endpoint,
    forcePathStyle: config.forcePathStyle,
    credentials: { accessKeyId: config.accessKeyId, secretAccessKey: config.secretAccessKey }
  });
  cachedObjectStorageClient = { client, signature };
  return client;
}
function getMediaObjectStorageConfig() {
  const r2 = resolveR2Environment();
  if (r2.active) return r2;
  return { ...getObjectStorageConfig(), privateBucket: '' };
}
function getMediaObjectStorageBucket() {
  return getMediaObjectStorageConfig().bucket || undefined;
}
function getMediaObjectStoragePrivateBucket() {
  return getMediaObjectStorageConfig().privateBucket || undefined;
}
function getMediaObjectStoragePublicBaseUrl() {
  return getMediaObjectStorageConfig().publicBaseUrl || undefined;
}
function getMediaObjectStorageClient(): S3Client | null {
  const config = getMediaObjectStorageConfig();
  if (!config.endpoint || !config.accessKeyId || !config.secretAccessKey) return null;
  const signature = JSON.stringify(config);
  if (cachedMediaObjectStorageClient && cachedMediaObjectStorageClient.signature === signature) {
    return cachedMediaObjectStorageClient.client;
  }
  const client = new S3Client({
    region: config.region,
    endpoint: config.endpoint,
    forcePathStyle: config.forcePathStyle,
    credentials: { accessKeyId: config.accessKeyId, secretAccessKey: config.secretAccessKey }
  });
  cachedMediaObjectStorageClient = { client, signature };
  return client;
}
function isMediaObjectStorageEnabled() {
  return Boolean(getMediaObjectStorageClient() && getMediaObjectStorageBucket());
}
function getMediaObjectPublicUrl(key: string) {
  const config = getMediaObjectStorageConfig();
  const bucket = config.bucket;
  if (!bucket) return '';
  return config.publicBaseUrl
    ? `${config.publicBaseUrl}/${key}`
    : `${config.endpoint.replace(/\/+$/, '')}/${bucket}/${key}`;
}
async function verifyMerchantMediaObject(
  merchantId: string,
  key: string,
  url: string,
  mediaType: 'image' | 'video'
): Promise<{ contentType: string; sizeBytes: number } | null> {
  const prefix = `merchants/${merchantId}/storefront/${mediaType === 'image' ? 'images' : 'videos'}/`;
  if (!key.startsWith(prefix) || key.includes('..') || url !== getMediaObjectPublicUrl(key)) return null;
  const storageClient = getMediaObjectStorageClient();
  const storageBucket = getMediaObjectStorageBucket();
  if (!storageClient || !storageBucket) throw new Error('MEDIA_STORAGE_UNAVAILABLE');
  let head;
  try {
    head = await storageClient.send(new HeadObjectCommand({ Bucket: storageBucket, Key: key }));
  } catch (error) {
    if ((error as { $metadata?: { httpStatusCode?: number } })?.$metadata?.httpStatusCode === 404) return null;
    throw error;
  }
  const contentType = head.ContentType?.toLowerCase() || '';
  const sizeBytes = head.ContentLength;
  const allowedTypes = mediaType === 'image'
    ? ['image/jpeg', 'image/png', 'image/webp']
    : ['video/mp4', 'video/webm'];
  const maxSize = mediaType === 'image' ? 12 * 1024 * 1024 : 100 * 1024 * 1024;
  if (!allowedTypes.includes(contentType) || !Number.isSafeInteger(sizeBytes) || !sizeBytes || sizeBytes > maxSize) return null;

  let object;
  try {
    object = await storageClient.send(new GetObjectCommand({
      Bucket: storageBucket,
      Key: key,
      Range: 'bytes=0-11'
    }));
  } catch (error) {
    if ((error as { $metadata?: { httpStatusCode?: number } })?.$metadata?.httpStatusCode === 404) return null;
    throw error;
  }
  if (!object.Body) return null;
  const signature = Buffer.from(await object.Body.transformToByteArray()).subarray(0, 12);
  const signatureMatches = contentType === 'image/jpeg'
    ? signature[0] === 0xff && signature[1] === 0xd8 && signature[2] === 0xff
    : contentType === 'image/png'
      ? signature.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))
      : contentType === 'image/webp'
        ? signature.toString('ascii', 0, 4) === 'RIFF' && signature.toString('ascii', 8, 12) === 'WEBP'
        : contentType === 'video/webm'
          ? signature.subarray(0, 4).equals(Buffer.from([0x1a, 0x45, 0xdf, 0xa3]))
          : signature.toString('ascii', 4, 8) === 'ftyp';
  if (!signatureMatches) return null;
  return { contentType, sizeBytes };
}
function getDedicatedDatabaseBackupStorageConfig() {
  const stored = integrationConfig.databaseBackupS3;
  return {
    endpoint: configuredIntegrationValue(stored.endpointEncrypted),
    region: configuredIntegrationValue(stored.regionEncrypted, 'auto'),
    bucket: configuredIntegrationValue(stored.bucketEncrypted),
    accessKeyId: configuredIntegrationValue(stored.accessKeyIdEncrypted),
    secretAccessKey: configuredIntegrationValue(stored.secretAccessKeyEncrypted),
    prefix: stored.prefix || 'database-backups',
    enabled: stored.enabled,
    forcePathStyle: stored.forcePathStyle
  };
}
function getDedicatedDatabaseBackupStorageClient(): S3Client | null {
  const config = getDedicatedDatabaseBackupStorageConfig();
  if (!config.endpoint || !config.accessKeyId || !config.secretAccessKey) return null;
  const signature = JSON.stringify(config);
  if (cachedDatabaseBackupStorageClient?.signature === signature) return cachedDatabaseBackupStorageClient.client;
  const client = new S3Client({
    region: config.region,
    endpoint: config.endpoint,
    forcePathStyle: config.forcePathStyle,
    credentials: { accessKeyId: config.accessKeyId, secretAccessKey: config.secretAccessKey }
  });
  cachedDatabaseBackupStorageClient = { client, signature };
  return client;
}
