function parseStoredJson<T>(value: string | null | undefined, fallback: T): T {
  if (!value) return fallback;
  try { return JSON.parse(value) as T; } catch { return fallback; }
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value && typeof value === 'object' && !Array.isArray(value));
}

async function reserveMerchantModaGptUsage(merchantId: string, feature: ModaGptFeature) {
  for (let attempt = 0; attempt < 6; attempt += 1) {
    const merchant = await prisma.merchant.findUnique({ where: { id: merchantId }, select: { settings: true } });
    if (!merchant) throw new Error('MODAGPT_MERCHANT_NOT_FOUND');
    const state = parseModaGptPlanState(merchant.settings);
    const reservation = reserveModaGptUsage(state, feature);
    const updated = await prisma.merchant.updateMany({
      where: { id: merchantId, settings: merchant.settings },
      data: { settings: serializeModaGptSettings(merchant.settings, reservation.nextState) }
    });
    if (updated.count === 1) return reservation.entitlements;
  }
  throw new Error('MODAGPT_USAGE_UPDATE_CONFLICT');
}

async function releaseMerchantModaGptUsage(merchantId: string, feature: ModaGptFeature, period: string) {
  for (let attempt = 0; attempt < 6; attempt += 1) {
    const merchant = await prisma.merchant.findUnique({ where: { id: merchantId }, select: { settings: true } });
    if (!merchant) throw new Error('MODAGPT_MERCHANT_NOT_FOUND');
    const state = parseModaGptPlanState(merchant.settings);
    const nextState = releaseModaGptUsage(state, feature, period);
    if (nextState === state) return;
    const updated = await prisma.merchant.updateMany({
      where: { id: merchantId, settings: merchant.settings },
      data: { settings: serializeModaGptSettings(merchant.settings, nextState) }
    });
    if (updated.count === 1) return;
  }
  throw new Error('MODAGPT_USAGE_UPDATE_CONFLICT');
}

async function updateMerchantModaGptPlan(merchantId: string, plan: 'free' | 'pro', expiresAt: string | null) {
  for (let attempt = 0; attempt < 6; attempt += 1) {
    const merchant = await prisma.merchant.findUnique({ where: { id: merchantId }, select: { settings: true } });
    if (!merchant) return null;
    const state = parseModaGptPlanState(merchant.settings);
    const nextState = { ...state, plan, expiresAt };
    const updated = await prisma.merchant.updateMany({
      where: { id: merchantId, settings: merchant.settings },
      data: { settings: serializeModaGptSettings(merchant.settings, nextState) }
    });
    if (updated.count === 1) return nextState;
  }
  throw new Error('MODAGPT_PLAN_UPDATE_CONFLICT');
}

async function searchMerchantAiInventory(
  merchantId: string,
  search: string
): Promise<AiEmployeeInventoryRecord[]> {
  const balances = await prisma.inventoryBalance.findMany({
    where: {
      merchantId,
      location: { code: SINGLE_WAREHOUSE_CODE },
      variant: {
        isActive: true,
        OR: [
          { sku: { contains: search, mode: 'insensitive' } },
          { color: { contains: search, mode: 'insensitive' } },
          { size: { contains: search, mode: 'insensitive' } },
          { product: { is: {
            merchantId,
            lifecycleStatus: { not: 'archived' },
            OR: [
              { name: { contains: search, mode: 'insensitive' } },
              { name_zh: { contains: search, mode: 'insensitive' } },
              { name_it: { contains: search, mode: 'insensitive' } },
              { styleNo: { contains: search, mode: 'insensitive' } }
            ]
          } } }
        ]
      }
    },
    orderBy: { updatedAt: 'desc' },
    take: 50,
    select: {
      onHandQuantity: true,
      reservedQuantity: true,
      inTransitQuantity: true,
      updatedAt: true,
      location: { select: { code: true, name: true } },
      variant: {
        select: {
          sku: true,
          color: true,
          size: true,
          product: { select: { id: true, styleNo: true, name: true, name_zh: true, name_it: true } }
        }
      }
    }
  });
  return balances.map(balance => ({
    productId: balance.variant.product.id,
    styleNo: balance.variant.product.styleNo,
    productName: balance.variant.product.name_zh || balance.variant.product.name_it || balance.variant.product.name,
    sku: balance.variant.sku,
    color: balance.variant.color,
    size: balance.variant.size,
    onHandQuantity: balance.onHandQuantity,
    reservedQuantity: balance.reservedQuantity,
    availableQuantity: balance.onHandQuantity - balance.reservedQuantity,
    inTransitQuantity: balance.inTransitQuantity,
    location: balance.location.name,
    updatedAt: balance.updatedAt.toISOString()
  }));
}

function getAiEmployeeSalesPeriod(now = new Date()): { periodStart: string; periodEnd: string } {
  const periodEnd = now.toISOString().slice(0, 10);
  const start = new Date(`${periodEnd}T00:00:00.000Z`);
  start.setUTCDate(start.getUTCDate() - 29);
  return { periodStart: start.toISOString().slice(0, 10), periodEnd };
}

async function getMerchantAiSalesSummary(merchantId: string) {
  const { periodStart, periodEnd } = getAiEmployeeSalesPeriod();
  const groups = await prisma.order.groupBy({
    by: ['status'],
    where: { merchantId, date: { gte: periodStart, lte: periodEnd } },
    _count: { _all: true },
    _sum: { totalAmount: true, totalQty: true }
  });
  const safeGroups: AiEmployeeSalesStatusGroup[] = groups.map(group => ({
    status: group.status,
    orderCount: group._count._all,
    totalAmount: Number(group._sum.totalAmount || 0),
    totalQuantity: group._sum.totalQty || 0
  }));
  return createAiEmployeeSalesSummary(periodStart, periodEnd, safeGroups);
}

async function getMerchantAiSkuSales(merchantId: string, sku?: string) {
  const { periodStart, periodEnd } = getAiEmployeeSalesPeriod();
  const groups = await prisma.orderItem.groupBy({
    by: ['sku'],
    where: {
      merchantId,
      ...(sku ? { sku } : {}),
      order: {
        is: {
          merchantId,
          date: { gte: periodStart, lte: periodEnd },
          status: { notIn: ['cancelled', 'returned'] }
        }
      }
    },
    _sum: { quantity: true }
  });
  return new Map(groups.map(group => [group.sku, group._sum.quantity || 0]));
}

function createShareToken(orderId: string, scope: 'order' | 'invoice' = 'order'): string {
  const payload = Buffer.from(JSON.stringify({
    orderId, scope, exp: Date.now() + 7 * 24 * 60 * 60 * 1000
  })).toString('base64url');
  const signature = crypto.createHmac('sha256', getShareSecret()).update(payload).digest('base64url');
  return `${payload}.${signature}`;
}

function readShareToken(token: string): { orderId: string; scope: 'order' | 'invoice' } | null {
  const [payload, signature] = token.split('.');
  if (!payload || !signature) return null;
  const expected = crypto.createHmac('sha256', getShareSecret()).update(payload).digest('base64url');
  if (signature.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) return null;
  try {
    const value = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
    if (!value.orderId || !['order', 'invoice'].includes(value.scope) || Number(value.exp) < Date.now()) return null;
    return { orderId: value.orderId, scope: value.scope };
  } catch {
    return null;
  }
}

function createQuoteToken(quoteId: string): string {
  const payload = Buffer.from(JSON.stringify({ quoteId, exp: Date.now() + 7 * 24 * 60 * 60 * 1000 })).toString('base64url');
  const signature = crypto.createHmac('sha256', getShareSecret()).update(payload).digest('base64url');
  return `${payload}.${signature}`;
}

function readQuoteToken(token: string): { quoteId: string } | null {
  const [payload, signature] = token.split('.');
  if (!payload || !signature) return null;
  const expected = crypto.createHmac('sha256', getShareSecret()).update(payload).digest('base64url');
  if (signature.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) return null;
  try {
    const value = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
    return value.quoteId && Number(value.exp) >= Date.now() ? { quoteId: value.quoteId } : null;
  } catch {
    return null;
  }
}

type SingleItemCheckoutClaims = { productId: string; merchantId: string; sku: string };

function createSingleItemCheckoutToken(claims: SingleItemCheckoutClaims): string {
  const secret = getSingleItemCheckoutSecret();
  if (!secret) throw new Error('SINGLE_ITEM_LINK_SIGNING_NOT_CONFIGURED');
  const payload = Buffer.from(JSON.stringify({ ...claims, exp: Date.now() + 180 * 24 * 60 * 60 * 1000 })).toString('base64url');
  const signature = crypto.createHmac('sha256', secret).update(payload).digest('base64url');
  return `${payload}.${signature}`;
}

function readSingleItemCheckoutToken(token: string): SingleItemCheckoutClaims | null {
  const secret = getSingleItemCheckoutSecret();
  if (!secret) return null;
  const [payload, signature] = token.split('.');
  if (!payload || !signature) return null;
  const expected = crypto.createHmac('sha256', secret).update(payload).digest('base64url');
  if (signature.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) return null;
  try {
    const value = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
    if (!value.productId || !value.merchantId || !value.sku || Number(value.exp) < Date.now()) return null;
    return { productId: String(value.productId), merchantId: String(value.merchantId), sku: String(value.sku) };
  } catch {
    return null;
  }
}

function makeStoreSlug(value: string): string {
  return value.normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 48);
}

function makeStoreCategorySlug(value: string): string {
  const slug = makeStoreSlug(value);
  return slug || `category-${crypto.createHash('sha256').update(value).digest('hex').slice(0, 16)}`;
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>\"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;'
  }[character] || character));
}

function applyLocalizedSeoHead(
  html: string,
  input: {
    language: SeoLanguage;
    pathname: string;
    title: string;
    description: string;
    origin?: string;
    image?: string;
    type?: string;
    schema?: Record<string, unknown>;
  }
): string {
  const origin = input.origin || `https://${PORTAL_DOMAINS.public}`;
  const canonical = canonicalPublicUrl(input.pathname, input.language, origin);
  const replaceTagContent = (pattern: RegExp, value: string) =>
    html.replace(pattern, (_match, prefix: string, suffix: string) => `${prefix}${escapeHtml(value)}${suffix}`);

  html = html.replace(/(<html\b[^>]*\blang=")[^"]*(")/i, `$1${input.language}$2`);
  html = html.replace(/(<html\b[^>]*\bdir=")[^"]*(")/i, `$1${input.language === 'ar' ? 'rtl' : 'ltr'}$2`);
  if (!/<html\b[^>]*\bdir="/i.test(html)) {
    html = html.replace(/<html\b([^>]*)>/i, `<html$1 dir="${input.language === 'ar' ? 'rtl' : 'ltr'}">`);
  }
  html = replaceTagContent(/(<title>)[\s\S]*?(<\/title>)/i, input.title);
  html = replaceTagContent(/(<meta name="description" content=")[^"]*("\s*\/?>)/i, input.description);
  html = replaceTagContent(/(<meta property="og:title" content=")[^"]*("\s*\/?>)/i, input.title);
  html = replaceTagContent(/(<meta property="og:description" content=")[^"]*("\s*\/?>)/i, input.description);
  html = replaceTagContent(/(<meta name="twitter:title" content=")[^"]*("\s*\/?>)/i, input.title);
  html = replaceTagContent(/(<meta name="twitter:description" content=")[^"]*("\s*\/?>)/i, input.description);
  html = replaceTagContent(/(<meta property="og:url" content=")[^"]*("\s*\/?>)/i, canonical);
  html = replaceTagContent(/(<meta property="og:locale" content=")[^"]*("\s*\/?>)/i, getLocalizedSeo('home', input.language).ogLocale);
  html = replaceTagContent(/(<meta property="og:type" content=")[^"]*("\s*\/?>)/i, input.type || 'website');
  if (input.image) {
    html = replaceTagContent(/(<meta property="og:image" content=")[^"]*("\s*\/?>)/i, input.image);
    html = replaceTagContent(/(<meta name="twitter:image" content=")[^"]*("\s*\/?>)/i, input.image);
  }
  html = replaceTagContent(/(<link rel="canonical" href=")[^"]*("\s*\/?>)/i, canonical);
  html = html.replace(/<link rel="alternate" hreflang="[^"]*" href="[^"]*"\s*\/?>/gi, '');
  html = html.replace(
    /(<link rel="canonical" href="[^"]*"\s*\/?>)/i,
    (canonicalTag) => `${canonicalTag}${localizedAlternates(input.pathname, origin)}`
  );
  const pageSchema = input.schema || {
    '@context': 'https://schema.org',
    '@type': 'Organization',
    name: 'RUDA Fashion B2B',
    description: input.description,
    logo: `${origin}/pwa-512x512.png`,
    url: canonical,
    inLanguage: input.language
  };
  const safeSchema = JSON.stringify(pageSchema).replace(/</g, '\\u003c');
  html = html.replace(
    /(<script type="application\/ld\+json" data-seo-schema>)[\s\S]*?(<\/script>)/i,
    (_match, prefix: string, suffix: string) => `${prefix}\n${safeSchema}\n${suffix}`
  );
  const websiteSchema = {
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    name: 'RUDA Fashion B2B',
    url: canonicalPublicUrl('/', input.language, origin),
    inLanguage: input.language.replace('_', '-'),
    potentialAction: {
      '@type': 'SearchAction',
      target: `${origin}${input.language === 'it' ? '/it' : `/${input.language}`}/catalog?search={search_term_string}`,
      'query-input': 'required name=search_term_string'
    }
  };
  html = html.replace(
    /(<script type="application\/ld\+json" data-seo-website-schema>)[\s\S]*?(<\/script>)/i,
    (_match, prefix: string, suffix: string) => `${prefix}\n${JSON.stringify(websiteSchema).replace(/</g, '\\u003c')}\n${suffix}`
  );
  if (input.language !== 'it') {
    html = html.replace(/<script type="application\/ld\+json" data-seo-faq-schema>[\s\S]*?<\/script>/i, '');
  }
  return html;
}

function serializeOrderRow(row: any) {
  return {
    ...row,
    createdAt: row.createdAt instanceof Date ? row.createdAt.toISOString() : row.createdAt,
    totalAmount: Number(row.totalAmount),
    shippingFee: Number(row.shippingFee || 0),
    discountAmount: Number(row.discountAmount || 0),
    refundAmount: row.refundAmount == null ? undefined : Number(row.refundAmount),
    timeline: parseStoredJson(row.timeline, []),
    items: (row.items || []).map((item: any) => ({ ...item, unitPrice: Number(item.unitPrice) })),
    shippingAddress: {
      street: row.shippingStreet,
      city: row.shippingCity,
      country: row.shippingCountry,
      zip: row.shippingZip
    }
  };
}

function serializeInvoiceRow(row: any) {
  return {
    ...row,
    taxRate: Number(row.taxRate),
    subtotal: Number(row.subtotal),
    discountAmount: Number(row.discountAmount || 0),
    taxAmount: Number(row.taxAmount),
    totalAmount: Number(row.totalAmount),
    buyer: parseStoredJson(row.buyerSnapshot, {}),
    seller: parseStoredJson(row.sellerSnapshot, {}),
    items: parseStoredJson(row.itemsSnapshot, [])
  };
}

async function ensureOrderInvoice(orderId: string) {
  const existing = await prisma.orderInvoice.findUnique({ where: { orderId } });
  if (existing) return existing;
  const order = await prisma.order.findUnique({
    where: { id: orderId },
    include: { items: true, customer: true, merchant: true }
  });
  if (!order) throw new Error('ORDER_NOT_FOUND');
  const subtotal = order.items.reduce((sum, item) => sum + Number(item.unitPrice) * item.quantity, 0) + Number(order.shippingFee || 0);
  const discountAmount = Number(order.discountAmount || 0);
  const taxRate = 0;
  const dueDate = order.paymentMethod === 'net_30'
    ? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)
    : new Date();
  try {
    return await prisma.orderInvoice.create({
      data: {
        id: crypto.randomUUID(),
        invoiceNo: `RUDA-${new Date().getFullYear()}-${Date.now().toString(36).toUpperCase()}`,
        orderId: order.id,
        customerId: order.customerId,
        merchantId: order.merchantId || order.items[0]?.merchantId || null,
        status: order.paymentStatus === 'paid' ? 'paid' : 'issued',
        dueDate,
        paidAt: order.paymentStatus === 'paid' ? new Date() : null,
        currency: 'EUR', taxRate, subtotal, discountAmount, taxAmount: 0, totalAmount: Number(order.totalAmount),
        paymentMethod: order.paymentMethod,
        buyerSnapshot: JSON.stringify(order.customer ? {
          companyName: order.customer.companyName, vatNumber: order.customer.vatNumber,
          address: order.customer.address, city: order.customer.city, country: order.customer.country,
          email: order.customer.email
        } : { companyName: order.companyName }),
        sellerSnapshot: JSON.stringify(order.merchant ? {
          name: order.merchant.name, legalName: order.merchant.companyLegalName,
          address: order.merchant.showroomAddress, country: order.merchant.country,
          email: order.merchant.contactEmail, vatNumber: ''
        } : { name: 'RUDA Fashion B2B', legalName: 'RUDA Fashion B2B' }),
        itemsSnapshot: JSON.stringify(order.items.map(item => ({
          styleNo: item.styleNo, name: item.productName, sku: item.sku,
          quantity: item.quantity, unitPrice: Number(item.unitPrice),
          total: Number(item.unitPrice) * item.quantity
        }))),
        notes: [
          'B2B intra-community supply: VAT reverse charge subject to buyer validation.',
          order.promotionCode ? `Promotion code: ${order.promotionCode}.` : '',
          discountAmount > 0 ? `Promotion discount: -EUR ${discountAmount.toFixed(2)}.` : ''
        ].filter(Boolean).join(' ')
      }
    });
  } catch (error: any) {
    if (error?.code === 'P2002') return prisma.orderInvoice.findUniqueOrThrow({ where: { orderId } });
    throw error;
  }
}

function serializeProductRow(row: any): Product {
  const safeRow = { ...row };
  delete safeRow.creationRequestKey;
  const legacyImages = parseStoredJson<string[]>(row.images, []);
  const storedMedia = parseStoredJson<any[]>(row.media, []);
  const media = storedMedia.length
    ? storedMedia
    : legacyImages.map((url, index) => ({ id: `legacy-image-${index}`, type: 'image', url }));
  const legacySkus = parseStoredJson<any[]>(row.skus, []);
  const skus = Array.isArray(row.variants) && row.variants.length
    ? [
      ...row.variants.map((variant: any) => {
      const attributes = parseStoredJson<Record<string, unknown>>(variant.attributes, {});
      const legacySku = legacySkus.find(sku => sku.sku === variant.sku) || {};
      const balances = Array.isArray(variant.inventoryBalances) ? variant.inventoryBalances : [];
      const centralBalances = balances.filter((balance: any) => balance.location?.code === 'central');
      return {
        ...legacySku,
        ...attributes,
        sku: variant.sku,
        color: variant.color || legacySku.color || '',
        colorCode: String(attributes.colorCode || legacySku.colorCode || ''),
        size: variant.size || legacySku.size || '',
        barcode: variant.barcode || legacySku.barcode || undefined,
        stockCentral: centralBalances.reduce((total: number, balance: any) => total + balance.onHandQuantity, 0),
        stockMestre: 0,
        stockMilano: 0,
        reserved: centralBalances.reduce((total: number, balance: any) => total + balance.reservedQuantity, 0),
        isActive: variant.isActive,
        cost: undefined
      };
      }),
      ...legacySkus.filter(sku => !row.variants.some((variant: any) => variant.sku === sku.sku))
    ]
    : legacySkus.map(sku => ({
      ...sku,
      stockMestre: 0,
      stockMilano: 0,
      reserved: Number(sku.reserved || 0)
    }));
  return {
    ...safeRow,
    images: media.filter(item => item.type === 'image').map(item => item.url),
    media,
    skus,
    wholesalePrice: Number(row.wholesalePrice),
    wholesalePrice100: row.wholesalePrice100 == null ? null : Number(row.wholesalePrice100),
    bulkPriceMinimumQuantity: Number(row.bulkPriceMinimumQuantity ?? 100),
    rrpPrice: Number(row.rrpPrice),
    costPrice: row.costPrice == null ? undefined : Number(row.costPrice),
    storeCategorySlug: row.storeCategorySlug ?? null
  } as Product;
}

function serializePublicProductRow(row: any): Product {
  return sanitizePublicProduct(serializeProductRow(row));
}

function serializeMerchantRow(row: any): Merchant {
  return {
    ...row,
    storefrontTemplate: getMerchantStorefrontTemplate(row.settings),
    platformFeeRate: Number(row.platformFeeRate ?? 0.08),
    specialties: parseStoredJson(row.specialties, []),
    showroomPanoramicImages: parseStoredJson(row.showroomPanoramicImages, []),
    storeCategories: Array.isArray(row.storeCategories)
      ? row.storeCategories
      : undefined
  } as Merchant;
}

function serializeCustomerRow(row: any) {
  return {
    ...row,
    creditLimit: Number(row.creditLimit || 0),
    usedCredit: Number(row.usedCredit || 0),
    discountRate: Number(row.discountRate || 1),
    totalSpent: Number(row.totalSpent || 0),
    documents: parseStoredJson(row.documents, []),
    paymentSlips: parseStoredJson(row.paymentSlips, [])
  };
}

function sendInternalError(res: express.Response, error: unknown, context: string) {
  const requestId = String(res.locals.requestId || createRequestId());
  console.error(`[${context}] requestId=${requestId}`, error);
  const safeError = error instanceof Error ? error : new Error('Unexpected error');
  return res.status(getHttpStatusForError(error)).json(createErrorEnvelope(safeError, requestId));
}

function sendApiError(
  res: express.Response,
  error: BusinessError,
  additionalFields: Record<string, unknown> = {}
) {
  const requestId = String(res.locals.requestId || createRequestId());
  return res.status(error.statusCode).json({
    ...createErrorEnvelope(error, requestId),
    ...additionalFields
  });
}

function sendAccessDenied(
  res: express.Response,
  code: string,
  details?: Record<string, unknown>,
  message = code
) {
  return sendApiError(res, new BusinessError(code, message, {
    statusCode: 403,
    details
  }));
}

function sendAuthenticationError(
  res: express.Response,
  code: string,
  details?: Record<string, unknown>
) {
  return sendApiError(res, new BusinessError(code, code, {
    statusCode: 401,
    details
  }));
}

function sendRateLimitError(
  res: express.Response,
  code: string,
  retryAfter?: number,
  retryable = retryAfter !== undefined
) {
  if (retryAfter !== undefined) res.setHeader('Retry-After', String(retryAfter));
  return sendApiError(res, new BusinessError(code, code, {
    statusCode: 429,
    retryable,
    ...(retryAfter === undefined ? {} : { details: { retryAfter } })
  }), retryAfter === undefined ? {} : { retryAfter });
}

function rateLimit(options: Parameters<typeof createExpressRateLimit>[0]) {
  return createExpressRateLimit({
    ...options,
    handler: options.handler ?? ((_req, res, _next, limitOptions) => {
      sendRateLimitError(res, 'API_RATE_LIMITED', Math.ceil(limitOptions.windowMs / 1000));
    })
  });
}

function isPrismaSchemaNotReady(error: unknown): boolean {
  return typeof error === 'object'
    && error !== null
    && 'code' in error
    && (error.code === 'P2021' || error.code === 'P2022');
}

function getPagination(req: express.Request, defaultPageSize = 100) {
  const page = Math.max(1, Number.parseInt(String(req.query.page || '1'), 10) || 1);
  const pageSize = Math.min(500, Math.max(1, Number.parseInt(String(req.query.pageSize || defaultPageSize), 10) || defaultPageSize));
  return { page, pageSize, skip: (page - 1) * pageSize, take: pageSize };
}

async function hydratePersistentDb() {
  if (!process.env.DATABASE_URL) {
    if (isProduction) {
      throw new Error('DATABASE_URL is required in production; refusing to start with demo data');
    }
    console.warn('[database] DATABASE_URL is not configured; using demo data only');
    return;
  }

  try {
    const [merchants, customers, products, orders, vaultRequests, transfers, payouts, showrooms, appointments] = await Promise.all([
      prisma.$queryRawUnsafe<Record<string, unknown>[]>('SELECT * FROM "Merchant"'),
      prisma.customer.findMany(),
      prisma.product.findMany(),
      prisma.order.findMany({ include: { items: true } }),
      prisma.vaultAccessRequest.findMany(),
      prisma.stockTransfer.findMany(),
      prisma.merchantPayout.findMany(),
      prisma.showroom.findMany(),
      prisma.appointment.findMany()
    ]);

    db.merchants = merchants.map(row => serializeMerchantRow(row));
    db.customers = customers.map(row => ({
      ...row, contactName: row.contactPerson, website: row.websiteOrSocial,
      documents: parseStoredJson(row.documents, []), paymentSlips: parseStoredJson(row.paymentSlips, [])
    })) as unknown as WholesaleCustomer[];
    db.products = products.map(row => serializeProductRow(row));
    db.orders = orders.map(row => ({
      ...row, createdAt: row.createdAt.toISOString(), totalAmount: Number(row.totalAmount),
      shippingFee: Number(row.shippingFee || 0),
      discountAmount: Number(row.discountAmount || 0),
      refundAmount: row.refundAmount == null ? undefined : Number(row.refundAmount),
      items: row.items.map(item => ({ ...item, unitPrice: Number(item.unitPrice) })),
      timeline: parseStoredJson(row.timeline, []),
      shippingAddress: { street: row.shippingStreet, city: row.shippingCity, country: row.shippingCountry, zip: row.shippingZip }
    })) as Order[];
    db.vaultRequests = vaultRequests as VaultAccessRequest[];
    db.transfers = transfers as StockTransferRecord[];
    db.payouts = payouts.map(row => ({
      ...row, grossSales: Number(row.grossSales), platformFeeRate: Number(row.platformFeeRate),
      platformFeeAmount: Number(row.platformFeeAmount), paymentProcessingFee: Number(row.paymentProcessingFee),
      refunds: Number(row.refunds), netPayout: Number(row.netPayout), orderIds: parseStoredJson(row.orderIds, []),
      settledAt: row.settledAt?.toISOString() || null
    })) as MerchantPayoutRecord[];
    db.showrooms = showrooms.map(row => ({
      ...row, features: parseStoredJson(row.features, []), features_it: parseStoredJson(row.features_it, []),
      features_zh: parseStoredJson(row.features_zh, [])
    }));
    db.appointments = appointments.map(row => ({
      ...row,
      interests: parseStoredJson(row.interests, []),
      status: row.status as Appointment['status'],
      notes: row.notes || undefined
    })) as Appointment[];
    console.log('[database] persistent data loaded from PostgreSQL');
  } catch (error) {
    console.error('[database] unable to load PostgreSQL data:', error instanceof Error ? error.message : 'unknown error');
    if (isProduction) {
      throw error;
    }
  }
}

function logAudit(userName: string, role: 'admin' | 'merchant' | 'system', action: string, entity: string, entityId: string, oldValue: string, newValue: string) {
  const newLog: AuditLogRecord = {
    id: `log-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
    userId: `usr-${role}`,
    userName,
    role,
    action,
    entity,
    entityId,
    oldValue,
    newValue,
    timestamp: new Date().toISOString().replace('T', ' ').substring(0, 19),
    ip: '127.0.0.1 (API Gateway)'
  };
  db.auditLogs.unshift(newLog);
  const requestContext = getAuditRequestContext();
  const event = createAuditEvent({
    eventName: action,
    actorId: requestContext?.actorId || newLog.userId,
    actorName: userName,
    actorRole: requestContext?.actorRole || role,
    merchantId: requestContext?.merchantId,
    targetType: entity,
    targetId: entityId,
    beforeState: oldValue || null,
    afterState: newValue || null,
    requestId: requestContext?.requestId,
    details: { legacyAction: action }
  });
  const auditRecord = buildPersistedAuditRecord(event, {
    id: newLog.id,
    ip: requestContext?.ip,
    userAgent: requestContext?.userAgent
  });
  void prisma.auditLog.create({ data: auditRecord }).catch(error => {
    console.error(`[audit-log] requestId=${event.requestId} persist failed:`, error);
  });
}

async function logAuditAndWait(
  userName: string,
  role: 'admin' | 'merchant' | 'system',
  action: string,
  entity: string,
  entityId: string,
  oldValue: string,
  newValue: string,
  tx?: Prisma.TransactionClient
): Promise<void> {
  const newLog: AuditLogRecord = {
    id: `log-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
    userId: `usr-${role}`,
    userName,
    role,
    action,
    entity,
    entityId,
    oldValue,
    newValue,
    timestamp: new Date().toISOString().replace('T', ' ').substring(0, 19),
    ip: '127.0.0.1 (API Gateway)'
  };
  const requestContext = getAuditRequestContext();
  const event = createAuditEvent({
    eventName: action,
    actorId: requestContext?.actorId || newLog.userId,
    actorName: userName,
    actorRole: requestContext?.actorRole || role,
    merchantId: requestContext?.merchantId,
    targetType: entity,
    targetId: entityId,
    beforeState: oldValue || null,
    afterState: newValue || null,
    requestId: requestContext?.requestId,
    details: { legacyAction: action }
  });
  const auditClient = tx ?? prisma;
  await auditClient.auditLog.create({
    data: buildPersistedAuditRecord(event, {
      id: newLog.id,
      ip: requestContext?.ip,
      userAgent: requestContext?.userAgent
    })
  });
  if (!tx) db.auditLogs.unshift(newLog);
}

function enqueueNotification(eventType: string, recipient: string, payload: Record<string, unknown>, channels: string[] = ['in_app', 'email']) {
  if (!recipient) return;
  for (const channel of channels) {
    const idempotencyKey = `${eventType}:${channel}:${recipient}:${String(payload.referenceId || crypto.randomUUID())}`;
    void prisma.notificationEvent.create({
      data: {
        id: crypto.randomUUID(),
        eventType,
        channel,
        recipient,
        payload: JSON.stringify(payload),
        status: channel === 'in_app' ? 'sent' : 'pending',
        idempotencyKey
      }
    }).catch(error => {
      if (error?.code !== 'P2002') console.error('[notification-queue] persist failed:', error);
    });
  }
}

