const footerConfigPath = path.join(process.cwd(), 'logs', 'footer-config.json');
const homepageVideoConfigPath = path.join(process.cwd(), 'logs', 'homepage-video-config.json');
type HomepageVideoConfig = { videoUrl: string };
const homepageVideoConfig: HomepageVideoConfig = { videoUrl: '/videos/ruda-home.mp4' };

function normalizeHomepageVideoUrl(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const videoUrl = value.trim();
  if (!videoUrl || videoUrl.length > 2000) return null;
  if (videoUrl.startsWith('/') && !videoUrl.startsWith('//') && !videoUrl.includes('\\')) return videoUrl;
  try {
    const parsed = new URL(videoUrl);
    return parsed.protocol === 'https:' || parsed.protocol === 'http:' ? videoUrl : null;
  } catch {
    return null;
  }
}

async function loadHomepageVideoConfig() {
  try {
    const saved = JSON.parse(await readFile(homepageVideoConfigPath, 'utf8')) as Partial<HomepageVideoConfig>;
    const videoUrl = normalizeHomepageVideoUrl(saved.videoUrl);
    if (videoUrl) homepageVideoConfig.videoUrl = videoUrl;
  } catch {
    // First launch uses the bundled RUDA homepage video.
  }
}

async function saveHomepageVideoConfig(videoUrl: string) {
  const nextConfig = { videoUrl };
  await writeFile(homepageVideoConfigPath, `${JSON.stringify(nextConfig, null, 2)}\n`, 'utf8');
  homepageVideoConfig.videoUrl = videoUrl;
}

