async function loadIntegrationConfig() {
  try {
    const saved = JSON.parse(await readFile(integrationConfigPath, 'utf8')) as Partial<IntegrationConfig>;
    for (const key of ['google', 'wechat', 'facebook', 'sharing', 'objectStorage', 'databaseGoogleDrive', 'databaseGoogleCloud', 'databaseBackupS3', 'mediaBackupS3'] as const) {
      if (saved[key]) Object.assign(integrationConfig[key], saved[key]);
    }
    if (
      typeof integrationConfig.databaseGoogleCloud.enabled !== 'boolean' ||
      typeof integrationConfig.databaseGoogleCloud.projectIdEncrypted !== 'string' ||
      typeof integrationConfig.databaseGoogleCloud.serviceAccountJsonEncrypted !== 'string'
    ) {
      integrationConfig.databaseGoogleCloud = {
        projectIdEncrypted: '',
        serviceAccountJsonEncrypted: '',
        recoveryServiceAccountJsonEncrypted: '',
        enabled: false
      };
    }
    if (typeof integrationConfig.databaseGoogleCloud.recoveryServiceAccountJsonEncrypted !== 'string') {
      integrationConfig.databaseGoogleCloud.recoveryServiceAccountJsonEncrypted = '';
    }
    if (
      typeof integrationConfig.databaseBackupS3.enabled !== 'boolean' ||
      typeof integrationConfig.databaseBackupS3.forcePathStyle !== 'boolean' ||
      typeof integrationConfig.databaseBackupS3.prefix !== 'string'
    ) {
      integrationConfig.databaseBackupS3 = {
        ...integrationConfig.databaseBackupS3,
        enabled: false,
        forcePathStyle: false,
        prefix: 'database-backups'
      };
    }
    if (
      typeof integrationConfig.mediaBackupS3.enabled !== 'boolean' ||
      typeof integrationConfig.mediaBackupS3.forcePathStyle !== 'boolean' ||
      typeof integrationConfig.mediaBackupS3.prefix !== 'string'
    ) {
      integrationConfig.mediaBackupS3 = {
        ...integrationConfig.mediaBackupS3,
        enabled: false,
        forcePathStyle: false,
        prefix: 'media-backups'
      };
    }
    if (
      saved.databaseBackupSchedule &&
      typeof saved.databaseBackupSchedule === 'object' &&
      validateDatabaseBackupSchedule(saved.databaseBackupSchedule)
    ) {
      integrationConfig.databaseBackupSchedule = saved.databaseBackupSchedule;
    }
    if (saved.aiEmployeeProviders && typeof saved.aiEmployeeProviders === 'object') {
      const storedProviders = saved.aiEmployeeProviders as unknown as Record<string, unknown>;
      if (typeof storedProviders.deepseekApiKeyEncrypted === 'string') integrationConfig.aiEmployeeProviders.deepseekApiKeyEncrypted = storedProviders.deepseekApiKeyEncrypted;
      if (typeof storedProviders.falApiKeyEncrypted === 'string') integrationConfig.aiEmployeeProviders.falApiKeyEncrypted = storedProviders.falApiKeyEncrypted;
      if (typeof storedProviders.openaiApiKeyEncrypted === 'string') integrationConfig.aiEmployeeProviders.openaiApiKeyEncrypted = storedProviders.openaiApiKeyEncrypted;
      if (typeof storedProviders.geminiApiKeyEncrypted === 'string') integrationConfig.aiEmployeeProviders.geminiApiKeyEncrypted = storedProviders.geminiApiKeyEncrypted;
      for (const key of ['reasoning', 'advancedReasoning', 'vision', 'image'] as const) {
        const savedProvider = storedProviders[key];
        if (!savedProvider || typeof savedProvider !== 'object' || Array.isArray(savedProvider)) continue;
        const provider = savedProvider as Record<string, unknown>;
        const target = integrationConfig.aiEmployeeProviders[key];
        if (
          (key === 'image' && (provider.provider === 'fal' || provider.provider === 'automatic1111'))
          || (key === 'reasoning' && (provider.provider === 'ollama' || provider.provider === 'deepseek'))
          || (key === 'advancedReasoning' && provider.provider === 'openai')
          || (key === 'vision' && (provider.provider === 'ollama' || provider.provider === 'gemini'))
        ) {
          target.provider = provider.provider as typeof target.provider;
        }
        if (typeof provider.model === 'string') target.model = provider.model;
        if (typeof provider.fallbackToLocal === 'boolean') target.fallbackToLocal = provider.fallbackToLocal;
      }
    }
    integrationConfig.facebook.publishingPages = Array.isArray(saved.facebook?.publishingPages)
      ? saved.facebook.publishingPages.filter(page =>
        page && typeof page.id === 'string' && typeof page.name === 'string' &&
        typeof page.accessTokenEncrypted === 'string' && page.accessTokenEncrypted.length > 0 &&
      (typeof page.instagramUserTokenEncrypted === 'string' || page.instagramUserTokenEncrypted === null) &&
      (typeof page.instagramUserTokenExpiresAt === 'string' || page.instagramUserTokenExpiresAt === null) &&
      Array.isArray(page.tasks) && page.tasks.every(task => typeof task === 'string') &&
      typeof page.connectedAt === 'string' &&
      (!page.instagramAccount || (typeof page.instagramAccount.id === 'string' && typeof page.instagramAccount.username === 'string'))
    ).slice(0, 50)
    : [];
  } catch {
    // First launch uses environment values until an administrator saves credentials.
  }
  try {
    const defaults = getDefaultAiEmployeeProviderSettings();
    const stored = integrationConfig.aiEmployeeProviders;
    const deepseekApiKey = stored.deepseekApiKeyEncrypted ? decryptSecret(stored.deepseekApiKeyEncrypted) : '';
    const falApiKey = stored.falApiKeyEncrypted ? decryptSecret(stored.falApiKeyEncrypted) : '';
    const openaiApiKey = stored.openaiApiKeyEncrypted ? decryptSecret(stored.openaiApiKeyEncrypted) : '';
    const geminiApiKey = stored.geminiApiKeyEncrypted ? decryptSecret(stored.geminiApiKeyEncrypted) : '';
    const settings: AiEmployeeProviderSettings = {
      reasoning: { ...defaults.reasoning, ...stored.reasoning, apiKey: deepseekApiKey },
      advancedReasoning: { ...defaults.advancedReasoning, ...stored.advancedReasoning, apiKey: openaiApiKey },
      vision: { ...defaults.vision, ...stored.vision, apiKey: geminiApiKey },
      image: { ...defaults.image, ...stored.image, apiKey: falApiKey }
    };
    if (!validateAiEmployeeProviderSettings(settings)) throw new Error('AI_EMPLOYEE_PROVIDER_CONFIG_INVALID');
    setAiEmployeeProviderSettings(settings);
  } catch (error) {
    console.error('[ai-employee-provider-config-load]', error instanceof Error ? error.message : 'invalid config');
  }
}

let integrationConfigWriteQueue = Promise.resolve();
async function saveIntegrationConfig() {
  const pendingWrite = integrationConfigWriteQueue.then(async () => {
    await mkdir(path.dirname(integrationConfigPath), { recursive: true });
    const temporaryPath = `${integrationConfigPath}.${crypto.randomUUID()}.tmp`;
    try {
      await writeFile(temporaryPath, `${JSON.stringify(integrationConfig, null, 2)}\n`, { encoding: 'utf8', mode: 0o600 });
      await rename(temporaryPath, integrationConfigPath);
    } catch (error) {
      await unlink(temporaryPath).catch(() => undefined);
      throw error;
    }
  });
  integrationConfigWriteQueue = pendingWrite.then(() => undefined, () => undefined);
  await pendingWrite;
}

