    if (typeof saved.resendCooldownSeconds === 'number') registrationConfig.resendCooldownSeconds = Math.min(600, Math.max(15, Math.round(saved.resendCooldownSeconds)));
    if (typeof saved.maxAttempts === 'number') registrationConfig.maxAttempts = Math.min(10, Math.max(3, Math.round(saved.maxAttempts)));
