function notificationText(payload: Record<string, unknown>) {
  return Object.entries(payload).map(([key, value]) => `${key}: ${String(value)}`).join('\n');
}

async function sendExternalNotification(
  channel: string,
  recipient: string,
  payload: Record<string, unknown>,
  idempotencyKey?: string,
  signal?: AbortSignal
): Promise<{ providerMessageId: string } | undefined> {
  if (signal?.aborted) throw new Error('NOTIFICATION_SEND_CANCELLED');
  const text = notificationText(payload);
  if (channel === 'email') {
    const config = notificationConfig.email;
    if (!config.enabled || !config.apiKeyEncrypted || !config.from) throw new Error('EMAIL_CHANNEL_NOT_CONFIGURED');
    const response = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: { Authorization: `Bearer ${decryptSecret(config.apiKeyEncrypted)}`, 'Content-Type': 'application/json', ...(idempotencyKey ? { 'Idempotency-Key': idempotencyKey } : {}) },
      body: JSON.stringify({ from: config.from, to: [recipient], subject: String(payload.subject || payload.eventType || 'RUDA B2B notification'), text }),
      signal
    });
    if (!response.ok) throw new Error(`EMAIL_PROVIDER_${response.status}`);
    let result: unknown;
    try {
      result = await response.json();
    } catch {
      throw new Error('EMAIL_PROVIDER_RESPONSE_INVALID');
    }
    if (!result || typeof result !== 'object' || !('id' in result) || typeof result.id !== 'string' || !result.id.trim()) {
      throw new Error('EMAIL_PROVIDER_MESSAGE_ID_MISSING');
    }
    return { providerMessageId: result.id };
  }
  if (channel === 'sms' || channel === 'whatsapp') {
    const config = notificationConfig[channel];
    if (!config.enabled || !config.accountSid || !config.authTokenEncrypted || !config.from) throw new Error(`${channel.toUpperCase()}_CHANNEL_NOT_CONFIGURED`);
    const to = channel === 'whatsapp' && !recipient.startsWith('whatsapp:') ? `whatsapp:${recipient}` : recipient;
    const body = new URLSearchParams({ To: to, From: channel === 'whatsapp' && !config.from.startsWith('whatsapp:') ? `whatsapp:${config.from}` : config.from, Body: text });
    const response = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${encodeURIComponent(config.accountSid)}/Messages.json`, {
      method: 'POST',
      headers: { Authorization: `Basic ${Buffer.from(`${config.accountSid}:${decryptSecret(config.authTokenEncrypted)}`).toString('base64')}`, 'Content-Type': 'application/x-www-form-urlencoded' },
      body,
      signal
    });
    if (!response.ok) throw new Error(`${channel.toUpperCase()}_PROVIDER_${response.status}`);
    return;
  }
  throw new Error('NOTIFICATION_CHANNEL_UNSUPPORTED');
}

async function processNotificationQueue() {
  const events = await prisma.notificationEvent.findMany({
    where: { status: 'pending', channel: { in: ['email', 'sms', 'whatsapp'] }, OR: [{ nextAttemptAt: null }, { nextAttemptAt: { lte: new Date() } }] },
    orderBy: { createdAt: 'asc' }, take: 20
  });
  for (const event of events) {
    const claimed = await prisma.notificationEvent.updateMany({ where: { id: event.id, status: 'pending' }, data: { status: 'sending', attempts: { increment: 1 } } });
    if (!claimed.count) continue;
    try {
      await sendExternalNotification(event.channel, event.recipient, { ...parseStoredJson(event.payload, {}), eventType: event.eventType });
      await prisma.notificationEvent.update({ where: { id: event.id }, data: { status: 'sent', lastError: null, nextAttemptAt: null } });
    } catch (error) {
      const attempts = event.attempts + 1;
      await prisma.notificationEvent.update({ where: { id: event.id }, data: { status: attempts >= 5 ? 'failed' : 'pending', lastError: error instanceof Error ? error.message : 'NOTIFICATION_SEND_FAILED', nextAttemptAt: new Date(Date.now() + Math.min(24 * 60 * 60 * 1000, 2 ** Math.min(attempts, 10) * 60 * 1000)) } });
    }
  }
}

