const JWT_BUYER_SECRET = process.env.JWT_BUYER_SECRET || (isProduction ? '' : 'dev-only-buyer-secret-change-me');
const JWT_MERCHANT_SECRET = process.env.JWT_MERCHANT_SECRET || (isProduction ? '' : 'dev-only-merchant-secret-change-me');
const JWT_ADMIN_SECRET = process.env.JWT_ADMIN_SECRET || (isProduction ? '' : 'dev-only-admin-secret-change-me');
const JWT_COMPANY_SECRET = process.env.JWT_COMPANY_SECRET || JWT_BUYER_SECRET;
const JWT_FASHION_ACCOUNT_SECRET = crypto.createHmac('sha256', JWT_BUYER_SECRET)
  .update('ruda-fashion-account-v1')
  .digest('hex');

function setAuthCookie(res: express.Response, name: string, token: string, maxAge: number, shareWithRudaSubdomains = false) {
  if (shareWithRudaSubdomains && isProduction) res.clearCookie(name, { path: '/' });
  res.cookie(name, token, {
    httpOnly: true,
    secure: isProduction,
    sameSite: 'lax',
    path: '/',
    maxAge: maxAge * 1000,
    ...(shareWithRudaSubdomains && isProduction ? { domain: '.ruda.fashion' } : {})
  });

}

function clearAuthCookiesExcept(res: express.Response, keep: string) {
  for (const name of [
    'ruda_buyer_jwt',
    'ruda_customer_jwt',
    'ruda_consumer_jwt',
    'ruda_merchant_jwt',
    'ruda_employee_jwt',
    'ruda_company_jwt',
    'ruda_admin_jwt'
  ]) {
    if (name !== keep) {
      res.clearCookie(name, { path: '/' });
      if (isProduction && (name === 'ruda_merchant_jwt' || name === 'ruda_employee_jwt')) {
        res.clearCookie(name, { path: '/', domain: '.ruda.fashion' });
      }
    }
  }
}

function base32Decode(value: string): Buffer {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  const normalized = value.toUpperCase().replace(/=+$/, '').replace(/\s+/g, '');
  let bits = '';
  for (const char of normalized) {
    const index = alphabet.indexOf(char);
    if (index < 0) throw new Error('INVALID_TOTP_SECRET');
    bits += index.toString(2).padStart(5, '0');
  }
  const bytes: number[] = [];
  for (let offset = 0; offset + 8 <= bits.length; offset += 8) {
    bytes.push(Number.parseInt(bits.slice(offset, offset + 8), 2));
  }
  return Buffer.from(bytes);
}

function verifyTotp(secret: string, code: string, now = Date.now()): boolean {
  if (!/^\d{6}$/.test(code)) return false;
  const key = base32Decode(secret);
  const counter = Math.floor(now / 1000 / 30);
  for (const drift of [-1, 0, 1]) {
    const message = Buffer.alloc(8);
    message.writeBigInt64BE(BigInt(counter + drift));
    const digest = crypto.createHmac('sha1', key).update(message).digest();
    const offset = digest[digest.length - 1] & 0x0f;
    const binary = ((digest[offset] & 0x7f) << 24) | (digest[offset + 1] << 16) | (digest[offset + 2] << 8) | digest[offset + 3];
    if (String(binary % 1_000_000).padStart(6, '0') === code) return true;
  }

  return false;
}

function encryptionKey(): Buffer {
  return crypto.createHash('sha256').update(process.env.ADMIN_TOTP_ENCRYPTION_KEY || JWT_ADMIN_SECRET).digest();
}

function encryptSecret(secret: string): string {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', encryptionKey(), iv);
  const encrypted = Buffer.concat([cipher.update(secret, 'utf8'), cipher.final()]);
  return `${iv.toString('base64url')}.${cipher.getAuthTag().toString('base64url')}.${encrypted.toString('base64url')}`;
}

function decryptSecret(value: string): string {
  const [ivValue, tagValue, encryptedValue] = value.split('.');
  const decipher = crypto.createDecipheriv('aes-256-gcm', encryptionKey(), Buffer.from(ivValue, 'base64url'));
  decipher.setAuthTag(Buffer.from(tagValue, 'base64url'));
  return Buffer.concat([decipher.update(Buffer.from(encryptedValue, 'base64url')), decipher.final()]).toString('utf8');
}

function createRuntimeAiEmployeeProviderSettings(
  stored: StoredAiEmployeeProviders
): AiEmployeeProviderSettings {
  const defaults = getDefaultAiEmployeeProviderSettings();
  if (
    typeof stored.deepseekApiKeyEncrypted !== 'string'
    || typeof stored.falApiKeyEncrypted !== 'string'
    || typeof stored.openaiApiKeyEncrypted !== 'string'
    || typeof stored.geminiApiKeyEncrypted !== 'string'
  ) throw new Error('AI_EMPLOYEE_PROVIDER_CONFIG_INVALID');
  const deepseekApiKey = stored.deepseekApiKeyEncrypted ? decryptSecret(stored.deepseekApiKeyEncrypted) : '';
  const falApiKey = stored.falApiKeyEncrypted ? decryptSecret(stored.falApiKeyEncrypted) : '';
  const openaiApiKey = stored.openaiApiKeyEncrypted ? decryptSecret(stored.openaiApiKeyEncrypted) : '';
  const geminiApiKey = stored.geminiApiKeyEncrypted ? decryptSecret(stored.geminiApiKeyEncrypted) : '';
  const settings: AiEmployeeProviderSettings = {
    reasoning: { ...defaults.reasoning, ...stored.reasoning, apiKey: deepseekApiKey },
    advancedReasoning: { ...defaults.advancedReasoning, ...stored.advancedReasoning, apiKey: openaiApiKey },
    vision: { ...defaults.vision, ...stored.vision, apiKey: geminiApiKey },
    image: { ...defaults.image, ...stored.image, apiKey: falApiKey }
  };
  if (!validateAiEmployeeProviderSettings(settings)) throw new Error('AI_EMPLOYEE_PROVIDER_CONFIG_INVALID');
  return settings;
}

function isValidConfiguredModel(value: string, provider: string): boolean {
  if (!/^[A-Za-z0-9][A-Za-z0-9._:/-]{0,119}$/.test(value) || value.includes('//')) return false;
  return provider !== 'fal' || isValidFalModelId(value);
}

function parseStoredAiTextProvider(
  input: unknown,
  allowedProviders: readonly AiEmployeeProviderSettings['reasoning']['provider'][]
): StoredAiEmployeeProviders['reasoning'] | null {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return null;
  const value = input as Record<string, unknown>;
  if (Object.keys(value).some(key => !['provider', 'model', 'fallbackToLocal'].includes(key))) return null;
  if (
    typeof value.provider !== 'string'
    || !allowedProviders.includes(value.provider as AiEmployeeProviderSettings['reasoning']['provider'])
    || typeof value.model !== 'string'
    || (value.provider === 'deepseek'
      ? !['deepseek-flash', 'deepseek-v4-pro'].includes(value.model.trim())
      : value.provider === 'openai'
        ? !isValidOpenAiModelId(value.model.trim())
        : value.provider === 'gemini'
          ? !isValidGeminiModelId(value.model.trim())
      : !isValidConfiguredModel(value.model.trim(), value.provider))
    || typeof value.fallbackToLocal !== 'boolean'
  ) return null;
  return {
    provider: value.provider as StoredAiEmployeeProviders['reasoning']['provider'],
    model: value.model.trim(),
    fallbackToLocal: value.fallbackToLocal
  };
}

function parseStoredAiImageProvider(input: unknown): StoredAiEmployeeProviders['image'] | null {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return null;
  const value = input as Record<string, unknown>;
  if (Object.keys(value).some(key => !['provider', 'model', 'fallbackToLocal'].includes(key))) return null;
  if (
    (value.provider !== 'automatic1111' && value.provider !== 'fal')
    || typeof value.model !== 'string'
    || !isValidConfiguredModel(value.model.trim(), value.provider)
    || typeof value.fallbackToLocal !== 'boolean'
  ) return null;
  return { provider: value.provider, model: value.model.trim(), fallbackToLocal: value.fallbackToLocal };
}

function parseStoredAiEmployeeProviderUpdate(input: unknown): StoredAiEmployeeProviders | null {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return null;
  const body = input as Record<string, unknown>;
  if (
    Object.keys(body).some(key => ![
      'reasoning', 'advancedReasoning', 'vision', 'image',
      'deepseekApiKey', 'clearDeepSeekApiKey',
      'falApiKey', 'clearFalApiKey',
      'openaiApiKey', 'clearOpenAiApiKey',
      'geminiApiKey', 'clearGeminiApiKey'
    ].includes(key))
    || !['reasoning', 'advancedReasoning', 'vision', 'image'].every(key => Object.hasOwn(body, key))
    || (body.deepseekApiKey !== undefined && (typeof body.deepseekApiKey !== 'string' || body.deepseekApiKey.length > 4000))
    || (body.clearDeepSeekApiKey !== undefined && typeof body.clearDeepSeekApiKey !== 'boolean')
    || (body.falApiKey !== undefined && (typeof body.falApiKey !== 'string' || body.falApiKey.length > 4000))
    || (body.clearFalApiKey !== undefined && typeof body.clearFalApiKey !== 'boolean')
    || (body.openaiApiKey !== undefined && (typeof body.openaiApiKey !== 'string' || body.openaiApiKey.length > 4000))
    || (body.clearOpenAiApiKey !== undefined && typeof body.clearOpenAiApiKey !== 'boolean')
    || (body.geminiApiKey !== undefined && (typeof body.geminiApiKey !== 'string' || body.geminiApiKey.length > 4000))
    || (body.clearGeminiApiKey !== undefined && typeof body.clearGeminiApiKey !== 'boolean')
  ) return null;

  const current = integrationConfig.aiEmployeeProviders;
  const reasoning = parseStoredAiTextProvider(body.reasoning, ['ollama', 'deepseek']);
  const parsedAdvancedReasoning = parseStoredAiTextProvider(body.advancedReasoning, ['openai']);
  const vision = parseStoredAiTextProvider(body.vision, ['ollama', 'gemini']);
  const image = parseStoredAiImageProvider(body.image);
  if (!reasoning || parsedAdvancedReasoning?.provider !== 'openai' || !vision || !image) return null;
  const advancedReasoning = { ...parsedAdvancedReasoning, provider: 'openai' as const };
  const deepseekApiKey = typeof body.deepseekApiKey === 'string' ? body.deepseekApiKey.trim() : '';
  const falApiKey = typeof body.falApiKey === 'string' ? body.falApiKey.trim() : '';
  const openaiApiKey = typeof body.openaiApiKey === 'string' ? body.openaiApiKey.trim() : '';
  const geminiApiKey = typeof body.geminiApiKey === 'string' ? body.geminiApiKey.trim() : '';
  if (
    (deepseekApiKey && body.clearDeepSeekApiKey === true)
    || (falApiKey && body.clearFalApiKey === true)
    || (openaiApiKey && body.clearOpenAiApiKey === true)
    || (geminiApiKey && body.clearGeminiApiKey === true)
  ) return null;
  const next: StoredAiEmployeeProviders = {
    deepseekApiKeyEncrypted: body.clearDeepSeekApiKey === true
      ? ''
      : deepseekApiKey
        ? encryptSecret(deepseekApiKey)
        : current.deepseekApiKeyEncrypted,
    falApiKeyEncrypted: body.clearFalApiKey === true
      ? ''
      : falApiKey
        ? encryptSecret(falApiKey)
        : current.falApiKeyEncrypted,
    openaiApiKeyEncrypted: body.clearOpenAiApiKey === true
      ? ''
      : openaiApiKey
        ? encryptSecret(openaiApiKey)
        : current.openaiApiKeyEncrypted,
    geminiApiKeyEncrypted: body.clearGeminiApiKey === true
      ? ''
      : geminiApiKey
        ? encryptSecret(geminiApiKey)
        : current.geminiApiKeyEncrypted,
    reasoning,
    advancedReasoning,
    vision,
    image
  };
  try {
    createRuntimeAiEmployeeProviderSettings(next);
  } catch {
    return null;
  }
  return next;
}

async function getMerchantPayPalCredentials(merchantId: string): Promise<PayPalCredentials | null> {
  const config = await prisma.merchantPayPalConfig.findUnique({ where: { merchantId } });
  if (!config?.enabled || !['sandbox', 'live'].includes(config.environment)) return null;
  return {
    clientId: decryptSecret(config.clientIdEncrypted),
    clientSecret: decryptSecret(config.clientSecretEncrypted),
    environment: config.environment as PayPalEnvironment
  };
}

async function getMerchantStripeCredentials(merchantId: string): Promise<MerchantStripeCredentials | null> {
  const config = await prisma.merchantStripeConfig.findUnique({ where: { merchantId } });
  if (!config?.enabled) return null;
  return {
    secretKey: decryptSecret(config.secretKeyEncrypted),
    accountId: config.stripeAccountId,
    livemode: config.livemode
  };
}

function serializeSolanaPaymentIntent(intent: {
  id: string;
  requestTokenEncrypted: string;
  recipient: string;
  platformWallet: string;
  reference: string;
  mint: string;
  tokenSymbol: string;
  tokenAmount: Prisma.Decimal;
  eurAmount: Prisma.Decimal;
  exchangeRate: Prisma.Decimal;
  exchangeRateSource: string;
  exchangeRateUpdatedAt: Date;
  commissionRate: Prisma.Decimal;
  merchantAmount: Prisma.Decimal;
  commissionAmount: Prisma.Decimal;
  quotedAt: Date;
  expiresAt: Date;
  status: string;
  signature: string | null;
}, orderNo: string) {
  const requestToken = decryptSecret(intent.requestTokenEncrypted);
  const appUrl = process.env.APP_URL;
  if (!appUrl) throw new Error('APP_URL_NOT_CONFIGURED');
  const requestUrl = new URL(
    `/api/payments/solana/request/${encodeURIComponent(requestToken)}`,
    appUrl
  ).toString();
  return {
    id: intent.id,
    uri: createSolanaPayUrl({
      requestUrl,
      orderNo
    }),
    tokenSymbol: intent.tokenSymbol as SolanaTokenSymbol,
    tokenAmount: intent.tokenAmount.toString(),
    eurAmount: intent.eurAmount.toString(),
    exchangeRate: intent.exchangeRate.toString(),
    exchangeRateSource: intent.exchangeRateSource,
    exchangeRateUpdatedAt: intent.exchangeRateUpdatedAt.toISOString(),
    commissionRate: intent.commissionRate.toString(),
    merchantAmount: intent.merchantAmount.toString(),
    commissionAmount: intent.commissionAmount.toString(),
    quotedAt: intent.quotedAt.toISOString(),
    expiresAt: intent.expiresAt.toISOString(),
    status: intent.status as 'pending' | 'paid' | 'expired' | 'late_payment' | 'review',
    signature: intent.signature
  };
}

async function settleRefundTransaction(refundId: string, providerRefundId: string): Promise<void> {
  await prisma.$transaction(async tx => {
    const refund = await tx.refundTransaction.findUnique({ where: { id: refundId } });
    if (!refund) throw new Error('REFUND_NOT_FOUND');
    if (refund.status === 'succeeded') {
      if (refund.providerRefundId === providerRefundId) return;
      throw new Error('REFUND_ALREADY_SETTLED');
    }
    const paymentLock = await tx.$queryRaw<Array<{ id: string }>>(Prisma.sql`
      SELECT "id" FROM "PaymentTransaction" WHERE "id" = ${refund.paymentTransactionId} FOR UPDATE
    `);
    if (!paymentLock.length) throw new Error('PAYMENT_NOT_FOUND');
    const payment = await tx.paymentTransaction.findUnique({ where: { id: refund.paymentTransactionId } });
    if (!payment) throw new Error('PAYMENT_NOT_FOUND');
    const claimed = await tx.refundTransaction.updateMany({
      where: { id: refund.id, status: refund.status },
      data: { status: 'succeeded', providerRefundId, lastError: null, nextRetryAt: null }
    });
    if (claimed.count !== 1) {
      const latest = await tx.refundTransaction.findUnique({ where: { id: refund.id } });
      if (latest?.status === 'succeeded' && latest.providerRefundId === providerRefundId) return;
      throw new Error('REFUND_STATE_CHANGED');
    }
    const paymentRefunds = await tx.refundTransaction.aggregate({
      where: { paymentTransactionId: payment.id, status: 'succeeded' },
      _sum: { amount: true }
    });
    await tx.paymentTransaction.update({
      where: { id: payment.id },
      data: { status: Number(paymentRefunds._sum.amount || 0) >= Number(payment.amount) ? 'refunded' : 'partially_refunded' }
    });
    await createPartnerCommissionReversals(tx, refund.orderId, refund.id);
    const [successfulRefunds, openRefunds, failedRefunds, paidPayments] = await Promise.all([
      tx.refundTransaction.aggregate({ where: { orderId: refund.orderId, status: 'succeeded' }, _sum: { amount: true } }),
      tx.refundTransaction.count({ where: { orderId: refund.orderId, status: { in: ['requested', 'processing'] } } }),
      tx.refundTransaction.count({ where: { orderId: refund.orderId, status: 'failed' } }),
      tx.paymentTransaction.aggregate({ where: { orderId: refund.orderId, status: { in: ['paid', 'partially_refunded', 'refunded'] } }, _sum: { amount: true } })
    ]);
    const refundedAmount = Number(successfulRefunds._sum.amount || 0);
    const refundProgress = getRefundProgress(Number(paidPayments._sum.amount || 0), refundedAmount, openRefunds, failedRefunds);
    await tx.order.update({
      where: { id: refund.orderId },
      data: { paymentStatus: refundProgress.paymentStatus, refundStatus: refundProgress.refundStatus, refundAmount: refundedAmount }
    });
    await tx.orderInvoice.updateMany({
      where: { orderId: refund.orderId },
      data: { status: refundProgress.paymentStatus === 'refunded' ? 'refunded' : refundedAmount > 0 ? 'partially_refunded' : 'paid' }
    });
    if (refund.returnRequestId) {
      const [total, succeeded] = await Promise.all([
        tx.refundTransaction.count({ where: { returnRequestId: refund.returnRequestId } }),
        tx.refundTransaction.count({ where: { returnRequestId: refund.returnRequestId, status: 'succeeded' } })
      ]);
      if (total > 0 && total === succeeded) {
        await tx.returnRequest.updateMany({
          where: { id: refund.returnRequestId, status: 'received' },
          data: { status: 'refunded' }
        });
        await tx.order.updateMany({
          where: { id: refund.orderId, status: 'return_requested' },
          data: { status: 'delivered' }
        });
      }
    }
    const payoutAllocation = await tx.merchantPayoutAllocation.findUnique({
      where: { orderId: refund.orderId },
      include: { payout: true }
    });
    if (payoutAllocation?.payout.status === 'pending') {
      const allocation = calculatePayoutAllocation(
        Number(payoutAllocation.grossAmount),
        refundedAmount,
        Number(payoutAllocation.payout.platformFeeRate)
      );
      await tx.merchantPayoutAllocation.update({
        where: { id: payoutAllocation.id },
        data: { refundAmount: refundedAmount, netAmount: allocation.netAmount }
      });
      const allocations = await tx.merchantPayoutAllocation.findMany({ where: { payoutId: payoutAllocation.payoutId } });
      await tx.merchantPayout.update({
        where: { id: payoutAllocation.payoutId },
        data: {
          refunds: Number(allocations.reduce((sum, item) => sum + Number(item.refundAmount), 0).toFixed(2)),
          netPayout: Number(allocations.reduce((sum, item) => sum + Number(item.netAmount), 0).toFixed(2))
        }
      });
    }
  });
}

async function queueLatePaymentRefund(
  tx: Prisma.TransactionClient,
  orderId: string,
  paymentTransactionId: string
): Promise<boolean> {
  const [order, payment] = await Promise.all([
    tx.order.findUnique({ where: { id: orderId }, select: { id: true, status: true } }),
    tx.paymentTransaction.findUnique({ where: { id: paymentTransactionId } })
  ]);
  if (!order || !payment || order.status !== 'cancelled') return false;
  if (await tx.refundTransaction.findFirst({ where: { paymentTransactionId } })) return true;

  const amount = Number(payment.amount);
  if (!Number.isFinite(amount) || amount <= 0) throw new Error('LATE_PAYMENT_REFUND_AMOUNT_INVALID');
  await tx.refundTransaction.create({
    data: {
      id: crypto.randomUUID(),
      paymentTransactionId,
      orderId,
      amount,
      status: 'requested',
      reason: 'Payment captured after order cancellation'
    }
  });
  const refundTotal = await tx.refundTransaction.aggregate({
    where: { orderId, status: { in: ['requested', 'processing', 'succeeded'] } },
    _sum: { amount: true }
  });
  await tx.order.updateMany({
    where: { id: orderId, status: 'cancelled' },
    data: {
      paymentStatus: 'pending_refund',
      refundStatus: 'processing',
      refundAmount: Number(refundTotal._sum.amount || 0)
    }
  });
  await tx.orderInvoice.updateMany({
    where: { orderId },
    data: { status: 'paid', paidAt: new Date() }
  });
  return true;
}

async function processMerchantStripeRefund(refund: {
  id: string;
  orderId: string;
  paymentTransactionId: string;
  amount: Prisma.Decimal;
  providerRefundId: string | null;
  retryCount: number;
}): Promise<string> {
  const [payment, order] = await Promise.all([
    prisma.paymentTransaction.findUnique({ where: { id: refund.paymentTransactionId } }),
    prisma.order.findUnique({ where: { id: refund.orderId }, select: { merchantId: true } })
  ]);
  if (!payment || !order?.merchantId) throw new Error('MERCHANT_STRIPE_REFUND_CONTEXT_MISSING');
  const credentials = await getMerchantStripeCredentials(order.merchantId);
  if (!credentials) throw new Error('STRIPE_MERCHANT_CONFIG_NOT_AVAILABLE');
  const paymentMetadata = parseStoredJson<Record<string, unknown>>(payment.metadata, {});
  const paymentIntentId = typeof paymentMetadata.paymentIntentId === 'string' ? paymentMetadata.paymentIntentId : '';
  if (!refund.providerRefundId && !paymentIntentId) throw new Error('STRIPE_PAYMENT_INTENT_MISSING');
  const result = refund.providerRefundId
    ? await retrieveMerchantStripeRefund(credentials, refund.providerRefundId)
    : await createMerchantStripeRefund(credentials, paymentIntentId, Number(refund.amount), `ruda-refund-${refund.id}`);
  if (result.status === 'succeeded') {
    await settleRefundTransaction(refund.id, result.refundId);
    return result.status;
  }
  const failed = result.status === 'failed' || result.status === 'canceled';
  await prisma.refundTransaction.update({
    where: { id: refund.id },
    data: {
      status: failed ? 'failed' : 'processing',
      providerRefundId: result.refundId,
      retryCount: refund.retryCount + 1,
      nextRetryAt: failed ? null : new Date(Date.now() + 5 * 60 * 1000),
      lastError: failed ? `STRIPE_REFUND_${result.status.toUpperCase()}` : null
    }
  });
  return result.status;
}

function normalizeIban(value: unknown): string {
  return String(value || '').replace(/\s+/g, '').toUpperCase();
}

function isValidIban(iban: string): boolean {
  if (!/^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$/.test(iban)) return false;
  const rearranged = `${iban.slice(4)}${iban.slice(0, 4)}`;
  let remainder = 0;
  for (const character of rearranged) {
    const value = character >= 'A' && character <= 'Z' ? String(character.charCodeAt(0) - 55) : character;
    for (const digit of value) remainder = (remainder * 10 + Number(digit)) % 97;
  }
  return remainder === 1;
}

function maskIban(last4: string): string {
  return `**** **** **** ${last4}`;
}

function generateBase32Secret(): string {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  const bytes = crypto.randomBytes(20);
  let bits = '';
  for (const byte of bytes) bits += byte.toString(2).padStart(8, '0');
  let secret = '';
  for (let offset = 0; offset < bits.length; offset += 5) {
    secret += alphabet[Number.parseInt(bits.slice(offset, offset + 5).padEnd(5, '0'), 2)];
  }
  return secret;
}

function generateRecoveryCodes(count = 8): string[] {
  return Array.from({ length: count }, () => crypto.randomBytes(5).toString('hex').toUpperCase());
}

async function verifyRecoveryCode(stored: string | null, code: string): Promise<{ valid: boolean; remaining: string[] }> {
  const hashes = parseStoredJson<string[]>(stored, []);
  for (let index = 0; index < hashes.length; index += 1) {
    if (await bcrypt.compare(code, hashes[index])) {
      return { valid: true, remaining: hashes.filter((_, hashIndex) => hashIndex !== index) };
    }
  }
  return { valid: false, remaining: hashes };
}

