async function loadMarketingCampaigns() {
  try {
    const saved = JSON.parse(await readFile(marketingCampaignPath, 'utf8')) as MarketingCampaign[];
    if (Array.isArray(saved)) {
      marketingCampaigns.push(...saved.filter(campaign =>
        campaign && typeof campaign.id === 'string' &&
        typeof campaign.name === 'string' &&
        Array.isArray(campaign.channels) &&
        campaign.channels.length > 0 &&
        campaign.channels.every(channel => marketingChannels.includes(channel)) &&
        ['/', '/catalog', '/showrooms'].includes(campaign.landingPath) &&
        (campaign.status === 'draft' || campaign.status === 'approved')
      ).map(campaign => ({
        ...campaign,
        instagramImageUrl: typeof campaign.instagramImageUrl === 'string' ? campaign.instagramImageUrl : null,
        publications: Array.isArray(campaign.publications)
          ? campaign.publications.filter(publication =>
            publication && ['instagram', 'facebook'].includes(publication.channel) &&
            typeof publication.pageId === 'string' && typeof publication.accountName === 'string' &&
            ['publishing', 'published', 'failed'].includes(publication.status) &&
            typeof publication.startedAt === 'string'
          ).slice(0, 100)
          : []
      })).slice(-200));
    }
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
      console.error('[marketing-campaigns-load]', error instanceof Error ? error.message : error);
    }
  }
}

function persistMarketingCampaigns() {
  const pendingWrite = marketingCampaignsWriteQueue.then(async () => {
    await mkdir(path.dirname(marketingCampaignPath), { recursive: true });
    const temporaryPath = `${marketingCampaignPath}.${crypto.randomUUID()}.tmp`;
    try {
      await writeFile(temporaryPath, `${JSON.stringify(marketingCampaigns)}\n`, 'utf8');
      await rename(temporaryPath, marketingCampaignPath);
    } catch (error) {
      await unlink(temporaryPath).catch(() => undefined);
      throw error;
    }
  });
  marketingCampaignsWriteQueue = pendingWrite.then(() => undefined, () => undefined);
  return pendingWrite;
}

