function toFashionCommunityPostData(post: SharedGalleryImage) {
  return {
    id: post.id,
    image: post.image || '',
    merchantId: post.merchantId,
    merchantName: post.merchantName,
    createdAt: new Date(post.createdAt),
    featured: Boolean(post.featured),
    title: post.title ?? null,
    caption: post.caption ?? null,
    category: post.category ?? null,
    city: post.city ?? null,
    mediaType: post.mediaType || 'image',
    videoUrl: post.videoUrl ?? null,
    videoStorageKey: post.videoStorageKey ?? null,
    imageStorageKey: post.imageStorageKey ?? null,
    posterStorageKey: post.posterStorageKey ?? null,
    mediaItems: post.mediaItems ? post.mediaItems as Prisma.InputJsonValue : Prisma.JsonNull,
    hashtags: post.hashtags || [],
    creatorAccountId: post.creatorAccountId ?? null,
    rightsStatus: post.rightsStatus || 'authorized',
    publicationStatus: post.publicationStatus || 'approved',
    updatedAt: new Date()
  };
}

function fromFashionCommunityPost(post: Awaited<ReturnType<typeof prisma.fashionCommunityPost.findUnique>>): SharedGalleryImage | undefined {
  if (!post) return undefined;
  return {
    id: post.id,
    image: post.image,
    merchantId: post.merchantId,
    merchantName: post.merchantName,
    createdAt: post.createdAt.toISOString(),
    featured: post.featured,
    ...(post.title !== null ? { title: post.title } : {}),
    ...(post.caption !== null ? { caption: post.caption } : {}),
    ...(post.category !== null ? { category: post.category } : {}),
    ...(post.city !== null ? { city: post.city } : {}),
    mediaType: post.mediaType === 'video' || post.mediaType === 'mixed' ? post.mediaType : 'image',
    ...(post.videoUrl !== null ? { videoUrl: post.videoUrl } : {}),
    ...(post.videoStorageKey !== null ? { videoStorageKey: post.videoStorageKey } : {}),
    ...(post.imageStorageKey !== null ? { imageStorageKey: post.imageStorageKey } : {}),
    ...(post.posterStorageKey !== null ? { posterStorageKey: post.posterStorageKey } : {}),
    ...(Array.isArray(post.mediaItems) ? { mediaItems: post.mediaItems as FashionPostMedia[] } : {}),
    hashtags: post.hashtags,
    ...(post.creatorAccountId ? { creatorAccountId: post.creatorAccountId } : {}),
    rightsStatus: post.rightsStatus as SharedGalleryImage['rightsStatus'],
    publicationStatus: post.publicationStatus as SharedGalleryImage['publicationStatus']
  };
}

async function saveFashionCommunityPost(post: SharedGalleryImage) {
  const data = toFashionCommunityPostData(post);
  return prisma.fashionCommunityPost.upsert({
    where: { id: post.id },
    create: data,
    update: data
  });
}

async function loadSharedGallery() {
  let savedPosts: SharedGalleryImage[] = [];
  try {
    const saved = JSON.parse(await readFile(sharedGalleryPath, 'utf8'));
    if (Array.isArray(saved)) savedPosts = saved.slice(0, 500);
    else throw new Error('shared-gallery.json must contain an array');
  } catch (error) {
    if (error && typeof error === 'object' && 'code' in error && error.code === 'ENOENT') {
      savedPosts = [];
    } else {
      throw error;
    }
  }
  if (!usesFashionCommunityDatabase) {
    sharedGallery = savedPosts;
    return;
  }
  const storedPostCount = await prisma.fashionCommunityPost.count({ where: { merchantId: 'public-fashion' } });
  if (storedPostCount === 0 && savedPosts.some(post => post.merchantId === 'public-fashion')) {
    throw new Error('Fashion Community database is empty while legacy posts exist; run the verified JSON import before enabling database storage');
  }
  sharedGallery = savedPosts.filter(post => post.merchantId !== 'public-fashion');
}

async function saveSharedGallery() {
  await writeFile(sharedGalleryPath, `${JSON.stringify(sharedGallery, null, 2)}\n`, 'utf8');
}

