async function loadFashionSocial() {
  if (usesFashionCommunityDatabase) {
    fashionSocial = {};
    return;
  }
  try {
    const saved = JSON.parse(await readFile(fashionSocialPath, 'utf8'));
    if (saved && typeof saved === 'object' && !Array.isArray(saved)) {
      fashionSocial = Object.fromEntries(Object.entries(saved)
        .filter(([id, value]) => isFashionSocialId(id) && value && typeof value === 'object' && !Array.isArray(value))
        .map(([id, value]) => {
          const stored = value as Record<string, unknown>;
          const comments = Array.isArray(stored.comments) ? stored.comments.filter(isFashionSocialComment).slice(-500) : [];
          return [id, {
            likes: Array.isArray(stored.likes) ? stored.likes.filter(isFashionViewerId) : [],
            saves: Array.isArray(stored.saves) ? stored.saves.filter(isFashionViewerId) : [],
            followers: Array.isArray(stored.followers) ? stored.followers.filter(isFashionViewerId) : [],
            comments
          }];
        }));
    }
  } catch (error) {
    if (!(error && typeof error === 'object' && 'code' in error && error.code === 'ENOENT')) throw error;
    fashionSocial = {};
  }
}

function saveFashionSocial() {
  const snapshot = `${JSON.stringify(fashionSocial)}\n`;
  const pendingWrite = fashionSocialWriteQueue.then(async () => {
    if (usesFashionCommunityDatabase) throw new Error('Fashion Community database writes must use scoped repository operations');
    const temporaryPath = `${fashionSocialPath}.${crypto.randomUUID()}.tmp`;
    try {
      await writeFile(temporaryPath, snapshot, 'utf8');
      await rename(temporaryPath, fashionSocialPath);
    } catch (error) {
      await unlink(temporaryPath).catch(cleanupError => {
        if (!(cleanupError && typeof cleanupError === 'object' && 'code' in cleanupError && cleanupError.code === 'ENOENT')) {
          console.error('[fashion-social-cleanup]', cleanupError);
        }
      });
      throw error;
    }
  });
  fashionSocialWriteQueue = pendingWrite.then(() => undefined, () => undefined);
  return pendingWrite;
}

function getFashionSocialItem(id: string): FashionSocialItem {
  const state = fashionSocial[id] ||= { likes: [], saves: [], followers: [], comments: [] };
  state.likes ||= [];
  state.saves ||= [];
  state.followers ||= [];
  state.comments ||= [];
  return state;
}

function isFashionSocialId(value: unknown): value is string {
  return typeof value === 'string' && /^[a-zA-Z0-9_-]{1,100}$/.test(value);
}

function isFashionViewerId(value: unknown): value is string {
  return typeof value === 'string' && /^[a-f0-9-]{36}$/i.test(value);
}

function fashionFeedImageUrl(postId: string, image: string | null | undefined): string | null {
  if (!image) return null;
  return image.startsWith('data:image/')
    ? `/api/fashion/posts/${encodeURIComponent(postId)}/image`
    : image;
}

function isFashionSocialComment(value: unknown): value is FashionSocialComment {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const comment = value as Record<string, unknown>;
  return typeof comment.id === 'string'
    && typeof comment.displayName === 'string'
    && typeof comment.text === 'string'
    && comment.text.length <= 300
    && typeof comment.createdAt === 'string'
    && isFashionViewerId(comment.viewerId);
}

function normalizeCollectorUrl(value: string): URL | null {
  try {
    const url = new URL(value.trim());
    if (!['http:', 'https:'].includes(url.protocol)) return null;
    const host = url.hostname.toLowerCase();
    if (host === 'localhost' || host === '[::1]' || /^(127|10|192\.168|169\.254)\./.test(host) || host.endsWith('.local')) return null;
    return url;
  } catch {
    return null;
  }
}

async function allowedByRobots(url: URL): Promise<boolean> {
  try {
    const robotsUrl = new URL('/robots.txt', url);
    const response = await fetch(robotsUrl, { signal: AbortSignal.timeout(8000), headers: { 'User-Agent': 'RUDA-Authorized-Image-Collector/1.0' } });
    if (!response.ok) return true;
    const lines = (await response.text()).split(/\r?\n/).map(line => line.trim());
    let applies = false;
    for (const line of lines) {
      const [key, rawValue = ''] = line.split(':', 2);
      const value = rawValue.trim();
      if (key.toLowerCase() === 'user-agent') applies = value === '*' || value.toLowerCase().includes('ruda');
      if (applies && key.toLowerCase() === 'disallow' && value && url.pathname.startsWith(value)) return false;
    }
    return true;
  } catch {
    return false;
  }
}

function collectorPHash(raw: { data: Buffer; info: { width: number; height: number; channels: number } }): string {
  const size = 32;
  const values: number[] = [];
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      values.push(raw.data[(y * size + x) * raw.info.channels] || 0);
    }

  }
  const coefficients: number[] = [];
  for (let v = 0; v < 8; v += 1) {
    for (let u = 0; u < 8; u += 1) {
      let sum = 0;
      for (let y = 0; y < size; y += 1) {
        for (let x = 0; x < size; x += 1) {
          sum += values[y * size + x] * Math.cos(((2 * x + 1) * u * Math.PI) / (2 * size)) * Math.cos(((2 * y + 1) * v * Math.PI) / (2 * size));
        }

      }
      coefficients.push(sum);
    }
  }
  const median = [...coefficients.slice(1)].sort((a, b) => a - b)[31];
  return coefficients.slice(1).map(value => value > median ? '1' : '0').join('');
}

function analyzeCollectorImage(sourceUrl: string, width: number, height: number, bytes: number) {
  const text = sourceUrl.toLowerCase();
  const category = /shoe|sneaker|heel|靴/.test(text) ? 'Shoes' : /bag|handbag|purse|包/.test(text) ? 'Bags' : /accessor|jewel|scarf|配饰/.test(text) ? 'Accessories' : 'Women';
  const materials = /leather|皮革|皮/.test(text) ? ['Leather'] : /knit|wool|针织|羊毛/.test(text) ? ['Knitwear'] : ['Unknown'];
  const colors = ['black', 'white', 'red', 'blue', 'green', 'pink', 'beige'].filter(color => text.includes(color));
  const style = /street|urban|街头/.test(text) ? ['Street Style'] : /runway|catwalk|秀场/.test(text) ? ['Runway'] : ['Editorial'];
  const qualityScore = Math.round(Math.min(100, Math.max(0, (Math.min(width, height) / 1000) * 65 + Math.min(35, bytes / (1024 * 1024) * 8))));
  return { category, colors: colors.length ? colors : ['Unclassified'], materials, style, trendTags: [...style, category], qualityScore };
}

function phashDistance(left: string, right: string) {
  if (left.length !== right.length) return 64;
  return left.split('').reduce((total, bit, index) => total + (bit === right[index] ? 0 : 1), 0);
}

async function runWebsiteCollector(job: WebsiteCollectorJob) {
  job.status = 'running';
  const browser = await chromium.launch({ headless: true });
  try {
    for (const pageUrl of job.urls) {
      const url = normalizeCollectorUrl(pageUrl);
      if (!url || !(await allowedByRobots(url))) {
        job.failed += 1;
        continue;
      }
      const page = await browser.newPage();
      try {
        await page.goto(url.toString(), { waitUntil: 'domcontentloaded', timeout: 20_000 });
        await page.waitForLoadState('networkidle', { timeout: 8_000 }).catch(() => undefined);
        const candidates = await page.evaluate(() => {
          const values = new Set<string>();
          document.querySelectorAll('img').forEach(node => {
            for (const attr of ['src', 'data-src', 'data-lazy-src', 'data-original']) if (node.getAttribute(attr)) values.add(node.getAttribute(attr)!);
            const srcset = node.getAttribute('srcset') || node.getAttribute('data-srcset') || '';
            srcset.split(',').forEach(item => { const source = item.trim().split(/\s+/)[0]; if (source) values.add(source); });
          });
          document.querySelectorAll('meta[property="og:image"], meta[name="twitter:image"]').forEach(node => { if (node.getAttribute('content')) values.add(node.getAttribute('content')!); });
          document.querySelectorAll('*').forEach(node => {
            const background = getComputedStyle(node).backgroundImage.match(/url\(["']?(.*?)["']?\)/)?.[1];
            if (background) values.add(background);
          });
          return Array.from(values);
        });
        job.discovered += candidates.length;
        for (const candidate of candidates.slice(0, 150)) {
          const imageUrl = new URL(candidate, url).toString();
          try {
            const response = await fetch(imageUrl, { signal: AbortSignal.timeout(15_000), headers: { 'User-Agent': 'RUDA-Authorized-Image-Collector/1.0', Referer: url.toString() } });
            if (!response.ok) throw new Error('image response failed');
            const contentType = response.headers.get('content-type') || '';
            if (!contentType.startsWith('image/')) throw new Error('not an image');
            const data = Buffer.from(await response.arrayBuffer());
            if (data.length > 8 * 1024 * 1024) throw new Error('image too large');
            const metadata = await sharp(data).metadata();
            if (!metadata.width || !metadata.height || metadata.width < 240 || metadata.height < 240) throw new Error('image too small');
            const lowerUrl = imageUrl.toLowerCase();
            if (/(logo|icon|favicon|sprite|avatar|tracking|pixel)/.test(lowerUrl)) throw new Error('decorative image');
            const sha256 = crypto.createHash('sha256').update(data).digest('hex');
            const raw = await sharp(data).resize(32, 32, { fit: 'fill' }).greyscale().raw().toBuffer({ resolveWithObject: true });
            const phash = collectorPHash(raw);
            if (collectorImageHashes.has(sha256) || collectorImagePhashes.has(phash)) {
              job.duplicates += 1;
              continue;
            }
            collectorImageHashes.add(sha256);
            collectorImagePhashes.add(phash);
            const analysis = analyzeCollectorImage(imageUrl, metadata.width, metadata.height, data.length);
            job.results.push({ id: `collector-${crypto.randomUUID()}`, image: `data:${contentType};base64,${data.toString('base64')}`, sourceUrl: imageUrl, pageUrl: url.toString(), sourceHost: url.hostname, width: metadata.width, height: metadata.height, bytes: data.length, sha256, phash, qualityScore: analysis.qualityScore, analysis, createdAt: new Date().toISOString(), rightsStatus: 'pending' });
            job.downloaded += 1;
          } catch {
            job.failed += 1;
          }
        }
      } finally {
        await page.close();
      }
    }
    job.status = 'completed';
  } catch (error) {
    job.status = 'failed';
    job.error = error instanceof Error ? error.message : 'Collector failed';
  } finally {
    job.finishedAt = new Date().toISOString();
    await writeFile(collectorJobPath, JSON.stringify([...websiteCollectorJobs.values()].map(item => ({ ...item, results: item.results.map(result => ({ ...result, image: undefined })) })), null, 2), 'utf8').catch(() => undefined);
    await browser.close();
  }
}

