const xmlText = (value: string, tag: string) => {
  const match = value.match(new RegExp(`<${tag}(?:\\s[^>]*)?>([\\s\\S]*?)</${tag}>`, 'i'));
  return match ? match[1].replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, '').trim() : '';
};

async function runFashionFeedIngestion() {
  for (const source of fashionFeedSources.filter(item => item.enabled)) {
    try {
      const response = await fetch(source.feedUrl, { headers: { accept: 'application/rss+xml, application/atom+xml, text/xml' } });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const xml = await response.text();
      const entries = xml.match(/<(?:item|entry)\b[\s\S]*?<\/(?:item|entry)>/gi) || [];
      for (const entry of entries.slice(0, 30)) {
        const link = xmlText(entry, 'link') || entry.match(/<link[^>]+href=["']([^"']+)/i)?.[1] || source.feedUrl;
        const title = xmlText(entry, 'title') || 'Fashion editorial';
        const summary = xmlText(entry, 'description') || xmlText(entry, 'summary') || 'Fashion image editorial';
        const image = entry.match(/<enclosure[^>]+url=["']([^"']+\.(?:jpg|jpeg|png|webp)[^"']*)/i)?.[1]
          || entry.match(/<media:content[^>]+url=["']([^"']+)/i)?.[1]
          || entry.match(/<img[^>]+src=["']([^"']+)/i)?.[1];
        if (!image) continue;
        const itemId = crypto.createHash('sha256').update(`${source.id}:${link}:${image}`).digest('hex').slice(0, 32);
        if (fashionFeedItems.some(item => item.id === itemId)) continue;
        fashionFeedItems.unshift({
          id: itemId, sourceId: source.id, sourceName: source.name, sourceUrl: link, image,
          title, summary: summary.slice(0, 500), tags: ['时尚趋势'], status: 'pending', createdAt: new Date().toISOString()
        });
      }
      source.lastFetchedAt = new Date().toISOString();
    } catch (error) {
      console.error(`[fashion-feed] ${source.name}:`, error instanceof Error ? error.message : error);
    }
  }
  fashionFeedItems = fashionFeedItems.slice(0, 1000);
  await saveFashionFeeds();
}

async function loadAiSupportConfig() {
  try {
    const saved = JSON.parse(await readFile(aiSupportConfigPath, 'utf8')) as Partial<AiSupportConfig>;
    const savedMerchantSupportAi = saved.merchantSupportAi;
    const legacyWelcomeMessages = [
      '您好，我是 RUDA AI 客服，可以帮您找现货、查商家、了解批发流程和授权规则。',
      '您好，我是 RUDA AI 助手，可以帮您找认证商家、筛选特价商品、了解平台和服装批发流程，也能协助整理文案与经营建议。'
    ];
    const legacyFallbackMessage = '我暂时没有找到完全匹配的信息。您可以留下款号、品类或商家名称，我会帮您继续查找。';
    const legacyQuickQuestions = ['怎么找现货？', '如何申请商家授权？', '怎么批量下单？', '有哪些品牌商家？'];
    const usesLegacyQuickQuestions = Array.isArray(saved.quickQuestions) &&
      saved.quickQuestions.length === legacyQuickQuestions.length &&
      saved.quickQuestions.every((question, index) => question === legacyQuickQuestions[index]);
    Object.assign(aiSupportConfig, {
      ...saved,
      welcomeMessage: legacyWelcomeMessages.includes(saved.welcomeMessage || '')
        ? aiSupportConfig.welcomeMessage
        : typeof saved.welcomeMessage === 'string' ? saved.welcomeMessage : aiSupportConfig.welcomeMessage,
      fallbackMessage: saved.fallbackMessage === legacyFallbackMessage
        ? aiSupportConfig.fallbackMessage
        : typeof saved.fallbackMessage === 'string' ? saved.fallbackMessage : aiSupportConfig.fallbackMessage,
      quickQuestions: usesLegacyQuickQuestions
        ? aiSupportConfig.quickQuestions
        : Array.isArray(saved.quickQuestions) ? saved.quickQuestions : aiSupportConfig.quickQuestions,
      merchantSupportAi: {
        enabled: typeof savedMerchantSupportAi?.enabled === 'boolean' ? savedMerchantSupportAi.enabled : defaultMerchantSupportAiConfig.enabled,
        autoReplyEnabled: typeof savedMerchantSupportAi?.autoReplyEnabled === 'boolean' ? savedMerchantSupportAi.autoReplyEnabled : defaultMerchantSupportAiConfig.autoReplyEnabled,
        model: savedMerchantSupportAi?.model === 'llama3.2:latest' || savedMerchantSupportAi?.model === 'qwen2.5:7b'
          ? savedMerchantSupportAi.model
          : defaultMerchantSupportAiConfig.model,
        instructions: typeof savedMerchantSupportAi?.instructions === 'string' ? savedMerchantSupportAi.instructions.slice(0, 20_000) : ''
      },
      merchantSupportSlaMinutes: {
        urgent: isValidMerchantSupportSlaMinutes(saved.merchantSupportSlaMinutes?.urgent)
          ? saved.merchantSupportSlaMinutes.urgent : defaultMerchantSupportSlaMinutes.urgent,
        high: isValidMerchantSupportSlaMinutes(saved.merchantSupportSlaMinutes?.high)
          ? saved.merchantSupportSlaMinutes.high : defaultMerchantSupportSlaMinutes.high,
        normal: isValidMerchantSupportSlaMinutes(saved.merchantSupportSlaMinutes?.normal)
          ? saved.merchantSupportSlaMinutes.normal : defaultMerchantSupportSlaMinutes.normal
      },
      merchantSupportKnowledgeArticles: validateMerchantSupportKnowledgeArticles(saved.merchantSupportKnowledgeArticles)
        ?.filter(article => !defaultMerchantSupportKnowledgeArticleIds.has(article.id)) || []
    });
  } catch {
    // First launch uses the built-in defaults.
  }
}

async function saveAiSupportConfig() {
  await writeFile(aiSupportConfigPath, `${JSON.stringify(aiSupportConfig, null, 2)}\n`, 'utf8');
}

// 校验 Token (generic)
function verifyToken(token: string, secret: string): any {
  try { return jwt.verify(token, secret); } catch { return null; }
}

