  app.post('/api/company/products', requireCompanyAuth, async (req: AuthRequest, res) => {
    try {
      const body = req.body || {};
      const merchantId = String(body.merchantId || '');
      const category = String(body.category || '').trim();
      const name = String(body.name || '').trim();
      const styleNo = String(body.styleNo || `STY-${Date.now().toString().slice(-6)}`).trim().toUpperCase();
      const wholesalePrice = Number(body.wholesalePrice);
      const rrpPrice = Number(body.rrpPrice);
      const moq = Number(body.moq || 1);
      const packSize = Number(body.packSize || 1);
      if (!merchantId || !name || !category || !styleNo ||
        !Number.isFinite(wholesalePrice) || wholesalePrice <= 0 ||
        !Number.isFinite(rrpPrice) || rrpPrice <= 0 ||
        !Number.isInteger(moq) || moq <= 0 ||
        !Number.isInteger(packSize) || packSize <= 0) {
        return res.status(400).json({ success: false, error: 'PRODUCT_FIELDS_INVALID' });
      }
      const merchant = await prisma.merchant.findUnique({
        where: { id: merchantId },
        select: { id: true, name: true, companyId: true }
      });
      if (!merchant) return sendAccessDenied(res, 'COMPANY_MERCHANT_FORBIDDEN');
      assertTenantScope(merchant.companyId, req.company!.companyId, {
        message: 'The selected merchant is outside the authenticated company'
      });
      const duplicate = await prisma.product.findFirst({ where: { merchantId, styleNo }, select: { id: true } });
      if (duplicate) return res.status(409).json({ success: false, error: 'STYLE_NO_ALREADY_EXISTS' });
      const submittedSkus = Array.isArray(body.skus) ? body.skus.slice(0, 500) : [];
      const images = Array.isArray(body.images) && body.images.length
        ? body.images.slice(0, 32)
        : ['https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?q=80&w=1000&auto=format&fit=crop'];
      const id = `prod-${Date.now()}-${crypto.randomBytes(3).toString('hex')}`;
      const product = await prisma.$transaction(async tx => {
        const created = await tx.product.create({
          data: {
          id, styleNo, name, category, subCategory: String(body.subCategory || 'general'),
          brand: merchant.name, season: String(body.season || '2026/27'),
          images: JSON.stringify(images), media: JSON.stringify(images.map((url: string, index: number) => ({ id: `image-${index}`, type: 'image', url }))),
          wholesalePrice, rrpPrice, costPrice: Number(body.costPrice || 0),
          moq, packSize, status: 'new', inventoryStatus: 'in_stock',
          origin: String(body.origin || ''), fabric: String(body.fabric || ''),
          composition: String(body.composition || ''), weight: String(body.weight || ''),
          packaging: String(body.packaging || ''), washCare: String(body.washCare || ''),
          description: String(body.description || ''), skus: JSON.stringify(submittedSkus),
          merchantId, merchantName: merchant.name, visibility: 'wholesale',
          lifecycleStatus: 'draft', isExclusiveProtected: false
          }
        });
        if (modaGptBrainEnabled) {
          await enqueueModaGptEventsInTransaction(tx, [{
            type: 'product.created',
            eventId: created.id,
            merchantId,
            occurredAt: created.createdAt.toISOString(),
            data: {
              productId: created.id,
              styleNo: created.styleNo,
              brand: created.brand,
              lifecycleStatus: created.lifecycleStatus
            }
          }]);
        }
        const auditEvent = createAuditEvent({
          eventName: 'product.create',
          actorId: req.company!.companyId,
          actorName: req.company!.companyId,
          actorRole: 'company',
          merchantId,
          targetType: 'Product',
          targetId: created.id,
          beforeState: null,
          afterState: 'draft',
          result: 'success',
          requestId: req.requestId,
          details: { styleNo: created.styleNo }
        });
        await tx.auditLog.create({
          data: buildPersistedAuditRecord(auditEvent, {
            id: crypto.randomUUID(),
            ip: getClientIp(req),
            userAgent: req.get('user-agent')
          })
        });
        return created;
      });
      res.status(201).json({ success: true, product: serializeProductRow(product) });
    } catch (error) {
      sendInternalError(res, error, 'company-product-create');
    }
  });

  app.put('/api/company/products/batch', requireCompanyAuth, async (req: AuthRequest, res) => {
    const ids: string[] = Array.isArray(req.body?.productIds)
      ? [...new Set<string>(req.body.productIds.map((id: unknown) => String(id).trim()).filter(Boolean))].slice(0, 500)
      : [];
    const lifecycleStatus = String(req.body?.lifecycleStatus || '');
    if (!ids.length || !['published', 'draft'].includes(lifecycleStatus)) {
      return res.status(400).json({ success: false, error: 'PRODUCT_BATCH_ACTION_INVALID' });
    }
    try {
      const merchantIds = (await prisma.merchant.findMany({
        where: { companyId: req.company!.companyId },
        select: { id: true }
      })).map(merchant => merchant.id);
      const scoped = await prisma.product.findMany({
        where: { id: { in: ids }, merchantId: { in: merchantIds }, lifecycleStatus: { not: 'archived' } },
        select: { id: true }
      });
      if (scoped.length !== ids.length) {
        return res.status(404).json({ success: false, error: 'PRODUCT_BATCH_SCOPE_INVALID' });
      }
      const result = await prisma.product.updateMany({
        where: { id: { in: ids }, merchantId: { in: merchantIds }, lifecycleStatus: { not: 'archived' } },
        data: { lifecycleStatus }
      });
      if (result.count !== ids.length) {
        return res.status(409).json({ success: false, error: 'PRODUCT_BATCH_CHANGED_RETRY' });
      }
      res.json({ success: true, updatedCount: result.count });
    } catch (error) {
      sendInternalError(res, error, 'company-product-batch-lifecycle');
    }
  });

  app.put('/api/company/products/:id', requireCompanyAuth, async (req: AuthRequest, res) => {
    try {
      const merchantIds = (await prisma.merchant.findMany({
        where: { companyId: req.company!.companyId },
        select: { id: true }
      })).map(merchant => merchant.id);
      const current = await prisma.product.findFirst({
        where: { id: req.params.id, merchantId: { in: merchantIds } }
      });
      if (!current) return res.status(404).json({ success: false, error: 'PRODUCT_NOT_FOUND' });

      const body = req.body || {};
      const data: Record<string, unknown> = {};
      if (body.name !== undefined) {
        const name = String(body.name).trim();
        if (!name) return res.status(400).json({ success: false, error: 'PRODUCT_NAME_INVALID' });
        data.name = name;
      }
      for (const field of ['wholesalePrice', 'rrpPrice']) {
        if (body[field] !== undefined) {
          const value = Number(body[field]);
          if (!Number.isFinite(value) || value <= 0) {
            return res.status(400).json({ success: false, error: `${field.toUpperCase()}_INVALID` });
          }
          data[field] = value;
        }
      }
      if (body.moq !== undefined || body.packSize !== undefined) {
        for (const field of ['moq', 'packSize']) {
          if (body[field] !== undefined) {
            const value = Number(body[field]);
            if (!Number.isInteger(value) || value <= 0) {
              return res.status(400).json({ success: false, error: `${field.toUpperCase()}_INVALID` });
            }
            data[field] = value;
          }
        }
      }
      if (body.status !== undefined) {
        if (!['new', 'hot', 'clearance', 'restocked'].includes(String(body.status))) {
          return res.status(400).json({ success: false, error: 'PRODUCT_STATUS_INVALID' });
        }
        data.status = String(body.status);
      }
      if (body.lifecycleStatus !== undefined) {
        if (!['published', 'pending_review', 'draft', 'rejected', 'archived'].includes(String(body.lifecycleStatus))) {
          return res.status(400).json({ success: false, error: 'PRODUCT_LIFECYCLE_INVALID' });
        }
        data.lifecycleStatus = String(body.lifecycleStatus);
      }
      if (body.visibility !== undefined) {
        if (!['public', 'wholesale', 'private'].includes(String(body.visibility))) {
          return res.status(400).json({ success: false, error: 'PRODUCT_VISIBILITY_INVALID' });
        }
        data.visibility = String(body.visibility);
        data.isExclusiveProtected = String(body.visibility) === 'private';
      }
      if (body.description !== undefined) data.description = String(body.description).slice(0, 10000);
      if (body.featuredOnHome !== undefined) data.featuredOnHome = Boolean(body.featuredOnHome);
      if (Array.isArray(body.skus)) data.skus = JSON.stringify(body.skus.slice(0, 500));
      const updated = await prisma.$transaction(async tx => {
        const product = await tx.product.update({ where: { id: current.id }, data });
        if (modaGptBrainEnabled) {
          await enqueueModaGptEventsInTransaction(tx, [{
            type: 'product.updated',
            eventId: `${product.id}-${product.updatedAt.getTime()}`,
            merchantId: product.merchantId,
            occurredAt: product.updatedAt.toISOString(),
            data: {
              productId: product.id,
              styleNo: product.styleNo,
              brand: product.brand,
              lifecycleStatus: product.lifecycleStatus
            }
          }]);
        }
        return product;
      });
      logAudit(req.company!.companyId, 'merchant', 'COMPANY_PRODUCT_UPDATE', 'Product', current.id, current.name, updated.name);
      res.json({ success: true, product: serializeProductRow(updated) });
    } catch (error) {
      sendInternalError(res, error, 'company-product-update');
    }
  });

