  app.post('/api/consumers/register', async (req, res) => {
    if (req.body?.acceptedTerms !== true || req.body?.acceptedPrivacy !== true) {
      return res.status(400).json({ success: false, error: 'LEGAL_CONSENT_REQUIRED' });
    }
    const email = String(req.body?.email || '').trim().toLowerCase();
    const password = String(req.body?.password || '');
    const firstName = String(req.body?.firstName || '').trim();
    const lastName = String(req.body?.lastName || '').trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || !firstName || !lastName || password.length < 8) {
      return res.status(400).json({ success: false, error: 'VALID_NAME_EMAIL_AND_PASSWORD_REQUIRED' });
    }
    try {
      const passwordHash = await bcrypt.hash(password, 12);
      const consumer = await prisma.$transaction(async tx => {
        const identity = await getOrCreateSharedAccountIdentity(tx, email, password, passwordHash);
        const created = await tx.consumer.create({
          data: {
            id: `consumer-${crypto.randomUUID()}`,
            email,
            passwordHash: identity?.passwordHash || passwordHash,
            firstName,
            lastName,
            phone: req.body?.phone ? String(req.body.phone).trim() : null,
            country: req.body?.country ? String(req.body.country).trim() : null,
            newsletterOptIn: req.body?.newsletterOptIn === true
          },
          select: {
            id: true, email: true, firstName: true, lastName: true, phone: true,
            country: true, currency: true, preferredLang: true, points: true, level: true
          }
        });
        await tx.authAccount.create({
          data: {
            id: crypto.randomUUID(),
            role: 'consumer',
            email,
            consumerId: created.id,
            identityId: identity?.id || null,
            emailVerifiedAt: identity?.emailVerifiedAt || null,
            passwordHash: identity?.passwordHash || passwordHash,
            updatedAt: new Date()
          }
        });
        await logAuditAndWait(email, 'system', 'CONSUMER_LEGAL_CONSENT_ACCEPTED', 'consumer', created.id, '', JSON.stringify({
          termsVersion: '2026-10-22',
          privacyVersion: '2026-10-22',
          acceptedTerms: true,
          acceptedPrivacy: true
        }), tx);
        return created;
      });
      const token = jwt.sign({ id: consumer.id, role: 'consumer' }, JWT_BUYER_SECRET, { expiresIn: '30d' });
      setAuthCookie(res, 'ruda_consumer_jwt', token, 2592000);
      return res.status(201).json({ success: true, token, consumer });
    } catch (error) {
      if ((error as { code?: string })?.code === 'P2002') {
        return res.status(409).json({ success: false, error: 'EMAIL_ALREADY_EXISTS' });
      }
      if (error instanceof Error && ['ACCOUNT_PASSWORD_CONFLICT', 'ACCOUNT_IDENTITY_CONFLICT'].includes(error.message)) {
        return res.status(409).json({ success: false, error: error.message });
      }
      sendInternalError(res, error, 'consumer-register');
    }
  });

  app.post('/api/consumers/login', async (req, res) => {
    const email = String(req.body?.email || '').trim().toLowerCase();
    const password = String(req.body?.password || '');
    if (!email || !password) return res.status(400).json({ success: false, error: 'EMAIL_PASSWORD_REQUIRED' });
    const consumer = await prisma.consumer.findUnique({ where: { email } });
    const account = consumer ? await prisma.authAccount.findFirst({
      where: { role: 'consumer', consumerId: consumer.id }
    }) : null;
    const identity = account?.identityId
      ? await prisma.accountIdentity.findUnique({ where: { id: account.identityId }, select: { passwordHash: true } })
      : null;
    if (!consumer || !(await bcrypt.compare(password, identity?.passwordHash || account?.passwordHash || consumer.passwordHash))) {
      return sendAuthenticationError(res, 'INVALID_EMAIL_OR_PASSWORD');
    }
    if (consumer.status !== 'active') return sendAccessDenied(res, 'CONSUMER_ACCOUNT_DISABLED');
    try {
      await prisma.$transaction(async tx => {
        const sharedIdentity = await getOrCreateSharedAccountIdentity(tx, email, password, consumer.passwordHash);
        if (account) {
          await tx.authAccount.update({
            where: { id: account.id },
            data: {
              identityId: sharedIdentity?.id || account.identityId,
              passwordHash: sharedIdentity?.passwordHash || account.passwordHash,
              lastLoginAt: new Date(),
              lastLoginIp: getClientIp(req)
            }
          });
        } else {
          await tx.authAccount.create({
            data: {
              id: crypto.randomUUID(),
              role: 'consumer',
              email,
              consumerId: consumer.id,
              identityId: sharedIdentity?.id || null,
              emailVerifiedAt: sharedIdentity?.emailVerifiedAt || consumer.emailVerifiedAt,
              passwordHash: sharedIdentity?.passwordHash || consumer.passwordHash,
              lastLoginAt: new Date(),
              lastLoginIp: getClientIp(req),
              updatedAt: new Date()
            }
          });
        }
        await tx.consumer.update({
          where: { id: consumer.id },
          data: { lastLoginAt: new Date(), lastLoginIp: getClientIp(req) }
        });
      });
    } catch (error) {
      if (error instanceof Error && ['ACCOUNT_PASSWORD_CONFLICT', 'ACCOUNT_IDENTITY_CONFLICT'].includes(error.message)) {
        return res.status(409).json({ success: false, error: error.message });
      }
      throw error;
    }
    const token = jwt.sign({ id: consumer.id, role: 'consumer' }, JWT_BUYER_SECRET, { expiresIn: '30d' });
    setAuthCookie(res, 'ruda_consumer_jwt', token, 2592000);
    const { passwordHash: _passwordHash, passwordSalt: _passwordSalt, ...safeConsumer } = consumer;
    return res.json({ success: true, token, consumer: safeConsumer });
  });

