  app.put('/api/admin/companies/:id/review', requireAdminAuth, requireAdminPermission('companies.review'), async (req: AuthRequest, res) => {
    try {
      const decision = String(req.body?.decision || '').toLowerCase();
      if (!['approve', 'reject', 'additional_info'].includes(decision)) {
        return res.status(400).json({ success: false, error: 'INVALID_REVIEW_DECISION' });
      }
      const companyId = String(req.params.id);
      const company = await prisma.company.findUnique({ where: { id: companyId }, include: { verification: true } });
      if (!company) return res.status(404).json({ success: false, error: 'COMPANY_NOT_FOUND' });
      const approved = decision === 'approve';
      const nextCompanyStatus = approved ? 'ACTIVE' : decision === 'reject' ? 'REJECTED' : 'VERIFICATION_PENDING';
      const verificationStatus = approved ? 'approved' : decision === 'reject' ? 'rejected' : 'additional_info_needed';
      await prisma.$transaction([
        prisma.company.update({ where: { id: companyId }, data: { status: nextCompanyStatus } }),
        prisma.companyVerification.upsert({
          where: { companyId },
          create: { companyId, status: verificationStatus, riskLevel: approved ? 'low' : 'high', reviewedBy: req.admin?.username || 'admin', reviewedAt: new Date(), rejectionReason: decision === 'reject' ? String(req.body?.reason || 'REJECTED_BY_REVIEW') : null },
          update: { status: verificationStatus, riskLevel: approved ? 'low' : 'high', reviewedBy: req.admin?.username || 'admin', reviewedAt: new Date(), rejectionReason: decision === 'reject' ? String(req.body?.reason || 'REJECTED_BY_REVIEW') : null }
        }),
        prisma.companyBusinessRole.updateMany({ where: { companyId }, data: { status: approved ? 'approved' : decision === 'reject' ? 'rejected' : 'pending' } }),
        prisma.merchant.updateMany({ where: { companyId }, data: { isVerified: approved } }),
        prisma.customer.updateMany({ where: { companyId }, data: { status: approved ? 'approved' : decision === 'reject' ? 'rejected' : 'pending', onboardingStatus: approved ? 'complete' : 'document_check' } }),
        prisma.merchantEmployee.updateMany({ where: { companyId }, data: { active: approved } }),
        prisma.warehouseLocation.updateMany({ where: { merchant: { companyId } }, data: { isActive: approved } })
      ]);
      res.json({ success: true, companyId, status: nextCompanyStatus, verificationStatus });
    } catch (error) {
      sendInternalError(res, error, 'admin-company-review');
    }
  });

