  app.post('/api/merchant-ai/support/chat', rateLimit({
    windowMs: 60 * 60 * 1000,
    limit: 40,
    standardHeaders: 'draft-8',
    legacyHeaders: false
  }), async (req, res) => {
    const merchantId = String(req.body?.merchantId || '').trim();
    const message = String(req.body?.message || '').trim();
    if (!merchantId || !message) return res.status(400).json({ success: false, error: 'MERCHANT_ID_AND_MESSAGE_REQUIRED' });
    if (message.length > 2000) return res.status(400).json({ success: false, error: 'MESSAGE_TOO_LONG' });
    const history = Array.isArray(req.body?.history)
      ? req.body.history.slice(-6).flatMap((item: unknown) => {
        if (!item || typeof item !== 'object' || Array.isArray(item)) return [];
        const turn = item as { role?: unknown; text?: unknown };
        if ((turn.role !== 'user' && turn.role !== 'assistant') || typeof turn.text !== 'string' || !turn.text.trim()) return [];
        return [{ role: turn.role, text: turn.text.trim().slice(0, 500) }];
      })
      : [];

    try {
      const merchant = await prisma.merchant.findUnique({ where: { id: merchantId } });
      if (!merchant || !isPublicStorefront(merchant)) {
        return res.status(404).json({ success: false, error: 'MERCHANT_NOT_FOUND' });
      }
      if (!canUseStorefrontAiAgent(
        merchant.storefrontEnabled === true || (merchant.storefrontEnabled == null && merchant.isVerified),
        merchant.storefrontAiEnabled,
        aiSupportConfig.merchantSupportAi.enabled
      )) {
        return sendAccessDenied(res, 'MERCHANT_AI_AGENT_NOT_ACTIVATED');
      }
      const products = await prisma.product.findMany({
        where: { merchantId, lifecycleStatus: 'published', ...PUBLIC_PRODUCT_VISIBILITY_FILTER },
        orderBy: { updatedAt: 'desc' },
        take: 500
      });
      const normalized = message.toLowerCase();
      const matchedProduct = products.find(product => [product.styleNo, product.name, product.name_zh, product.name_it, product.fabric]
        .filter(Boolean).some(value => normalized.includes(String(value).toLowerCase())));
      const merchantName = merchant.name;
      const publicStock = (product: typeof products[number]) => parseStoredJson<any[]>(product.skus, [])
        .reduce((sum, sku) => sum + Number(sku.stockCentral || 0), 0);
      let reply = `我是 ${merchantName} 的专属 AI 客服，可以帮您查询本店公开现货、起订量、面料、授权规则和采购方式。`;
      if (/你好|您好|hello|hi/i.test(message)) {
        reply = `您好，我是 ${merchantName} 专属 AI 客服。您可以问我款号、库存、面料、起订量或授权看货。`;
      } else if (matchedProduct && /库存|现货|数量|stock|available/i.test(message)) {
        reply = `款号 ${matchedProduct.styleNo} 当前公开现货约 ${publicStock(matchedProduct)} 件，起订量为 ${matchedProduct.moq} 件。下单前建议以商品详情页的实时配码为准。`;
      } else if (matchedProduct) {
        reply = `已找到 ${matchedProduct.styleNo}「${matchedProduct.name}」。面料为 ${matchedProduct.fabric}，起订量 ${matchedProduct.moq} 件，公开现货约 ${publicStock(matchedProduct)} 件。您可以打开商品详情查看配码和采购价。`;
      } else if (/库存|现货|款式|商品|style|sku|product/i.test(message)) {
        reply = `${merchantName} 当前有 ${products.length} 款公开商品。您可以发送款号、商品名或面料名称，我会继续帮您定位；授权专属款需要向本店提交申请。`;
      } else if (/起订|MOQ|批量|下单|采购|order|price|价格|报价/i.test(message)) {
        reply = `本店支持按商品详情页的 SKU 配码采购。每款商品的起订量和现货数量不同，确认款式后可直接加入采购清单；需要特殊报价时请提交企业买手信息。`;
      } else if (/授权|私密|新品|权限|申请/i.test(message)) {
        reply = `本店授权专属系列不会在公开目录展示。完成买手企业登录后，可在“授权专属系列”提交看货申请，审核通过后查看高清图片、配码和专属报价。`;
      } else if (/地址|电话|联系|showroom|展厅|物流|发货/i.test(message)) {
        reply = `本店展厅位于 ${merchant.city}，地址为 ${merchant.showroomAddress}。联系电话：${merchant.contactPhone}。公开现货会按订单确认后的仓储安排发货。`;
      } else if (/谁|品牌|介绍|about/i.test(message)) {
        reply = `${merchantName}：${merchant.tagline_zh || merchant.tagline || merchant.description || '欧洲源头时尚批发商'}。您可以先浏览本店公开现货，再向客服咨询具体款式。`;
      }
      const trustedFacts = {
        merchant: {
          name: merchantName,
          city: merchant.city,
          country: merchant.country,
          tagline: merchant.tagline_zh || merchant.tagline,
          description: merchant.description_zh || merchant.description,
          showroomAddress: merchant.showroomAddress
        },
        publishedPublicProducts: products.slice(0, 100).map(product => ({
          styleNo: product.styleNo,
          name: product.name_zh || product.name,
          fabric: product.fabric_zh || product.fabric,
          wholesalePrice: Number(product.wholesalePrice),
          moq: product.moq,
          publicStock: publicStock(product)
        }))
      };
      const assistantReply = aiSupportConfig.merchantSupportAi.enabled
        ? await answerMerchantOperationsQuestion(
          message,
          trustedFacts,
          reply,
          aiSupportConfig.merchantSupportAi,
          history
        )
        : reply;
      res.json({
        success: true,
        merchant: { id: merchant.id, name: merchantName },
        reply: assistantReply,
        suggestions: ['本店有哪些现货？', '怎么申请授权款？', '这款库存多少？', '起订量是多少？']
      });
    } catch (error) {
      sendInternalError(res, error, 'merchant-ai-support');
    }
  });

