  app.post('/api/admin/partners', requireAdminAuth, requireAdminPermission('growth.partners'), async (req: AuthRequest, res) => {
    try {
      const body = req.body || {};
      const role = body.role;
      const name = typeof body.name === 'string' ? body.name.trim() : '';
      const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';
      const password = typeof body.password === 'string' ? body.password : '';
      const parentId = typeof body.parentId === 'string' && body.parentId.trim() ? body.parentId.trim() : null;
      const status = body.status === undefined ? 'pending' : body.status;
      const rate = Number(body.commissionRate);
      if (!isPartnerRole(role) || !name || name.length > 120 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
        || email.length > 254 || password.length < 12 || password.trim().length < 12) {
        return res.status(400).json({ success: false, error: 'PARTNER_PROFILE_INPUT_INVALID' });
      }
      if (!isPartnerStatus(status) || !Number.isFinite(rate) || rate < 0 || rate > 100) {
        return res.status(400).json({ success: false, error: 'PARTNER_STATUS_OR_COMMISSION_INVALID' });
      }
      const sequenceByRole: Record<PartnerRole, string> = {
        agent: 'partner_agent_code_seq',
        city_agent: 'partner_city_code_seq',
        partner: 'partner_network_code_seq'
      };
      const created = await prisma.$transaction(async tx => {
        const existing = await tx.authAccount.findFirst({ where: { role: 'partner', email }, select: { id: true } });
        if (existing) throw new Error('PARTNER_EMAIL_ALREADY_EXISTS');
        const parent = parentId
          ? await tx.partner.findUnique({
            where: { id: parentId },
            select: { id: true, role: true, status: true, parentId: true, commissionRate: true, cityCommissionRate: true, partnerCommissionRate: true }
          })
          : null;
        if (parentId && (!parent || parent.status !== 'active' || !isAllowedPartnerParent(role, parent.role))) {
          throw new Error('PARTNER_PARENT_INVALID');
        }
        const ancestorRates: number[] = [];
        let ancestor = parent;
        let depth = 0;
        while (ancestor && depth < 2) {
          const ancestorRate = ancestor.role === 'agent' ? ancestor.commissionRate
            : ancestor.role === 'city_agent' ? ancestor.cityCommissionRate
              : ancestor.partnerCommissionRate;
          ancestorRates.push(Number(ancestorRate));
          ancestor = ancestor.parentId
            ? await tx.partner.findUnique({
              where: { id: ancestor.parentId },
              select: { id: true, role: true, status: true, parentId: true, commissionRate: true, cityCommissionRate: true, partnerCommissionRate: true }
            })
            : null;
          depth += 1;
        }
        if (ancestorRates.reduce((sum, value) => sum + value, rate) > 100) {
          throw new Error('PARTNER_COMMISSION_TOTAL_RATE_EXCEEDED');
        }
        const sequence = sequenceByRole[role];
        const [{ value }] = await tx.$queryRaw<Array<{ value: bigint }>>(Prisma.raw(`SELECT nextval('"${sequence}"') AS value`));
        const partnerCode = `${partnerCodePrefix(role)}${String(value).padStart(6, '0')}`;
        const partnerId = crypto.randomUUID();
        const partner = await tx.partner.create({
          data: {
            id: partnerId,
            partnerCode,
            role,
            status,
            name,
            email,
            phone: typeof body.phone === 'string' ? body.phone.trim().slice(0, 40) || null : null,
            country: typeof body.country === 'string' ? body.country.trim().slice(0, 80) : '',
            city: typeof body.city === 'string' ? body.city.trim().slice(0, 100) : '',
            region: typeof body.region === 'string' ? body.region.trim().slice(0, 100) : '',
            language: typeof body.language === 'string' ? body.language.trim().slice(0, 12) || 'en' : 'en',
            parentId,
            commissionRate: role === 'agent' ? rate : 0,
            cityCommissionRate: role === 'city_agent' ? rate : 0,
            partnerCommissionRate: role === 'partner' ? rate : 0,
            account: {
              create: {
                role: 'partner',
                email,
                passwordHash: await bcrypt.hash(password, 12)
              }
            }
          },
          include: { parent: { select: { partnerCode: true, name: true, role: true } } }
        });
        await tx.partnerAuditEvent.create({
          data: {
            id: crypto.randomUUID(),
            partnerId,
            operatorId: req.admin?.username || 'admin',
            action: 'partner_created',
            entityType: 'partner',
            entityId: partnerId,
            metadata: JSON.stringify({ partnerCode, role, status, parentId })
          }
        });
        return partner;
      });
      res.status(201).json({ success: true, partner: created });
    } catch (error) {
      const message = error instanceof Error ? error.message : '';
      if (['PARTNER_EMAIL_ALREADY_EXISTS', 'PARTNER_PARENT_INVALID', 'PARTNER_COMMISSION_TOTAL_RATE_EXCEEDED'].includes(message)) {
        return res.status(message === 'PARTNER_EMAIL_ALREADY_EXISTS' ? 409 : 400).json({ success: false, error: message });
      }
      sendInternalError(res, error, 'admin-partner-create');
    }
  });

  app.patch('/api/admin/partners/:id/status', requireAdminAuth, requireAdminPermission('growth.partners'), async (req: AuthRequest, res) => {
    const status = req.body?.status;
    if (!isPartnerStatus(status)) return res.status(400).json({ success: false, error: 'PARTNER_STATUS_INVALID' });
    try {
      const updated = await prisma.$transaction(async tx => {
        const current = await tx.partner.findUnique({ where: { id: req.params.id } });
        if (!current) return null;
        const partner = await tx.partner.update({ where: { id: current.id }, data: { status } });
        await tx.partnerAuditEvent.create({
          data: {
            id: crypto.randomUUID(),
            partnerId: current.id,
            operatorId: req.admin?.username || 'admin',
            action: 'partner_status_changed',
            entityType: 'partner',
            entityId: current.id,
            metadata: JSON.stringify({ previousStatus: current.status, status })
          }
        });
        return partner;
      });
      if (!updated) return res.status(404).json({ success: false, error: 'PARTNER_NOT_FOUND' });
      res.json({ success: true, partner: updated });
    } catch (error) {
      sendInternalError(res, error, 'admin-partner-status');
    }
  });

  app.patch('/api/admin/partners/:id/commission-rate', requireAdminAuth, requireAdminPermission('growth.partners'), async (req: AuthRequest, res) => {
    const rate = Number(req.body?.rate);
    if (!Number.isFinite(rate) || rate < 0 || rate > 100) {
      return res.status(400).json({ success: false, error: 'PARTNER_COMMISSION_RATE_INVALID' });
    }
    try {
      const partner = await prisma.$transaction(async tx => {
        const current = await tx.partner.findUnique({ where: { id: req.params.id } });
        if (!current) return null;
        const allPartners = await tx.partner.findMany({
          select: { id: true, role: true, parentId: true, commissionRate: true, cityCommissionRate: true, partnerCommissionRate: true }
        });
        const proposed = allPartners.map(item => item.id !== current.id ? item : {
          ...item,
          ...(current.role === 'agent' ? { commissionRate: rate } : {}),
          ...(current.role === 'city_agent' ? { cityCommissionRate: rate } : {}),
          ...(current.role === 'partner' ? { partnerCommissionRate: rate } : {})
        });
        const byId = new Map(proposed.map(item => [item.id, item]));
        for (const candidate of proposed) {
          let cursor: typeof candidate | undefined = candidate;
          let totalRate = 0;
          let depth = 0;
          while (cursor && depth < 3) {
            totalRate += Number(cursor.role === 'agent' ? cursor.commissionRate
              : cursor.role === 'city_agent' ? cursor.cityCommissionRate
                : cursor.partnerCommissionRate);
            cursor = cursor.parentId ? byId.get(cursor.parentId) : undefined;
            depth += 1;
          }
          if (totalRate > 100) throw new Error('PARTNER_COMMISSION_TOTAL_RATE_EXCEEDED');
        }
        const updated = await tx.partner.update({
          where: { id: current.id },
          data: {
            ...(current.role === 'agent' ? { commissionRate: rate } : {}),
            ...(current.role === 'city_agent' ? { cityCommissionRate: rate } : {}),
            ...(current.role === 'partner' ? { partnerCommissionRate: rate } : {})
          }
        });
        await tx.partnerAuditEvent.create({
          data: {
            id: crypto.randomUUID(),
            partnerId: current.id,
            operatorId: req.admin?.username || 'admin',
            action: 'commission_rate_changed',
            entityType: 'partner',
            entityId: current.id,
            metadata: JSON.stringify({ previousRate: Number(current.role === 'agent' ? current.commissionRate
              : current.role === 'city_agent' ? current.cityCommissionRate : current.partnerCommissionRate), rate })
          }
        });
        return updated;
      });
      if (!partner) return res.status(404).json({ success: false, error: 'PARTNER_NOT_FOUND' });
      res.json({ success: true, partner });
    } catch (error) {
      const message = error instanceof Error ? error.message : '';
      if (message === 'PARTNER_COMMISSION_TOTAL_RATE_EXCEEDED') return res.status(400).json({ success: false, error: message });
      sendInternalError(res, error, 'admin-partner-commission-rate');
    }
  });

  app.patch('/api/admin/partners/referrals/:id/attribution', requireAdminAuth, requireAdminPermission('growth.partners'), async (req: AuthRequest, res) => {
    const newPartnerId = typeof req.body?.partnerId === 'string' ? req.body.partnerId.trim() : '';
    const reason = typeof req.body?.reason === 'string' ? req.body.reason.trim() : '';
    if (!newPartnerId || reason.length < 8 || reason.length > 500) {
      return res.status(400).json({ success: false, error: 'PARTNER_ATTRIBUTION_ADJUSTMENT_INVALID' });
    }
    try {
      const result = await prisma.$transaction(async tx => {
        const referral = await tx.partnerReferral.findUnique({ where: { id: req.params.id } });
        if (!referral) return null;
        const directPartner = await tx.partner.findUnique({ where: { id: newPartnerId } });
        if (!directPartner || directPartner.status !== 'active' || !isPartnerRole(directPartner.role)) {
          throw new Error('PARTNER_ATTRIBUTION_TARGET_INVALID');
        }
        const ancestors: Array<{ id: string; role: string; parentId: string | null }> = [];
        let parentId = directPartner.parentId;
        while (parentId && ancestors.length < 2) {
          const parent = await tx.partner.findUnique({
            where: { id: parentId },
            select: { id: true, role: true, status: true, parentId: true }
          });
          if (!parent) break;
          if (parent.status === 'active') ancestors.push(parent);
          parentId = parent.parentId;
        }
        const cityPartner = directPartner.role === 'city_agent'
          ? directPartner
          : ancestors.find(ancestor => ancestor.role === 'city_agent');
        const networkPartner = directPartner.role === 'partner'
          ? directPartner
          : ancestors.find(ancestor => ancestor.role === 'partner');
        const updated = await tx.partnerReferral.update({
          where: { id: referral.id },
          data: {
            partnerId: directPartner.id,
            cityPartnerId: cityPartner?.id || null,
            networkPartnerId: networkPartner?.id || null,
            campaignId: null,
            source: 'admin_adjusted'
          }
        });
        await tx.partnerReferralChange.create({
          data: {
            id: crypto.randomUUID(),
            referralId: referral.id,
            previousPartnerId: referral.partnerId,
            newPartnerId: directPartner.id,
            operatorId: req.admin?.username || 'admin',
            reason
          }
        });
        await tx.partnerAuditEvent.create({
          data: {
            id: crypto.randomUUID(),
            partnerId: directPartner.id,
            operatorId: req.admin?.username || 'admin',
            action: 'referral_attribution_changed',
            entityType: 'referral',
            entityId: referral.id,
            metadata: JSON.stringify({ previousPartnerId: referral.partnerId, newPartnerId: directPartner.id, reason })
          }
        });
        return updated;
      });
      if (!result) return res.status(404).json({ success: false, error: 'PARTNER_REFERRAL_NOT_FOUND' });
      res.json({ success: true, referral: result });
    } catch (error) {
      const message = error instanceof Error ? error.message : '';
      if (message === 'PARTNER_ATTRIBUTION_TARGET_INVALID') return res.status(400).json({ success: false, error: message });
      sendInternalError(res, error, 'admin-partner-attribution');
    }
  });

