  app.get('/api/admin/partners/commissions', requireAdminAuth, requireAdminPermission('growth.partners'), async (req, res) => {
    try {
      const status = typeof req.query.status === 'string' ? req.query.status : '';
      const statuses = ['pending', 'approved', 'available', 'paid', 'cancelled'];
      if (status && !statuses.includes(status)) return res.status(400).json({ success: false, error: 'PARTNER_COMMISSION_STATUS_INVALID' });
      const entries = await prisma.partnerCommissionEntry.findMany({
        where: status ? { status } : {},
        include: {
          partner: { select: { id: true, partnerCode: true, name: true, role: true } },
          order: { select: { id: true, orderNo: true, totalAmount: true, paymentStatus: true, refundStatus: true, refundAmount: true } },
          referral: { select: { customer: { select: { id: true, companyName: true } } } },
          reversals: { select: { amount: true } }
        },
        orderBy: { createdAt: 'desc' },
        take: 500
      });
      res.json({
        success: true,
        entries: entries.map(entry => ({
          ...entry,
          effectiveAmount: Number(entry.amount) + entry.reversals.reduce((sum, reversal) => sum + Number(reversal.amount), 0)
        }))
      });
    } catch (error) {
      sendInternalError(res, error, 'admin-partner-commissions');
    }
  });

  app.post('/api/admin/partners/commissions/:id/approve', requireAdminAuth, requireAdminPermission('growth.partners'), async (req: AuthRequest, res) => {
    try {
      const result = await prisma.$transaction(async tx => {
        const locator = await tx.partnerCommissionEntry.findUnique({
          where: { id: req.params.id },
          select: { orderId: true }
        });
        if (!locator) return { error: 'PARTNER_COMMISSION_NOT_FOUND' as const };
        if (!await lockPartnerCommissionOrder(tx, locator.orderId)) {
          return { error: 'PARTNER_COMMISSION_NOT_FOUND' as const };
        }
        const entry = await tx.partnerCommissionEntry.findUnique({
          where: { id: req.params.id },
          include: { order: true, reversals: { select: { amount: true } } }
        });
        if (!entry) return { error: 'PARTNER_COMMISSION_NOT_FOUND' as const };
        const effectiveAmount = Number(entry.amount)
          + entry.reversals.reduce((sum, reversal) => sum + Number(reversal.amount), 0);
        if (entry.entryType !== 'commission' || entry.status !== 'pending'
          || !['paid', 'partially_refunded'].includes(entry.order.paymentStatus)
          || entry.order.status === 'cancelled'
          || !['none', 'partially_refunded'].includes(entry.order.refundStatus)
          || effectiveAmount <= 0) {
          return { error: 'PARTNER_COMMISSION_NOT_ELIGIBLE' as const };
        }
        const changed = await tx.partnerCommissionEntry.updateMany({
          where: { id: entry.id, status: 'pending' },
          data: { status: 'approved' }
        });
        if (!changed.count) return { error: 'PARTNER_COMMISSION_NOT_ELIGIBLE' as const };
        await tx.partnerAuditEvent.create({
          data: {
            id: crypto.randomUUID(),
            partnerId: entry.partnerId,
            operatorId: req.admin?.username || 'admin',
            action: 'commission_approved',
            entityType: 'commission',
            entityId: entry.id,
            metadata: JSON.stringify({ orderId: entry.orderId, amount: Number(entry.amount), effectiveAmount })
          }
        });
        return { entry: await tx.partnerCommissionEntry.findUniqueOrThrow({ where: { id: entry.id } }) };
      });
      if ('error' in result) {
        const status = result.error === 'PARTNER_COMMISSION_NOT_FOUND' ? 404 : 409;
        return res.status(status).json({ success: false, error: result.error });
      }
      res.json({ success: true, entry: result.entry });
    } catch (error) {
      sendInternalError(res, error, 'admin-partner-commission-approve');
    }
  });

  app.get('/api/partner/profile', requirePartnerAuth, async (req: AuthRequest, res) => {
    try {
      const partner = req.partner!;
      const scopeIds = await getPartnerScopeIds(prisma, partner.id);
      const [referrals, commissions, recentOrders, campaigns] = await Promise.all([
        prisma.partnerReferral.findMany({
          where: { partnerId: { in: scopeIds } },
          select: { id: true, registeredAt: true, customer: { select: { status: true } } }
        }),
        prisma.partnerCommissionEntry.findMany({
          where: { partnerId: { in: scopeIds } },
          select: { amount: true, status: true, createdAt: true }
        }),
        prisma.order.aggregate({
          where: {
            partnerId: { in: scopeIds },
            paymentStatus: 'paid',
            status: { not: 'cancelled' }
          },
          _sum: { totalAmount: true }
        }),
        prisma.partnerCampaign.count({ where: { partnerId: { in: scopeIds }, status: 'active' } })
      ]);
      const now = new Date();
      const monthStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
      const commissionTotal = (entries: typeof commissions) => entries
        .filter(entry => entry.status !== 'cancelled')
        .reduce((sum, entry) => sum + Number(entry.amount), 0);
      res.json({
        success: true,
        partner,
        stats: {
          customers: referrals.length,
          activeCustomers: referrals.filter(item => item.customer.status === 'approved').length,
          newCustomersThisMonth: referrals.filter(item => item.registeredAt >= monthStart).length,
          paidSales: Number(recentOrders._sum.totalAmount || 0),
          commissions: commissionTotal(commissions),
          commissionsThisMonth: commissionTotal(commissions.filter(entry => entry.createdAt >= monthStart)),
          pendingCommissions: commissionTotal(commissions.filter(entry => ['pending', 'approved', 'available'].includes(entry.status))),
          activeCampaigns: campaigns
        }
      });
    } catch (error) {
      sendInternalError(res, error, 'partner-profile');
    }
  });

