  app.get('/api/admin/growth/overview', requireAdminAuth, requireAdminPermission('settings.ai_support'), async (_req, res) => {
    try {
      const periodDays = 30;
      const asOf = new Date();
      const since = new Date(asOf.getTime());
      since.setUTCHours(0, 0, 0, 0);
      since.setUTCDate(since.getUTCDate() - (periodDays - 1));
      const [
        customers,
        consumers,
        retainedConsumers,
        merchants,
        orders,
        paidOrders,
        repeatPaidOrders,
        unknownRegistrations,
        inquiryCount,
        inquiryDaily,
        marketingEventCounts,
        marketingEventDaily,
        marketingCampaignGroups
      ] = await Promise.all([
        prisma.customer.count({ where: { createdAt: { gte: since, lt: asOf } } }),
        prisma.consumer.count({ where: { createdAt: { gte: since, lt: asOf } } }),
        prisma.consumer.count({
          where: {
            status: 'active',
            createdAt: { lt: since },
            lastLoginAt: { gte: since, lt: asOf }
          }
        }),
        prisma.merchant.count({ where: { createdAt: { gte: since, lt: asOf } } }),
        prisma.order.count({ where: { createdAt: { gte: since, lt: asOf } } }),
        prisma.order.count({
          where: {
            createdAt: { gte: since, lt: asOf },
            paymentStatus: { in: ['paid', 'partially_refunded', 'refunded'] }
          }
        }),
        prisma.$queryRaw<Array<{ count: number }>>`
          WITH paid_orders AS (
            SELECT
              "id",
              "customerId",
              "createdAt",
              ROW_NUMBER() OVER (PARTITION BY "customerId" ORDER BY "createdAt", "id") AS "purchaseNumber"
            FROM "Order"
            WHERE "customerId" IS NOT NULL
              AND "status" <> 'cancelled'
              AND "paymentStatus" IN ('paid', 'partially_refunded', 'refunded')
          )
          SELECT COUNT(*)::INTEGER AS "count"
          FROM paid_orders
          WHERE "purchaseNumber" > 1 AND "createdAt" >= ${since} AND "createdAt" < ${asOf}
        `,
        prisma.customer.count({
          where: {
            createdAt: { gte: since, lt: asOf },
            partnerReferral: { is: null }
          }
        }),
        prisma.supportRequest.count({ where: { createdAt: { gte: since, lt: asOf } } }),
        prisma.$queryRaw<Array<{ day: string; count: number }>>`
          SELECT
            to_char(date_trunc('day', "createdAt"), 'YYYY-MM-DD') AS "day",
            COUNT(*)::INTEGER AS "count"
          FROM "SupportRequest"
          WHERE "createdAt" >= ${since} AND "createdAt" < ${asOf}
          GROUP BY date_trunc('day', "createdAt")
        `,
        prisma.growthMarketingEvent.groupBy({
          by: ['event'],
          where: { createdAt: { gte: since, lt: asOf } },
          _count: { _all: true }
        }),
        prisma.$queryRaw<Array<{ day: string; event: MarketingEventName; count: number }>>`
          SELECT
            to_char(date_trunc('day', "createdAt"), 'YYYY-MM-DD') AS "day",
            "event",
            COUNT(*)::INTEGER AS "count"
          FROM "GrowthMarketingEvent"
          WHERE "createdAt" >= ${since} AND "createdAt" < ${asOf}
          GROUP BY date_trunc('day', "createdAt"), "event"
        `,
        prisma.growthMarketingEvent.groupBy({
          by: ['source', 'medium', 'campaign'],
          where: { createdAt: { gte: since, lt: asOf } },
          _count: { _all: true }
        })
      ]);
      let referralAttribution: {
        status: 'available' | 'migration_required';
        clicks: number;
        registrations: number;
        unknownRegistrations: number;
        firstPaid: number;
        daily: Array<{ day: string; clicks: number; registrations: number; unknownRegistrations: number; firstPaid: number }>;
        breakdown: Array<{
          key: string;
          partnerCode: string;
          partnerName: string;
          campaignName: string | null;
          source: string;
          clicks: number;
          registrations: number;
          firstPaid: number;
        }>;
      } = {
        status: 'available',
        clicks: 0,
        registrations: 0,
        unknownRegistrations,
        firstPaid: 0,
        daily: [],
        breakdown: []
      };
      try {
        const [clicks, registrations, firstPaid] = await Promise.all([
          prisma.partnerReferralClick.groupBy({
            by: ['partnerId', 'campaignId', 'source'],
            where: { clickedAt: { gte: since, lt: asOf } },
            _count: { _all: true }
          }),
          prisma.partnerReferral.groupBy({
            by: ['partnerId', 'campaignId', 'source'],
            where: { registeredAt: { gte: since, lt: asOf } },
            _count: { _all: true }
          }),
          prisma.partnerReferral.groupBy({
            by: ['partnerId', 'campaignId', 'source'],
            where: { firstPaidAt: { gte: since, lt: asOf } },
            _count: { _all: true }
          })
        ]);
        const referralDaily = await prisma.$queryRaw<Array<{
          day: string;
          metric: 'clicks' | 'registrations' | 'unknownRegistrations' | 'firstPaid';
          count: number;
        }>>`
          SELECT
            "day",
            "metric",
            SUM("count")::INTEGER AS "count"
          FROM (
            SELECT
              to_char(date_trunc('day', "clickedAt"), 'YYYY-MM-DD') AS "day",
              'clicks'::TEXT AS "metric",
              COUNT(*)::INTEGER AS "count"
            FROM "PartnerReferralClick"
            WHERE "clickedAt" >= ${since} AND "clickedAt" < ${asOf}
            GROUP BY date_trunc('day', "clickedAt")
            UNION ALL
            SELECT
              to_char(date_trunc('day', "registeredAt"), 'YYYY-MM-DD') AS "day",
              'registrations'::TEXT AS "metric",
              COUNT(*)::INTEGER AS "count"
            FROM "PartnerReferral"
            WHERE "registeredAt" >= ${since} AND "registeredAt" < ${asOf}
            GROUP BY date_trunc('day', "registeredAt")
            UNION ALL
            SELECT
              to_char(date_trunc('day', "firstPaidAt"), 'YYYY-MM-DD') AS "day",
              'firstPaid'::TEXT AS "metric",
              COUNT(*)::INTEGER AS "count"
            FROM "PartnerReferral"
            WHERE "firstPaidAt" >= ${since} AND "firstPaidAt" < ${asOf}
            GROUP BY date_trunc('day', "firstPaidAt")
            UNION ALL
            SELECT
              to_char(date_trunc('day', c."createdAt"), 'YYYY-MM-DD') AS "day",
              'unknownRegistrations'::TEXT AS "metric",
              COUNT(*)::INTEGER AS "count"
            FROM "Customer" c
            WHERE c."createdAt" >= ${since} AND c."createdAt" < ${asOf}
              AND NOT EXISTS (
                SELECT 1 FROM "PartnerReferral" r WHERE r."customerId" = c."id"
              )
            GROUP BY date_trunc('day', c."createdAt")
          ) referral_daily
          GROUP BY "day", "metric"
          ORDER BY "day", "metric"
        `;
        const referralDailyByDay = new Map<string, {
          day: string;
          clicks: number;
          registrations: number;
          unknownRegistrations: number;
          firstPaid: number;
        }>();
        for (const row of referralDaily) {
          const day = referralDailyByDay.get(row.day) || {
            day: row.day,
            clicks: 0,
            registrations: 0,
            unknownRegistrations: 0,
            firstPaid: 0
          };
          day[row.metric] = row.count;
          referralDailyByDay.set(row.day, day);
        }
        referralAttribution.daily = [...referralDailyByDay.values()];
        const grouped = buildGrowthReferralBreakdown(
          clicks.map(item => ({
            partnerId: item.partnerId,
            campaignId: item.campaignId,
            source: item.source,
            count: item._count._all
          })),
          registrations.map(item => ({
            partnerId: item.partnerId,
            campaignId: item.campaignId,
            source: item.source,
            count: item._count._all
          })),
          firstPaid.map(item => ({
            partnerId: item.partnerId,
            campaignId: item.campaignId,
            source: item.source,
            count: item._count._all
          }))
        );
        referralAttribution.registrations = grouped.reduce((total, item) => total + item.registrations, 0);
        referralAttribution.firstPaid = grouped.reduce((total, item) => total + item.firstPaid, 0);
        referralAttribution.clicks = grouped.reduce((total, item) => total + item.clicks, 0);
        const [partners, campaigns] = await Promise.all([
          prisma.partner.findMany({
            where: { id: { in: [...new Set(grouped.map(item => item.partnerId))] } },
            select: { id: true, partnerCode: true, name: true }
          }),
          prisma.partnerCampaign.findMany({
            where: { id: { in: [...new Set(grouped.flatMap(item => item.campaignId ? [item.campaignId] : []))] } },
            select: { id: true, name: true }
          })
        ]);
        const partnerById = new Map(partners.map(partner => [partner.id, partner]));
        const campaignById = new Map(campaigns.map(campaign => [campaign.id, campaign]));
        referralAttribution.breakdown = grouped.slice(0, 10).map(item => {
          const partner = partnerById.get(item.partnerId);
          if (!partner) throw new Error('GROWTH_ATTRIBUTION_PARTNER_MISSING');
          return {
            key: item.key,
            partnerCode: partner.partnerCode,
            partnerName: partner.name,
            campaignName: item.campaignId ? campaignById.get(item.campaignId)?.name || null : null,
            source: item.source,
            clicks: item.clicks,
            registrations: item.registrations,
            firstPaid: item.firstPaid
          };
        });
        if (unknownRegistrations > 0) {
          referralAttribution.breakdown.push({
            key: 'unknown',
            partnerCode: 'unknown',
            partnerName: '未归属（无持久化 Referral）',
            campaignName: null,
            source: 'unknown',
            clicks: 0,
            registrations: unknownRegistrations,
            firstPaid: 0
          });
        }
      } catch (error) {
        if (error && typeof error === 'object' && 'code' in error
          && (error.code === 'P2021' || error.code === 'P2022')) {
          referralAttribution = {
            status: 'migration_required',
            clicks: 0,
            registrations: 0,
            unknownRegistrations: 0,
            firstPaid: 0,
            daily: [],
            breakdown: []
          };
          console.error('[admin-growth-overview] Partner referral schema is not deployed; attribution metrics are unavailable');
        } else {
          throw error;
        }
      }
      const eventCountByName = new Map(marketingEventCounts.map(item => [item.event, item._count._all]));
      const eventCount = (name: MarketingEventName) => eventCountByName.get(name) || 0;
      const dailyByDate = new Map<string, {
        day: string;
        pageViews: number;
        aiQuestions: number;
        inquiries: number;
        referralClicks: number;
        referralRegistrations: number;
        unknownRegistrations: number;
        referralFirstPaid: number;
      }>();
      for (let index = 0; index < periodDays; index += 1) {
        const day = new Date(asOf.getTime());
        day.setUTCHours(0, 0, 0, 0);
        day.setUTCDate(day.getUTCDate() - (periodDays - index - 1));
        const key = day.toISOString().slice(0, 10);
        dailyByDate.set(key, {
          day: key,
          pageViews: 0,
          aiQuestions: 0,
          inquiries: 0,
          referralClicks: 0,
          referralRegistrations: 0,
          unknownRegistrations: 0,
          referralFirstPaid: 0
        });
      }
      for (const item of marketingEventDaily) {
        const day = dailyByDate.get(item.day);
        if (!day) continue;
        if (item.event === 'page_view') day.pageViews += item.count;
        if (item.event === 'ai_question') day.aiQuestions += item.count;
      }
      for (const item of inquiryDaily) {
        const day = dailyByDate.get(item.day);
        if (day) day.inquiries = item.count;
      }
      const daily = mergeGrowthReferralDaily([...dailyByDate.values()], referralAttribution.daily);
      const campaignGroups = marketingCampaignGroups.map(item => ({
        source: item.source || 'direct',
        medium: item.medium || 'none',
        campaign: item.campaign,
        events: item._count._all
      }));
      const channels = publicNotificationConfig();
      res.setHeader('Cache-Control', 'no-store');
      res.json({
        success: true,
        periodDays,
        periodStart: since.toISOString(),
        periodEnd: asOf.toISOString(),
        asOf: asOf.toISOString(),
        metricDefinitions: {
          pageViews: { source: 'GrowthMarketingEvent.event=page_view + createdAt', unit: 'events', definition: '窗口内已持久化且同意分析的 page_view 事件数，不是去重访客数。' },
          aiOpens: { source: 'GrowthMarketingEvent.event=ai_open + createdAt', unit: 'events', definition: '窗口内已持久化且同意分析的 ai_open 事件数，不是去重用户数。' },
          aiQuestions: { source: 'GrowthMarketingEvent.event=ai_question + createdAt', unit: 'events', definition: '窗口内已持久化且同意分析的 ai_question 事件数，不代表线索或成交。' },
          merchantApplicationViews: { source: 'GrowthMarketingEvent.event=merchant_application_view + createdAt', unit: 'events', definition: '窗口内已持久化且同意分析的 merchant_application_view 事件数。' },
          buyerRegistrationViews: { source: 'GrowthMarketingEvent.event=buyer_registration_view + createdAt', unit: 'events', definition: '窗口内已持久化且同意分析的 buyer_registration_view 事件数。' },
          inquiries: { source: 'SupportRequest.createdAt', unit: 'records', definition: '窗口内新建的客服请求，不等于已同意营销的线索。' },
          customers: { source: 'Customer.createdAt', unit: 'records', definition: '窗口内创建的 B2B 买手账户记录。' },
          consumers: { source: 'Consumer.createdAt', unit: 'records', definition: '窗口内创建的消费者账户记录。' },
          merchants: { source: 'Merchant.createdAt', unit: 'records', definition: '窗口内创建的商家记录。' },
          orders: { source: 'Order.createdAt', unit: 'records', definition: '窗口内创建的所有订单记录，不区分订单状态。' },
          paidOrders: { source: 'Order.createdAt + Order.paymentStatus', unit: 'records', definition: '窗口内创建且当前付款状态为 paid、partially_refunded 或 refunded 的订单；包含部分或全部退款订单。' },
          repeatPaidOrders: { source: 'Order.customerId + Order.createdAt + current Order.paymentStatus', unit: 'records', definition: '窗口内创建、当前为有效已付款/已退款状态，且同一 B2B Customer 在该订单前至少有一笔有效已付款订单的订单数；不含取消订单，不是收入金额。' },
          retainedConsumers: { source: 'Consumer.createdAt + Consumer.lastLoginAt + Consumer.status', unit: 'records', definition: '窗口开始前已注册、窗口内至少登录一次且当前状态为 active 的消费者账户数；是回访账户数，不是 cohort 留存率。' },
          referralClicks: { source: 'PartnerReferralClick.clickedAt', unit: 'events', definition: '窗口内已持久化的 Partner 推广链接点击记录数，不是独立访客数。' },
          referralRegistrations: { source: 'PartnerReferral.registeredAt', unit: 'records', definition: '窗口内已持久化归属于 Partner 的 B2B 买手注册数；不包含未建立 Referral 的客户。' },
          unknownRegistrations: { source: 'Customer.createdAt + absence of PartnerReferral', unit: 'records', definition: '窗口内创建且没有持久化 PartnerReferral 记录的 B2B 买手账户数；来源显示为 unknown，不根据 Cookie、Campaign 参数或模型推断。' },
          referralFirstPaid: { source: 'PartnerReferral.firstPaidAt', unit: 'records', definition: '窗口内首次已付款且有效归属订单成功生成佣金时写入的 Referral 买手数；不等于全部付款买手或净收入。' }
        },
        metrics: {
          pageViews: eventCount('page_view'),
          aiOpens: eventCount('ai_open'),
          aiQuestions: eventCount('ai_question'),
          merchantApplicationViews: eventCount('merchant_application_view'),
          buyerRegistrationViews: eventCount('buyer_registration_view'),
          inquiries: inquiryCount,
          customers,
          consumers,
          merchants,
          orders,
          paidOrders,
          repeatPaidOrders: repeatPaidOrders[0]?.count || 0,
          retainedConsumers,
          referralClicks: referralAttribution.clicks,
          referralRegistrations: referralAttribution.registrations,
          unknownRegistrations: referralAttribution.unknownRegistrations,
          referralFirstPaid: referralAttribution.firstPaid
        },
        referralAttribution,
        daily,
        campaigns: campaignGroups.sort((left, right) => right.events - left.events).slice(0, 10),
        assistant: { enabled: aiSupportConfig.enabled, mode: 'catalog-rules' },
        notifications: {
          email: { enabled: channels.email.enabled, configured: channels.email.configured },
          sms: { enabled: channels.sms.enabled, configured: channels.sms.configured },
          whatsapp: { enabled: channels.whatsapp.enabled, configured: channels.whatsapp.configured }
        }
      });
    } catch (error) {
      if (error && typeof error === 'object' && 'code' in error && (error.code === 'P2021' || error.code === 'P2022')) {
        console.error('[admin-growth-overview] required marketing events migration is not applied');
        return res.status(503).json({ success: false, error: 'GROWTH_MARKETING_EVENTS_MIGRATION_REQUIRED' });
      }
      sendInternalError(res, error, 'admin-growth-overview');
    }
  });

  app.get('/api/admin/growth/workers', requireAdminAuth, requireAdminPermission('settings.ai_support'), async (_req, res) => {
    try {
      const [schema] = await prisma.$queryRaw<Array<{
        taskQueueReady: boolean;
        growthMissionReady: boolean;
        crmAutomationReady: boolean;
      }>>`
        SELECT
          to_regclass('public."ModaGptTask"') IS NOT NULL AS "taskQueueReady",
          to_regclass('public."GrowthMission"') IS NOT NULL AS "growthMissionReady",
          (
            to_regclass('public."GrowthCrmFollowUp"') IS NOT NULL
            AND EXISTS (
              SELECT 1 FROM information_schema.columns
              WHERE table_schema = 'public'
                AND table_name = 'GrowthCrmFollowUp'
                AND column_name = 'automationKey'
            )
          ) AS "crmAutomationReady"
      `;
      const reviewTasks = schema.taskQueueReady
        ? await prisma.modaGptTask.groupBy({
          by: ['status'],
          where: { taskType: 'growth.mission.review', tenantId: 'platform', merchantId: null },
          _count: { _all: true },
          _max: { updatedAt: true }
        })
        : [];
      const workers = buildGrowthWorkerCenter({
        growthMissionReady: schema.growthMissionReady,
        taskQueueReady: schema.taskQueueReady,
        crmAutomationReady: schema.crmAutomationReady,
        taskWorkerRuntimeStatus: modaGptWorkerRunning ? 'running' : 'stopped',
        reviewTasks: reviewTasks.map(task => ({
          status: task.status,
          count: task._count._all,
          lastUpdatedAt: task._max.updatedAt
        }))
      });
      res.setHeader('Cache-Control', 'no-store');
      res.json({ success: true, checkedAt: new Date().toISOString(), workers });
    } catch (error) {
      sendInternalError(res, error, 'admin-growth-workers');
    }
  });

  app.get('/api/admin/growth/missions', requireAdminAuth, requireAdminPermission('settings.ai_support'), async (_req, res) => {
    try {
      const missions = await prisma.growthMission.findMany({
        orderBy: { createdAt: 'desc' },
        take: 50
      });
      res.setHeader('Cache-Control', 'no-store');
      res.json({ success: true, missions: missions.map(serializeGrowthMission) });
    } catch (error) {
      if (error && typeof error === 'object' && 'code' in error && error.code === 'P2021') {
        console.error('[admin-growth-missions] required database migration is not applied');
        return res.status(503).json({ success: false, error: 'GROWTH_MISSION_MIGRATION_REQUIRED' });
      }
      sendInternalError(res, error, 'admin-growth-missions');
    }
  });

  app.post('/api/admin/growth/missions', requireAdminAuth, requireAdminPermission('settings.ai_support'), async (req: AuthRequest, res) => {
    const idempotencyKey = req.get('Idempotency-Key') || '';
    if (!/^[A-Za-z0-9._:-]{8,160}$/.test(idempotencyKey)) {
      return res.status(400).json({ success: false, error: 'GROWTH_MISSION_IDEMPOTENCY_KEY_REQUIRED' });
    }
    let input: GrowthMissionInput | null = null;
    try {
      input = validateGrowthMissionInput(req.body);
      const existing = await prisma.growthMission.findUnique({ where: { idempotencyKey } });
      if (existing) {
        const storedInput = {
          ...existing,
          budgetAmount: Number(existing.budgetAmount),
          markets: JSON.parse(existing.markets) as GrowthMarket[],
          channels: JSON.parse(existing.channels) as string[],
          startAt: existing.startAt.toISOString(),
          endAt: existing.endAt.toISOString()
        };
        if (!input || !growthMissionMatchesInput(storedInput, input)) {
          return res.status(409).json({ success: false, error: 'GROWTH_MISSION_IDEMPOTENCY_CONFLICT' });
        }
        return res.json({
          success: true,
          duplicate: true,
          mission: serializeGrowthMission(existing)
        });
      }
      const plan = buildGrowthMissionPlan(input);
      const mission = await prisma.$transaction(async tx => {
        const createdMission = await tx.growthMission.create({
          data: {
            id: crypto.randomUUID(),
            ...input,
            markets: JSON.stringify(input.markets),
            channels: JSON.stringify(input.channels),
            plan: JSON.stringify({
              version: 1,
              kind: 'deterministic_review_checklist',
              executionEnabled: false,
              steps: plan
            }),
            status: 'plan_ready',
            idempotencyKey,
            createdBy: req.admin?.username || 'admin'
          }
        });
        await logAuditAndWait(
          req.admin?.username || 'Platform SuperAdmin',
          'admin',
          'GROWTH_MISSION_PLAN_CREATED',
          'GrowthMission',
          createdMission.id,
          createdMission.name,
          JSON.stringify({ markets: input.markets, channels: input.channels, executionEnabled: false }),
          tx
        );
        return createdMission;
      });
      res.status(201).json({
        success: true,
        duplicate: false,
        mission: serializeGrowthMission(mission)
      });
    } catch (error) {
      if (error instanceof Error && error.message.startsWith('GROWTH_MISSION_')) {
        return res.status(400).json({ success: false, error: error.message });
      }
      if (error && typeof error === 'object' && 'code' in error && error.code === 'P2021') {
        console.error('[admin-growth-mission-create] required database migration is not applied');
        return res.status(503).json({ success: false, error: 'GROWTH_MISSION_MIGRATION_REQUIRED' });
      }
      if (error && typeof error === 'object' && 'code' in error && error.code === 'P2002') {
        const existing = await prisma.growthMission.findUnique({ where: { idempotencyKey } });
        if (existing) {
          const storedInput = {
            ...existing,
            budgetAmount: Number(existing.budgetAmount),
            markets: JSON.parse(existing.markets) as GrowthMarket[],
            channels: JSON.parse(existing.channels) as string[],
            startAt: existing.startAt.toISOString(),
            endAt: existing.endAt.toISOString()
          };
          if (!input || !growthMissionMatchesInput(storedInput, input)) {
            return res.status(409).json({ success: false, error: 'GROWTH_MISSION_IDEMPOTENCY_CONFLICT' });
          }
          return res.json({
            success: true,
            duplicate: true,
            mission: serializeGrowthMission(existing)
          });
        }
      }
      sendInternalError(res, error, 'admin-growth-mission-create');
    }
  });

  app.post('/api/admin/growth/missions/:id/approve-plan', requireAdminAuth, requireAdminPermission('settings.ai_support'), async (req: AuthRequest, res) => {
    const missionId = typeof req.params.id === 'string' ? req.params.id : '';
    if (!/^[A-Za-z0-9_-]{8,40}$/.test(missionId)) {
      return res.status(400).json({ success: false, error: 'GROWTH_MISSION_ID_INVALID' });
    }
    try {
      const outcome = await prisma.$transaction(async tx => {
        const updated = await tx.growthMission.updateMany({
          where: { id: missionId, status: 'plan_ready' },
          data: {
            status: 'plan_approved',
            approvedBy: req.admin?.username || 'admin',
            approvedAt: new Date()
          }
        });
        if (updated.count !== 1) {
          const mission = await tx.growthMission.findUnique({ where: { id: missionId }, select: { id: true } });
          return { error: mission ? 'GROWTH_MISSION_PLAN_NOT_REVIEWABLE' as const : 'GROWTH_MISSION_NOT_FOUND' as const };
        }
        const mission = await tx.growthMission.findUniqueOrThrow({ where: { id: missionId } });
        await logAuditAndWait(
          req.admin?.username || 'Platform SuperAdmin',
          'admin',
          'GROWTH_MISSION_PLAN_APPROVED',
          'GrowthMission',
          mission.id,
          mission.name,
          JSON.stringify({ executionEnabled: false }),
          tx
        );
        return { mission };
      });
      if ('error' in outcome) {
        return res.status(outcome.error === 'GROWTH_MISSION_NOT_FOUND' ? 404 : 409).json({
          success: false,
          error: outcome.error
        });
      }
      const mission = outcome.mission;
      res.json({
        success: true,
        mission: serializeGrowthMission(mission),
        notice: 'Plan approval is recorded; no channel task, post, message, or ad has been executed.'
      });
    } catch (error) {
      if (error && typeof error === 'object' && 'code' in error && error.code === 'P2021') {
        console.error('[admin-growth-mission-approve] required database migration is not applied');
        return res.status(503).json({ success: false, error: 'GROWTH_MISSION_MIGRATION_REQUIRED' });
      }
      sendInternalError(res, error, 'admin-growth-mission-approve');
    }
  });

  const createGrowthMissionActionLimiter = () => rateLimit({
    windowMs: 10 * 60 * 1000,
    limit: 10,
    standardHeaders: true,
    legacyHeaders: false
  });
  const growthMissionStrategyLimiter = createGrowthMissionActionLimiter();
  const growthMissionReviewTasksLimiter = createGrowthMissionActionLimiter();
  app.post('/api/admin/growth/missions/:id/strategy', growthMissionStrategyLimiter, requireAdminAuth, requireAdminPermission('settings.ai_support'), async (req: AuthRequest, res) => {
    const missionId = typeof req.params.id === 'string' ? req.params.id : '';
    if (!/^[A-Za-z0-9_-]{8,40}$/.test(missionId)) {
      return res.status(400).json({ success: false, error: 'GROWTH_MISSION_ID_INVALID' });
    }
    try {
      const mission = await prisma.growthMission.findUnique({ where: { id: missionId } });
      if (!mission) return res.status(404).json({ success: false, error: 'GROWTH_MISSION_NOT_FOUND' });
      if (mission.status !== 'plan_ready') {
        return res.status(409).json({ success: false, error: 'GROWTH_MISSION_STRATEGY_NOT_EDITABLE' });
      }
      const input = validateGrowthMissionInput({
        ...mission,
        budgetAmount: Number(mission.budgetAmount),
        markets: JSON.parse(mission.markets),
        channels: JSON.parse(mission.channels),
        startAt: mission.startAt.toISOString(),
        endAt: mission.endAt.toISOString()
      });
      const strategy = await generateGrowthMissionStrategy(input, generateAiEmployeeText);
      const plan = JSON.parse(mission.plan) as unknown;
      if (!isPlainRecord(plan) || !Array.isArray(plan.steps)) {
        console.error('[admin-growth-mission-strategy] persisted plan shape is invalid', mission.id);
        return res.status(500).json({ success: false, error: 'GROWTH_MISSION_PLAN_INVALID' });
      }
      const nextPlan = {
        ...plan,
        kind: 'ai_assisted_review_plan',
        executionEnabled: false,
        strategy
      };
      const nextPlanSerialized = JSON.stringify(nextPlan);
      const strategyOutcome = await prisma.$transaction(async tx => {
        const updated = await tx.growthMission.updateMany({
          where: { id: mission.id, status: 'plan_ready', plan: mission.plan },
          data: { plan: nextPlanSerialized }
        });
        if (updated.count !== 1) return null;
        const updatedMission = await tx.growthMission.findUniqueOrThrow({ where: { id: mission.id } });
        await logAuditAndWait(
          req.admin?.username || 'Platform SuperAdmin',
          'admin',
          'GROWTH_MISSION_AI_STRATEGY_GENERATED',
          'GrowthMission',
          mission.id,
          JSON.stringify({ strategyGenerated: Boolean((plan as Record<string, unknown>).strategy) }),
          JSON.stringify({
            source: strategy.source,
            recommendationCount: strategy.recommendations.length,
            executionEnabled: false
          }),
          tx
        );
        return updatedMission;
      });
      if (!strategyOutcome) {
        return res.status(409).json({ success: false, error: 'GROWTH_MISSION_STATE_CHANGED' });
      }
      res.json({
        success: true,
        mission: serializeGrowthMission(strategyOutcome),
        notice: 'AI recommendations are an unapproved draft; no task was queued and no channel action was executed.'
      });
    } catch (error) {
      if (error instanceof Error && error.message.startsWith('GROWTH_MISSION_')) {
        return res.status(422).json({ success: false, error: error.message });
      }
      if (error instanceof Error && error.message.startsWith('AI_EMPLOYEE_')) {
        console.error('[admin-growth-mission-strategy] AI provider failed', error.message);
        return res.status(502).json({ success: false, error: 'GROWTH_MISSION_AI_PROVIDER_FAILED' });
      }
      if (error && typeof error === 'object' && 'code' in error && error.code === 'P2021') {
        console.error('[admin-growth-mission-strategy] required database migration is not applied');
        return res.status(503).json({ success: false, error: 'GROWTH_MISSION_MIGRATION_REQUIRED' });
      }
      sendInternalError(res, error, 'admin-growth-mission-strategy');
    }
  });

  app.get('/api/admin/growth/missions/:id/review-tasks', requireAdminAuth, requireAdminPermission('settings.ai_support'), async (req: AuthRequest, res) => {
    const missionId = typeof req.params.id === 'string' ? req.params.id : '';
    if (!/^[A-Za-z0-9_-]{8,40}$/.test(missionId)) {
      return res.status(400).json({ success: false, error: 'GROWTH_MISSION_ID_INVALID' });
    }
    try {
      const mission = await prisma.growthMission.findUnique({
        where: { id: missionId },
        select: { id: true, plan: true }
      });
      if (!mission) return res.status(404).json({ success: false, error: 'GROWTH_MISSION_NOT_FOUND' });
      const plan: unknown = JSON.parse(mission.plan);
      if (!isPlainRecord(plan) || !isPlainRecord(plan.strategy)) {
        return res.json({ success: true, tasks: [] });
      }
      const strategy = plan.strategy;
      if (!Array.isArray(strategy.recommendations)) return res.json({ success: true, tasks: [] });
      const candidates = await Promise.all(strategy.recommendations.map((_, recommendationIndex) =>
        prisma.modaGptTask.findFirst({
          where: {
            taskType: 'growth.mission.review',
            tenantId: 'platform',
            merchantId: null,
            payload: JSON.stringify({ version: 1, missionId: mission.id, recommendationIndex })
          },
          orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
          select: { id: true, status: true, payload: true, result: true, createdAt: true, lastErrorCode: true }
        })
      ));
      const tasks = candidates.flatMap(task => {
        const payload: unknown = JSON.parse(task.payload);
        if (!isPlainRecord(payload) || payload.version !== 1 || payload.missionId !== mission.id
          || !Number.isInteger(payload.recommendationIndex)) {
          throw new Error('GROWTH_MISSION_REVIEW_TASK_PAYLOAD_INVALID');
        }
        const recommendationIndex = Number(payload.recommendationIndex);
        const recommendation = strategy.recommendations[recommendationIndex];
        if (!recommendation) throw new Error('GROWTH_MISSION_REVIEW_RECOMMENDATION_NOT_FOUND');
        const result: unknown = task.result ? JSON.parse(task.result) : null;
        if (result !== null && !isPlainRecord(result)) {
          throw new Error('GROWTH_MISSION_REVIEW_TASK_RESULT_INVALID');
        }
        const decision = readGrowthMissionReviewDecisionMetadata(result);
        return [{
          id: task.id,
          status: task.status,
          resultStatus: isPlainRecord(result) && typeof result.status === 'string' ? result.status : null,
          ...decision,
          recommendationIndex,
          recommendation,
          createdAt: task.createdAt,
          lastErrorCode: task.lastErrorCode
        }];
      });
      res.setHeader('Cache-Control', 'no-store');
      res.json({ success: true, tasks });
    } catch (error) {
      if (error && typeof error === 'object' && 'code' in error && error.code === 'P2021') {
        console.error('[admin-growth-mission-review-tasks-list] required database migration is not applied');
        return res.status(503).json({ success: false, error: 'GROWTH_MISSION_MIGRATION_REQUIRED' });
      }
      sendInternalError(res, error, 'admin-growth-mission-review-tasks-list');
    }
  });

  app.post('/api/admin/growth/missions/:id/review-tasks', growthMissionReviewTasksLimiter, requireAdminAuth, requireAdminPermission('settings.ai_support'), async (req: AuthRequest, res) => {
    const missionId = typeof req.params.id === 'string' ? req.params.id : '';
    if (!/^[A-Za-z0-9_-]{8,40}$/.test(missionId)) {
      return res.status(400).json({ success: false, error: 'GROWTH_MISSION_ID_INVALID' });
    }
    try {
      const outcome = await prisma.$transaction(async tx => {
        await tx.$queryRaw`SELECT "id" FROM "GrowthMission" WHERE "id" = ${missionId} FOR UPDATE`;
        const mission = await tx.growthMission.findUnique({ where: { id: missionId } });
        if (!mission) return { error: 'GROWTH_MISSION_NOT_FOUND' as const };
        if (mission.status !== 'plan_approved') return { error: 'GROWTH_MISSION_NOT_APPROVED' as const };
        const input = validateGrowthMissionInput({
          ...mission,
          budgetAmount: Number(mission.budgetAmount),
          markets: JSON.parse(mission.markets),
          channels: JSON.parse(mission.channels),
          startAt: mission.startAt.toISOString(),
          endAt: mission.endAt.toISOString()
        });
        const plan: unknown = JSON.parse(mission.plan);
        if (!isPlainRecord(plan) || !isPlainRecord(plan.strategy)
          || plan.strategy.source !== 'ai_draft'
          || plan.strategy.executionEnabled !== false
          || !Array.isArray(plan.strategy.recommendations)) {
          return { error: 'GROWTH_MISSION_AI_STRATEGY_REQUIRED' as const };
        }
        const recommendations = parseGrowthMissionRecommendations(
          JSON.stringify({ recommendations: plan.strategy.recommendations }),
          input
        );
        const queueInputs = [];
        for (let index = 0; index < recommendations.length; index += 1) {
          const previousTask = await tx.modaGptTask.findFirst({
            where: {
              taskType: 'growth.mission.review',
              tenantId: 'platform',
              merchantId: null,
              payload: JSON.stringify({ version: 1, missionId: mission.id, recommendationIndex: index })
            },
            orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
            select: { status: true, context: true, result: true }
          });
          queueInputs.push({
            missionId: mission.id,
            recommendationIndex: index,
            reviewRound: getNextGrowthMissionReviewRound(previousTask)
          });
        }
        const batch = await PrismaModaGptTaskStore.enqueueGrowthMissionReviewBatch(tx, queueInputs);
        await logAuditAndWait(
          req.admin?.username || 'Platform SuperAdmin',
          'admin',
          'GROWTH_MISSION_REVIEW_TASKS_QUEUED',
          'GrowthMission',
          mission.id,
          '',
          JSON.stringify({
            taskCount: batch.tasks.length,
            createdCount: batch.createdCount,
            deduplicatedCount: batch.tasks.length - batch.createdCount,
            taskIds: batch.tasks.map(task => task.id),
            externalExecution: false
          }),
          tx
        );
        return { missionId: mission.id, recommendations, tasks: batch.tasks };
      });
      if ('error' in outcome) {
        if (outcome.error === 'GROWTH_MISSION_NOT_FOUND') {
          return res.status(404).json({ success: false, error: outcome.error });
        }
        return res.status(409).json({ success: false, error: outcome.error });
      }
      res.status(202).json({
        success: true,
        missionId: outcome.missionId,
        tasks: outcome.tasks.map((task, recommendationIndex) => ({
          ...task,
          recommendationIndex,
          recommendation: outcome.recommendations[recommendationIndex]
        })),
        notice: 'Internal review tasks were queued. They do not publish, message, spend budget, or call channel connectors.'
      });
    } catch (error) {
      if (error instanceof Error && error.message.startsWith('GROWTH_MISSION_')) {
        return res.status(422).json({ success: false, error: error.message });
      }
      if (error instanceof Error && error.message.startsWith('MODAGPT_')) {
        console.error('[admin-growth-mission-review-tasks] queue rejected task', error.message);
        return res.status(503).json({ success: false, error: 'GROWTH_MISSION_REVIEW_QUEUE_FAILED' });
      }
      if (error && typeof error === 'object' && 'code' in error && error.code === 'P2021') {
        console.error('[admin-growth-mission-review-tasks] required database migration is not applied');
        return res.status(503).json({ success: false, error: 'GROWTH_MISSION_MIGRATION_REQUIRED' });
      }
      sendInternalError(res, error, 'admin-growth-mission-review-tasks');
    }
  });

  app.post('/api/admin/growth/missions/:missionId/review-tasks/:taskId/decision', requireAdminAuth, requireAdminPermission('settings.ai_support'), async (req: AuthRequest, res) => {
    const missionId = typeof req.params.missionId === 'string' ? req.params.missionId : '';
    const taskId = typeof req.params.taskId === 'string' ? req.params.taskId : '';
    const decision = req.body && typeof req.body === 'object' && !Array.isArray(req.body)
      ? (req.body as Record<string, unknown>).decision
      : null;
    if (!/^[A-Za-z0-9_-]{8,40}$/.test(missionId) || !/^[A-Za-z0-9_-]{8,40}$/.test(taskId)) {
      return res.status(400).json({ success: false, error: 'GROWTH_MISSION_REVIEW_TASK_ID_INVALID' });
    }
    if (decision !== 'accept' && decision !== 'return') {
      return res.status(400).json({ success: false, error: 'GROWTH_MISSION_REVIEW_DECISION_INVALID' });
    }
    try {
      const task = await prisma.modaGptTask.findFirst({
        where: {
          id: taskId,
          taskType: 'growth.mission.review',
          tenantId: 'platform',
          merchantId: null,
          status: 'waiting_approval',
          payload: { contains: `"missionId":"${missionId}"` }
        },
        select: { id: true, payload: true, result: true }
      });
      if (!task) {
        const exists = await prisma.modaGptTask.findFirst({
          where: { id: taskId, taskType: 'growth.mission.review', tenantId: 'platform', merchantId: null },
          select: { id: true, status: true }
        });
        return res.status(exists ? 409 : 404).json({
          success: false,
          error: exists ? 'GROWTH_MISSION_REVIEW_TASK_NOT_REVIEWABLE' : 'GROWTH_MISSION_REVIEW_TASK_NOT_FOUND'
        });
      }
      const payload: unknown = JSON.parse(task.payload);
      const result: unknown = task.result ? JSON.parse(task.result) : null;
      if (!isPlainRecord(payload) || payload.version !== 1 || payload.missionId !== missionId
        || !Number.isInteger(payload.recommendationIndex) || !isPlainRecord(result)
        || result.approvalRequired !== true || result.externalExecution !== false) {
        console.error('[admin-growth-mission-review-decision] persisted review task shape invalid', task.id);
        return res.status(409).json({ success: false, error: 'GROWTH_MISSION_REVIEW_TASK_INVALID' });
      }
      const nextStatus = decision === 'accept' ? 'completed' : 'cancelled';
      const decisionResult = {
        ...result,
        approvalRequired: false,
        externalExecution: false,
        humanDecision: decision === 'accept' ? 'accepted_for_internal_planning' : 'returned_for_revision',
        decidedBy: req.admin?.username || 'admin',
        decidedAt: new Date().toISOString()
      };
      const decisionOutcome = await prisma.$transaction(async tx => {
        await tx.$queryRaw`SELECT "id" FROM "GrowthMission" WHERE "id" = ${missionId} FOR UPDATE`;
        const mission = await tx.growthMission.findUnique({ where: { id: missionId }, select: { status: true } });
        if (!mission) return { updated: false, error: 'GROWTH_MISSION_NOT_FOUND' as const };
        if (decision === 'accept' && mission.status !== 'plan_approved') {
          return { updated: false, error: 'GROWTH_MISSION_NOT_APPROVED' as const };
        }
        const updated = await tx.modaGptTask.updateMany({
          where: { id: task.id, status: 'waiting_approval' },
          data: {
            status: nextStatus,
            result: JSON.stringify(decisionResult),
            completedAt: new Date()
          }
        });
        if (updated.count === 1) {
          await logAuditAndWait(
            req.admin?.username || 'Platform SuperAdmin',
            'admin',
            decision === 'accept' ? 'GROWTH_MISSION_REVIEW_ACCEPTED' : 'GROWTH_MISSION_REVIEW_RETURNED',
            'ModaGptTask',
            task.id,
            JSON.stringify({ missionId, status: 'waiting_approval' }),
            JSON.stringify({ status: nextStatus, humanDecision: decisionResult.humanDecision, externalExecution: false }),
            tx
          );
        }
        return { updated: updated.count === 1, error: null };
      });
      if (decisionOutcome.error === 'GROWTH_MISSION_NOT_FOUND') {
        return res.status(404).json({ success: false, error: decisionOutcome.error });
      }
      if (decisionOutcome.error === 'GROWTH_MISSION_NOT_APPROVED') {
        return res.status(409).json({ success: false, error: decisionOutcome.error });
      }
      if (!decisionOutcome.updated) {
        return res.status(409).json({ success: false, error: 'GROWTH_MISSION_REVIEW_TASK_ALREADY_DECIDED' });
      }
      return res.json({
        success: true,
        taskId: task.id,
        status: nextStatus,
        humanDecision: decisionResult.humanDecision,
        notice: 'Decision recorded for internal planning only; no channel action was authorized or executed.'
      });
    } catch (error) {
      if (error && typeof error === 'object' && 'code' in error && error.code === 'P2021') {
        console.error('[admin-growth-mission-review-decision] required database migration is not applied');
        return res.status(503).json({ success: false, error: 'GROWTH_MISSION_MIGRATION_REQUIRED' });
      }
      sendInternalError(res, error, 'admin-growth-mission-review-decision');
    }
  });

  app.post('/api/admin/growth/missions/:id/lifecycle', requireAdminAuth, requireAdminPermission('settings.ai_support'), async (req: AuthRequest, res) => {
    const missionId = typeof req.params.id === 'string' ? req.params.id : '';
    if (!/^[A-Za-z0-9_-]{8,40}$/.test(missionId)) {
      return res.status(400).json({ success: false, error: 'GROWTH_MISSION_ID_INVALID' });
    }
    const action = req.body && typeof req.body === 'object' && !Array.isArray(req.body)
      ? (req.body as Record<string, unknown>).action
      : null;
    if (!isGrowthMissionAction(action)) {
      return res.status(400).json({ success: false, error: 'GROWTH_MISSION_ACTION_INVALID' });
    }
    try {
      const outcome = await prisma.$transaction(async tx => {
        await tx.$queryRaw`SELECT "id" FROM "GrowthMission" WHERE "id" = ${missionId} FOR UPDATE`;
        const mission = await tx.growthMission.findUnique({
          where: { id: missionId },
          select: { id: true, name: true, status: true }
        });
        if (!mission) return { error: 'GROWTH_MISSION_NOT_FOUND' as const };
        if (!isGrowthMissionStatus(mission.status)) {
          throw new Error('GROWTH_MISSION_STATUS_INVALID');
        }
        let nextStatus: ReturnType<typeof transitionGrowthMissionStatus>;
        try {
          nextStatus = transitionGrowthMissionStatus(mission.status, action);
        } catch (error) {
          if (error instanceof Error && error.message === 'GROWTH_MISSION_TRANSITION_INVALID') {
            return { error: 'GROWTH_MISSION_TRANSITION_INVALID' as const };
          }
          throw error;
        }
        const updated = await tx.growthMission.updateMany({
          where: { id: mission.id, status: mission.status },
          data: { status: nextStatus }
        });
        if (updated.count !== 1) return { error: 'GROWTH_MISSION_STATE_CHANGED' as const };
        const reviewTaskChanges = action === 'pause'
          ? {
            stopped: await PrismaModaGptTaskStore.pauseGrowthMissionReviewTasks(tx, mission.id),
            resumed: 0
          }
          : action === 'cancel'
            ? {
              stopped: await PrismaModaGptTaskStore.cancelGrowthMissionReviewTasks(tx, mission.id),
              resumed: 0
            }
            : {
              stopped: 0,
              resumed: await PrismaModaGptTaskStore.resumeGrowthMissionReviewTasks(tx, mission.id)
            };
        const updatedMission = await tx.growthMission.findUniqueOrThrow({ where: { id: mission.id } });
        await logAuditAndWait(
          req.admin?.username || 'Platform SuperAdmin',
          'admin',
          `GROWTH_MISSION_${action === 'cancel' ? 'CANCELLED' : action === 'pause' ? 'PAUSED' : 'RESUMED'}`,
          'GrowthMission',
          mission.id,
          JSON.stringify({ status: mission.status }),
          JSON.stringify({
            status: nextStatus,
            executionEnabled: false,
            stoppedReviewTasks: reviewTaskChanges.stopped,
            resumedReviewTasks: reviewTaskChanges.resumed
          }),
          tx
        );
        return { mission, nextStatus, updatedMission, reviewTaskChanges };
      });
      if ('error' in outcome) {
        if (outcome.error === 'GROWTH_MISSION_NOT_FOUND') {
          return res.status(404).json({ success: false, error: outcome.error });
        }
        if (outcome.error === 'GROWTH_MISSION_TRANSITION_INVALID') {
          return res.status(409).json({ success: false, error: outcome.error });
        }
        return res.status(409).json({ success: false, error: outcome.error });
      }
      res.json({
        success: true,
        mission: serializeGrowthMission(outcome.updatedMission),
        cancelledReviewTasks: outcome.reviewTaskChanges.stopped,
        resumedReviewTasks: outcome.reviewTaskChanges.resumed,
        notice: 'Mission status updated; no channel task, post, message, or ad was executed.'
      });
    } catch (error) {
      if (error && typeof error === 'object' && 'code' in error && error.code === 'P2021') {
        console.error('[admin-growth-mission-lifecycle] required database migration is not applied');
        return res.status(503).json({ success: false, error: 'GROWTH_MISSION_MIGRATION_REQUIRED' });
      }
      sendInternalError(res, error, 'admin-growth-mission-lifecycle');
    }
  });

