  app.get('/api/admin/growth/meta/connect', requireAdminAuth, requireAdminPermission('settings.integrations'), metaOAuthLimiter, (req: AuthRequest, res) => {
    try {
      const { appId, appSecret, loginConfigId } = getMetaAppCredentials();
      if (!appId || !appSecret || !loginConfigId) return res.status(409).json({ success: false, error: 'META_APP_NOT_CONFIGURED' });
      const now = Date.now();
      for (const [state, value] of metaOAuthStates) {
        if (value.expiresAt <= now) metaOAuthStates.delete(state);
      }
      if (metaOAuthStates.size >= 500) return sendRateLimitError(res, 'META_OAUTH_BUSY', undefined, true);
      const state = crypto.randomBytes(32).toString('base64url');
      metaOAuthStates.set(state, { adminUsername: req.admin?.username || '', expiresAt: now + 10 * 60 * 1000 });

      const redirectUri = getMetaRedirectUri(req);
      const authorizationUrl = new URL(`https://www.facebook.com/${getMetaGraphVersion()}/dialog/oauth`);
      authorizationUrl.searchParams.set('client_id', appId);
      authorizationUrl.searchParams.set('redirect_uri', redirectUri);
      authorizationUrl.searchParams.set('response_type', 'code');
      authorizationUrl.searchParams.set('config_id', loginConfigId);
      authorizationUrl.searchParams.set('state', state);
      res.redirect(302, authorizationUrl.toString());
    } catch (error) {
      sendInternalError(res, error, 'admin-meta-oauth-start');
    }
  });

  app.get('/api/admin/growth/meta/callback', requireAdminAuth, requireAdminPermission('settings.integrations'), metaOAuthLimiter, async (req: AuthRequest, res) => {
    const redirectToAdmin = (result: 'connected' | 'denied' | 'invalid_state' | 'failed') => {
      const baseUrl = process.env.APP_URL || `${req.protocol}://${req.get('host')}`;
      const url = new URL('/admin', baseUrl);
      url.searchParams.set('meta_oauth', result);
      return res.redirect(303, url.toString());
    };
    const state = typeof req.query.state === 'string' ? req.query.state : '';
    const pendingState = metaOAuthStates.get(state);
    metaOAuthStates.delete(state);
    if (!pendingState || pendingState.expiresAt <= Date.now() || pendingState.adminUsername !== (req.admin?.username || '')) {
      return redirectToAdmin('invalid_state');
    }
    if (typeof req.query.error === 'string') return redirectToAdmin('denied');
    const code = typeof req.query.code === 'string' ? req.query.code : '';
    if (!code) return redirectToAdmin('failed');

    try {
      const { appId, appSecret, loginConfigId } = getMetaAppCredentials();
      if (!appId || !appSecret || !loginConfigId) return redirectToAdmin('failed');
      const redirectUri = getMetaRedirectUri(req);
      const version = getMetaGraphVersion();
      const exchangeUrl = new URL(`https://graph.facebook.com/${version}/oauth/access_token`);
      exchangeUrl.searchParams.set('client_id', appId);
      exchangeUrl.searchParams.set('client_secret', appSecret);
      exchangeUrl.searchParams.set('redirect_uri', redirectUri);
      exchangeUrl.searchParams.set('code', code);
      const shortTokenResponse = await fetch(exchangeUrl);
      const shortTokenData = await shortTokenResponse.json() as { access_token?: string; error?: { code?: number } };
      if (!shortTokenResponse.ok || !shortTokenData.access_token) {
        console.error('[meta-oauth] authorization code exchange failed', shortTokenData.error?.code || shortTokenResponse.status);
        return redirectToAdmin('failed');
      }

      const longTokenUrl = new URL(`https://graph.facebook.com/${version}/oauth/access_token`);
      longTokenUrl.searchParams.set('grant_type', 'fb_exchange_token');
      longTokenUrl.searchParams.set('client_id', appId);
      longTokenUrl.searchParams.set('client_secret', appSecret);
      longTokenUrl.searchParams.set('fb_exchange_token', shortTokenData.access_token);
      const longTokenResponse = await fetch(longTokenUrl);
      const longTokenData = await longTokenResponse.json() as { access_token?: string; expires_in?: number; error?: { code?: number } };
      if (!longTokenResponse.ok || !longTokenData.access_token) {
        console.error('[meta-oauth] long-lived token exchange failed', longTokenData.error?.code || longTokenResponse.status);
        return redirectToAdmin('failed');
      }

      const pagesUrl = new URL(`https://graph.facebook.com/${version}/me/accounts`);
      pagesUrl.searchParams.set('fields', 'id,name,tasks,access_token,instagram_business_account{id,username}');
      pagesUrl.searchParams.set('limit', '100');
      pagesUrl.searchParams.set('access_token', longTokenData.access_token);
      const pagesResponse = await fetch(pagesUrl);
      const pagesData = await pagesResponse.json() as {
        data?: Array<{
          id?: string;
          name?: string;
          tasks?: string[];
          access_token?: string;
          instagram_business_account?: { id?: string; username?: string };
        }>;
        error?: { code?: number };
      };
      if (!pagesResponse.ok || !Array.isArray(pagesData.data)) {
        console.error('[meta-oauth] page discovery failed', pagesData.error?.code || pagesResponse.status);
        return redirectToAdmin('failed');
      }
      const connectedAt = new Date().toISOString();
      const instagramUserTokenExpiresAt = new Date(Date.now() + Math.max(1, Number(longTokenData.expires_in) || 60 * 24 * 60 * 60) * 1000).toISOString();
      const publishingPages = pagesData.data
        .filter(page =>
          typeof page.id === 'string' && typeof page.name === 'string' &&
          typeof page.access_token === 'string' && hasMetaPublishingTask(page.tasks)
        )
        .slice(0, 50)
        .map(page => ({
          id: page.id!,
          name: page.name!,
          accessTokenEncrypted: encryptSecret(page.access_token!),
          instagramUserTokenEncrypted: page.instagram_business_account?.id ? encryptSecret(longTokenData.access_token!) : null,
          instagramUserTokenExpiresAt: page.instagram_business_account?.id ? instagramUserTokenExpiresAt : null,
          tasks: page.tasks!,
          instagramAccount: typeof page.instagram_business_account?.id === 'string'
            ? { id: page.instagram_business_account.id, username: page.instagram_business_account.username || '' }
            : null,
          connectedAt
        }));
      if (publishingPages.length === 0) {
        console.warn('[meta-oauth] no authorized Pages with publishing tasks were returned');
        return redirectToAdmin('failed');
      }

      const previousPages = integrationConfig.facebook.publishingPages;
      integrationConfig.facebook.publishingPages = publishingPages;
      try {
        await saveIntegrationConfig();
      } catch (error) {
        integrationConfig.facebook.publishingPages = previousPages;
        throw error;
      }
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'META_PUBLISHING_CONNECTED', 'MetaPages', 'all', '', `${publishingPages.length} page(s)`);
      return redirectToAdmin('connected');
    } catch (error) {
      console.error('[meta-oauth] callback failed', error instanceof Error ? error.name : 'unknown error');
      return redirectToAdmin('failed');
    }
  });

  app.post('/api/admin/growth/meta/disconnect', requireAdminAuth, requireAdminPermission('settings.integrations'), async (req: AuthRequest, res) => {
    const pageId = typeof req.body?.pageId === 'string' ? req.body.pageId : '';
    if (!pageId) return res.status(400).json({ success: false, error: 'META_PAGE_ID_REQUIRED' });
    const pageIndex = integrationConfig.facebook.publishingPages.findIndex(page => page.id === pageId);
    if (pageIndex < 0) return res.status(404).json({ success: false, error: 'META_PAGE_NOT_FOUND' });
    const [removedPage] = integrationConfig.facebook.publishingPages.splice(pageIndex, 1);
    try {
      await saveIntegrationConfig();
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'META_PUBLISHING_DISCONNECTED', 'MetaPage', pageId, removedPage.name, 'disconnected');
      res.json({ success: true, pages: publicMetaPublishingPages() });
    } catch (error) {
      integrationConfig.facebook.publishingPages.splice(pageIndex, 0, removedPage);
      sendInternalError(res, error, 'admin-meta-disconnect');
    }
  });

  app.get('/api/admin/growth/campaigns', requireAdminAuth, requireAdminPermission('settings.ai_support'), (_req, res) => {
    res.json({ success: true, campaigns: [...marketingCampaigns].sort((left, right) => right.updatedAt.localeCompare(left.updatedAt)) });
  });

  app.post('/api/admin/growth/campaigns', requireAdminAuth, requireAdminPermission('settings.ai_support'), async (req: AuthRequest, res) => {
    const body = req.body || {};
    const name = typeof body.name === 'string' ? body.name.trim().slice(0, 100) : '';
    const objective = typeof body.objective === 'string' ? body.objective.trim().slice(0, 300) : '';
    const landingPath = typeof body.landingPath === 'string' ? body.landingPath : '';
    const instagramImageUrl = typeof body.instagramImageUrl === 'string' && body.instagramImageUrl.trim()
      ? body.instagramImageUrl.trim()
      : null;
    const rawChannels: unknown[] = Array.isArray(body.channels) ? body.channels : [];
    const channels = [...new Set(rawChannels.filter((channel: unknown): channel is MarketingChannel => typeof channel === 'string' && marketingChannels.includes(channel as MarketingChannel)))];
    const rawCopies = body.copies && typeof body.copies === 'object' && !Array.isArray(body.copies) ? body.copies : {};
    const copies: Partial<Record<MarketingChannel, string>> = {};
    for (const channel of channels) {
      const copy = rawCopies[channel];
      if (typeof copy === 'string' && copy.trim()) copies[channel] = copy.trim().slice(0, 5000);
    }
    if (!name || !channels.length || channels.length !== rawChannels.length || !['/', '/catalog', '/showrooms'].includes(landingPath)) {
      return res.status(400).json({ success: false, error: 'MARKETING_CAMPAIGN_FIELDS_INVALID' });
    }
    if (instagramImageUrl && !isPublicHttpsMediaUrl(instagramImageUrl)) {
      return res.status(400).json({ success: false, error: 'MARKETING_INSTAGRAM_IMAGE_URL_INVALID' });
    }
    if (Object.keys(copies).length === 0) return res.status(400).json({ success: false, error: 'MARKETING_CAMPAIGN_COPY_REQUIRED' });
    if (marketingCampaigns.length >= 200) return res.status(409).json({ success: false, error: 'MARKETING_CAMPAIGN_LIMIT_REACHED' });
    const now = new Date().toISOString();
    const campaign: MarketingCampaign = {
      id: crypto.randomUUID(),
      name,
      objective,
      channels,
      landingPath,
      copies,
      instagramImageUrl,
      publications: [],
      status: 'draft',
      createdAt: now,
      updatedAt: now,
      approvedAt: null
    };
    marketingCampaigns.push(campaign);
    try {
      await persistMarketingCampaigns();
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'MARKETING_CAMPAIGN_CREATED', 'MarketingCampaign', campaign.id, '', name);
      res.status(201).json({ success: true, campaign });
    } catch (error) {
      marketingCampaigns.splice(marketingCampaigns.findIndex(item => item.id === campaign.id), 1);
      sendInternalError(res, error, 'admin-marketing-campaign-create');
    }
  });

  app.put('/api/admin/growth/campaigns/:id', requireAdminAuth, requireAdminPermission('settings.ai_support'), async (req: AuthRequest, res) => {
    const campaign = marketingCampaigns.find(item => item.id === req.params.id);
    if (!campaign) return res.status(404).json({ success: false, error: 'MARKETING_CAMPAIGN_NOT_FOUND' });
    const requestedStatus = req.body?.status;
    if (requestedStatus !== 'draft' && requestedStatus !== 'approved') {
      return res.status(400).json({ success: false, error: 'MARKETING_CAMPAIGN_STATUS_INVALID' });
    }
    const previousStatus = campaign.status;
    const previousApprovedAt = campaign.approvedAt;
    const previousUpdatedAt = campaign.updatedAt;
    campaign.status = requestedStatus;
    campaign.approvedAt = requestedStatus === 'approved' ? new Date().toISOString() : null;
    campaign.updatedAt = new Date().toISOString();
    try {
      await persistMarketingCampaigns();
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', requestedStatus === 'approved' ? 'MARKETING_CAMPAIGN_APPROVED' : 'MARKETING_CAMPAIGN_REOPENED', 'MarketingCampaign', campaign.id, previousStatus, requestedStatus);
      res.json({ success: true, campaign });
    } catch (error) {
      campaign.status = previousStatus;
      campaign.approvedAt = previousApprovedAt;
      campaign.updatedAt = previousUpdatedAt;
      sendInternalError(res, error, 'admin-marketing-campaign-update');
    }
  });

  function runMerchantTenantMiddleware(req: express.Request, res: express.Response, next: express.NextFunction) {
    const stack = requireMerchantTenant as express.RequestHandler[];
    let index = 0;
    const run = (error?: unknown) => {
      if (error) return next(error);
      const middleware = stack[index++];
      if (middleware) return middleware(req, res, run);
      next();
    };
    run();
  }

  const supplierProductUpload = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: 8 * 1024 * 1024, files: 1, fields: 0, parts: 1 },
    fileFilter: (_req, file, callback) => {
      if (!detectSupplierSourceType(file.originalname, file.mimetype)) {
        callback(new Error('AI_EMPLOYEE_IMPORT_FILE_TYPE_INVALID'));
        return;
      }
      callback(null, true);
    }
  }).single('file');
  const parseSupplierProductUpload: express.RequestHandler = (req, res, next) => {
    supplierProductUpload(req, res, error => {
      if (!error) {
        next();
        return;
      }
      if (error instanceof multer.MulterError) {
        const tooLarge = error.code === 'LIMIT_FILE_SIZE';
        res.status(tooLarge ? 413 : 400).json({
          success: false,
          error: tooLarge ? 'AI_EMPLOYEE_IMPORT_FILE_TOO_LARGE' : 'AI_EMPLOYEE_IMPORT_UPLOAD_INVALID'
        });
        return;
      }
      if (error instanceof Error && error.message === 'AI_EMPLOYEE_IMPORT_FILE_TYPE_INVALID') {
        res.status(400).json({ success: false, error: error.message });
        return;
      }
      sendInternalError(res, error, 'merchant-ai-employee-product-import-upload');
    });
  };

  app.post(
    '/api/merchant/ai-employees/:id/tools/product-import',
    runMerchantTenantMiddleware,
    requireEmployeePermission('employees.manage'),
    parseSupplierProductUpload,
    async (req: AuthRequest, res) => {
      const file = req.file;
      if (!file) return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_IMPORT_FILE_REQUIRED' });
      const sourceType = detectSupplierSourceType(file.originalname, file.mimetype);
      if (!sourceType) return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_IMPORT_FILE_TYPE_INVALID' });

      try {
        let sourceBuffer = file.buffer;
        if (sourceType === 'image') {
          const image = sharp(file.buffer, { limitInputPixels: 25_000_000 });
          const metadata = await image.metadata();
          if (!metadata.format || !['jpeg', 'png', 'webp'].includes(metadata.format)) {
            return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_IMPORT_IMAGE_INVALID' });
          }
          sourceBuffer = await image.rotate().resize({
            width: 1600,
            height: 1600,
            fit: 'inside',
            withoutEnlargement: true
          }).jpeg({ quality: 82 }).toBuffer();
        } else if (sourceType === 'pdf' && !file.buffer.subarray(0, 5).equals(Buffer.from('%PDF-'))) {
          return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_IMPORT_PDF_INVALID' });
        } else if (sourceType === 'xlsx' && !file.buffer.subarray(0, 2).equals(Buffer.from('PK'))) {
          return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_IMPORT_XLSX_INVALID' });
        }

        const candidates = await extractSupplierProductCandidates(sourceType, sourceBuffer);
        const merchantId = req.merchant!.merchantId;
        const installationId = req.params.id;
        const filename = path.basename(file.originalname).replace(/[\u0000-\u001f\u007f]/g, '').slice(0, 255) || 'supplier-catalog';
        const savedDrafts = await prisma.$transaction(async tx => {
          const installation = await tx.merchantAiEmployeeInstallation.findFirst({
            where: { id: installationId, merchantId },
            include: { definition: { select: { slug: true, status: true } } }
          });
          if (!installation || !canUseAiEmployeeProductImport({
            employeeSlug: installation.definition.slug,
            employeeStatus: installation.definition.status,
            installationStatus: installation.status,
            grantedPermissions: parseStoredJson<unknown>(installation.grantedPermissions, [])
          })) return null;

          const drafts = [];
          for (const candidate of candidates) {
            drafts.push(await tx.aiEmployeeProductImportDraft.create({
              data: {
                merchantId,
                installationId,
                sourceFilename: filename,
                sourceType,
                extractedData: JSON.stringify(candidate)
              }
            }));
          }
          await tx.employeeAuditLog.create({
            data: {
              id: crypto.randomUUID(),
              merchantId,
              employeeId: req.merchant!.employeeId || null,
              action: 'AI_EMPLOYEE_PRODUCT_IMPORT_EXTRACTED',
              entityType: 'AiEmployeeProductImportDraft',
              metadata: JSON.stringify({ sourceType, candidateCount: drafts.length }),
              ipAddress: getClientIp(req)
            }
          });
          return drafts;
        });
        if (!savedDrafts) return sendAccessDenied(res, 'AI_EMPLOYEE_IMPORT_PERMISSION_REQUIRED');
        res.setHeader('Cache-Control', 'no-store');
        res.status(201).json({
          success: true,
          drafts: savedDrafts.map(draft => ({
            id: draft.id,
            sourceFilename: draft.sourceFilename,
            sourceType: draft.sourceType,
            candidate: JSON.parse(draft.extractedData),
            status: draft.status,
            createdAt: draft.createdAt
          }))
        });
      } catch (error) {
        const errorCode = error instanceof Error ? error.message : '';
        if (errorCode.startsWith('AI_EMPLOYEE_IMPORT_')) {
          console.error('[merchant-ai-employee-product-import]', errorCode);
          const statusCode = errorCode.includes('MODEL') ? 503
            : errorCode.includes('EXTRACTION') || errorCode.includes('NO_PRODUCTS') ? 502
              : 400;
          return res.status(statusCode).json({ success: false, error: errorCode });
        }
        console.error('[merchant-ai-employee-product-import]', error instanceof Error ? error.name : 'unknown error');
        res.status(503).json({ success: false, error: 'AI_EMPLOYEE_IMPORT_MODEL_UNAVAILABLE' });
      }
    }
  );

  app.get(
    '/api/merchant/ai-employees/:id/tools/product-import-drafts',
    runMerchantTenantMiddleware,
    requireEmployeePermission('employees.manage'),
    async (req: AuthRequest, res) => {
      try {
        const merchantId = req.merchant!.merchantId;
        const installation = await prisma.merchantAiEmployeeInstallation.findFirst({
          where: { id: req.params.id, merchantId },
          include: { definition: { select: { slug: true, status: true } } }
        });
        if (!installation) return res.status(404).json({ success: false, error: 'AI_EMPLOYEE_INSTALLATION_NOT_FOUND' });
        if (!canUseAiEmployeeProductImport({
          employeeSlug: installation.definition.slug,
          employeeStatus: installation.definition.status,
          installationStatus: installation.status,
          grantedPermissions: parseStoredJson<unknown>(installation.grantedPermissions, [])
        })) return sendAccessDenied(res, 'AI_EMPLOYEE_IMPORT_PERMISSION_REQUIRED');

        const drafts = await prisma.aiEmployeeProductImportDraft.findMany({
          where: { merchantId, installationId: installation.id, status: 'pending' },
          orderBy: { createdAt: 'desc' },
          take: 100
        });
        res.setHeader('Cache-Control', 'no-store');
        res.json({
          success: true,
          drafts: drafts.map(draft => ({
            id: draft.id,
            sourceFilename: draft.sourceFilename,
            sourceType: draft.sourceType,
            candidate: parseSupplierProductCandidate(JSON.parse(draft.extractedData)),
            status: draft.status,
            createdAt: draft.createdAt
          }))
        });
      } catch (error) {
        sendInternalError(res, error, 'merchant-ai-employee-product-import-drafts');
      }
    }
  );

  app.patch(
    '/api/merchant/ai-employees/:id/tools/product-import-drafts/:draftId',
    runMerchantTenantMiddleware,
    requireEmployeePermission('employees.manage'),
    async (req: AuthRequest, res) => {
      const body = req.body;
      if (
        !body || typeof body !== 'object' || Array.isArray(body)
        || !['create_product_draft', 'reject'].includes(body.action)
        || Object.keys(body).some(key => !['action', 'candidate'].includes(key))
        || (body.action === 'reject' && Object.keys(body).length !== 1)
        || (body.action === 'create_product_draft' && Object.keys(body).length !== 2)
      ) return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_IMPORT_REVIEW_INVALID' });

      try {
        const merchantId = req.merchant!.merchantId;
        const installation = await prisma.merchantAiEmployeeInstallation.findFirst({
          where: { id: req.params.id, merchantId },
          include: { definition: { select: { slug: true, status: true } } }
        });
        if (!installation) return res.status(404).json({ success: false, error: 'AI_EMPLOYEE_INSTALLATION_NOT_FOUND' });
        if (!canUseAiEmployeeProductImport({
          employeeSlug: installation.definition.slug,
          employeeStatus: installation.definition.status,
          installationStatus: installation.status,
          grantedPermissions: parseStoredJson<unknown>(installation.grantedPermissions, [])
        })) return sendAccessDenied(res, 'AI_EMPLOYEE_IMPORT_PERMISSION_REQUIRED');

        const action = body.action as 'create_product_draft' | 'reject';
        let candidate: SupplierProductCandidate | null = null;
        if (action === 'create_product_draft') {
          try {
            candidate = parseSupplierProductCandidate(body.candidate);
          } catch {
            return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_IMPORT_CANDIDATE_INVALID' });
          }
          if (
            !candidate.styleNo || !candidate.name || !candidate.brand || !candidate.category
            || candidate.wholesalePrice === null || candidate.rrpPrice === null || candidate.moq === null
          ) return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_IMPORT_REQUIRED_FIELDS_MISSING' });
        }

        const result = await prisma.$transaction(async tx => {
          const draft = await tx.aiEmployeeProductImportDraft.findFirst({
            where: { id: req.params.draftId, merchantId, installationId: installation.id, status: 'pending' }
          });
          if (!draft) return { error: 'AI_EMPLOYEE_IMPORT_DRAFT_NOT_FOUND' as const };
          const currentInstallation = await tx.merchantAiEmployeeInstallation.findFirst({
            where: { id: installation.id, merchantId },
            include: { definition: { select: { slug: true, status: true } } }
          });
          if (!currentInstallation || !canUseAiEmployeeProductImport({
            employeeSlug: currentInstallation.definition.slug,
            employeeStatus: currentInstallation.definition.status,
            installationStatus: currentInstallation.status,
            grantedPermissions: parseStoredJson<unknown>(currentInstallation.grantedPermissions, [])
          })) return { error: 'AI_EMPLOYEE_IMPORT_PERMISSION_REQUIRED' as const };

          if (action === 'reject') {
            const updated = await tx.aiEmployeeProductImportDraft.updateMany({
              where: { id: draft.id, merchantId, installationId: installation.id, status: 'pending' },
              data: { status: 'rejected', reviewedBy: req.merchant!.employeeId || req.merchant!.id, reviewedAt: new Date() }
            });
            if (!updated.count) throw new Error('AI_EMPLOYEE_IMPORT_REVIEW_RACE');
          } else if (candidate) {
            const duplicate = await tx.product.findFirst({
              where: { merchantId, styleNo: candidate.styleNo },
              select: { id: true }
            });
            if (duplicate) return { error: 'AI_EMPLOYEE_IMPORT_STYLE_ALREADY_EXISTS' as const };
            const productId = crypto.randomUUID();
            const product = await tx.product.create({
              data: {
                id: productId,
                styleNo: candidate.styleNo,
                name: candidate.name,
                category: candidate.category,
                subCategory: candidate.subCategory,
                brand: candidate.brand,
                season: candidate.season,
                images: '[]',
                media: '[]',
                wholesalePrice: candidate.wholesalePrice!,
                rrpPrice: candidate.rrpPrice!,
                moq: candidate.moq!,
                packSize: 1,
                status: 'new',
                inventoryStatus: 'coming_soon',
                origin: '',
                fabric: candidate.fabric,
                composition: candidate.composition,
                weight: '',
                packaging: '',
                washCare: '',
                description: candidate.description,
                skus: '[]',
                merchantId,
                merchantName: req.merchant!.name,
                visibility: 'wholesale',
                lifecycleStatus: 'draft',
                isExclusiveProtected: false,
                protectionLevel: 'public'
              },
              select: { id: true, styleNo: true, name: true }
            });
            const updated = await tx.aiEmployeeProductImportDraft.updateMany({
              where: { id: draft.id, merchantId, installationId: installation.id, status: 'pending' },
              data: {
                status: 'created',
                extractedData: JSON.stringify(candidate),
                productId: product.id,
                reviewedBy: req.merchant!.employeeId || req.merchant!.id,
                reviewedAt: new Date()
              }
            });
            if (!updated.count) throw new Error('AI_EMPLOYEE_IMPORT_REVIEW_RACE');
            await tx.employeeAuditLog.create({
              data: {
                id: crypto.randomUUID(),
                merchantId,
                employeeId: req.merchant!.employeeId || null,
                action: 'AI_EMPLOYEE_PRODUCT_IMPORT_DRAFT_CREATED',
                entityType: 'Product',
                entityId: product.id,
                metadata: JSON.stringify({ importDraftId: draft.id, sourceType: draft.sourceType }),
                ipAddress: getClientIp(req)
              }
            });
            return { status: 'created' as const, product };
          }

          await tx.employeeAuditLog.create({
            data: {
              id: crypto.randomUUID(),
              merchantId,
              employeeId: req.merchant!.employeeId || null,
              action: 'AI_EMPLOYEE_PRODUCT_IMPORT_REJECTED',
              entityType: 'AiEmployeeProductImportDraft',
              entityId: draft.id,
              metadata: JSON.stringify({ sourceType: draft.sourceType }),
              ipAddress: getClientIp(req)
            }
          });
          return { status: 'rejected' as const };
        });
        if ('error' in result) {
          const statusCode = result.error === 'AI_EMPLOYEE_IMPORT_PERMISSION_REQUIRED' ? 403
            : result.error === 'AI_EMPLOYEE_IMPORT_STYLE_ALREADY_EXISTS' ? 409
              : 404;
          return res.status(statusCode).json({ success: false, error: result.error });
        }
        res.setHeader('Cache-Control', 'no-store');
        res.json({ success: true, ...result });
      } catch (error) {
        sendInternalError(res, error, 'merchant-ai-employee-product-import-review');
      }
    }
  );

  app.post(
    '/api/admin/growth/campaigns/:id/publish',
    requireAdminAuth,
    requireAdminPermission('settings.ai_support'),
    requireAdminPermission('settings.integrations'),
    metaOAuthLimiter,
    async (req: AuthRequest, res) => {
      const campaign = marketingCampaigns.find(item => item.id === req.params.id);
      if (!campaign) return res.status(404).json({ success: false, error: 'MARKETING_CAMPAIGN_NOT_FOUND' });
      if (campaign.status !== 'approved') return res.status(409).json({ success: false, error: 'MARKETING_CAMPAIGN_REVIEW_REQUIRED' });
      const channel = req.body?.channel;
      if (channel !== 'instagram' && channel !== 'facebook') {
        return res.status(400).json({ success: false, error: 'META_PUBLISH_CHANNEL_INVALID' });
      }
      if (!campaign.channels.includes(channel) || !campaign.copies[channel]?.trim()) {
        return res.status(400).json({ success: false, error: 'META_PUBLISH_CAMPAIGN_COPY_REQUIRED' });
      }
      const pageId = typeof req.body?.pageId === 'string' ? req.body.pageId : '';
      const page = integrationConfig.facebook.publishingPages.find(item => item.id === pageId);
      if (!page) return res.status(404).json({ success: false, error: 'META_PAGE_NOT_FOUND' });
      if (!canPublishToMetaChannel(page.tasks, channel)) {
        return sendAccessDenied(res, 'META_PAGE_PUBLISH_TASK_REQUIRED');
      }
      if (channel === 'instagram' && !page.instagramAccount) {
        return res.status(409).json({ success: false, error: 'META_INSTAGRAM_ACCOUNT_NOT_LINKED' });
      }
      if (channel === 'instagram' && !isPublicHttpsMediaUrl(campaign.instagramImageUrl)) {
        return res.status(400).json({ success: false, error: 'META_INSTAGRAM_PUBLIC_IMAGE_REQUIRED' });
      }
      if (channel === 'instagram' && (campaign.copies.instagram || '').length > 2200) {
        return res.status(400).json({ success: false, error: 'META_INSTAGRAM_CAPTION_TOO_LONG' });
      }
      const publicationKeyMatches = (publication: MarketingPublication) =>
        publication.channel === channel && publication.pageId === page.id;
      const previousPublication = (campaign.publications || []).find(publicationKeyMatches);
      if (previousPublication && previousPublication.status !== 'failed') {
        return res.status(409).json({
          success: false,
          error: previousPublication.status === 'published' ? 'META_PUBLICATION_ALREADY_SENT' : 'META_PUBLICATION_REQUIRES_REVIEW'
        });
      }
      const publishLockKey = `${campaign.id}:${channel}:${page.id}`;
      if (metaPublishLocks.has(publishLockKey)) {
        return res.status(409).json({ success: false, error: 'META_PUBLICATION_IN_PROGRESS' });
      }
      metaPublishLocks.add(publishLockKey);
      res.once('finish', () => metaPublishLocks.delete(publishLockKey));
      const { appId, appSecret } = getMetaAppCredentials();
      if (!appSecret) return res.status(503).json({ success: false, error: 'META_APP_NOT_CONFIGURED' });

      let graphAccessToken: string;
      try {
        const encryptedToken = channel === 'instagram' ? page.instagramUserTokenEncrypted : page.accessTokenEncrypted;
        if (!encryptedToken) return res.status(503).json({ success: false, error: 'META_INSTAGRAM_RECONNECT_REQUIRED' });
        graphAccessToken = decryptSecret(encryptedToken);
      } catch {
        return res.status(503).json({ success: false, error: 'META_TOKEN_DECRYPTION_FAILED' });
      }
      if (channel === 'instagram') {
        const expiry = page.instagramUserTokenExpiresAt ? Date.parse(page.instagramUserTokenExpiresAt) : Number.NaN;
        if (!Number.isFinite(expiry) || expiry <= Date.now() + 7 * 24 * 60 * 60 * 1000) {
          if (!appId) return res.status(503).json({ success: false, error: 'META_APP_NOT_CONFIGURED' });
          const refreshUrl = new URL(`https://graph.facebook.com/${getMetaGraphVersion()}/oauth/access_token`);
          refreshUrl.searchParams.set('grant_type', 'fb_exchange_token');
          refreshUrl.searchParams.set('client_id', appId);
          refreshUrl.searchParams.set('client_secret', appSecret);
          refreshUrl.searchParams.set('fb_exchange_token', graphAccessToken);
          try {
            const refreshResponse = await fetch(refreshUrl, { signal: AbortSignal.timeout(15_000) });
            const refreshData = await refreshResponse.json().catch(() => null) as { access_token?: string; expires_in?: number } | null;
            if (!refreshResponse.ok || !refreshData?.access_token) {
              return res.status(503).json({ success: false, error: 'META_INSTAGRAM_RECONNECT_REQUIRED' });
            }
            const renewedExpiry = new Date(Date.now() + Math.max(1, Number(refreshData.expires_in) || 60 * 24 * 60 * 60) * 1000).toISOString();
            const linkedPages = integrationConfig.facebook.publishingPages.filter(item => item.instagramAccount);
            const oldTokenValues = linkedPages.map(item => ({
              page: item,
              encryptedToken: item.instagramUserTokenEncrypted,
              expiresAt: item.instagramUserTokenExpiresAt
            }));
            for (const linkedPage of linkedPages) {
              linkedPage.instagramUserTokenEncrypted = encryptSecret(refreshData.access_token);
              linkedPage.instagramUserTokenExpiresAt = renewedExpiry;
            }
            try {
              await saveIntegrationConfig();
            } catch (error) {
              for (const oldValue of oldTokenValues) {
                oldValue.page.instagramUserTokenEncrypted = oldValue.encryptedToken;
                oldValue.page.instagramUserTokenExpiresAt = oldValue.expiresAt;
              }
              console.error('[meta-token-refresh] refreshed token persistence failed', error instanceof Error ? error.name : 'unknown error');
              return res.status(503).json({ success: false, error: 'META_INSTAGRAM_RECONNECT_REQUIRED' });
            }
            graphAccessToken = refreshData.access_token;
          } catch (error) {
            console.error('[meta-token-refresh] request failed', error instanceof Error ? error.name : 'unknown error');
            return res.status(503).json({ success: false, error: 'META_INSTAGRAM_RECONNECT_REQUIRED' });
          }
        }
      }
      const startedAt = new Date().toISOString();
      const previousPublications = campaign.publications || [];
      const previousUpdatedAt = campaign.updatedAt;
      const publication: MarketingPublication = {
        channel,
        pageId: page.id,
        accountName: channel === 'instagram' ? `@${page.instagramAccount?.username || page.instagramAccount?.id}` : page.name,
        status: 'publishing',
        startedAt
      };
      campaign.publications = [...(campaign.publications || []).filter(item => !publicationKeyMatches(item)), publication];
      campaign.updatedAt = startedAt;
      try {
        await persistMarketingCampaigns();
      } catch (error) {
        campaign.publications = previousPublications;
        campaign.updatedAt = previousUpdatedAt;
        sendInternalError(res, error, 'admin-meta-publish-reserve');
        return;
      }

      const version = getMetaGraphVersion();
      const appSecretProof = crypto.createHmac('sha256', appSecret).update(graphAccessToken).digest('hex');
      const graphPost = async (pathValue: string, fields: Record<string, string>) => {
        const url = new URL(`https://graph.facebook.com/${version}/${pathValue}`);
        const body = new URLSearchParams({ ...fields, access_token: graphAccessToken, appsecret_proof: appSecretProof });
        const response = await fetch(url, { method: 'POST', body, signal: AbortSignal.timeout(20_000) });
        const payload = await response.json().catch(() => null) as { id?: string; error?: { code?: number } } | null;
        if (!payload || !response.ok || payload.error) {
          throw new MetaApiError(typeof payload?.error?.code === 'number' ? payload.error.code : response.status, response.status < 500);
        }
        return payload;
      };

      try {
        let externalPostId: string | undefined;
        if (channel === 'facebook') {
          const result = await graphPost(`${encodeURIComponent(page.id)}/feed`, {
            message: campaign.copies.facebook!.trim()
          });
          externalPostId = typeof result.id === 'string' ? result.id : undefined;
        } else {
          const instagramAccountId = page.instagramAccount!.id;
          const container = await graphPost(`${encodeURIComponent(instagramAccountId)}/media`, {
            image_url: campaign.instagramImageUrl!,
            caption: campaign.copies.instagram!.trim()
          });
          if (typeof container.id !== 'string') throw new Error('META_CONTAINER_ID_MISSING');
          const statusUrl = new URL(`https://graph.facebook.com/${version}/${encodeURIComponent(container.id)}`);
          statusUrl.searchParams.set('fields', 'status_code');
          statusUrl.searchParams.set('access_token', graphAccessToken);
          statusUrl.searchParams.set('appsecret_proof', appSecretProof);
          let ready = false;
          for (let attempt = 0; attempt < 20; attempt += 1) {
            await new Promise(resolve => setTimeout(resolve, 1000));
            const statusResponse = await fetch(statusUrl, { signal: AbortSignal.timeout(10_000) });
            const statusPayload = await statusResponse.json().catch(() => null) as { status_code?: string; error?: { code?: number } } | null;
            if (!statusPayload || !statusResponse.ok || statusPayload.error) {
              throw new MetaApiError(typeof statusPayload?.error?.code === 'number' ? statusPayload.error.code : statusResponse.status, statusResponse.status < 500);
            }
            if (statusPayload.status_code === 'FINISHED') {
              ready = true;
              break;
            }
            if (statusPayload.status_code === 'ERROR' || statusPayload.status_code === 'EXPIRED') {
              throw new MetaApiError(0, true);
            }
          }
          if (!ready) throw new MetaApiError(0, true);
          const published = await graphPost(`${encodeURIComponent(instagramAccountId)}/media_publish`, { creation_id: container.id });
          externalPostId = typeof published.id === 'string' ? published.id : undefined;
        }
        if (!externalPostId) throw new Error('META_PUBLICATION_ID_MISSING');
        publication.status = 'published';
        publication.externalPostId = externalPostId;
        publication.publishedAt = new Date().toISOString();
        campaign.updatedAt = publication.publishedAt;
        try {
          await persistMarketingCampaigns();
        } catch (error) {
          publication.status = 'publishing';
          publication.externalPostId = undefined;
          publication.publishedAt = undefined;
          console.error('[meta-publish] provider accepted post but persistence failed', error instanceof Error ? error.name : 'unknown error');
          return res.status(503).json({ success: false, error: 'META_PUBLISH_RESULT_UNCERTAIN' });
        }
        logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'META_CAMPAIGN_PUBLISHED', 'MarketingCampaign', campaign.id, '', `${channel}:${page.id}`);
        return res.json({ success: true, campaign });
      } catch (error) {
        if (error instanceof MetaApiError) {
          if (!error.canRetry) {
            console.error('[meta-publish] provider result requires manual verification', error.providerCode);
            return res.status(502).json({ success: false, error: 'META_PUBLISH_RESULT_UNCERTAIN', providerErrorCode: error.providerCode });
          }
          publication.status = 'failed';
          publication.providerErrorCode = error.providerCode;
          campaign.updatedAt = new Date().toISOString();
          try {
            await persistMarketingCampaigns();
          } catch (persistError) {
            console.error('[meta-publish] provider error could not be persisted', persistError instanceof Error ? persistError.name : 'unknown error');
          }
          logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'META_CAMPAIGN_PUBLISH_FAILED', 'MarketingCampaign', campaign.id, '', `${channel}:${error.providerCode}`);
          return res.status(502).json({ success: false, error: 'META_PUBLISH_FAILED', providerErrorCode: error.providerCode });
        }
        console.error('[meta-publish] result uncertain', error instanceof Error ? error.name : 'unknown error');
        return res.status(502).json({ success: false, error: 'META_PUBLISH_RESULT_UNCERTAIN' });
      }
    }
  );

  app.put('/api/admin/ai-support/config', requireAdminAuth, requireAdminPermission('settings.ai_support'), async (req, res) => {
    const body = req.body || {};
    if (typeof body.enabled === 'boolean') aiSupportConfig.enabled = body.enabled;
    if (typeof body.welcomeMessage === 'string' && body.welcomeMessage.trim()) aiSupportConfig.welcomeMessage = body.welcomeMessage.trim().slice(0, 500);
    if (typeof body.fallbackMessage === 'string' && body.fallbackMessage.trim()) aiSupportConfig.fallbackMessage = body.fallbackMessage.trim().slice(0, 500);
    if (Array.isArray(body.quickQuestions)) {
      aiSupportConfig.quickQuestions = body.quickQuestions.map((item: unknown) => String(item).trim()).filter(Boolean).slice(0, 8);
    }
    try {
      await saveAiSupportConfig();
      res.json({ success: true, config: aiSupportConfig });
    } catch (error) {
      sendInternalError(res, error, 'ai-support-config-save');
    }
  });

  // GET /api/products (买手端商品列表，根据 customerId 过滤可见性)
  app.get('/api/products', async (req, res) => {
    try {
    const { merchantId, category, search } = req.query;
    const authorizedVisibility = await getAuthorizedProductVisibility(req);

    const list = await prisma.product.findMany({
      where: {
        lifecycleStatus: 'published',
        merchant: { OR: [{ storefrontEnabled: true }, { isVerified: true, storefrontEnabled: null }] },
        merchantId: merchantId ? String(merchantId) : undefined,
        category: category && category !== 'all' ? String(category) : undefined,
        AND: [{ OR: authorizedVisibility }],
        OR: search && typeof search === 'string' ? [
          { styleNo: { contains: search, mode: 'insensitive' } },
          { name: { contains: search, mode: 'insensitive' } },
          { brand: { contains: search, mode: 'insensitive' } }
        ] : undefined
      },
      orderBy: [{ featuredOnSale: 'desc' }, { featuredOnHome: 'desc' }, { createdAt: 'desc' }],
      take: 1000,
      include: {
        variants: {
          where: { isActive: true },
          include: { inventoryBalances: { include: { location: { select: { code: true } } } } }
        }
      }
    });
    const visibleProducts = list.map(prod => ({
      ...serializePublicProductRow(prod),
      isLockedForBuyer: false
    }));
    res.json({ success: true, count: visibleProducts.length, products: visibleProducts });
    } catch (error) {
      sendInternalError(res, error, 'public-products');
    }
  });

