  app.post('/api/payments/solana/request/:token', async (req, res) => {
    res.setHeader('Cache-Control', 'no-store');
    try {
      const token = typeof req.params.token === 'string' ? req.params.token : '';
      const account = typeof req.body?.account === 'string' ? req.body.account : '';
      if (!/^[A-Za-z0-9_-]{43}$/.test(token) || !account) {
        return res.status(400).json({ error: 'SOLANA_TRANSACTION_REQUEST_INVALID' });
      }
      const payer = new PublicKey(normalizeSolanaWalletAddress(account));
      const requestTokenHash = crypto.createHash('sha256').update(token).digest('hex');
      const intent = await prisma.solanaPaymentIntent.findUnique({
        where: { requestTokenHash },
        include: { order: { select: { orderNo: true, status: true, paymentStatus: true } } }
      });
      if (!intent || intent.status !== 'pending' || intent.expiresAt <= new Date()
        || intent.order.status === 'cancelled' || intent.order.paymentStatus === 'paid') {
        return res.status(410).json({ error: 'SOLANA_PAYMENT_REQUEST_EXPIRED' });
      }
      await assertSolanaMainnet();
      const transaction = await createSolanaSplitTransaction({
        payer,
        recipient: intent.recipient,
        platformWallet: intent.platformWallet,
        reference: intent.reference,
        mint: intent.mint,
        merchantAmountAtomic: intent.merchantAmountAtomic,
        commissionAmountAtomic: intent.commissionAmountAtomic
      });
      return res.json({
        transaction: transaction.serialize({ requireAllSignatures: false, verifySignatures: false }).toString('base64'),
        message: `${intent.tokenAmount.toString()} ${intent.tokenSymbol} total · ${intent.merchantAmount.toString()} to merchant · ${intent.commissionAmount.toString()} to RUDA`
      });
    } catch (error) {
      const code = error instanceof Error ? error.message : 'SOLANA_TRANSACTION_CREATE_FAILED';
      if (['SOLANA_WALLET_ADDRESS_INVALID', 'SOLANA_BUYER_TOKEN_BALANCE_INSUFFICIENT', 'SOLANA_STABLECOIN_MINT_INVALID'].includes(code)) {
        return res.status(409).json({ error: code });
      }
      if (['SOLANA_RPC_NOT_CONFIGURED', 'SOLANA_RPC_URL_INVALID', 'SOLANA_RPC_NOT_MAINNET'].includes(code)) {
        return res.status(503).json({ error: code });
      }
      console.error('[solana-transaction-request]', code);
      return res.status(500).json({ error: 'SOLANA_TRANSACTION_CREATE_FAILED' });
    }
  });

  app.get('/api/payments/solana/availability', requireBuyerAuth, async (req: AuthRequest, res) => {
    res.setHeader('Cache-Control', 'no-store');
    const merchantId = typeof req.query.merchantId === 'string' ? req.query.merchantId.trim() : '';
    if (!merchantId) return res.status(400).json({ success: false, error: 'MERCHANT_ID_REQUIRED' });
    const config = await prisma.merchantSolanaConfig.findFirst({
      where: { merchantId, enabled: true },
      select: { walletAddress: true, commissionRate: true }
    });
    if (!config) return res.json({ success: true, available: false });
    try {
      const platformWallet = getSolanaPlatformWalletAddress();
      if (config.walletAddress === platformWallet) {
        return res.json({ success: true, available: false, reason: 'SOLANA_PLATFORM_WALLET_CONFLICT' });
      }
      await assertSolanaMainnet();
      return res.json({ success: true, available: true, commissionRate: config.commissionRate.toString() });
    } catch (error) {
      const code = error instanceof Error ? error.message : 'SOLANA_RPC_UNAVAILABLE';
      if (['SOLANA_PLATFORM_WALLET_NOT_CONFIGURED', 'SOLANA_WALLET_ADDRESS_INVALID', 'SOLANA_RPC_NOT_CONFIGURED', 'SOLANA_RPC_URL_INVALID', 'SOLANA_RPC_NOT_MAINNET'].includes(code)) {
        return res.json({ success: true, available: false, reason: code });
      }
      return res.status(503).json({ success: false, error: 'SOLANA_RPC_UNAVAILABLE' });
    }
  });

  app.get('/api/payments/solana/:orderId', requireBuyerAuth, async (req: AuthRequest, res) => {
    try {
      const order = await prisma.order.findFirst({
        where: { id: req.params.orderId, customerId: req.buyer!.customerId },
        include: { items: true }
      });
      if (!order) return res.status(404).json({ success: false, error: 'ORDER_NOT_FOUND' });
      const intent = await prisma.solanaPaymentIntent.findUnique({ where: { orderId: order.id } });
      if (!intent) return res.status(404).json({ success: false, error: 'SOLANA_PAYMENT_NOT_FOUND' });

      if (!['paid', 'late_payment'].includes(intent.status)) {
        await assertSolanaMainnet();
        const verified = await findVerifiedSolanaSplitTransfer({
          recipient: intent.recipient,
          platformWallet: intent.platformWallet,
          reference: intent.reference,
          mint: intent.mint,
          merchantAmountAtomic: intent.merchantAmountAtomic,
          commissionAmountAtomic: intent.commissionAmountAtomic
        });
        if (verified && 'invalidTransactionFound' in verified) {
          await prisma.solanaPaymentIntent.update({
            where: { id: intent.id },
            data: { status: 'review', lastCheckedAt: new Date() }
          });
        } else if (verified && 'signature' in verified && verified.blockTime !== null) {
          const paidBeforeExpiry = verified.blockTime * 1000 <= intent.expiresAt.getTime();
          const canFulfill = order.status !== 'cancelled';
          const paymentStatus = paidBeforeExpiry && canFulfill ? 'paid' : 'review';
          await prisma.$transaction(async tx => {
            await tx.solanaPaymentIntent.updateMany({
              where: { id: intent.id, status: { not: 'paid' } },
              data: {
                status: paymentStatus === 'paid' ? 'paid' : 'late_payment',
                signature: verified.signature,
                lastCheckedAt: new Date()
              }
            });
            await tx.paymentTransaction.updateMany({
              where: { orderId: order.id, provider: 'solana_pay', status: { not: 'paid' } },
              data: {
                providerPaymentId: verified.signature,
                status: order.status === 'cancelled' ? 'paid' : paymentStatus
              }
            });
            if (order.status === 'cancelled') {
              const solanaPayment = await tx.paymentTransaction.findFirst({
                where: { orderId: order.id, provider: 'solana_pay' },
                select: { id: true }
              });
              if (solanaPayment) await queueLatePaymentRefund(tx, order.id, solanaPayment.id);
            } else if (paymentStatus === 'paid') {
              const confirmed = await tx.order.updateMany({
                where: { id: order.id, status: { not: 'cancelled' } },
                data: { status: 'confirmed', paymentStatus: 'paid' }
              });
              if (!confirmed.count) {
                const solanaPayment = await tx.paymentTransaction.findFirst({
                  where: { orderId: order.id, provider: 'solana_pay' },
                  select: { id: true }
                });
                if (solanaPayment) await queueLatePaymentRefund(tx, order.id, solanaPayment.id);
              } else {
                await createPaidOrderPartnerCommissions(tx, order.id);
              }
              await tx.orderInvoice.updateMany({ where: { orderId: order.id }, data: { status: 'paid', paidAt: new Date() } });
              if (modaGptBrainEnabled && order.merchantId) {
                await enqueueModaGptEventsInTransaction(tx, [{
                  type: 'payment.completed',
                  eventId: `${order.id}-payment-${crypto.createHash('sha256').update(verified.signature).digest('hex').slice(0, 24)}`,
                  merchantId: order.merchantId,
                  occurredAt: new Date().toISOString(),
                  data: {
                    orderId: order.id,
                    paymentProvider: 'solana_pay',
                    amount: Number(order.totalAmount),
                    currency: 'EUR'
                  }
                }]);
              }
            } else if (verified && 'signature' in verified) {
              await prisma.solanaPaymentIntent.update({
                where: { id: intent.id },
                data: { lastCheckedAt: new Date() }
              });
            } else {
              await tx.order.update({ where: { id: order.id }, data: { paymentStatus: 'payment_required' } });
            }
          });
        } else {
          const now = new Date();
          const status = now >= intent.expiresAt ? 'expired' : intent.status === 'review' ? 'review' : 'pending';
          await prisma.solanaPaymentIntent.update({
            where: { id: intent.id },
            data: { status, lastCheckedAt: now }
          });
          if (status === 'expired') {
            await prisma.order.updateMany({
              where: { id: order.id, paymentStatus: { not: 'paid' } },
              data: { paymentStatus: 'payment_timeout' }
            });
          }
        }
      }

      const [currentIntent, currentOrder] = await Promise.all([
        prisma.solanaPaymentIntent.findUnique({ where: { id: intent.id } }),
        prisma.order.findUnique({ where: { id: order.id }, include: { items: true } })
      ]);
      if (!currentIntent || !currentOrder) return res.status(404).json({ success: false, error: 'SOLANA_PAYMENT_NOT_FOUND' });
      res.setHeader('Cache-Control', 'no-store');
      return res.json({
        success: true,
        payment: serializeSolanaPaymentIntent(currentIntent, currentOrder.orderNo),
        order: serializeOrderRow(currentOrder)
      });
    } catch (error) {
      const code = error instanceof Error ? error.message : 'SOLANA_PAYMENT_CHECK_FAILED';
      if (['SOLANA_RPC_NOT_CONFIGURED', 'SOLANA_RPC_URL_INVALID', 'SOLANA_RPC_NOT_MAINNET'].includes(code)) {
        return res.status(503).json({ success: false, error: code });
      }
      sendInternalError(res, error, 'solana-payment-status');
    }
  });

  app.post('/api/payments/stripe/confirm', requireBuyerAuth, async (req: AuthRequest, res) => {
    try {
      const sessionId = typeof req.body?.sessionId === 'string' ? req.body.sessionId.trim() : '';
      const requestedOrderNo = typeof req.body?.orderNo === 'string' ? req.body.orderNo.trim() : '';
      if (!/^cs_(test|live)_[A-Za-z0-9]+$/.test(sessionId) || !requestedOrderNo || requestedOrderNo.length > 128) {
        return res.status(400).json({ success: false, error: 'STRIPE_ORDER_REFERENCE_REQUIRED' });
      }
      const payment = await prisma.paymentTransaction.findFirst({
        where: { provider: 'merchant_stripe', providerPaymentId: sessionId }
      });
      const order = payment
        ? await prisma.order.findFirst({ where: { id: payment.orderId, customerId: req.buyer!.customerId }, include: { items: true } })
        : null;
      if (!payment || !order || (order.parentOrderNo !== requestedOrderNo && order.orderNo !== requestedOrderNo)) {
        return res.status(404).json({ success: false, error: 'STRIPE_PAYMENT_NOT_FOUND' });
      }
      if (order.status === 'cancelled') return res.status(409).json({ success: false, error: 'ORDER_CANCELLED' });
      if (payment.status === 'paid') {
        return res.json({ success: true, payment: { status: 'paid' }, order: serializeOrderRow(order) });
      }
      if (payment.status !== 'pending') return res.status(409).json({ success: false, error: 'STRIPE_PAYMENT_NOT_PENDING' });

      const claimed = await prisma.paymentTransaction.updateMany({
        where: { id: payment.id, status: 'pending' },
        data: { status: 'processing' }
      });
      if (!claimed.count) {
        const current = await prisma.paymentTransaction.findUnique({ where: { id: payment.id }, select: { status: true } });
        if (current?.status === 'paid') {
          const paidOrder = await prisma.order.findUnique({ where: { id: order.id }, include: { items: true } });
          return res.json({ success: true, payment: { status: 'paid' }, order: paidOrder ? serializeOrderRow(paidOrder) : undefined });
        }
        return res.status(409).json({ success: false, error: 'STRIPE_CONFIRM_IN_PROGRESS' });
      }

      try {
        const credentials = await getMerchantStripeCredentials(order.merchantId || '');
        if (!credentials) throw new Error('STRIPE_MERCHANT_CONFIG_NOT_AVAILABLE');
        const checkout = await retrieveMerchantStripeCheckout(credentials, sessionId);
        if (checkout.status !== 'complete' || checkout.paymentStatus !== 'paid' || !checkout.paymentIntentId) {
          throw new Error('STRIPE_CHECKOUT_NOT_PAID');
        }
        if (checkout.currency.toUpperCase() !== payment.currency.toUpperCase()
          || Number(checkout.amount.toFixed(2)) !== Number(Number(payment.amount).toFixed(2))) {
          throw new Error('STRIPE_CHECKOUT_AMOUNT_MISMATCH');
        }
        const metadata = parseStoredJson<Record<string, unknown>>(payment.metadata, {});
        await prisma.$transaction(async tx => {
          await tx.paymentTransaction.update({
            where: { id: payment.id },
            data: {
              status: 'paid',
              metadata: JSON.stringify({ ...metadata, paymentIntentId: checkout.paymentIntentId })
            }
          });
          const confirmed = await tx.order.updateMany({
            where: { id: order.id, status: { not: 'cancelled' } },
            data: { status: 'confirmed', paymentStatus: 'paid' }
          });
          if (!confirmed.count) await queueLatePaymentRefund(tx, order.id, payment.id);
          else await createPaidOrderPartnerCommissions(tx, order.id);
          await tx.orderInvoice.updateMany({ where: { orderId: order.id }, data: { status: 'paid', paidAt: new Date() } });
        });
        const updatedOrder = await prisma.order.findUnique({ where: { id: order.id }, include: { items: true } });
        return res.json({ success: true, payment: { status: 'paid' }, order: updatedOrder ? serializeOrderRow(updatedOrder) : undefined });
      } catch (error) {
        await prisma.paymentTransaction.updateMany({
          where: { id: payment.id, status: 'processing' },
          data: { status: 'pending' }
        });
        throw error;
      }
    } catch (error) {
      const code = error instanceof Error ? error.message : 'STRIPE_CONFIRM_FAILED';
      if (['STRIPE_CHECKOUT_NOT_PAID', 'STRIPE_CHECKOUT_AMOUNT_MISMATCH', 'STRIPE_MERCHANT_CONFIG_NOT_AVAILABLE'].includes(code)) {
        return res.status(409).json({ success: false, error: code });
      }
      sendInternalError(res, error, 'merchant-stripe-payment-confirm');
    }
  });

  app.post('/api/payments/paypal/capture', requireBuyerAuth, async (req: AuthRequest, res) => {
    try {
      const paypalOrderId = typeof req.body?.paypalOrderId === 'string' ? req.body.paypalOrderId.trim() : '';
      const requestedOrderNo = typeof req.body?.orderNo === 'string' ? req.body.orderNo.trim() : '';
      if (!paypalOrderId || paypalOrderId.length > 128 || !requestedOrderNo || requestedOrderNo.length > 128) {
        return res.status(400).json({ success: false, error: 'PAYPAL_ORDER_REFERENCE_REQUIRED' });
      }
      const payment = await prisma.paymentTransaction.findFirst({
        where: { provider: 'paypal', providerPaymentId: paypalOrderId }
      });
      const order = payment
        ? await prisma.order.findFirst({ where: { id: payment.orderId, customerId: req.buyer!.customerId }, include: { items: true } })
        : null;
      if (!payment || !order || (order.parentOrderNo !== requestedOrderNo && order.orderNo !== requestedOrderNo)) {
        return res.status(404).json({ success: false, error: 'PAYPAL_PAYMENT_NOT_FOUND' });
      }
      if (order.status === 'cancelled') return res.status(409).json({ success: false, error: 'ORDER_CANCELLED' });
      if (payment.status === 'paid') {
        return res.json({ success: true, payment: { status: 'paid' }, order: serializeOrderRow(order) });
      }
      if (payment.status !== 'pending') return res.status(409).json({ success: false, error: 'PAYPAL_PAYMENT_NOT_PENDING' });

      const claimed = await prisma.paymentTransaction.updateMany({
        where: { id: payment.id, status: 'pending' },
        data: { status: 'processing' }
      });
      if (!claimed.count) {
        const current = await prisma.paymentTransaction.findUnique({ where: { id: payment.id }, select: { status: true } });
        if (current?.status === 'paid') {
          const paidOrder = await prisma.order.findUnique({ where: { id: order.id }, include: { items: true } });
          return res.json({ success: true, payment: { status: 'paid' }, order: paidOrder ? serializeOrderRow(paidOrder) : undefined });
        }
        return res.status(409).json({ success: false, error: 'PAYPAL_CAPTURE_IN_PROGRESS' });
      }

      try {
        const credentials = await getMerchantPayPalCredentials(order.merchantId || '');
        if (!credentials) throw new Error('PAYPAL_MERCHANT_CONFIG_NOT_AVAILABLE');
        const capture = await capturePayPalCheckout(
          credentials,
          paypalOrderId,
          `ruda-capture-${crypto.createHash('sha256').update(payment.id).digest('hex').slice(0, 48)}`
        );
        if (capture.status !== 'COMPLETED' || !capture.captureId) throw new Error('PAYPAL_CAPTURE_NOT_COMPLETED');
        if (capture.currency.toUpperCase() !== payment.currency.toUpperCase()
          || Number(capture.amount.toFixed(2)) !== Number(Number(payment.amount).toFixed(2))) {
          throw new Error('PAYPAL_CAPTURE_AMOUNT_MISMATCH');
        }
        const metadata = parseStoredJson<Record<string, unknown>>(payment.metadata, {});
        await prisma.$transaction(async tx => {
          await tx.paymentTransaction.update({
            where: { id: payment.id },
            data: {
              status: 'paid',
              metadata: JSON.stringify({ ...metadata, captureId: capture.captureId, captureStatus: capture.status })
            }
          });
          const confirmed = await tx.order.updateMany({
            where: { id: order.id, status: { not: 'cancelled' } },
            data: { status: 'confirmed', paymentStatus: 'paid' }
          });
          if (!confirmed.count) await queueLatePaymentRefund(tx, order.id, payment.id);
          else await createPaidOrderPartnerCommissions(tx, order.id);
          await tx.orderInvoice.updateMany({
            where: { orderId: order.id },
            data: { status: 'paid', paidAt: new Date() }
          });
        });
        const updatedOrder = await prisma.order.findUnique({ where: { id: order.id }, include: { items: true } });
        res.json({ success: true, payment: { status: 'paid' }, order: updatedOrder ? serializeOrderRow(updatedOrder) : undefined });
      } catch (error) {
        await prisma.paymentTransaction.updateMany({
          where: { id: payment.id, status: 'processing' },
          data: { status: 'pending' }
        });
        throw error;
      }
    } catch (error) {
      const code = error instanceof Error ? error.message : 'PAYPAL_CAPTURE_FAILED';
      if (code === 'PAYPAL_CAPTURE_NOT_COMPLETED' || code === 'PAYPAL_CAPTURE_AMOUNT_MISMATCH') {
        return res.status(409).json({ success: false, error: code });
      }
      if (code === 'PAYPAL_MERCHANT_CONFIG_NOT_AVAILABLE') {
        return res.status(409).json({ success: false, error: code });
      }
      sendInternalError(res, error, 'paypal-payment-capture');
    }
  });

  app.post('/api/storefront/single-item-link', async (req, res) => {
    try {
      if (!getPaymentIntegrationStatus().supportsPayments) {
        return res.status(503).json({ success: false, error: 'ONLINE_PAYMENT_NOT_CONFIGURED' });
      }
      if (!getSingleItemCheckoutSecret()) {
        return res.status(503).json({ success: false, error: 'SINGLE_ITEM_LINK_SIGNING_NOT_CONFIGURED' });
      }
      const productId = typeof req.body?.productId === 'string' ? req.body.productId : '';
      const skuCode = typeof req.body?.sku === 'string' ? req.body.sku : '';
      if (!productId || !skuCode) return res.status(400).json({ success: false, error: 'PRODUCT_AND_SKU_REQUIRED' });
      const product = await prisma.product.findFirst({
        where: {
          id: productId,
          lifecycleStatus: 'published',
          ...PUBLIC_PRODUCT_VISIBILITY_FILTER,
          merchant: PUBLIC_STOREFRONT_MERCHANT_FILTER
        }
      });
      if (!product?.merchantId) return res.status(404).json({ success: false, error: 'PUBLIC_PRODUCT_NOT_FOUND' });
      const sku = parseStoredJson<any[]>(product.skus, []).find(item => item.sku === skuCode);
      if (!sku) return res.status(404).json({ success: false, error: 'SKU_NOT_FOUND' });
      const variant = await prisma.productVariant.findUnique({
        where: { productId_sku: { productId, sku: skuCode } },
        include: { inventoryBalances: { include: { location: { select: { code: true } } } } }
      });
      const available = variant?.inventoryBalances
        .filter(balance => balance.location.code === 'central')
        .reduce((sum, balance) => sum + balance.onHandQuantity - balance.reservedQuantity, 0) || 0;
      if (available < 1) return res.status(409).json({ success: false, error: 'SKU_OUT_OF_STOCK' });
      const merchant = await prisma.merchant.findUnique({
        where: { id: product.merchantId },
        select: { storeSlug: true, code: true, storefrontEnabled: true, isVerified: true }
      });
      if (!merchant) return res.status(404).json({ success: false, error: 'MERCHANT_STORE_NOT_FOUND' });
      if (!isPublicStorefront(merchant)) {
        return res.status(404).json({ success: false, error: 'MERCHANT_STORE_NOT_FOUND' });
      }
      const token = createSingleItemCheckoutToken({ productId, merchantId: product.merchantId, sku: skuCode });
      const slug = merchant.storeSlug || merchant.code || product.merchantId;
      const baseUrl = process.env.APP_URL || `${req.protocol}://${req.get('host')}`;
      const url = new URL(`/shop/${encodeURIComponent(slug)}`, baseUrl);
      url.searchParams.set('product', productId);
      url.searchParams.set('sku', skuCode);
      url.searchParams.set('singleItemToken', token);
      res.json({ success: true, url: url.toString(), expiresInDays: 180 });
    } catch (error) {
      sendInternalError(res, error, 'storefront-single-item-link');
    }
  });

  app.get('/api/showrooms', async (_req, res) => {
    try {
      const showrooms = await prisma.showroom.findMany({ orderBy: { city: 'asc' } });
      res.json({ success: true, showrooms: showrooms.map(showroom => ({
        ...showroom,
        features: parseStoredJson(showroom.features, []),
        features_it: parseStoredJson(showroom.features_it, []),
        features_zh: parseStoredJson(showroom.features_zh, [])
      })) });
    } catch (error) {
      sendInternalError(res, error, 'public-showrooms');
    }
  });

  // GET /api/suppliers (买手长期合作供应商与多商户结构：店铺 + 展厅 + Private Collection)
  app.get('/api/suppliers', async (req, res) => {
    try {
    const customerId = getOptionalBuyerCustomerId(req);
    const [merchants, products, showrooms, customer, accessRequests] = await Promise.all([
      prisma.merchant.findMany({ where: PUBLIC_STOREFRONT_MERCHANT_FILTER, orderBy: { name: 'asc' } }),
      prisma.product.findMany({
        where: {
          lifecycleStatus: 'published',
          ...PUBLIC_PRODUCT_VISIBILITY_FILTER
        }
      }),
      prisma.showroom.findMany(),
      customerId
        ? prisma.customer.findUnique({ where: { id: customerId }, select: { status: true } })
        : Promise.resolve(null),
      customerId
        ? prisma.vaultAccessRequest.findMany({
          where: { customerId, status: { in: ['pending', 'approved', 'rejected'] } },
          orderBy: { createdAt: 'desc' }
        })
        : Promise.resolve([])
    ]);
    const suppliers = merchants.map(m => {
      const merchantProducts = products.filter(p => p.merchantId === m.id);
      const publicProducts = merchantProducts.filter(isPublicProduct);
      const showroom = showrooms.find(s => s.code.toLowerCase().includes(m.code.toLowerCase())) || showrooms[0];

      const reqItem = accessRequests.find(vr => vr.merchantId === m.id);
      const accessStatus = getBuyerVaultAccessStatus(customer?.status, reqItem);

      return {
        id: m.id,
        name: m.name,
        companyLegalName: m.companyLegalName,
        code: m.code,
        city: m.city,
        country: m.country,
        logo: m.logo,
        banner: m.banner,
        tagline: m.tagline,
        specialties: parseStoredJson(m.specialties, []),
        rating: m.rating,
        store: {
          publicCount: publicProducts.length,
          topProducts: publicProducts.slice(0, 3).map(serializePublicProductRow)
        },
        showroom: showroom ? {
          id: showroom.id,
          name: showroom.name,
          address: showroom.address,
          openingHours: showroom.openingHours,
          image: showroom.image
        } : null,
        privateCollection: {
          accessStatus,
          hasAccess: accessStatus === 'approved' && customer?.status === 'approved',
          notice: '需经商家授权、登录权限、买家专属水印等机制查阅专属新品，降低资料扩散风险。'
        }
      };
    });

    res.json({ success: true, suppliers });
    } catch (error) {
      sendInternalError(res, error, 'public-suppliers');
    }
  });

  // POST /api/po/ocr-parse (智能采购单/拍照 OCR 解析与 SKU 自动匹配引擎)
  app.post('/api/po/ocr-parse', requireBuyerAuth, async (req: AuthRequest, res) => {
    try {
    const customerId = req.buyer?.customerId;
    if (!customerId) return sendAuthenticationError(res, 'BUYER_PROFILE_REQUIRED');
    const customer = await prisma.customer.findUnique({ where: { id: customerId }, select: { status: true } });
    if (!customer || customer.status !== 'approved') return sendAccessDenied(res, 'BUYER_KYC_NOT_APPROVED');
    const rawContent = typeof req.body?.text === 'string' ? req.body.text : '';
    if (rawContent.length > 50000) return res.status(400).json({ success: false, error: 'OCR_TEXT_TOO_LONG' });
    const authorizedVisibility = await getAuthorizedProductVisibility(req);
    const dbProducts = await prisma.product.findMany({
      where: {
        lifecycleStatus: 'published',
        merchant: PUBLIC_STOREFRONT_MERCHANT_FILTER,
        AND: [{ OR: authorizedVisibility }]
      }
    });
    const products: Product[] = dbProducts.map(serializePublicProductRow);
    const lines = rawContent.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

    const matchedItems: any[] = [];
    const exceptions: any[] = [];
    let estimatedTotalAmount = 0;
    let totalQty = 0;

    for (const line of lines) {
      if (line.startsWith('#') || (line.includes('款号') && line.includes('数量'))) {
        continue;
      }

      const tokens = line.split(/[\t,，\s|]+/).filter(Boolean);
      if (tokens.length < 2) continue;

      let foundProduct: Product | undefined;
      let matchedQty = 0;
      let detectedColor = '';
      let detectedSize = '';

      for (const token of tokens) {
        const p = products.find(prod =>
          prod.styleNo.toLowerCase().includes(token.toLowerCase()) ||
          token.toLowerCase().includes(prod.styleNo.toLowerCase()) ||
          prod.name.toLowerCase().includes(token.toLowerCase())
        );
        if (p) {
          foundProduct = p;
          break;
        }
      }

      for (let i = tokens.length - 1; i >= 0; i--) {
        const num = parseInt(tokens[i], 10);
        if (!isNaN(num) && num > 0 && num < 10000 && !tokens[i].includes('-')) {
          matchedQty = num;
          break;
        }
      }
      if (matchedQty === 0) matchedQty = 6;

      for (const token of tokens) {
        const upper = token.toUpperCase();
        if (['XS', 'S', 'M', 'L', 'XL', 'XXL', '38', '39', '40', '41', '42', '43', '44', '45', 'ONE SIZE'].includes(upper)) {
          detectedSize = upper;
          break;
        }
      }

      for (const token of tokens) {
        if (['黑', '黑色', '白', '白色', '驼色', '红', '米色', '军绿', '深咖', 'NERO', 'BIANCO', 'CAMMELLO', 'ROSSO'].some(c => token.toUpperCase().includes(c))) {
          detectedColor = token;
          break;
        }
      }

      if (foundProduct) {
        const defaultSku = foundProduct.skus.find(s =>
          (detectedSize && s.size.toUpperCase() === detectedSize) ||
          (detectedColor && s.color.toUpperCase().includes(detectedColor.toUpperCase()))
        ) || foundProduct.skus[0];

        const isMoqMet = matchedQty >= (foundProduct.moq || 1);
        const subtotal = (foundProduct.wholesalePrice || 0) * matchedQty;

        const itemRecord = {
          rawLine: line,
          productId: foundProduct.id,
          styleNo: foundProduct.styleNo,
          productName: foundProduct.name,
          brand: foundProduct.brand,
          image: foundProduct.images[0] || '',
          sku: defaultSku?.sku || `${foundProduct.styleNo}-DEFAULT`,
          color: defaultSku?.color || detectedColor || '标准色',
          size: defaultSku?.size || detectedSize || 'M',
          quantity: matchedQty,
          unitPrice: foundProduct.wholesalePrice || 0,
          subtotal,
          packSize: foundProduct.packSize || 6,
          moq: foundProduct.moq || 6,
          isMoqMet,
          matched: true,
          status: isMoqMet ? 'valid' : 'moq_warning'
        };

        matchedItems.push(itemRecord);
        totalQty += matchedQty;
        estimatedTotalAmount += subtotal;

        if (!isMoqMet) {
          exceptions.push({
            rawLine: line,
            type: 'moq_below',
            message: `款号 ${foundProduct.styleNo} 最低起订量为 ${foundProduct.moq} 件，当前填报为 ${matchedQty} 件，建议按包配齐`,
            item: itemRecord
          });
        }
      } else {
        exceptions.push({
          rawLine: line,
          type: 'unmatched_style',
          message: `未在平台现货库中找到款号或商品名匹配项，建议人工核验或选择替代款`,
          suggestedProducts: products.slice(0, 2)
        });
      }
    }

    res.json({
      success: true,
      summary: {
        totalLines: lines.length,
        matchedCount: matchedItems.length,
        exceptionCount: exceptions.length,
        totalQty,
        estimatedTotalAmount
      },
      matchedItems,
      exceptions
    });
    } catch (error) {
      sendInternalError(res, error, 'purchase-order-ocr-parse');
    }
  });

  const normalizePromotionCode = (value: unknown) => (
    typeof value === 'string' && value.trim() ? value.trim().toUpperCase().slice(0, 80) : ''
  );
  const isPromotionActive = (promotion: {
    isActive: boolean;
    startsAt: Date;
    expiresAt: Date | null;
    appliesOn: string;
  }, now = new Date()) => (
    promotion.isActive
    && promotion.startsAt <= now
    && (!promotion.expiresAt || promotion.expiresAt > now)
    && ['wholesale', 'both'].includes(promotion.appliesOn)
  );
  const getPromotionCalculationRule = (promotion: {
    type: string;
    scope: string;
    appliesOn: string;
    minSubtotal: Prisma.Decimal | null;
    minQty: number | null;
    percentOff: Prisma.Decimal | null;
    fixedAmountOff: Prisma.Decimal | null;
    buyQty: number | null;
    getQty: number | null;
    getPercentOff: Prisma.Decimal | null;
    tiersJson: string | null;
    merchantIds: string[];
    categoryIds: string[];
    productIds: string[];
    excludeSaleItems: boolean;
  }) => ({
    type: promotion.type as 'percent_discount' | 'fixed_amount' | 'buy_x_get_y' | 'free_shipping' | 'tiered_discount' | 'bundle_deal',
    scope: promotion.scope as 'sitewide' | 'merchant' | 'category' | 'product' | 'consumer_tier',
    appliesOn: promotion.appliesOn as 'retail' | 'wholesale' | 'both',
    minSubtotal: promotion.minSubtotal === null ? null : Number(promotion.minSubtotal),
    minQty: promotion.minQty,
    percentOff: promotion.percentOff === null ? null : Number(promotion.percentOff),
    fixedAmountOff: promotion.fixedAmountOff === null ? null : Number(promotion.fixedAmountOff),
    buyQty: promotion.buyQty,
    getQty: promotion.getQty,
    getPercentOff: promotion.getPercentOff === null ? null : Number(promotion.getPercentOff),
    tiers: parseStoredJson<Array<{ thresholdQty?: number; thresholdAmount?: number; percentOff: number }>>(promotion.tiersJson, []),
    merchantIds: promotion.merchantIds,
    categoryIds: promotion.categoryIds,
    productIds: promotion.productIds,
    excludeSaleItems: promotion.excludeSaleItems
  });

  app.post('/api/promotions/quote', requireBuyerAuth, async (req: AuthRequest, res) => {
    try {
      const customerId = req.buyer?.customerId;
      if (!customerId) return sendAuthenticationError(res, 'BUYER_PROFILE_REQUIRED');
      const customer = await prisma.customer.findUnique({ where: { id: customerId } });
      if (!customer || customer.status !== 'approved') return sendAccessDenied(res, 'BUYER_KYC_NOT_APPROVED');
      const code = normalizePromotionCode(req.body?.code);
      const requestedItems = req.body?.items;
      if (!code || !Array.isArray(requestedItems) || requestedItems.length === 0 || requestedItems.length > 100) {
        return res.status(400).json({ success: false, error: 'PROMOTION_QUOTE_INPUT_INVALID' });
      }
      const promotion = await prisma.promotionRule.findUnique({ where: { code } });
      if (!promotion || !isPromotionActive(promotion)) return res.status(404).json({ success: false, error: 'PROMOTION_CODE_INVALID_OR_INACTIVE' });
      if (promotion.totalUsageLimit !== null && promotion.totalUsedCount >= promotion.totalUsageLimit) {
        return res.status(409).json({ success: false, error: 'PROMOTION_USAGE_LIMIT_REACHED' });
      }
      if (promotion.usageLimitPerConsumer !== null) {
        const priorRedemptions = await prisma.couponRedemption.findMany({
          where: { promotionId: promotion.id, consumerId: customerId },
          select: { parentOrderNo: true, orderId: true }
        });
        if (new Set(priorRedemptions.map(item => item.parentOrderNo || item.orderId)).size >= promotion.usageLimitPerConsumer) {
          return res.status(409).json({ success: false, error: 'PROMOTION_CUSTOMER_USAGE_LIMIT_REACHED' });
        }
      }
      const productIds = [...new Set(requestedItems.map((item: any) => String(item?.productId || '')).filter(Boolean))];
      const authorizedVisibility = await getAuthorizedProductVisibility(req);
      const products = await prisma.product.findMany({
        where: {
          id: { in: productIds },
          lifecycleStatus: 'published',
          merchant: PUBLIC_STOREFRONT_MERCHANT_FILTER,
          AND: [{ OR: authorizedVisibility }]
        }
      });
      if (products.length !== productIds.length) return res.status(409).json({ success: false, error: 'PRODUCT_NOT_AVAILABLE' });
      const productById = new Map(products.map(product => [product.id, product]));
      const calculationItems = requestedItems.map((item: any) => {
        const product = productById.get(String(item.productId));
        const quantity = Number(item.quantity);
        if (!product || !product.merchantId || !Number.isInteger(quantity) || quantity <= 0) throw new Error('PROMOTION_QUOTE_INPUT_INVALID');
        const sku = parseStoredJson<any[]>(product.skus, []).find(candidate => candidate.sku === String(item.sku));
        if (!sku) throw new Error('SKU_NOT_AVAILABLE');
        return {
          productId: product.id,
          merchantId: product.merchantId,
          categoryId: product.category,
          quantity,
          unitPrice: Number((Number(product.wholesalePrice) * Number(customer.discountRate || 1)).toFixed(2)),
          isSaleItem: Boolean(sku.isOnSale)
        };
      });
      const subtotal = calculationItems.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0);
      const shippingFee = req.body?.deliveryType === 'showroom_pickup' || subtotal > 1000 ? 0 : 45;
      const calculationRule = getPromotionCalculationRule(promotion);
      const shippingEligible = calculationRule.scope !== 'merchant'
        || calculationRule.merchantIds?.includes(calculationItems[0]?.merchantId);
      const calculation = calculatePromotion(calculationRule, calculationItems, shippingEligible ? shippingFee : 0);
      const discountAmount = Number((calculation.discountAmount + calculation.shippingDiscount).toFixed(2));
      if (discountAmount <= 0) return res.status(422).json({ success: false, error: 'PROMOTION_NOT_APPLICABLE' });
      res.json({
        success: true,
        code,
        name: promotion.name,
        subtotal: Number(subtotal.toFixed(2)),
        shippingFee,
        discountAmount,
        shippingDiscount: calculation.shippingDiscount,
        totalAmount: Number(Math.max(0, subtotal + shippingFee - discountAmount).toFixed(2))
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : '';
      if (['PROMOTION_QUOTE_INPUT_INVALID', 'SKU_NOT_AVAILABLE'].includes(message)) {
        return res.status(400).json({ success: false, error: message });
      }
      sendInternalError(res, error, 'promotion-quote');
    }
  });

  // POST /api/orders — authoritative multi-merchant order creation
  app.post('/api/orders', requireBuyerAuth, async (req: AuthRequest, res) => {
    try {
      const input = req.body || {};
      if (input.miniprogram === true
        && (input.acceptedTerms !== true || input.acceptedPrivacy !== true)) {
        return res.status(400).json({ success: false, error: 'LEGAL_CONSENT_REQUIRED' });
      }
      const master = input.masterOrder;
      const subOrders = Array.isArray(input.subOrders) && input.subOrders.length ? input.subOrders : [master];
      if (!master || !Array.isArray(master.items) || master.items.length === 0) {
        return res.status(400).json({ success: false, error: 'ORDER_ITEMS_REQUIRED' });
      }

      const customerId = req.buyer?.customerId;
      const customer = customerId ? await prisma.customer.findUnique({ where: { id: customerId } }) : null;
      if (!customer) return sendAuthenticationError(res, 'BUYER_PROFILE_REQUIRED');
      if (customer.status !== 'approved') return sendAccessDenied(res, 'BUYER_KYC_NOT_APPROVED');
      const requestedPromotionCode = normalizePromotionCode(master.promotionCode);
      const singleItemClaims = typeof input.singleItemToken === 'string'
        ? readSingleItemCheckoutToken(input.singleItemToken)
        : null;
      if (input.singleItemToken && !singleItemClaims) return res.status(400).json({ success: false, error: 'SINGLE_ITEM_LINK_INVALID_OR_EXPIRED' });
      if (singleItemClaims && requestedPromotionCode) return res.status(400).json({ success: false, error: 'PROMOTION_NOT_AVAILABLE_FOR_SINGLE_ITEM_CHECKOUT' });
      const requestedPaymentMethod = String(master.paymentMethod || '');
      let solanaPlatformWallet: string | null = null;
      if (requestedPaymentMethod === 'solana_pay') {
        if (master.solanaToken !== 'USDC' && master.solanaToken !== 'EURC') {
          return res.status(400).json({ success: false, error: 'SOLANA_TOKEN_INVALID' });
        }
        try {
          if (!process.env.APP_URL || new URL(process.env.APP_URL).protocol !== 'https:') {
            throw new Error('SOLANA_TRANSACTION_REQUEST_URL_INVALID');
          }
          solanaPlatformWallet = getSolanaPlatformWalletAddress();
          await assertSolanaMainnet();
        } catch (error) {
          const reason = error instanceof Error ? error.message : 'SOLANA_RPC_UNAVAILABLE';
          console.error('[solana-mainnet-check]', reason);
          return res.status(503).json({
            success: false,
            error: ['SOLANA_PLATFORM_WALLET_NOT_CONFIGURED', 'SOLANA_WALLET_ADDRESS_INVALID', 'SOLANA_TRANSACTION_REQUEST_URL_INVALID', 'SOLANA_RPC_NOT_CONFIGURED', 'SOLANA_RPC_URL_INVALID', 'SOLANA_RPC_NOT_MAINNET'].includes(reason)
              ? reason
              : 'SOLANA_RPC_UNAVAILABLE'
          });
        }
      }
      const requestItems = subOrders.flatMap((order: any) => Array.isArray(order?.items) ? order.items : []);
      if (singleItemClaims && (
        requestItems.length !== 1 ||
        Number(requestItems[0]?.quantity) !== 1 ||
        String(requestItems[0]?.productId) !== singleItemClaims.productId ||
        String(requestItems[0]?.sku) !== singleItemClaims.sku ||
        !['credit_card', 'paypal', 'stripe'].includes(requestedPaymentMethod)
      )) {
        return res.status(400).json({ success: false, error: 'SINGLE_ITEM_ORDER_MISMATCH' });
      }
      if (singleItemClaims && requestedPaymentMethod === 'credit_card' && !getPaymentIntegrationStatus().supportsPayments) {
        return res.status(503).json({ success: false, error: 'ONLINE_PAYMENT_NOT_CONFIGURED' });
      }

      const existingOrders = await prisma.order.findMany({
        where: { customerId, OR: [{ orderNo: String(master.orderNo) }, { parentOrderNo: String(master.orderNo) }] },
        include: { items: true }
      });
      if (existingOrders.length > 0) {
        const existingIntent = requestedPaymentMethod === 'solana_pay'
          ? await prisma.solanaPaymentIntent.findUnique({ where: { orderId: existingOrders[0].id } })
          : null;
        return res.status(200).json({
          success: true,
          orders: existingOrders,
          totalQty: existingOrders.reduce((sum, order) => sum + order.totalQty, 0),
          totalAmount: existingOrders.reduce((sum, order) => sum + Number(order.totalAmount), 0),
          idempotentReplay: true,
          ...(existingIntent ? {
            payment: {
              status: existingIntent.status === 'paid' ? 'paid' : 'pending',
              solana: serializeSolanaPaymentIntent(existingIntent, existingOrders[0].orderNo)
            }
          } : {})
        });
      }

      const created = await prisma.$transaction(async tx => {
        const partnerReferral = customerId
          ? await tx.partnerReferral.findUnique({
            where: { customerId },
            select: { id: true, partnerId: true, cityPartnerId: true, networkPartnerId: true }
          })
          : null;
        const allItems = subOrders.flatMap((order: any) => Array.isArray(order?.items) ? order.items : []);
        const quantityByProduct = new Map<string, number>();
        for (const item of allItems) {
          const quantity = Number(item.quantity);
          if (!Number.isInteger(quantity) || quantity <= 0) throw new Error('INVALID_ITEM_QUANTITY');
          const productId = String(item.productId);
          quantityByProduct.set(productId, (quantityByProduct.get(productId) || 0) + quantity);
        }
        const productIds: string[] = [...new Set(allItems.map((item: any) => String(item.productId)))] as string[];
        const products = await tx.product.findMany({ where: { id: { in: productIds }, lifecycleStatus: 'published' } });
        const productById = new Map(products.map(product => [product.id, product]));
        for (const [productId, quantity] of quantityByProduct) {
          const product = productById.get(productId);
          if (!product) continue;
          if (!singleItemClaims && quantity < product.moq) throw new Error('MOQ_NOT_MET');
          if (product.requiresFullCarton && quantity % product.packSize !== 0) throw new Error('CARTON_MULTIPLE_REQUIRED');
        }
        const stockByProduct = new Map<string, any>();
        const normalizedStockBySku = new Map<string, { central: number }>();
        const inventoryVersions = new Map(products.map(product => [product.id, product.inventoryVersion]));
        const stockMovements: Array<{ id: string; productId: string; sku: string; location: 'central'; quantity: number; referenceId: string; merchantId: string | null }> = [];
        const itemsByMerchant = new Map<string, { merchantName: string | null; items: any[] }>();
        let calculatedTotal = 0;
        let calculatedQty = 0;

        for (const item of allItems) {
          const product = productById.get(String(item.productId));
          if (!product) throw new Error('PRODUCT_NOT_AVAILABLE');
          if (product.id.startsWith('demo-showroom-product-sale-')) throw new Error('SHOWCASE_PRODUCT_ORDER_DISABLED');
          if (!product.merchantId) throw new Error('PRODUCT_MERCHANT_REQUIRED');
          const quantity = Number(item.quantity);
          if (!Number.isInteger(quantity) || quantity <= 0) throw new Error('INVALID_ITEM_QUANTITY');
          const authorizedSingleItem = Boolean(
            singleItemClaims &&
            singleItemClaims.productId === product.id &&
            singleItemClaims.merchantId === product.merchantId &&
            singleItemClaims.sku === String(item.sku) &&
            quantity === 1 &&
            allItems.length === 1
          );
          if (singleItemClaims && !authorizedSingleItem) throw new Error('SINGLE_ITEM_ORDER_MISMATCH');

          const skus = stockByProduct.get(product.id) || parseStoredJson<any[]>(product.skus, []);
          const sku = skus.find((candidate: any) => candidate.sku === item.sku);
          if (!sku || sku.isActive === false) throw new Error('SKU_NOT_AVAILABLE');
          const normalizedSkuKey = `${product.id}:${String(item.sku)}`;
          let normalizedStock = normalizedStockBySku.get(normalizedSkuKey);
          if (!normalizedStock) {
            const variant = await tx.productVariant.findUnique({
              where: { productId_sku: { productId: product.id, sku: String(item.sku) } },
              include: { inventoryBalances: { include: { location: { select: { code: true } } } } }
            });
            if (!variant) throw new Error('INVENTORY_BALANCE_NOT_FOUND');
            normalizedStock = { central: 0 };
            for (const balance of variant.inventoryBalances) {
              if (balance.location.code === 'central') normalizedStock.central += balance.onHandQuantity - balance.reservedQuantity;
            }
            normalizedStockBySku.set(normalizedSkuKey, normalizedStock);
          }
          const isPrivate = product.visibility === 'private' || product.isExclusiveProtected;
          if (isPrivate) {
            const vaultAccess = await tx.vaultAccessRequest.findMany({
              where: { merchantId: product.merchantId, customerId, status: 'approved' },
              select: { status: true, expiresAt: true }
            });
            if (!vaultAccess.some(access => isActiveVaultAuthorization(access.status, access.expiresAt))) {
              throw new Error('PRIVATE_PRODUCT_NOT_AUTHORIZED');
            }
          }
          const totalStock = normalizedStock.central;
          if (totalStock < quantity) throw new Error('INSUFFICIENT_STOCK');

          let remaining = quantity;
          const deducted = Math.min(normalizedStock.central, remaining);
          normalizedStock.central -= deducted;
          {
            const location = 'stockCentral';
            const movementLocation = 'central' as const;
            sku[location] = Math.max(0, Number(sku[location] || 0) - deducted);
            if (deducted > 0) {
              stockMovements.push({
                id: crypto.randomUUID(),
                productId: product.id,
                sku: String(item.sku),
                location: movementLocation,
                quantity: -deducted,
                referenceId: String(master.orderNo),
                merchantId: product.merchantId
              });
            }
            remaining -= deducted;
          }
          stockByProduct.set(product.id, skus);
          const merchantItems = itemsByMerchant.get(product.merchantId) || {
            merchantName: product.merchantName,
            items: []
          };
          merchantItems.items.push(item);
          itemsByMerchant.set(product.merchantId, merchantItems);
          const productWholesalePrice = getProductWholesalePriceForQuantity(
            Number(product.wholesalePrice),
            product.wholesalePrice100 === null ? null : Number(product.wholesalePrice100),
            quantityByProduct.get(product.id) || quantity,
            product.bulkPriceMinimumQuantity
          );
          const unitPrice = Number((productWholesalePrice * Number(customer.discountRate || 1)).toFixed(2));
          calculatedTotal += unitPrice * quantity;
          calculatedQty += quantity;
        }

        const paymentMethod = String(master.paymentMethod || '');
        if (paymentMethod === 'paypal') {
          if (itemsByMerchant.size !== 1) throw new Error('PAYPAL_SINGLE_MERCHANT_ONLY');
          const merchantId = itemsByMerchant.keys().next().value as string | undefined;
          const config = merchantId
            ? await tx.merchantPayPalConfig.findUnique({ where: { merchantId }, select: { enabled: true } })
            : null;
          if (!config?.enabled) throw new Error('PAYPAL_MERCHANT_NOT_CONFIGURED');
        }
        if (paymentMethod === 'stripe') {
          if (itemsByMerchant.size !== 1) throw new Error('STRIPE_SINGLE_MERCHANT_ONLY');
          const merchantId = itemsByMerchant.keys().next().value as string | undefined;
          const config = merchantId
            ? await tx.merchantStripeConfig.findUnique({ where: { merchantId }, select: { enabled: true } })
            : null;
          if (!config?.enabled) throw new Error('STRIPE_MERCHANT_NOT_CONFIGURED');
        }
        if (paymentMethod === 'solana_pay') {
          if (itemsByMerchant.size !== 1) throw new Error('SOLANA_SINGLE_MERCHANT_ONLY');
          const merchantId = itemsByMerchant.keys().next().value as string | undefined;
          const config = merchantId
            ? await tx.merchantSolanaConfig.findUnique({ where: { merchantId }, select: { enabled: true, walletAddress: true, commissionRate: true } })
            : null;
          if (!config?.enabled) throw new Error('SOLANA_MERCHANT_NOT_CONFIGURED');
          if (config.walletAddress === solanaPlatformWallet) throw new Error('SOLANA_PLATFORM_WALLET_CONFLICT');
        }
        const usesNet30 = paymentMethod === 'net_30' || paymentMethod === 'net_30_days';
        const shippingFee = String(master.deliveryType) === 'showroom_pickup' ? 0 : (calculatedTotal > 1000 ? 0 : 45);
        const grossSubtotal = calculatedTotal;
        const merchantDiscounts = new Map<string, number>();
        let promotion: Awaited<ReturnType<typeof tx.promotionRule.findUnique>> = null;
        let shippingDiscount = 0;
        if (requestedPromotionCode) {
          promotion = await tx.promotionRule.findUnique({ where: { code: requestedPromotionCode } });
          if (!promotion || !isPromotionActive(promotion)) throw new Error('PROMOTION_CODE_INVALID_OR_INACTIVE');
          const promotionItems = allItems.map((item: any) => {
            const product = productById.get(String(item.productId));
            if (!product || !product.merchantId) throw new Error('PRODUCT_NOT_AVAILABLE');
            const sku = parseStoredJson<any[]>(product.skus, []).find(candidate => candidate.sku === String(item.sku));
            if (!sku) throw new Error('SKU_NOT_AVAILABLE');
            return {
              productId: product.id,
              merchantId: product.merchantId,
              categoryId: product.category,
              quantity: Number(item.quantity),
              unitPrice: Number((getProductWholesalePriceForQuantity(
                Number(product.wholesalePrice),
                product.wholesalePrice100 === null ? null : Number(product.wholesalePrice100),
                quantityByProduct.get(product.id) || Number(item.quantity),
                product.bulkPriceMinimumQuantity
              ) * Number(customer.discountRate || 1)).toFixed(2)),
              isSaleItem: Boolean(sku.isOnSale)
            };
          });
          const calculationRule = getPromotionCalculationRule(promotion);
          const shippingEligible = calculationRule.scope !== 'merchant'
            || calculationRule.merchantIds?.includes(promotionItems[0]?.merchantId);
          const calculation = calculatePromotion(calculationRule, promotionItems, shippingEligible ? shippingFee : 0);
          const discountAmount = Number((calculation.discountAmount + calculation.shippingDiscount).toFixed(2));
          if (discountAmount <= 0) throw new Error('PROMOTION_NOT_APPLICABLE');
          calculation.itemDiscounts.forEach((amount, index) => {
            const merchantId = promotionItems[index].merchantId;
            merchantDiscounts.set(merchantId, Number(((merchantDiscounts.get(merchantId) || 0) + amount).toFixed(2)));
          });
          shippingDiscount = calculation.shippingDiscount;

          await tx.$queryRaw(Prisma.sql`SELECT pg_advisory_xact_lock(hashtext(${promotion.id}), hashtext(${customerId}))`);
          if (promotion.usageLimitPerConsumer !== null) {
            const priorRedemptions = await tx.couponRedemption.findMany({
              where: { promotionId: promotion.id, consumerId: customerId },
              select: { parentOrderNo: true, orderId: true }
            });
            const usedParentOrders = new Set(priorRedemptions.map(redemption => redemption.parentOrderNo || redemption.orderId));
            if (usedParentOrders.size >= promotion.usageLimitPerConsumer) throw new Error('PROMOTION_CUSTOMER_USAGE_LIMIT_REACHED');
          }
          const updatedPromotion = await tx.promotionRule.updateMany({
            where: {
              id: promotion.id,
              isActive: true,
              startsAt: { lte: new Date() },
              AND: [
                { OR: [{ expiresAt: null }, { expiresAt: { gt: new Date() } }] },
                ...(promotion.totalUsageLimit === null ? [] : [{ totalUsedCount: { lt: promotion.totalUsageLimit } }])
              ]
            },
            data: { totalUsedCount: { increment: 1 } }
          });
          if (updatedPromotion.count !== 1) throw new Error('PROMOTION_USAGE_LIMIT_REACHED');
        }
        const totalDiscount = Number(([...merchantDiscounts.values()].reduce((sum, amount) => sum + amount, 0) + shippingDiscount).toFixed(2));
        const orderTotal = Number(Math.max(0, grossSubtotal + shippingFee - totalDiscount).toFixed(2));
        if (usesNet30) {
          const openCredit = await tx.order.aggregate({
            where: { customerId, paymentMethod: 'net_30', status: { notIn: ['returned', 'cancelled'] } },
            _sum: { totalAmount: true }
          });
          const usedCredit = Number(customer.usedCredit || 0) + Number(openCredit._sum.totalAmount || 0);
          if (orderTotal > Number(customer.creditLimit) - usedCredit) throw new Error('CREDIT_LIMIT_EXCEEDED');
        }

        for (const [productId, skus] of stockByProduct) {
          const expectedVersion = inventoryVersions.get(productId);
          const updated = await tx.product.updateMany({
            where: { id: productId, inventoryVersion: expectedVersion },
            data: { skus: JSON.stringify(skus), inventoryVersion: { increment: 1 } }
          });
          if (updated.count !== 1) throw new Error('INVENTORY_CONCURRENT_UPDATE');
        }
        if (stockMovements.length) {
          await tx.stockMovement.createMany({
            data: stockMovements.map(({ merchantId: _merchantId, ...movement }) => ({
              ...movement,
              movementType: 'sale',
              operatorId: customerId
            }))
          });
          await applyInventoryLedgerChanges(tx, stockMovements.map(movement => ({
            productId: movement.productId,
            sku: movement.sku,
            locationCode: movement.location,
            merchantId: movement.merchantId,
            onHandDelta: movement.quantity,
            movementType: 'sale',
            referenceType: 'Order',
            referenceId: movement.referenceId,
            operatorId: customerId
          })));
        }

        const createdOrders = [];
        let merchantOrderIndex = 0;
        for (const [merchantId, merchantOrder] of itemsByMerchant) {
          merchantOrderIndex += 1;
          const orderItems = merchantOrder.items.map((item: any) => {
            const product = productById.get(String(item.productId))!;
            const productWholesalePrice = getProductWholesalePriceForQuantity(
              Number(product.wholesalePrice),
              product.wholesalePrice100 === null ? null : Number(product.wholesalePrice100),
              quantityByProduct.get(product.id) || Number(item.quantity),
              product.bulkPriceMinimumQuantity
            );
            const unitPrice = Number((productWholesalePrice * Number(customer.discountRate || 1)).toFixed(2));
            return {
              productId: product.id,
              styleNo: product.styleNo,
              productName: product.name,
              image: JSON.parse(product.images)[0] || '',
              sku: String(item.sku), color: String(item.color || ''), size: String(item.size || ''),
              quantity: Number(item.quantity), unitPrice, packSize: product.packSize,
              pricingSnapshot: JSON.stringify({
                styleQuantity: quantityByProduct.get(product.id) || Number(item.quantity),
                bulkMinimumQuantity: product.bulkPriceMinimumQuantity,
                baseWholesalePrice: Number(product.wholesalePrice),
                bulkWholesalePrice: product.wholesalePrice100 === null ? null : Number(product.wholesalePrice100),
                bulkPriceApplied: product.wholesalePrice100 !== null &&
                  (quantityByProduct.get(product.id) || Number(item.quantity)) >= product.bulkPriceMinimumQuantity,
                customerDiscountRate: Number(customer.discountRate || 1),
                unitPrice
              }),
              merchantId: product.merchantId, merchantName: product.merchantName
            };
          });
          const itemSubtotal = orderItems.reduce((sum: number, item: any) => sum + item.quantity * item.unitPrice, 0);
          const merchantShippingFee = merchantOrderIndex === 1 ? shippingFee : 0;
          const merchantShippingDiscount = merchantOrderIndex === 1 ? shippingDiscount : 0;
          const merchantDiscount = Number(((merchantDiscounts.get(merchantId) || 0) + merchantShippingDiscount).toFixed(2));
          const totalAmount = Number(Math.max(0, itemSubtotal + merchantShippingFee - merchantDiscount).toFixed(2));
          const saved = await tx.order.create({
            data: {
              id: crypto.randomUUID(),
              orderNo: `${String(master.orderNo)}-${merchantOrderIndex}`,
              date: String(master.date),
              customerId,
              partnerReferralId: partnerReferral?.id || null,
              partnerId: partnerReferral?.partnerId || null,
              partnerCityAgentId: partnerReferral?.cityPartnerId || null,
              partnerNetworkId: partnerReferral?.networkPartnerId || null,
              companyName: customer.companyName, totalQty: orderItems.reduce((sum: number, item: any) => sum + item.quantity, 0),
              totalAmount, shippingFee: merchantShippingFee, discountAmount: merchantDiscount,
              promotionCode: merchantDiscount > 0 ? requestedPromotionCode : null,
              status: 'pending', deliveryType: String(master.deliveryType), pickupLocation: master.pickupLocation || null,
              paymentMethod, paymentStatus: ['credit_card', 'paypal', 'stripe', 'solana_pay'].includes(paymentMethod) ? 'pending' : 'pending_credit',
              trackingNumber: null, carrier: null, timeline: JSON.stringify(master.timeline || []),
              shippingStreet: master.shippingAddress?.street || '', shippingCity: master.shippingAddress?.city || '',
              shippingCountry: master.shippingAddress?.country || '', shippingZip: master.shippingAddress?.zip || '',
              notes: master.notes || null, merchantId, merchantName: merchantOrder.merchantName,
              idempotencyKey: `${String(master.orderNo)}:${merchantId}`,
              parentOrderNo: String(master.orderNo), items: { create: orderItems }
            }, include: { items: true }
          });
          createdOrders.push(saved);
          if (promotion && merchantDiscount > 0) {
            await tx.couponRedemption.create({
              data: {
                id: crypto.randomUUID(),
                promotionId: promotion.id,
                code: requestedPromotionCode,
                orderId: saved.id,
                consumerId: customerId,
                parentOrderNo: String(master.orderNo),
                discountAmount: merchantDiscount
              }
            });
          }
        }
        if (modaGptBrainEnabled) {
          await enqueueModaGptEventsInTransaction(tx, createdOrders.map(order => ({
                type: 'order.created',
                eventId: order.id,
                merchantId: order.merchantId,
                occurredAt: order.createdAt.toISOString(),
                data: {
                  orderId: order.id,
                  orderNo: order.orderNo,
                  totalUnits: order.totalQty,
                  totalAmount: Number(order.totalAmount),
                  currency: 'EUR'
                }
              })));
        }
        if (usesNet30 && calculatedTotal > 0) {
          await tx.creditLedgerEntry.create({
            data: {
              id: crypto.randomUUID(),
              customerId,
              orderId: createdOrders[0]?.id,
              entryType: 'order_hold',
              amount: orderTotal,
              balanceAfter: Number(customer.usedCredit || 0) + orderTotal,
              note: `Net 30 order ${master.orderNo}`
            }
          });
        }
        return { createdOrders, calculatedTotal: orderTotal, calculatedQty, shippingFee };
      }, { isolationLevel: Prisma.TransactionIsolationLevel.Serializable });

      logAudit(customer.email, 'system', 'ORDER_CREATED', 'Order', String(master.orderNo), '', `qty=${created.calculatedQty}; total=${created.calculatedTotal.toFixed(2)}`);
      await Promise.all(created.createdOrders.map(order => ensureOrderInvoice(order.id)));
      enqueueNotification('order.created', customer.email, {
        referenceId: String(master.orderNo),
        orderNo: String(master.orderNo),
        totalAmount: created.calculatedTotal,
        currency: 'EUR'
      }, ['email', 'in_app']);
      let payment: { status: string; providerReference?: string; checkoutUrl?: string; solana?: ReturnType<typeof serializeSolanaPaymentIntent> } | undefined;
      if (requestedPaymentMethod === 'paypal') {
        try {
          const order = created.createdOrders[0];
          if (!order?.merchantId || created.createdOrders.length !== 1) throw new Error('PAYPAL_SINGLE_MERCHANT_ONLY');
          const credentials = await getMerchantPayPalCredentials(order.merchantId);
          if (!credentials) throw new Error('PAYPAL_MERCHANT_NOT_CONFIGURED');
          const baseUrl = process.env.APP_URL || `${req.protocol}://${req.get('host')}`;
          const checkout = await createPayPalCheckout(credentials, {
            amount: created.calculatedTotal,
            currency: 'EUR',
            reference: String(master.orderNo),
            description: `RUDA order ${master.orderNo}`,
            returnUrl: `${baseUrl}/account?paypal=return&order=${encodeURIComponent(String(master.orderNo))}`,
            cancelUrl: `${baseUrl}/account?paypal=cancelled&order=${encodeURIComponent(String(master.orderNo))}`
          });
          payment = { status: 'pending', providerReference: checkout.orderId, checkoutUrl: checkout.approvalUrl };
          await prisma.paymentTransaction.create({
            data: {
              id: crypto.randomUUID(),
              orderId: order.id,
              provider: 'paypal',
              providerPaymentId: checkout.orderId,
              amount: order.totalAmount,
              currency: 'EUR',
              status: 'pending',
              idempotencyKey: `payment:paypal:${String(master.orderNo)}:${order.id}`,
              metadata: JSON.stringify({
                parentOrderNo: String(master.orderNo),
                merchantId: order.merchantId,
                environment: credentials.environment
              })
            }
          });
        } catch (paymentError) {
          payment = { status: 'failed' };
          await cancelUnpaidOrdersAndReleaseInventory(created.createdOrders.map(order => order.id), 'paypal-payment-create-failed');
          console.error('[paypal-payment-create]', paymentError instanceof Error ? paymentError.message : paymentError);
        }
      } else if (requestedPaymentMethod === 'stripe') {
        try {
          const order = created.createdOrders[0];
          if (!order?.merchantId || created.createdOrders.length !== 1) throw new Error('STRIPE_SINGLE_MERCHANT_ONLY');
          const credentials = await getMerchantStripeCredentials(order.merchantId);
          if (!credentials) throw new Error('STRIPE_MERCHANT_NOT_CONFIGURED');
          const baseUrl = process.env.APP_URL || `${req.protocol}://${req.get('host')}`;
          const checkout = await createMerchantStripeCheckout(credentials, {
            amount: created.calculatedTotal,
            currency: 'EUR',
            reference: String(master.orderNo),
            description: `RUDA order ${master.orderNo}`,
            successUrl: `${baseUrl}/account?stripe=return&order=${encodeURIComponent(String(master.orderNo))}&session_id={CHECKOUT_SESSION_ID}`,
            cancelUrl: `${baseUrl}/account?stripe=cancelled&order=${encodeURIComponent(String(master.orderNo))}`
          }, `ruda-order-${crypto.createHash('sha256').update(String(master.orderNo)).digest('hex').slice(0, 48)}`);
          await prisma.paymentTransaction.create({
            data: {
              id: crypto.randomUUID(),
              orderId: order.id,
              provider: 'merchant_stripe',
              providerPaymentId: checkout.sessionId,
              amount: order.totalAmount,
              currency: 'EUR',
              status: 'pending',
              idempotencyKey: `payment:merchant-stripe:${String(master.orderNo)}:${order.id}`,
              metadata: JSON.stringify({
                parentOrderNo: String(master.orderNo),
                merchantId: order.merchantId,
                stripeAccountId: credentials.accountId,
                livemode: credentials.livemode
              })
            }
          });
          payment = { status: 'pending', providerReference: checkout.sessionId, checkoutUrl: checkout.checkoutUrl };
        } catch (paymentError) {
          payment = { status: 'failed' };
          await cancelUnpaidOrdersAndReleaseInventory(created.createdOrders.map(order => order.id), 'stripe-payment-create-failed');
          console.error('[merchant-stripe-payment-create]', paymentError instanceof Error ? paymentError.message : paymentError);
        }
      } else if (requestedPaymentMethod === 'solana_pay') {
        try {
          const order = created.createdOrders[0];
          if (!order?.merchantId || created.createdOrders.length !== 1) throw new Error('SOLANA_SINGLE_MERCHANT_ONLY');
          const merchantConfig = await prisma.merchantSolanaConfig.findUnique({
            where: { merchantId: order.merchantId },
            select: { walletAddress: true, enabled: true, commissionRate: true }
          });
          if (!merchantConfig?.enabled) throw new Error('SOLANA_MERCHANT_NOT_CONFIGURED');
          const tokenSymbol = master.solanaToken as SolanaTokenSymbol;
          const rateQuote = tokenSymbol === 'USDC'
            ? await fetchLatestEurUsdRate()
            : { rate: 1, source: 'EURC/EUR nominal parity', updatedAt: new Date() };
          const quote = createSolanaTokenQuote(
            Number(order.totalAmount),
            tokenSymbol,
            rateQuote.rate,
            rateQuote.source,
            rateQuote.updatedAt
          );
          const commissionRate = merchantConfig.commissionRate.toString();
          const split = calculateSolanaCommissionSplit(quote.amountAtomic, commissionRate);
          const recipient = normalizeSolanaWalletAddress(merchantConfig.walletAddress);
          const quotedAt = new Date();
          const expiresAt = new Date(quotedAt.getTime() + 30 * 60 * 1000);
          const reference = createSolanaReference();
          const requestToken = crypto.randomBytes(32).toString('base64url');
          const requestTokenHash = crypto.createHash('sha256').update(requestToken).digest('hex');
          const intent = await prisma.$transaction(async tx => {
            await tx.paymentTransaction.create({
              data: {
                id: crypto.randomUUID(),
                orderId: order.id,
                provider: 'solana_pay',
                amount: order.totalAmount,
                currency: 'EUR',
                status: 'pending',
                idempotencyKey: `payment:solana:${order.id}`,
                metadata: JSON.stringify({
                  parentOrderNo: String(master.orderNo),
                  merchantId: order.merchantId,
                  tokenSymbol,
                  mint: quote.mint,
                  reference,
                  exchangeRate: quote.exchangeRate,
                  exchangeRateSource: quote.exchangeRateSource,
                  exchangeRateUpdatedAt: quote.exchangeRateUpdatedAt.toISOString(),
                  tokenAmount: quote.tokenAmount,
                  amountAtomic: quote.amountAtomic,
                  platformWallet: solanaPlatformWallet,
                  commissionRate: split.commissionRate,
                  merchantAmount: split.merchantAmount,
                  merchantAmountAtomic: split.merchantAmountAtomic,
                  commissionAmount: split.commissionAmount,
                  commissionAmountAtomic: split.commissionAmountAtomic
                })
              }
            });
            return tx.solanaPaymentIntent.create({
              data: {
                id: crypto.randomUUID(),
                orderId: order.id,
                merchantId: order.merchantId!,
                reference,
                requestTokenHash,
                requestTokenEncrypted: encryptSecret(requestToken),
                recipient,
                platformWallet: solanaPlatformWallet!,
                mint: quote.mint,
                tokenSymbol: quote.tokenSymbol,
                eurAmount: order.totalAmount,
                exchangeRate: quote.exchangeRate,
                exchangeRateSource: quote.exchangeRateSource,
                exchangeRateUpdatedAt: quote.exchangeRateUpdatedAt,
                tokenAmount: quote.tokenAmount,
                amountAtomic: quote.amountAtomic,
                commissionRate: split.commissionRate,
                merchantAmount: split.merchantAmount,
                merchantAmountAtomic: split.merchantAmountAtomic,
                commissionAmount: split.commissionAmount,
                commissionAmountAtomic: split.commissionAmountAtomic,
                quotedAt,
                expiresAt,
                status: 'pending'
              }
            });
          });
          payment = {
            status: 'pending',
            providerReference: reference,
            solana: serializeSolanaPaymentIntent(intent, order.orderNo)
          };
        } catch (paymentError) {
          payment = { status: 'failed' };
          const failedOrderId = created.createdOrders[0]?.id;
          if (failedOrderId) {
            await prisma.$transaction([
              prisma.paymentTransaction.updateMany({
                where: { orderId: failedOrderId, provider: 'solana_pay', status: 'pending' },
                data: { status: 'failed' }
              }),
              prisma.solanaPaymentIntent.updateMany({
                where: { orderId: failedOrderId, status: 'pending' },
                data: { status: 'expired' }
              })
            ]);
          }
          await cancelUnpaidOrdersAndReleaseInventory(created.createdOrders.map(order => order.id), 'solana-payment-create-failed');
          console.error('[solana-payment-create]', paymentError instanceof Error ? paymentError.message : paymentError);
        }
      } else if (requestedPaymentMethod === 'credit_card') {
        try {
          const baseUrl = process.env.APP_URL || `${req.protocol}://${req.get('host')}`;
          const paymentResult = await paymentProvider.createPayment({
            orderId: String(created.createdOrders[0]?.id),
            amount: created.calculatedTotal,
            currency: 'EUR',
            description: `RUDA order ${master.orderNo}`,
            successUrl: `${baseUrl}/account?payment=success&order=${encodeURIComponent(String(master.orderNo))}`,
            cancelUrl: `${baseUrl}/shop/${encodeURIComponent(String(created.createdOrders[0]?.merchantId || ''))}?payment=cancelled`
          });
          payment = paymentResult;
          await prisma.$transaction(async tx => {
            await tx.paymentTransaction.createMany({
              data: created.createdOrders.map(order => ({
                id: crypto.randomUUID(),
                orderId: order.id,
                provider: paymentProvider.id,
                providerPaymentId: paymentResult.providerReference || null,
                amount: order.totalAmount,
                currency: 'EUR',
                status: paymentResult.status === 'pending' ? 'pending' : 'failed',
                idempotencyKey: `payment:${String(master.orderNo)}:${order.id}`,
                metadata: JSON.stringify({
                  parentOrderNo: String(master.orderNo),
                  paymentReference: paymentResult.providerReference || null
                })
              }))
            });
            if (paymentResult.status === 'not_configured') {
              await tx.order.updateMany({ where: { id: { in: created.createdOrders.map(order => order.id) } }, data: { paymentStatus: 'payment_required' } });
            }
          });
        } catch (paymentError: any) {
          payment = { status: 'failed' };
          await prisma.order.updateMany({ where: { id: { in: created.createdOrders.map(order => order.id) } }, data: { paymentStatus: 'payment_failed' } });
          console.error('[payment-create]', paymentError);
        }
      }
      const responseOrders = payment
        ? (await prisma.order.findMany({ where: { id: { in: created.createdOrders.map(order => order.id) } }, include: { items: true } })).map(serializeOrderRow)
        : created.createdOrders;
      res.status(201).json({ success: true, orders: responseOrders, totalQty: created.calculatedQty, totalAmount: created.calculatedTotal, payment });
    } catch (error: any) {
      const knownErrors = new Set(['PRODUCT_NOT_AVAILABLE', 'PRODUCT_MERCHANT_REQUIRED', 'INVALID_ITEM_QUANTITY', 'MOQ_NOT_MET', 'CARTON_MULTIPLE_REQUIRED', 'SKU_NOT_AVAILABLE', 'INSUFFICIENT_STOCK', 'PRIVATE_PRODUCT_NOT_AUTHORIZED', 'CREDIT_LIMIT_EXCEEDED', 'INVENTORY_CONCURRENT_UPDATE', 'INVENTORY_LOCATION_NOT_CONFIGURED', 'INVENTORY_BALANCE_NOT_FOUND', 'INVENTORY_LEDGER_CONCURRENT_UPDATE', 'SHOWCASE_PRODUCT_ORDER_DISABLED', 'PAYPAL_SINGLE_MERCHANT_ONLY', 'PAYPAL_MERCHANT_NOT_CONFIGURED', 'STRIPE_SINGLE_MERCHANT_ONLY', 'STRIPE_MERCHANT_NOT_CONFIGURED', 'SOLANA_SINGLE_MERCHANT_ONLY', 'SOLANA_MERCHANT_NOT_CONFIGURED', 'SOLANA_PLATFORM_WALLET_CONFLICT', 'PROMOTION_CODE_INVALID_OR_INACTIVE', 'PROMOTION_NOT_APPLICABLE', 'PROMOTION_CUSTOMER_USAGE_LIMIT_REACHED', 'PROMOTION_USAGE_LIMIT_REACHED']);
      const code = knownErrors.has(error?.message) ? error.message : 'ORDER_CREATE_FAILED';
      const publicCode = ['INVENTORY_CONCURRENT_UPDATE', 'INVENTORY_LEDGER_CONCURRENT_UPDATE'].includes(code) ? 'INVENTORY_CHANGED_RETRY_ORDER' : code;
      res.status(code === 'ORDER_CREATE_FAILED' ? 500 : 409).json({ success: false, error: publicCode });
    }
  });

