  app.post(
    '/api/merchant/email/domains',
    requireMerchantTenant,
    requireEmployeePermission('employees.manage', 'store_manager'),
    async (req: AuthRequest, res) => {
      const domainName = normalizeMerchantEmailDomain(req.body?.domainName);
      if (!domainName) return res.status(400).json({ success: false, error: 'EMAIL_DOMAIN_INVALID' });
      try {
        const domain = await prisma.merchantEmailDomain.create({
          data: {
            merchantId: req.merchant!.merchantId,
            domainName,
            verificationToken: `ruda-domain-verification=${crypto.randomBytes(24).toString('hex')}`
          },
          select: { id: true, domainName: true, verificationToken: true }
        });
        await logEmployeeAudit(
          req.merchant!.merchantId,
          req.merchant!.employeeId,
          'EMAIL_DOMAIN_ADDED',
          'MerchantEmailDomain',
          domain.id,
          req,
          { domainName: domain.domainName }
        );
        return res.status(201).json({
          success: true,
          domain: {
            id: domain.id,
            domainName: domain.domainName,
            isVerified: false,
            verificationRecordName: merchantEmailDomainVerificationHost(domain.domainName),
            verificationRecordValue: domain.verificationToken,
            spfStatus: 'not_configured',
            dkimStatus: 'not_configured',
            dmarcStatus: 'not_configured'
          }
        });
      } catch (error) {
        if ((error as { code?: string })?.code === 'P2002') {
          return res.status(409).json({ success: false, error: 'EMAIL_DOMAIN_ALREADY_ADDED' });
        }
        return sendInternalError(res, error, 'merchant-email-domain-add');
      }
    }
  );
  app.post(
    '/api/merchant/email/domains/:id/verify',
    requireMerchantTenant,
    requireEmployeePermission('employees.manage', 'store_manager'),
    rateLimit({ windowMs: 10 * 60 * 1000, limit: 20, standardHeaders: true, legacyHeaders: false }),
    async (req: AuthRequest, res) => {
      try {
        const domain = await prisma.merchantEmailDomain.findFirst({
          where: { id: req.params.id, merchantId: req.merchant!.merchantId },
          select: { id: true, domainName: true, verificationToken: true, verifiedAt: true }
        });
        if (!domain) return res.status(404).json({ success: false, error: 'EMAIL_DOMAIN_NOT_FOUND' });
        if (domain.verifiedAt) {
          return res.json({ success: true, isVerified: true, verifiedAt: domain.verifiedAt.toISOString() });
        }
        let records: string[][];
        try {
          records = await resolveTxt(merchantEmailDomainVerificationHost(domain.domainName));
        } catch (error) {
          const code = (error as NodeJS.ErrnoException)?.code;
          if (code === 'ENODATA' || code === 'ENOTFOUND') {
            return res.status(409).json({ success: false, error: 'EMAIL_DOMAIN_DNS_RECORD_NOT_FOUND' });
          }
          console.error('[merchant-email-domain-dns-check]', code || 'unknown error');
          return res.status(502).json({ success: false, error: 'EMAIL_DOMAIN_DNS_LOOKUP_FAILED' });
        }
        if (!hasMerchantEmailDomainVerificationRecord(records, domain.verificationToken)) {
          return res.status(409).json({ success: false, error: 'EMAIL_DOMAIN_DNS_TOKEN_MISMATCH' });
        }
        const verifiedAt = new Date();
        await prisma.merchantEmailDomain.updateMany({
          where: { id: domain.id, merchantId: req.merchant!.merchantId, verifiedAt: null },
          data: { verifiedAt }
        });
        await logEmployeeAudit(
          req.merchant!.merchantId,
          req.merchant!.employeeId,
          'EMAIL_DOMAIN_VERIFIED',
          'MerchantEmailDomain',
          domain.id,
          req,
          { domainName: domain.domainName }
        );
        return res.json({ success: true, isVerified: true, verifiedAt: verifiedAt.toISOString() });
      } catch (error) {
        sendInternalError(res, error, 'merchant-email-domain-verify');
      }
    }
  );
