  const loadMerchantSupportMemoryContext = async (merchantId: string, question: string) => {
    if (isSensitiveMerchantSupportQuestion(question)) return [];
    const memories = await prisma.merchantSupportMemory.findMany({
      where: { merchantId },
      orderBy: { updatedAt: 'desc' },
      take: 100,
      select: { id: true, summary: true, embedding: true, updatedAt: true }
    });
    if (!memories.length) return [];
    try {
      const matches = await retrieveMerchantSupportMemories(question, memories);
      await Promise.all(matches
        .filter(memory => memories.find(candidate => candidate.id === memory.id)?.embedding !== memory.embedding)
        .map(memory => prisma.merchantSupportMemory.update({
          where: { id: memory.id },
          data: { embedding: memory.embedding }
        })));
      return matches.map(memory => ({
        senderRole: 'memory' as const,
        content: `${memory.summary}\n检索相关度：${memory.score.toFixed(2)}`
      }));
    } catch (error) {
      console.error('[merchant-support-memory-retrieval]', error instanceof Error ? error.name : 'unknown error');
      return [];
    }
  };
  const getMerchantSupportProfileContext = (merchant: AuthRequest['merchant']): MerchantSupportProfileContext | undefined => {
    if (!merchant) return undefined;
    const businessTypes: Record<string, string> = {
      brand_supplier: '生产商 / 品牌商',
      manufacturer: '服装工厂',
      wholesaler: '批发商',
      atelier: '设计工作室 / Atelier',
      distributor: '区域代理 / 分销商'
    };
    const merchantZones: Record<string, string> = {
      iolo: '服装现货区',
      tavoro: '服装订货区',
      leather: '精品皮包区',
      boutique_department: '精品百货区'
    };
    const employeeRoles: Record<string, string> = {
      owner: '企业老板',
      manager: '企业管理员',
      sales: '销售员工',
      warehouse: '仓储员工',
      production: '生产员工',
      store_manager: '店铺经理'
    };
    return {
      merchantName: merchant.name || '',
      legalName: merchant.companyLegalName || '',
      merchantCode: merchant.code || '',
      businessType: businessTypes[merchant.businessType || ''] || merchant.businessType || '',
      merchantZone: merchantZones[merchant.merchantZone || ''] || merchant.merchantZone || '',
      country: merchant.country_zh || merchant.country || '',
      city: merchant.city_zh || merchant.city || '',
      isVerified: merchant.isVerified === true,
      ...(merchant.employeeRole
        ? { employeeRole: employeeRoles[merchant.employeeRole] || merchant.employeeRole }
        : {})
    };
  };

