  app.post('/api/merchant/support/conversations/:id/messages', requireMerchantTenant, merchantSupportMessageRateLimit, async (req: AuthRequest, res) => {
    const content = typeof req.body?.content === 'string' ? req.body.content.trim() : '';
    if (!content || content.length > 4000) return res.status(400).json({ success: false, error: 'MERCHANT_SUPPORT_MESSAGE_INVALID' });
    try {
      const merchantId = req.merchant!.merchantId;
      const now = new Date();
      const senderName = req.merchant!.employeeName || req.merchant!.name || '商家';
      const target = await prisma.merchantSupportConversation.findFirst({
        where: { id: req.params.id, merchantId },
        select: {
          id: true,
          subject: true,
          status: true,
          priority: true,
          firstRespondedAt: true,
          firstResponseDueAt: true,
          responseCycleStartedAt: true
        }
      });
      if (!target) return res.status(404).json({ success: false, error: 'MERCHANT_SUPPORT_NOT_FOUND' });
      const history = await prisma.merchantSupportMessage.findMany({
        where: { conversationId: target.id, senderRole: { in: ['merchant', 'admin', 'ai'] } },
        orderBy: { createdAt: 'desc' },
        take: 6,
        select: { senderRole: true, content: true }
      });
      const memory = await loadMerchantSupportMemoryContext(merchantId, `${target.subject}\n${content}`);
      const activeHistory: Array<{ senderRole: 'merchant' | 'admin' | 'ai' | 'memory'; content: string }> = [];
      for (const message of history.reverse()) {
        if (message.senderRole === 'merchant' || message.senderRole === 'admin' || message.senderRole === 'ai') {
          activeHistory.push({ senderRole: message.senderRole, content: message.content });
        }
      }
      const answer = await answerMerchantSupportQuestion(
        content,
        target.subject,
        aiSupportConfig.merchantSupportAi,
        undefined,
        undefined,
        [...memory, ...activeHistory],
        getMerchantSupportProfileContext(req.merchant),
        aiSupportConfig.merchantSupportKnowledgeArticles
      );
      const aiResolved = Boolean(answer && !answer.needsHuman);
      const reopening = target.status === 'resolved';
      const conversation = await prisma.$transaction(async tx => {
        await tx.merchantSupportMessage.createMany({
          data: [
            {
              id: crypto.randomUUID(),
              conversationId: target.id,
              senderId: req.merchant!.employeeId || req.merchant!.id,
              senderRole: 'merchant',
              senderName,
              content,
              createdAt: now
            },
            ...(answer ? [{
              id: crypto.randomUUID(),
              conversationId: target.id,
              senderId: 'ruda-support-ai',
              senderRole: 'ai',
              senderName: answer.source === 'qwen' ? 'RUDA AI · Qwen2.5-7B' : 'RUDA AI · 安全指引',
              content: answer.reply,
              createdAt: new Date(now.getTime() + 1)
            }] : [])
          ]
        });
        await tx.merchantSupportConversation.update({
          where: { id: target.id },
          data: {
            status: aiResolved ? 'resolved' : reopening ? 'open' : target.status,
            lastMessageAt: new Date(now.getTime() + (answer ? 1 : 0)),
            lastMessagePreview: (answer?.reply || content).slice(0, 240),
            responseCycleStartedAt: reopening || target.firstRespondedAt ? now : target.responseCycleStartedAt,
            firstRespondedAt: null,
            firstResponseDueAt: aiResolved ? null : reopening || target.firstRespondedAt
              ? getMerchantSupportFirstResponseDueAt(now, target.priority as MerchantSupportPriority, aiSupportConfig.merchantSupportSlaMinutes)
              : target.firstResponseDueAt,
            resolvedAt: aiResolved ? new Date(now.getTime() + (answer ? 2 : 0)) : reopening ? null : undefined,
            resolvedByAi: aiResolved,
            aiHandoffReason: answer?.needsHuman
              ? isSensitiveMerchantSupportQuestion(`${target.subject}\n${content}`) ? 'sensitive' : 'ai_uncertain'
              : null
          }
        });
        await tx.merchantSupportMemory.deleteMany({
          where: { conversationId: target.id }
        });
        return tx.merchantSupportConversation.findUnique({
          where: { id: target.id },
          include: { messages: { orderBy: { createdAt: 'asc' }, take: 200 } }
        });
      });
      if (!conversation) return res.status(404).json({ success: false, error: 'MERCHANT_SUPPORT_NOT_FOUND' });
      res.status(201).json({ success: true, conversation });
    } catch (error) {
      sendInternalError(res, error, 'merchant-support-message-create');
    }
  });

