  app.get('/api/merchant/ai-employees', requireMerchantTenant, async (req: AuthRequest, res) => {
    try {
      const merchantId = req.merchant!.merchantId;
      const [definitions, installations] = await Promise.all([
        prisma.aiEmployeeDefinition.findMany({
          where: {
            OR: [
              { status: { in: ['planned', 'development', 'pilot', 'available'] } },
              { merchantInstallations: { some: { merchantId } } }
            ]
          },
          orderBy: [{ department: 'asc' }, { name: 'asc' }]
        }),
        prisma.merchantAiEmployeeInstallation.findMany({
          where: { merchantId },
          select: { id: true, definitionId: true, status: true, grantedPermissions: true, createdAt: true, updatedAt: true }
        })
      ]);
      const installationsByDefinition = new Map(installations.map(installation => [installation.definitionId, installation]));
      res.setHeader('Cache-Control', 'no-store');
      res.json({
        success: true,
        canManage: !req.merchant!.employeeId || employeeHasPermission(req, 'employees.manage'),
        employees: definitions.map(definition => {
          const installation = installationsByDefinition.get(definition.id);
          return {
            id: definition.id,
            slug: definition.slug,
            name: definition.name,
            department: definition.department,
            description: definition.description,
            version: definition.version,
            status: definition.status === 'available' && !executableAiEmployeeSlugs.some(slug => slug === definition.slug)
              ? 'planned'
              : definition.status,
            capabilities: parseStoredJson<string[]>(definition.capabilities, []),
            requiredPermissions: parseStoredJson<string[]>(definition.requiredPermissions, []),
            installation: installation ? {
              id: installation.id,
              status: installation.status,
              grantedPermissions: parseStoredJson<string[]>(installation.grantedPermissions, []),
              createdAt: installation.createdAt,
              updatedAt: installation.updatedAt
            } : null
          };
        })
      });
    } catch (error) {
      sendInternalError(res, error, 'merchant-ai-employee-list');
    }
  });

  app.get(
    '/api/merchant/ai-team',
    requireMerchantTenant,
    requireEmployeePermission('employees.manage', 'store_manager'),
    async (req: AuthRequest, res) => {
    const merchantId = req.merchant!.merchantId;
    try {
      const merchant = await prisma.merchant.findUnique({
        where: { id: merchantId },
        select: { industry: true }
        }
      );
      if (!merchant) return res.status(404).json({ success: false, error: 'MERCHANT_NOT_FOUND' });
      const industry = requireModaGptIndustry(merchant.industry);
      let assignments = await prisma.merchantAiTeamAssignment.findMany({
        where: { merchantId, industry },
        orderBy: { agentId: 'asc' }
      });
      if (!isCurrentModaGptCoreTeam(assignments)) {
        assignments = await prisma.$transaction(tx => provisionModaGptIndustryTeam({
          tx,
          merchantId,
          industry,
          idempotencyKey: `team-bootstrap:${merchantId}:${industry}:v${MODAGPT_INDUSTRY_PACK_VERSION}`
        }));
      }
      res.setHeader('Cache-Control', 'no-store');
      return res.json({ success: true, industry, assignments });
    } catch (error) {
      if (isPrismaSchemaNotReady(error)) {
        console.error('[merchant-modagpt-team] Industry migration is not applied');
        return res.status(503).json({ success: false, error: 'MODAGPT_INDUSTRY_MIGRATION_REQUIRED' });
      }
      sendInternalError(res, error, 'merchant-modagpt-team');
    }
  });

  app.patch(
    '/api/merchant/ai-team/industry',
    requireMerchantTenant,
    requireEmployeePermission('employees.manage', 'store_manager'),
    async (req: AuthRequest, res) => {
      const industry = parseModaGptIndustry(req.body?.industry);
      if (!industry) return res.status(400).json({ success: false, error: 'INVALID_INDUSTRY' });
      const merchantId = req.merchant!.merchantId;
      const idempotencyKey = String(req.get('Idempotency-Key') || crypto.randomUUID()).trim();
      if (idempotencyKey.length > 160) {
        return res.status(400).json({ success: false, error: 'INVALID_IDEMPOTENCY_KEY' });
      }
      try {
        const assignments = await prisma.$transaction(tx => provisionModaGptIndustryTeam({
          tx,
          merchantId,
          industry,
          industrySource: 'MERCHANT_UPDATED',
          idempotencyKey,
          actorId: req.merchant?.employeeId || req.merchant?.id || null
        }));
        res.setHeader('Cache-Control', 'no-store');
        return res.json({ success: true, industry, assignments });
      } catch (error) {
        if (isPrismaSchemaNotReady(error)) {
          console.error('[merchant-modagpt-industry-change] Industry migration is not applied');
          return res.status(503).json({ success: false, error: 'MODAGPT_INDUSTRY_MIGRATION_REQUIRED' });
        }
        const code = error instanceof Error ? error.message : '';
        if (code.includes('idempotency key')) {
          return res.status(409).json({ success: false, error: 'MODAGPT_INDUSTRY_REQUEST_CONFLICT' });
        }
        sendInternalError(res, error, 'merchant-modagpt-industry-change');
      }
    }
  );

  app.post('/api/merchant/ai-employees', requireMerchantTenant, requireEmployeePermission('employees.manage', 'store_manager'), async (req: AuthRequest, res) => {
    const definitionId = typeof req.body?.definitionId === 'string' ? req.body.definitionId.trim() : '';
    if (!definitionId || Object.keys(req.body || {}).some(key => key !== 'definitionId')) {
      return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_DEFINITION_REQUIRED' });
    }

    try {
      const definition = await prisma.aiEmployeeDefinition.findUnique({ where: { id: definitionId } });
      if (!definition) return res.status(404).json({ success: false, error: 'AI_EMPLOYEE_NOT_FOUND' });
      if (definition.status === 'paused') return res.status(409).json({ success: false, error: 'AI_EMPLOYEE_NOT_AVAILABLE' });
      const existing = await prisma.merchantAiEmployeeInstallation.findUnique({
        where: { merchantId_definitionId: { merchantId: req.merchant!.merchantId, definitionId: definition.id } }
      });
      const installation = existing?.status === 'declined'
        ? await prisma.merchantAiEmployeeInstallation.update({
          where: { id: existing.id },
          data: {
            status: 'requested',
            grantedPermissions: '[]',
            installedBy: req.merchant!.employeeId || req.merchant!.id
          },
          select: { id: true, definitionId: true, status: true, grantedPermissions: true, createdAt: true, updatedAt: true }
        })
        : existing
          ? null
          : await prisma.merchantAiEmployeeInstallation.create({
            data: {
              merchantId: req.merchant!.merchantId,
              definitionId: definition.id,
              status: 'requested',
              grantedPermissions: '[]',
              installedBy: req.merchant!.employeeId || req.merchant!.id
            },
            select: { id: true, definitionId: true, status: true, grantedPermissions: true, createdAt: true, updatedAt: true }
          });
      if (!installation) return res.status(409).json({ success: false, error: 'AI_EMPLOYEE_ALREADY_INSTALLED' });
      await logEmployeeAudit(
        req.merchant!.merchantId,
        req.merchant!.employeeId,
        'AI_EMPLOYEE_REQUESTED',
        'AiEmployeeDefinition',
        definition.id,
        req,
        { installationId: installation.id }
      );
      res.status(201).json({
        success: true,
        installation: {
          ...installation,
          grantedPermissions: []
        }
      });
    } catch (error) {
      if ((error as { code?: string })?.code === 'P2002') {
        return res.status(409).json({ success: false, error: 'AI_EMPLOYEE_ALREADY_INSTALLED' });
      }
      sendInternalError(res, error, 'merchant-ai-employee-install');
    }
  });

  app.patch('/api/merchant/ai-employees/:id/status', requireMerchantTenant, requireEmployeePermission('employees.manage', 'store_manager'), async (req: AuthRequest, res) => {
    if (typeof req.body?.active !== 'boolean' || Object.keys(req.body).some(key => key !== 'active')) {
      return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_STATUS_INVALID' });
    }
    const existing = await prisma.merchantAiEmployeeInstallation.findFirst({
      where: { id: req.params.id, merchantId: req.merchant!.merchantId },
      include: { definition: { select: { status: true, slug: true } } }
    });
    if (!existing) return res.status(404).json({ success: false, error: 'AI_EMPLOYEE_INSTALLATION_NOT_FOUND' });
    if (existing.status !== 'active' && existing.status !== 'paused') {
      return res.status(409).json({ success: false, error: 'AI_EMPLOYEE_REQUEST_NOT_DECIDED' });
    }
    if (req.body.active && !canMerchantHireAiEmployee(existing.definition.status, existing.definition.slug)) {
      return res.status(409).json({ success: false, error: 'AI_EMPLOYEE_NOT_AVAILABLE' });
    }
    const status = req.body.active ? 'active' : 'paused';
    const updated = await prisma.merchantAiEmployeeInstallation.updateMany({
      where: { id: existing.id, merchantId: req.merchant!.merchantId },
      data: { status }
    });
    if (!updated.count) return res.status(404).json({ success: false, error: 'AI_EMPLOYEE_INSTALLATION_NOT_FOUND' });
    await logEmployeeAudit(
      req.merchant!.merchantId,
      req.merchant!.employeeId,
      req.body.active ? 'AI_EMPLOYEE_RESUMED' : 'AI_EMPLOYEE_PAUSED',
      'AiEmployeeDefinition',
      existing.definitionId,
      req,
      { installationId: existing.id }
    );
    res.json({ success: true, installation: { id: existing.id, status } });
  });

  app.patch('/api/merchant/ai-employees/:id/permissions', requireMerchantTenant, requireEmployeePermission('employees.manage', 'store_manager'), async (req: AuthRequest, res) => {
    if (!req.body || Object.keys(req.body).length !== 1 || !Object.hasOwn(req.body, 'grantedPermissions')) {
      return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_PERMISSIONS_INVALID' });
    }
    const grantedPermissions = parseAiEmployeePermissions(req.body.grantedPermissions);
    if (!grantedPermissions) return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_PERMISSIONS_INVALID' });

    try {
      const merchantId = req.merchant!.merchantId;
      const existing = await prisma.merchantAiEmployeeInstallation.findFirst({
        where: { id: req.params.id, merchantId },
        include: { definition: { select: { slug: true, status: true } } }
      });
      if (!existing) return res.status(404).json({ success: false, error: 'AI_EMPLOYEE_INSTALLATION_NOT_FOUND' });
      if (!areAiEmployeePermissionsSupportedForSlug(existing.definition.slug, grantedPermissions)
        || (grantedPermissions.length > 0
          && (existing.status !== 'active'
            || !canMerchantHireAiEmployee(existing.definition.status, existing.definition.slug)))) {
        return res.status(409).json({ success: false, error: 'AI_EMPLOYEE_TOOL_NOT_AVAILABLE' });
      }

      const updated = await prisma.merchantAiEmployeeInstallation.updateMany({
        where: { id: existing.id, merchantId },
        data: { grantedPermissions: JSON.stringify(grantedPermissions) }
      });
      if (!updated.count) return res.status(404).json({ success: false, error: 'AI_EMPLOYEE_INSTALLATION_NOT_FOUND' });
      await logEmployeeAudit(
        merchantId,
        req.merchant!.employeeId,
        'AI_EMPLOYEE_PERMISSIONS_UPDATED',
        'AiEmployeeDefinition',
        existing.definitionId,
        req,
        { installationId: existing.id, grantedPermissions }
      );
      res.setHeader('Cache-Control', 'no-store');
      res.json({ success: true, installation: { id: existing.id, grantedPermissions } });
    } catch (error) {
      sendInternalError(res, error, 'merchant-ai-employee-permissions-update');
    }
  });

  app.get(
    '/api/merchant/ai-employees/:id/tools/product-catalog',
    requireMerchantTenant,
    requireAnyEmployeePermission('sales.order.create', 'production.report'),
    async (req: AuthRequest, res) => {
      const search = parseProductCatalogSearchQuery(req.query.search);
      if (search === null) return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_PRODUCT_SEARCH_INVALID' });

      try {
        const merchantId = req.merchant!.merchantId;
        const installation = await prisma.merchantAiEmployeeInstallation.findFirst({
          where: { id: req.params.id, merchantId },
          include: { definition: { select: { slug: true, status: true } } }
        });
        if (!installation) return res.status(404).json({ success: false, error: 'AI_EMPLOYEE_INSTALLATION_NOT_FOUND' });
        const grantedPermissions = parseStoredJson<unknown>(installation.grantedPermissions, []);
        if (!canUseAiEmployeeProductCatalog({
          employeeSlug: installation.definition.slug,
          employeeStatus: installation.definition.status,
          installationStatus: installation.status,
          grantedPermissions
        })) {
          return sendAccessDenied(res, 'AI_EMPLOYEE_TOOL_PERMISSION_REQUIRED');
        }

        const products = await prisma.product.findMany({
          where: {
            merchantId,
            lifecycleStatus: { not: 'archived' },
            ...(search ? {
              OR: [
                { name: { contains: search, mode: 'insensitive' } },
                { name_zh: { contains: search, mode: 'insensitive' } },
                { name_it: { contains: search, mode: 'insensitive' } },
                { styleNo: { contains: search, mode: 'insensitive' } },
                { brand: { contains: search, mode: 'insensitive' } }
              ]
            } : {})
          },
          orderBy: { updatedAt: 'desc' },
          take: 50,
          select: {
            id: true,
            styleNo: true,
            name: true,
            name_zh: true,
            name_it: true,
            brand: true,
            category: true,
            subCategory: true,
            wholesalePrice: true,
            moq: true,
            lifecycleStatus: true,
            inventoryStatus: true,
            updatedAt: true
          }
        });
        await logEmployeeAudit(
          merchantId,
          req.merchant!.employeeId,
          'AI_EMPLOYEE_PRODUCT_CATALOG_READ',
          'AiEmployeeDefinition',
          installation.definitionId,
          req,
          { installationId: installation.id, resultCount: products.length, searchLength: search.length }
        );
        res.setHeader('Cache-Control', 'no-store');
        res.json({
          success: true,
          count: products.length,
          products,
          canManageCosts: !req.merchant?.employeeId || employeeHasPermission(req as AuthRequest, 'product.cost.view')
        });
      } catch (error) {
        sendInternalError(res, error, 'merchant-ai-employee-product-catalog-read');
      }
    }
  );

  app.post(
    '/api/merchant/ai-employees/:id/tools/inventory-search',
    requireMerchantTenant,
    requireEmployeePermission('employees.manage'),
    merchantSupportMessageRateLimit,
    async (req: AuthRequest, res) => {
      if (!req.body || Object.keys(req.body).length !== 1 || !Object.hasOwn(req.body, 'message')) {
        return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_MESSAGE_INVALID' });
      }
      const message = typeof req.body.message === 'string' ? req.body.message.trim() : '';
      if (!message) return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_MESSAGE_REQUIRED' });
      if (message.length > 500) return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_MESSAGE_TOO_LONG' });
      if (hasSensitiveOnboardingInformation(message)) {
        return res.status(400).json({ success: false, error: 'AI_EMPLOYEE_SENSITIVE_INPUT_BLOCKED' });
      }

      const merchantId = req.merchant!.merchantId;
      try {
        const installation = await prisma.merchantAiEmployeeInstallation.findFirst({
          where: { id: req.params.id, merchantId },
          include: { definition: { select: { id: true, slug: true, status: true } } }
        });
        if (!installation) return res.status(404).json({ success: false, error: 'AI_EMPLOYEE_INSTALLATION_NOT_FOUND' });
        if (!canUseAiEmployeeInventory({
          employeeSlug: installation.definition.slug,
          employeeStatus: installation.definition.status,
          installationStatus: installation.status,
          grantedPermissions: parseStoredJson<unknown>(installation.grantedPermissions, [])
        })) return sendAccessDenied(res, 'AI_EMPLOYEE_INVENTORY_PERMISSION_REQUIRED');

        const memories = await prisma.merchantAiEmployeeMemory.findMany({
          where: { merchantId },
          orderBy: { updatedAt: 'desc' },
          take: 30,
          select: { category: true, content: true }
        });
        const businessMemory = serializeAiEmployeeMemories(memories);
        let plan: Awaited<ReturnType<typeof planInventorySearch>>;
        try {
          plan = await planInventorySearch(message, undefined, businessMemory);
        } catch (error) {
          const errorCode = error instanceof Error ? error.message : '';
          if (errorCode === 'AI_EMPLOYEE_INVENTORY_PLAN_INVALID') {
            console.error('[merchant-ai-inventory-search]', errorCode);
            return res.status(502).json({ success: false, error: errorCode });
          }
          console.error('[merchant-ai-inventory-search]', error instanceof Error ? error.name : 'unknown error');
          return res.status(503).json({ success: false, error: 'AI_EMPLOYEE_MODEL_UNAVAILABLE' });
        }
        if (!plan.search) return res.status(422).json({ success: false, error: 'AI_EMPLOYEE_INVENTORY_SEARCH_REQUIRED' });

        const records = await searchMerchantAiInventory(merchantId, plan.search);
        const currentInstallation = await prisma.merchantAiEmployeeInstallation.findFirst({
          where: { id: installation.id, merchantId },
          include: { definition: { select: { slug: true, status: true } } }
        });
        if (!currentInstallation || !canUseAiEmployeeInventory({
          employeeSlug: currentInstallation.definition.slug,
          employeeStatus: currentInstallation.definition.status,
          installationStatus: currentInstallation.status,
          grantedPermissions: parseStoredJson<unknown>(currentInstallation.grantedPermissions, [])
        })) return sendAccessDenied(res, 'AI_EMPLOYEE_INVENTORY_PERMISSION_REQUIRED');

        if (records.length === 0) {
          await logEmployeeAudit(
            merchantId,
            req.merchant!.employeeId,
            'AI_EMPLOYEE_INVENTORY_READ',
            'AiEmployeeDefinition',
            installation.definitionId,
            req,
            { installationId: installation.id, resultCount: 0, searchLength: plan.search.length }
          );
          res.setHeader('Cache-Control', 'no-store');
          return res.json({
            success: true,
            reply: '没有找到与该商品、款号、SKU、颜色或尺码匹配的库存记录。',
            search: plan.search,
            records: []
          });
        }

        let reply: string;
        try {
          reply = await answerWithInventory(message, records, undefined, businessMemory);
        } catch (error) {
          const errorCode = error instanceof Error ? error.message : '';
          if (errorCode.startsWith('AI_EMPLOYEE_INVENTORY_')) {
            console.error('[merchant-ai-inventory-answer]', errorCode);
            return res.status(502).json({ success: false, error: errorCode });
          }
          console.error('[merchant-ai-inventory-answer]', error instanceof Error ? error.name : 'unknown error');
          return res.status(503).json({ success: false, error: 'AI_EMPLOYEE_MODEL_UNAVAILABLE' });
        }
        await logEmployeeAudit(
          merchantId,
          req.merchant!.employeeId,
          'AI_EMPLOYEE_INVENTORY_READ',
          'AiEmployeeDefinition',
          installation.definitionId,
          req,
          { installationId: installation.id, resultCount: records.length, searchLength: plan.search.length }
        );
        res.setHeader('Cache-Control', 'no-store');
        return res.json({ success: true, reply, search: plan.search, records });
      } catch (error) {
        sendInternalError(res, error, 'merchant-ai-employee-inventory-search');
      }
    }
  );

