  app.put('/api/merchant/settings', requireMerchantTenant, requireEmployeePermission('employees.manage', 'store_manager'), async (req: AuthRequest, res) => {
    try {
      const body = req.body || {};
      const moq = Number(body.moq);
      const defaultPaymentTerm = String(body.defaultPaymentTerm || 'prepaid');
      const shippingNote = String(body.shippingNote || '').trim();
      const mobileDefaultTab = String(body.mobileDefaultTab || 'dashboard');
      const mobileLanguage = String(body.mobileLanguage || 'auto');
      const rawWebsiteUrl = typeof body.websiteUrl === 'string' ? body.websiteUrl.trim() : '';
      const websiteUrl = rawWebsiteUrl ? normalizeMerchantWebsiteUrl(rawWebsiteUrl) : '';
      const rawLatitude = typeof body.mapLatitude === 'string' || typeof body.mapLatitude === 'number' ? String(body.mapLatitude).trim() : '';
      const rawLongitude = typeof body.mapLongitude === 'string' || typeof body.mapLongitude === 'number' ? String(body.mapLongitude).trim() : '';
      const mapLatitude = rawLatitude ? Number(rawLatitude) : null;
      const mapLongitude = rawLongitude ? Number(rawLongitude) : null;
      if (!Number.isInteger(moq) || moq < 1 || moq > 100000) return res.status(400).json({ success: false, error: 'MOQ_INVALID' });
      if (!['prepaid', 'net_15', 'net_30', 'net_60'].includes(defaultPaymentTerm)) return res.status(400).json({ success: false, error: 'PAYMENT_TERM_INVALID' });
      if (shippingNote.length > 500) return res.status(400).json({ success: false, error: 'SHIPPING_NOTE_TOO_LONG' });
      if (!isMerchantMobileDefaultTab(mobileDefaultTab)) return res.status(400).json({ success: false, error: 'MOBILE_DEFAULT_TAB_INVALID' });
      if (mobileLanguage !== 'auto' && !isUiTranslationLanguage(mobileLanguage)) return res.status(400).json({ success: false, error: 'MOBILE_LANGUAGE_INVALID' });
      if (rawWebsiteUrl && !websiteUrl) return res.status(400).json({ success: false, error: 'WEBSITE_URL_INVALID' });
      if ((rawLatitude && !rawLongitude) || (!rawLatitude && rawLongitude)
        || (mapLatitude !== null && (!Number.isFinite(mapLatitude) || mapLatitude < -90 || mapLatitude > 90))
        || (mapLongitude !== null && (!Number.isFinite(mapLongitude) || mapLongitude < -180 || mapLongitude > 180))) {
        return res.status(400).json({ success: false, error: 'MAP_COORDINATES_INVALID' });
      }
      const existingSettings = parseStoredJson<Record<string, unknown>>(
        (await prisma.merchant.findUnique({ where: { id: req.merchant!.merchantId }, select: { settings: true } }))?.settings,
        {}
      );
      const settings = { ...existingSettings, moq, defaultPaymentTerm, shippingNote, notifyOrders: Boolean(body.notifyOrders), notifyPayouts: Boolean(body.notifyPayouts), notifyVault: Boolean(body.notifyVault), notifyMarketing: Boolean(body.notifyMarketing), mobileAlerts: Boolean(body.mobileAlerts), mobileCompact: Boolean(body.mobileCompact), mobileDefaultTab, mobileLanguage, websiteUrl, mapLatitude, mapLongitude };
      const text = (value: unknown, max: number) => typeof value === 'string' ? value.trim().slice(0, max) : undefined;
      const profile = {
        name: text(body.name, 120), companyLegalName: text(body.companyLegalName, 160),
        vatNumber: text(body.vatNumber, 80), country: text(body.country, 80), city: text(body.city, 80),
        showroomAddress: text(body.showroomAddress, 240), contactPerson: text(body.contactPerson, 100),
        contactPhone: text(body.contactPhone, 60), contactEmail: text(body.contactEmail, 160)
      };
      if (!profile.name || !profile.contactEmail || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(profile.contactEmail)) {
        return res.status(400).json({ success: false, error: 'MERCHANT_PROFILE_INVALID' });
      }
      const merchant = await prisma.merchant.update({ where: { id: req.merchant!.merchantId }, data: { settings: JSON.stringify(settings), ...profile } });
      await logEmployeeAudit(req.merchant!.merchantId, req.merchant!.employeeId, 'MERCHANT_SETTINGS_UPDATED', 'Merchant', req.merchant!.merchantId, req, { fields: Object.keys(settings) });
      res.json({ success: true, settings, merchant: serializeMerchantRow(merchant) });
    } catch (error) { sendInternalError(res, error, 'merchant-settings-update'); }
  });

