  app.put(
    '/api/merchant/workspace-drafts/:workspace',
    requireMerchantTenant,
    requireEmployeePermission('employees.manage', 'store_manager'),
    async (req: AuthRequest, res) => {
      const merchantId = req.merchant!.merchantId;
      const workspace = req.params.workspace;
      if (!isMerchantWorkspaceDraftKind(workspace)) {
        return res.status(400).json({ success: false, error: 'MERCHANT_WORKSPACE_DRAFT_KIND_INVALID' });
      }
      const expectedRevision = req.body?.expectedRevision;
      if (!Number.isSafeInteger(expectedRevision) || expectedRevision < 0) {
        return res.status(400).json({ success: false, error: 'MERCHANT_WORKSPACE_DRAFT_REVISION_INVALID' });
      }
      let document: string;
      try {
        document = serializeMerchantWorkspaceDraft(req.body?.document);
      } catch (error) {
        const code = error instanceof Error ? error.message : 'MERCHANT_WORKSPACE_DRAFT_INVALID';
        return res.status(code === 'MERCHANT_WORKSPACE_DRAFT_TOO_LARGE' ? 413 : 400).json({ success: false, error: code });
      }
      try {
        if (expectedRevision === 0) {
          try {
            const draft = await prisma.merchantWorkspaceDraft.create({
              data: { merchantId, workspace, document, revision: 1 },
              select: { revision: true, updatedAt: true }
            });
            await logEmployeeAudit(merchantId, req.merchant!.employeeId, 'MERCHANT_WORKSPACE_DRAFT_SAVED', 'MerchantWorkspaceDraft', workspace, req, { revision: draft.revision });
            return res.status(201).json({ success: true, revision: draft.revision, updatedAt: draft.updatedAt.toISOString() });
          } catch (error) {
            if ((error as { code?: string })?.code === 'P2002') {
              return res.status(409).json({ success: false, error: 'MERCHANT_WORKSPACE_DRAFT_CONFLICT' });
            }
            throw error;
          }
        }
        const updated = await prisma.merchantWorkspaceDraft.updateMany({
          where: { merchantId, workspace, revision: expectedRevision },
          data: { document, revision: { increment: 1 } }
        });
        if (updated.count !== 1) {
          return res.status(409).json({ success: false, error: 'MERCHANT_WORKSPACE_DRAFT_CONFLICT' });
        }
        const draft = await prisma.merchantWorkspaceDraft.findUniqueOrThrow({
          where: { merchantId_workspace: { merchantId, workspace } },
          select: { revision: true, updatedAt: true }
        });
        await logEmployeeAudit(merchantId, req.merchant!.employeeId, 'MERCHANT_WORKSPACE_DRAFT_SAVED', 'MerchantWorkspaceDraft', workspace, req, { revision: draft.revision });
        return res.json({ success: true, revision: draft.revision, updatedAt: draft.updatedAt.toISOString() });
      } catch (error) {
        sendInternalError(res, error, 'merchant-workspace-draft-save');
      }
    }
  );

