  app.post('/api/fashion/posts', requireFashionAccount, requireFashionObjectStorage, publicFashionPostRateLimit, async (req, res) => {
    let videoFilePath: string | null = null;
    let imageFilePath: string | null = null;
    let imageStorageKey: string | undefined;
    try {
      const title = typeof req.body?.title === 'string' ? req.body.title.trim().slice(0, 120) : '';
      const text = typeof req.body?.text === 'string' ? req.body.text.trim().slice(0, 2000) : '';
      const image = typeof req.body?.image === 'string' ? req.body.image : '';
      const video = typeof req.body?.video === 'string' ? req.body.video : '';
      const category = typeof req.body?.category === 'string' ? req.body.category : '女装趋势';
      const requestedCity = req.body?.city;
      if (requestedCity !== undefined
        && (typeof requestedCity !== 'string' || (requestedCity !== '' && !fashionCommunityCities.includes(requestedCity as typeof fashionCommunityCities[number])))) {
        return res.status(400).json({ success: false, error: 'FASHION_POST_CITY_INVALID' });
      }
      const city = typeof requestedCity === 'string' && requestedCity ? requestedCity : undefined;
      const mediaType: 'image' | 'video' | null = req.body?.mediaType === undefined || req.body.mediaType === 'image'
        ? 'image'
        : req.body.mediaType === 'video' ? 'video' : null;
      if (req.body?.rightsConfirmed !== true) return res.status(400).json({ success: false, error: 'FASHION_POST_RIGHTS_CONFIRMATION_REQUIRED' });
      if (!mediaType) return res.status(400).json({ success: false, error: 'FASHION_POST_MEDIA_TYPE_INVALID' });
      if (mediaType === 'video') return res.status(400).json({ success: false, error: 'FASHION_POST_MULTIPART_REQUIRED' });
      if (!fashionCommunityCategories.includes(category as typeof fashionCommunityCategories[number])) return res.status(400).json({ success: false, error: 'FASHION_POST_CATEGORY_INVALID' });
      if (!title && !text && !image && !video) return res.status(400).json({ success: false, error: 'FASHION_POST_EMPTY' });
      if (image && (!/^data:image\/(jpeg|png|webp);base64,[a-z0-9+/=]+$/i.test(image) || image.length > 2_200_000)) {
        return res.status(400).json({ success: false, error: 'FASHION_POST_IMAGE_INVALID' });
      }
      if (mediaType === 'image' && video) return res.status(400).json({ success: false, error: 'FASHION_POST_MEDIA_MISMATCH' });
      if (!usesFashionCommunityDatabase && sharedGallery.filter(item => item.merchantId === 'public-fashion').length >= 500) {
        return res.status(409).json({ success: false, error: 'FASHION_COMMUNITY_CAPACITY_REACHED' });
      }
      let imageUrl = '';
      let imageMedia: FashionPostMedia | undefined;
      const postId = `fashion-post-${crypto.randomUUID()}`;
      if (image) {
        const match = /^data:(image\/(?:jpeg|png|webp));base64,([a-z0-9+/=]+)$/i.exec(image);
        if (!match) return res.status(400).json({ success: false, error: 'FASHION_POST_IMAGE_INVALID' });
        const contentType = match[1].toLowerCase();
        const bytes = Buffer.from(match[2], 'base64');
        const storedImage = await persistFashionAsset(bytes, contentType);
        imageUrl = isPrivateFashionMediaKey(storedImage.key)
          ? fashionMediaRouteUrl(postId, 0, 'content')
          : storedImage.url;
        imageStorageKey = storedImage.key || undefined;
        imageFilePath = storedImage.localPath;
        imageMedia = {
          type: 'image',
          url: imageUrl,
          contentType: storedImage.contentType,
          sizeBytes: storedImage.sizeBytes,
          ...(storedImage.key ? { storageKey: storedImage.key } : {}),
          ...(storedImage.bucket ? { storageBucket: storedImage.bucket } : {})
        };
      }
      const post: SharedGalleryImage = {
        id: postId,
        image: imageUrl,
        ...(imageStorageKey ? { imageStorageKey } : {}),
        mediaType,
        ...(imageMedia ? { mediaItems: [imageMedia] } : {}),
        merchantId: 'public-fashion',
        merchantName: 'RUDA Fashion Community',
        createdAt: new Date().toISOString(),
        featured: false,
        title: title || 'RUDA Fashion',
        caption: text,
        category,
        ...(city ? { city } : {}),
        creatorAccountId: (req as FashionAccountRequest).fashionAccountId,
        rightsStatus: 'authorized' as const,
        publicationStatus: 'pending' as const
      };
      if (!usesFashionCommunityDatabase) sharedGallery = [post, ...sharedGallery];
      try {
        if (usesFashionCommunityDatabase) await saveFashionCommunityPost(post);
        else await saveSharedGallery();
      } catch (error) {
        if (!usesFashionCommunityDatabase) sharedGallery = sharedGallery.filter(item => item.id !== post.id);
        throw error;
      }
      res.status(201).json({
        success: true,
        post: { id: post.id, image: post.image || null, videoUrl: post.videoUrl || null, mediaType: post.mediaType, title: post.title, text: post.caption, createdAt: post.createdAt, category: post.category, city: post.city }
      });
    } catch (error) {
      if (typeof videoFilePath === 'string') {
        await unlink(videoFilePath).catch(cleanupError => console.error('[fashion-video-cleanup]', cleanupError));
      }
      await deleteFashionAsset(imageStorageKey, imageFilePath).catch(cleanupError => console.error('[fashion-image-cleanup]', cleanupError));
      sendInternalError(res, error, 'fashion-public-post');
    }
  });

  const mixedFashionUpload = multer({
    storage: multer.diskStorage({
      destination: (_req, _file, callback) => {
        void mkdir(fashionVideoDirectory, { recursive: true })
          .then(() => callback(null, fashionVideoDirectory), error => callback(error as Error, ''));
      },
      filename: (_req, file, callback) => callback(null, `${crypto.randomUUID()}${path.extname(file.originalname).slice(0, 8)}`)
    }),
    limits: { fileSize: 20 * 1024 * 1024, files: 16, fields: 10, fieldSize: 120_000, parts: 26 },
    fileFilter: (_req, file, callback) => {
      const isMedia = /^media-\d+$/.test(file.fieldname)
        && ['image/jpeg', 'image/png', 'image/webp', 'video/mp4', 'video/webm', 'video/quicktime'].includes(file.mimetype);
      const isPoster = /^poster-\d+$/.test(file.fieldname) && file.mimetype === 'image/jpeg';
      if (!isMedia && !isPoster) {
        callback(new Error('FASHION_MIXED_MEDIA_FORMAT_INVALID'));
        return;
      }
      callback(null, true);
    }
  }).any();

  const parseMixedFashionUpload: express.RequestHandler = (req, res, next) => {
    mixedFashionUpload(req, res, error => {
      if (!error) {
        next();
        return;
      }
      const uploaded = Array.isArray(req.files) ? req.files : [];
      void Promise.all(uploaded.map(file => unlink(file.path).catch(cleanupError => console.error('[fashion-mixed-upload-cleanup]', cleanupError))))
        .then(() => {
          if (error instanceof multer.MulterError) {
            res.status(error.code === 'LIMIT_FILE_SIZE' ? 413 : 400).json({
              success: false,
              error: error.code === 'LIMIT_FILE_SIZE' ? 'FASHION_POST_MEDIA_TOO_LARGE' : 'FASHION_POST_MEDIA_INVALID'
            });
          } else if (error instanceof Error && error.message === 'FASHION_MIXED_MEDIA_FORMAT_INVALID') {
            res.status(400).json({ success: false, error: error.message });
          } else {
            sendInternalError(res, error, 'fashion-mixed-upload-parse');
          }
        });
    });
  };

  app.post('/api/fashion/posts/mixed', requireFashionAccount, requireFashionObjectStorage, publicFashionPostRateLimit, parseMixedFashionUpload, async (req, res) => {
    const uploaded = (Array.isArray(req.files) ? req.files : []) as Express.Multer.File[];
    const storedAssets: Array<{ key?: string; localPath: string | null }> = [];
    const cleanup = async () => {
      await Promise.all(storedAssets.map(asset => deleteFashionAsset(asset.key, asset.localPath)
        .catch(error => console.error('[fashion-mixed-asset-cleanup]', error))));
      await Promise.all(uploaded.map(file => unlink(file.path)
        .catch(error => error && (error as NodeJS.ErrnoException).code !== 'ENOENT' && console.error('[fashion-mixed-temp-cleanup]', error))));
    };
    const reject = async (status: number, error: string) => {
      await cleanup();
      return res.status(status).json({ success: false, error });
    };
    try {
      if (req.body?.rightsConfirmed !== 'true') return reject(400, 'FASHION_POST_RIGHTS_CONFIRMATION_REQUIRED');
      let manifest: Array<{ type: 'image' | 'video'; name: string }>;
      try {
        manifest = JSON.parse(String(req.body?.manifest || ''));
      } catch {
        return reject(400, 'FASHION_POST_MEDIA_MANIFEST_INVALID');
      }
      if (!Array.isArray(manifest) || manifest.length < 1 || manifest.length > 8
        || manifest.some(entry => !entry || !['image', 'video'].includes(entry.type) || typeof entry.name !== 'string')) {
        return reject(400, 'FASHION_POST_MEDIA_MANIFEST_INVALID');
      }
      if (uploaded.reduce((total, file) => total + file.size, 0) > 50 * 1024 * 1024) {
        return reject(413, 'FASHION_POST_MEDIA_TOTAL_TOO_LARGE');
      }
      const title = typeof req.body?.title === 'string' ? req.body.title.trim().slice(0, 120) : '';
      const text = typeof req.body?.text === 'string' ? req.body.text.trim().slice(0, 2000) : '';
      const category = typeof req.body?.category === 'string' ? req.body.category : '女装趋势';
      const requestedCity = req.body?.city;
      if (!fashionCommunityCategories.includes(category as typeof fashionCommunityCategories[number])) {
        return reject(400, 'FASHION_POST_CATEGORY_INVALID');
      }
      let hashtagsInput: unknown = [];
      if (req.body?.hashtags !== undefined) {
        try {
          hashtagsInput = JSON.parse(String(req.body.hashtags));
        } catch {
          return reject(400, 'FASHION_POST_HASHTAGS_INVALID');
        }
      }
      const hashtags = normalizeFashionHashtags(hashtagsInput);
      if (!hashtags) return reject(400, 'FASHION_POST_HASHTAGS_INVALID');
      if (requestedCity !== undefined && (typeof requestedCity !== 'string'
        || (requestedCity !== '' && !fashionCommunityCities.includes(requestedCity as typeof fashionCommunityCities[number])))) {
        return reject(400, 'FASHION_POST_CITY_INVALID');
      }
      const fileByField = new Map(uploaded.map(file => [file.fieldname, file]));
      const postId = `fashion-post-${crypto.randomUUID()}`;
      const mediaItems: FashionPostMedia[] = [];
      for (let index = 0; index < manifest.length; index += 1) {
        const item = manifest[index];
        const file = fileByField.get(`media-${index}`);
        const poster = fileByField.get(`poster-${index}`);
        if (!file || file.originalname !== item.name) return reject(400, 'FASHION_POST_MEDIA_INVALID');
        const bytes = await readFile(file.path);
        let contentType = file.mimetype.toLowerCase();
        let posterUrl: string | undefined;
        let posterStorageKey: string | undefined;
        let storedPoster: Awaited<ReturnType<typeof persistFashionAsset>> | undefined;
        if (item.type === 'image') {
          if (!contentType.startsWith('image/')) return reject(400, 'FASHION_POST_MEDIA_INVALID');
          const metadata = await sharp(bytes).metadata();
          if (!metadata.format || !['jpeg', 'png', 'webp'].includes(metadata.format)) return reject(400, 'FASHION_POST_MEDIA_INVALID');
          contentType = `image/${metadata.format === 'jpeg' ? 'jpeg' : metadata.format}`;
        } else {
          const validMp4 = contentType === 'video/mp4' && bytes.subarray(4, 8).toString('ascii') === 'ftyp';
          const validWebm = contentType === 'video/webm' && bytes.subarray(0, 4).equals(Buffer.from([0x1a, 0x45, 0xdf, 0xa3]));
          const validMov = contentType === 'video/quicktime' && bytes.subarray(4, 8).toString('ascii') === 'ftyp';
          if ((!validMp4 && !validWebm && !validMov) || !validateVideoDuration(bytes, contentType)) {
            return reject(400, 'FASHION_POST_VIDEO_INVALID');
          }
          if (!poster || poster.size > 2_200_000) return reject(400, 'FASHION_POST_VIDEO_POSTER_INVALID');
          const posterBytes = await readFile(poster.path);
          if (!posterBytes.subarray(0, 3).equals(Buffer.from([0xff, 0xd8, 0xff]))) return reject(400, 'FASHION_POST_VIDEO_POSTER_INVALID');
          storedPoster = await persistFashionAsset(posterBytes, 'image/jpeg');
          storedAssets.push({ key: storedPoster.key || undefined, localPath: storedPoster.localPath });
          posterUrl = isPrivateFashionMediaKey(storedPoster.key)
            ? fashionMediaRouteUrl(postId, index, 'poster')
            : storedPoster.url;
          posterStorageKey = storedPoster.key || undefined;
        }
        const stored = await persistFashionAsset(bytes, contentType);
        storedAssets.push({ key: stored.key || undefined, localPath: stored.localPath });
        const mediaUrl = isPrivateFashionMediaKey(stored.key)
          ? fashionMediaRouteUrl(postId, index, 'content')
          : stored.url;
        mediaItems.push({
          type: item.type,
          url: mediaUrl,
          contentType,
          sizeBytes: stored.sizeBytes,
          ...(posterUrl ? { posterUrl } : {}),
          ...(stored.key ? { storageKey: stored.key } : {}),
          ...(stored.bucket ? { storageBucket: stored.bucket } : {}),
          ...(storedPoster ? {
            posterContentType: storedPoster.contentType,
            posterSizeBytes: storedPoster.sizeBytes,
            ...(storedPoster.bucket ? { posterStorageBucket: storedPoster.bucket } : {})
          } : {}),
          ...(posterStorageKey ? { posterStorageKey } : {})
        });
      }
      const city = typeof requestedCity === 'string' && requestedCity ? requestedCity : undefined;
      const firstItem = mediaItems[0];
      const post: SharedGalleryImage = {
        id: postId,
        image: firstItem.type === 'image' ? firstItem.url : firstItem.posterUrl || '',
        mediaType: mediaItems.every(item => item.type === mediaItems[0].type) ? mediaItems[0].type : 'mixed',
        mediaItems,
        hashtags,
        ...(mediaItems.find(item => item.type === 'video') ? { videoUrl: mediaItems.find(item => item.type === 'video')?.url } : {}),
        merchantId: 'public-fashion',
        merchantName: 'RUDA Fashion Community',
        createdAt: new Date().toISOString(),
        featured: false,
        title: title || 'RUDA Fashion',
        caption: text,
        category,
        ...(city ? { city } : {}),
        creatorAccountId: (req as FashionAccountRequest).fashionAccountId,
        rightsStatus: 'authorized',
        publicationStatus: 'pending'
      };
      if (!usesFashionCommunityDatabase && sharedGallery.filter(item => item.merchantId === 'public-fashion').length >= 500) {
        return reject(409, 'FASHION_COMMUNITY_CAPACITY_REACHED');
      }
      if (!usesFashionCommunityDatabase) sharedGallery = [post, ...sharedGallery];
      try {
        if (usesFashionCommunityDatabase) await saveFashionCommunityPost(post);
        else await saveSharedGallery();
      } catch (error) {
        if (!usesFashionCommunityDatabase) sharedGallery = sharedGallery.filter(item => item.id !== post.id);
        throw error;
      }
      storedAssets.length = 0;
      await cleanup();
      return res.status(201).json({
        success: true,
        post: {
          id: post.id, image: post.image, videoUrl: post.videoUrl || null,
          mediaType: post.mediaType, mediaItems, hashtags, title: post.title, text: post.caption,
          createdAt: post.createdAt, category: post.category, city: post.city
        }
      });
    } catch (error) {
      await cleanup();
      sendInternalError(res, error, 'fashion-public-mixed-post');
    }
  });

  app.get('/api/admin/fashion/community', requireAdminAuth, requireAdminPermission('content.gallery'), async (req, res) => {
    const requestedStatus = req.query.status;
    const allowedStatuses = ['all', 'draft', 'pending', 'approved', 'unpublished'] as const;
    const status = allowedStatuses.includes(requestedStatus as typeof allowedStatuses[number])
      ? requestedStatus as typeof allowedStatuses[number]
      : 'all';
    const query = typeof req.query.q === 'string' ? req.query.q.trim().toLocaleLowerCase().slice(0, 100) : '';
    if (usesFashionCommunityDatabase) {
      try {
      const requestedLimit = Number.parseInt(String(req.query.limit || '50'), 10);
      const requestedOffset = Number.parseInt(String(req.query.offset || '0'), 10);
      const limit = Number.isFinite(requestedLimit) ? Math.min(100, Math.max(1, requestedLimit)) : 50;
      const offset = Number.isFinite(requestedOffset) ? Math.min(100_000, Math.max(0, requestedOffset)) : 0;
      const baseWhere = {
        merchantId: 'public-fashion',
        ...(query ? {
          OR: [
            { title: { contains: query, mode: 'insensitive' as const } },
            { caption: { contains: query, mode: 'insensitive' as const } },
            { merchantName: { contains: query, mode: 'insensitive' as const } }
          ]
        } : {})
      };
      const where = {
        ...baseWhere,
        ...(status !== 'all' ? { publicationStatus: status } : {})
      };
      const [rows, total, draft, pending, approved, unpublished] = await Promise.all([
        prisma.fashionCommunityPost.findMany({
          where,
          orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
          skip: offset,
          take: limit + 1,
          include: {
            _count: { select: { reactions: true, comments: true } },
            reactions: { where: { reaction: 'save' }, select: { id: true } },
            comments: { orderBy: [{ createdAt: 'desc' }, { id: 'desc' }], take: 5 }
          }
        }),
        prisma.fashionCommunityPost.count({ where }),
        prisma.fashionCommunityPost.count({ where: { merchantId: 'public-fashion', publicationStatus: 'draft' } }),
        prisma.fashionCommunityPost.count({ where: { merchantId: 'public-fashion', publicationStatus: 'pending' } }),
        prisma.fashionCommunityPost.count({ where: { merchantId: 'public-fashion', publicationStatus: 'approved' } }),
        prisma.fashionCommunityPost.count({ where: { merchantId: 'public-fashion', publicationStatus: 'unpublished' } })
      ]);
      const hasMore = rows.length > limit;
      const items = rows.slice(0, limit).map(post => withAdminFashionMediaUrls({
        ...fromFashionCommunityPost(post),
        mediaType: post.mediaType || 'image',
        videoUrl: post.videoUrl || null,
        publicationStatus: post.publicationStatus || 'approved',
        stats: {
          likes: post._count.reactions - post.reactions.length,
          comments: post._count.comments,
          saves: post.reactions.length
        },
        comments: post.comments.map(comment => ({ ...comment, createdAt: comment.createdAt.toISOString() }))
      }));
      return res.json({
        success: true,
        items,
        hasMore,
        summary: { total, draft, pending, approved, unpublished }
      });
      } catch (error) {
        sendInternalError(res, error, 'fashion-community-admin-list');
        return;
      }
    }
    const items = sharedGallery
      .filter(item => item.merchantId === 'public-fashion')
      .filter(item => status === 'all' || (item.publicationStatus || 'approved') === status)
      .filter(item => !query || [item.title, item.caption, item.merchantName].some(value => value?.toLocaleLowerCase().includes(query)))
      .map(item => {
        const social = fashionSocial[item.id];
        return withAdminFashionMediaUrls({
          ...item,
          mediaType: item.mediaType || 'image',
          videoUrl: item.videoUrl || null,
          publicationStatus: item.publicationStatus || 'approved',
          stats: {
            likes: social?.likes.length || 0,
            comments: social?.comments.length || 0,
            saves: social?.saves.length || 0
          },
          comments: (social?.comments || []).slice(-5).reverse()
        });
      });
    res.json({
      success: true,
      items,
      hasMore: false,
      summary: {
        total: sharedGallery.filter(item => item.merchantId === 'public-fashion').length,
        draft: sharedGallery.filter(item => item.merchantId === 'public-fashion' && item.publicationStatus === 'draft').length,
        pending: sharedGallery.filter(item => item.merchantId === 'public-fashion' && item.publicationStatus === 'pending').length,
        approved: sharedGallery.filter(item => item.merchantId === 'public-fashion' && (item.publicationStatus || 'approved') === 'approved').length,
        unpublished: sharedGallery.filter(item => item.merchantId === 'public-fashion' && item.publicationStatus === 'unpublished').length
      }
    });
  });

  app.post('/api/admin/fashion/community', requireAdminAuth, requireAdminPermission('content.gallery'), requireFashionObjectStorage, async (req: AuthRequest, res) => {
    let videoFilePath: string | null = null;
    let imageFilePath: string | null = null;
    let imageStorageKey: string | undefined;
    try {
      const title = typeof req.body?.title === 'string' ? req.body.title.trim().slice(0, 120) : '';
      const caption = typeof req.body?.caption === 'string' ? req.body.caption.trim().slice(0, 2000) : '';
      const category = typeof req.body?.category === 'string' ? req.body.category : '女装趋势';
      const image = typeof req.body?.image === 'string' ? req.body.image : '';
      const video = typeof req.body?.video === 'string' ? req.body.video : '';
      const mediaType = req.body?.mediaType;
      const publicationStatus = req.body?.publicationStatus;
      if (mediaType !== 'image' && mediaType !== 'video') return res.status(400).json({ success: false, error: 'FASHION_POST_MEDIA_TYPE_INVALID' });
      if (mediaType === 'video') return res.status(400).json({ success: false, error: 'FASHION_POST_MULTIPART_REQUIRED' });
      if (mediaType === 'video') return res.status(400).json({ success: false, error: 'FASHION_POST_MULTIPART_REQUIRED' });
      if (!fashionCommunityCategories.includes(category as typeof fashionCommunityCategories[number])) return res.status(400).json({ success: false, error: 'FASHION_POST_CATEGORY_INVALID' });
      if (publicationStatus !== 'pending' && publicationStatus !== 'approved') return res.status(400).json({ success: false, error: 'FASHION_PUBLICATION_STATUS_INVALID' });
      if (!usesFashionCommunityDatabase && sharedGallery.filter(item => item.merchantId === 'public-fashion').length >= 500) {
        return res.status(409).json({ success: false, error: 'FASHION_COMMUNITY_CAPACITY_REACHED' });
      }
      if (mediaType === 'image' && (!/^data:image\/(jpeg|png|webp);base64,[a-z0-9+/=]+$/i.test(image) || image.length > 2_200_000 || video)) {
        return res.status(400).json({ success: false, error: 'FASHION_POST_IMAGE_INVALID' });
      }
      if (mediaType === 'video' && image && (!/^data:image\/(jpeg|png|webp);base64,[a-z0-9+/=]+$/i.test(image) || image.length > 2_200_000)) {
        return res.status(400).json({ success: false, error: 'FASHION_POST_IMAGE_INVALID' });
      }
      const imageMatch = /^data:(image\/(?:jpeg|png|webp));base64,([a-z0-9+/=]+)$/i.exec(image);
      if (!imageMatch) return res.status(400).json({ success: false, error: 'FASHION_POST_IMAGE_INVALID' });
      const postId = `fashion-post-${crypto.randomUUID()}`;
      const storedImage = await persistFashionAsset(Buffer.from(imageMatch[2], 'base64'), imageMatch[1].toLowerCase());
      imageStorageKey = storedImage.key || undefined;
      imageFilePath = storedImage.localPath;
      const imageUrl = isPrivateFashionMediaKey(storedImage.key)
        ? fashionMediaRouteUrl(postId, 0, 'content')
        : storedImage.url;
      if (mediaType === 'video') {
        const match = /^data:(video\/(?:mp4|webm|quicktime));base64,([a-z0-9+/=]+)$/i.exec(video);
        if (!match) return res.status(400).json({ success: false, error: 'FASHION_POST_VIDEO_INVALID' });
        const contentType = match[1].toLowerCase();
        const bytes = Buffer.from(match[2], 'base64');
        if (bytes.length > 6 * 1024 * 1024 || bytes.toString('base64') !== match[2]) {
          return res.status(400).json({ success: false, error: 'FASHION_POST_VIDEO_TOO_LARGE' });
        }
        const isMp4 = contentType === 'video/mp4' && bytes.subarray(4, 8).toString('ascii') === 'ftyp';
        const isWebm = contentType === 'video/webm' && bytes.subarray(0, 4).equals(Buffer.from([0x1a, 0x45, 0xdf, 0xa3]));
        const isQuicktime = contentType === 'video/quicktime' && bytes.subarray(4, 8).toString('ascii') === 'ftyp';
        if (!isMp4 && !isWebm && !isQuicktime) return res.status(400).json({ success: false, error: 'FASHION_POST_VIDEO_FORMAT_INVALID' });
        const extension = contentType === 'video/webm' ? 'webm' : contentType === 'video/quicktime' ? 'mov' : 'mp4';
        const videoId = crypto.randomUUID();
        const videoDirectory = path.join(process.cwd(), 'public', 'uploads', 'fashion');
        await mkdir(videoDirectory, { recursive: true });
        videoFilePath = path.join(videoDirectory, `${videoId}.${extension}`);
        await writeFile(videoFilePath, bytes, { flag: 'wx' });
      }
      const videoUrl = videoFilePath ? `/uploads/fashion/${path.basename(videoFilePath)}` : undefined;
      const imageMedia: FashionPostMedia = {
        type: 'image',
        url: imageUrl,
        contentType: storedImage.contentType,
        sizeBytes: storedImage.sizeBytes,
        ...(storedImage.key ? { storageKey: storedImage.key } : {}),
        ...(storedImage.bucket ? { storageBucket: storedImage.bucket } : {})
      };
      const post: SharedGalleryImage = {
        id: postId,
        image: imageUrl,
        ...(imageStorageKey ? { imageStorageKey } : {}),
        mediaType,
        mediaItems: [imageMedia],
        merchantId: 'public-fashion',
        merchantName: 'RUDA Fashion Editorial',
        createdAt: new Date().toISOString(),
        featured: false,
        title: title || 'RUDA Fashion',
        caption,
        category,
        rightsStatus: 'authorized',
        publicationStatus
      };
      if (!usesFashionCommunityDatabase) sharedGallery = [post, ...sharedGallery];
      try {
        if (usesFashionCommunityDatabase) await saveFashionCommunityPost(post);
        else await saveSharedGallery();
      } catch (error) {
        if (!usesFashionCommunityDatabase) sharedGallery = sharedGallery.filter(item => item.id !== post.id);
        throw error;
      }
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'FASHION_POST_CREATED', 'SharedGallery', post.id, '-', publicationStatus);
      res.status(201).json({ success: true, item: post });
    } catch (error) {
      if (videoFilePath) await unlink(videoFilePath).catch(cleanupError => console.error('[fashion-admin-video-cleanup]', cleanupError));
      await deleteFashionAsset(imageStorageKey, imageFilePath).catch(cleanupError => console.error('[fashion-admin-image-cleanup]', cleanupError));
      sendInternalError(res, error, 'fashion-community-upload');
    }
  });

  app.put('/api/admin/fashion/community/:id', requireAdminAuth, requireAdminPermission('content.gallery'), requireFashionObjectStorage, async (req: AuthRequest, res) => {
    let target: SharedGalleryImage | undefined;
    try {
      target = usesFashionCommunityDatabase
        ? fromFashionCommunityPost(await prisma.fashionCommunityPost.findFirst({ where: { id: req.params.id, merchantId: 'public-fashion' } }))
        : sharedGallery.find(item => item.merchantId === 'public-fashion' && item.id === req.params.id);
    } catch (error) {
      sendInternalError(res, error, 'fashion-community-find-for-update');
      return;
    }
    if (!target) return res.status(404).json({ success: false, error: 'FASHION_POST_NOT_FOUND' });
    const publicationStatus = req.body?.publicationStatus;
    if (typeof publicationStatus !== 'undefined' && !['draft', 'pending', 'approved', 'unpublished'].includes(publicationStatus)) {
      return res.status(400).json({ success: false, error: 'FASHION_PUBLICATION_STATUS_INVALID' });
    }
    const mediaType = req.body?.mediaType;
    const replacingMedia = typeof mediaType !== 'undefined';
    let newVideoFilePath: string | null = null;
    let newImageFilePath: string | null = null;
    let newImageStorageKey: string | undefined;
    const previousItem = { ...target };
    if (replacingMedia && mediaType !== 'image' && mediaType !== 'video') {
      return res.status(400).json({ success: false, error: 'FASHION_POST_MEDIA_TYPE_INVALID' });
    }
    if (mediaType === 'video') return res.status(400).json({ success: false, error: 'FASHION_POST_MULTIPART_REQUIRED' });
    if (typeof req.body?.category !== 'undefined' && (typeof req.body.category !== 'string' || !fashionCommunityCategories.includes(req.body.category as typeof fashionCommunityCategories[number]))) {
      return res.status(400).json({ success: false, error: 'FASHION_POST_CATEGORY_INVALID' });
    }
    if (mediaType === 'image') {
      const image = typeof req.body?.image === 'string' ? req.body.image : '';
      if (!/^data:image\/(jpeg|png|webp);base64,[a-z0-9+/=]+$/i.test(image) || image.length > 2_200_000 || req.body?.video) {
        return res.status(400).json({ success: false, error: 'FASHION_POST_IMAGE_INVALID' });
      }
      const imageMatch = /^data:(image\/(?:jpeg|png|webp));base64,([a-z0-9+/=]+)$/i.exec(image);
      if (!imageMatch) return res.status(400).json({ success: false, error: 'FASHION_POST_IMAGE_INVALID' });
      try {
        const storedImage = await persistFashionAsset(Buffer.from(imageMatch[2], 'base64'), imageMatch[1].toLowerCase());
        const imageUrl = isPrivateFashionMediaKey(storedImage.key)
          ? fashionMediaRouteUrl(target.id, 0, 'content')
          : storedImage.url;
        target.image = imageUrl;
        newImageFilePath = storedImage.localPath;
        newImageStorageKey = storedImage.key || undefined;
        target.mediaItems = [{
          type: 'image',
          url: imageUrl,
          contentType: storedImage.contentType,
          sizeBytes: storedImage.sizeBytes,
          ...(storedImage.key ? { storageKey: storedImage.key } : {}),
          ...(storedImage.bucket ? { storageBucket: storedImage.bucket } : {})
        }];
      } catch (error) {
        sendInternalError(res, error, 'fashion-community-image-replace');
        return;
      }
      if (newImageStorageKey) target.imageStorageKey = newImageStorageKey;
      else delete target.imageStorageKey;
      target.mediaType = 'image';
      delete target.videoUrl;
      delete target.videoStorageKey;
      delete target.posterStorageKey;
    }
    if (mediaType === 'video') {
      const image = typeof req.body?.image === 'string' ? req.body.image : '';
      if (image && (!/^data:image\/(jpeg|png|webp);base64,[a-z0-9+/=]+$/i.test(image) || image.length > 2_200_000)) {
        return res.status(400).json({ success: false, error: 'FASHION_POST_IMAGE_INVALID' });
      }
      const match = /^data:(video\/(?:mp4|webm|quicktime));base64,([a-z0-9+/=]+)$/i.exec(String(req.body?.video || ''));
      if (!match) return res.status(400).json({ success: false, error: 'FASHION_POST_VIDEO_INVALID' });
      const contentType = match[1].toLowerCase();
      const bytes = Buffer.from(match[2], 'base64');
      if (bytes.length > 6 * 1024 * 1024 || bytes.toString('base64') !== match[2]) {
        return res.status(400).json({ success: false, error: 'FASHION_POST_VIDEO_TOO_LARGE' });
      }
      const isMp4 = contentType === 'video/mp4' && bytes.subarray(4, 8).toString('ascii') === 'ftyp';
      const isWebm = contentType === 'video/webm' && bytes.subarray(0, 4).equals(Buffer.from([0x1a, 0x45, 0xdf, 0xa3]));
      const isQuicktime = contentType === 'video/quicktime' && bytes.subarray(4, 8).toString('ascii') === 'ftyp';
      if (!isMp4 && !isWebm && !isQuicktime) return res.status(400).json({ success: false, error: 'FASHION_POST_VIDEO_FORMAT_INVALID' });
      const extension = contentType === 'video/webm' ? 'webm' : contentType === 'video/quicktime' ? 'mov' : 'mp4';
      const videoId = crypto.randomUUID();
      const videoDirectory = path.join(process.cwd(), 'public', 'uploads', 'fashion');
      try {
        await mkdir(videoDirectory, { recursive: true });
        newVideoFilePath = path.join(videoDirectory, `${videoId}.${extension}`);
        await writeFile(newVideoFilePath, bytes, { flag: 'wx' });
      } catch (error) {
        if (newVideoFilePath) await unlink(newVideoFilePath).catch(cleanupError => console.error('[fashion-admin-video-cleanup]', cleanupError));
        sendInternalError(res, error, 'fashion-community-video-replace');
        return;
      }
      target.videoUrl = `/uploads/fashion/${path.basename(newVideoFilePath)}`;
      target.image = image;
      target.mediaType = 'video';
    }
    if (typeof req.body?.title === 'string') target.title = req.body.title.trim().slice(0, 120) || 'RUDA Fashion';
    if (typeof req.body?.caption === 'string') target.caption = req.body.caption.trim().slice(0, 2000);
    if (typeof req.body?.category === 'string') target.category = req.body.category;
    if (publicationStatus) target.publicationStatus = publicationStatus;
    if (publicationStatus && publicationStatus !== 'approved') target.featured = false;
    if (publicationStatus === 'approved') target.rightsStatus = 'authorized';
    else if (req.body?.rightsStatus === 'restricted') target.rightsStatus = 'restricted';
    try {
      if (usesFashionCommunityDatabase) await saveFashionCommunityPost(target);
      else await saveSharedGallery();
    } catch (error) {
      Object.assign(target, previousItem);
      if (newVideoFilePath) await unlink(newVideoFilePath).catch(cleanupError => console.error('[fashion-admin-video-cleanup]', cleanupError));
      await deleteFashionAsset(newImageStorageKey, newImageFilePath).catch(cleanupError => console.error('[fashion-admin-image-cleanup]', cleanupError));
      sendInternalError(res, error, 'fashion-community-update');
      return;
    }
    if (replacingMedia && mediaType === 'image') {
      await deleteFashionPostAssets(previousItem).catch(error => console.error('[fashion-admin-media-replace]', error));
    }
    logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'FASHION_POST_UPDATED', 'SharedGallery', target.id, '-', JSON.stringify({ publicationStatus: target.publicationStatus, title: target.title }));
    res.json({ success: true, item: target });
  });

  app.delete('/api/admin/fashion/community/:id', requireAdminAuth, requireAdminPermission('content.gallery'), async (req: AuthRequest, res) => {
    let target: SharedGalleryImage | undefined;
    try {
      target = usesFashionCommunityDatabase
        ? fromFashionCommunityPost(await prisma.fashionCommunityPost.findFirst({ where: { id: req.params.id, merchantId: 'public-fashion' } }))
        : sharedGallery.find(item => item.merchantId === 'public-fashion' && item.id === req.params.id);
    } catch (error) {
      sendInternalError(res, error, 'fashion-community-find-for-delete');
      return;
    }
    if (!target) return res.status(404).json({ success: false, error: 'FASHION_POST_NOT_FOUND' });
    try {
      if (usesFashionCommunityDatabase) await prisma.fashionCommunityPost.delete({ where: { id: target.id } });
      else {
        sharedGallery = sharedGallery.filter(item => item.id !== target.id);
        await saveSharedGallery();
      }
    } catch (error) {
      if (!usesFashionCommunityDatabase) sharedGallery.unshift(target);
      sendInternalError(res, error, 'fashion-community-delete');
      return;
    }
    await deleteFashionPostAssets(target).catch(error => console.error('[fashion-community-media-delete]', error));
    if (!usesFashionCommunityDatabase) {
      delete fashionSocial[target.id];
      await saveFashionSocial();
    }
    logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'FASHION_POST_DELETED', 'SharedGallery', target.id, '-', 'deleted');
    res.json({ success: true, id: target.id });
  });

  app.delete('/api/admin/fashion/community/:id/comments/:commentId', requireAdminAuth, requireAdminPermission('content.gallery'), async (req: AuthRequest, res) => {
    let target: SharedGalleryImage | undefined;
    try {
      target = usesFashionCommunityDatabase
        ? fromFashionCommunityPost(await prisma.fashionCommunityPost.findFirst({ where: { id: req.params.id, merchantId: 'public-fashion' } }))
        : sharedGallery.find(item => item.merchantId === 'public-fashion' && item.id === req.params.id);
    } catch (error) {
      sendInternalError(res, error, 'fashion-community-find-for-comment-delete');
      return;
    }
    if (!target) return res.status(404).json({ success: false, error: 'FASHION_POST_NOT_FOUND' });
    if (usesFashionCommunityDatabase) {
      const commentsCount = await prisma.$transaction(async transaction => {
        const deleted = await transaction.fashionCommunityComment.deleteMany({
            where: { id: req.params.commentId, contentId: target.id }
        });
        if (!deleted.count) return null;
        await transaction.fashionCommunityPost.update({
          where: { id: target.id },
          data: { engagementScore: { decrement: 3 } },
          select: { id: true }
        });
        return transaction.fashionCommunityComment.count({ where: { postId: target.id } });
      });
      if (commentsCount === null) return res.status(404).json({ success: false, error: 'FASHION_COMMENT_NOT_FOUND' });
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'FASHION_COMMENT_DELETED', 'FashionComment', req.params.commentId, target.id, 'deleted');
      return res.json({ success: true, commentsCount });
    }
    const social = fashionSocial[target.id];
    if (!social?.comments.some(comment => comment.id === req.params.commentId)) {
      return res.status(404).json({ success: false, error: 'FASHION_COMMENT_NOT_FOUND' });
    }
    social.comments = social.comments.filter(comment => comment.id !== req.params.commentId);
    await saveFashionSocial();
    logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'FASHION_COMMENT_DELETED', 'FashionComment', req.params.commentId, target.id, 'deleted');
    res.json({ success: true, commentsCount: social.comments.length });
  });

  app.get('/api/admin/fashion-feeds', requireAdminAuth, requireAdminPermission('content.gallery'), (_req, res) => {
    res.json({ success: true, sources: fashionFeedSources, items: fashionFeedItems });
  });

  app.post('/api/admin/fashion-feeds/sources', requireAdminAuth, requireAdminPermission('content.gallery'), async (req: AuthRequest, res) => {
    const name = String(req.body?.name || '').trim();
    const feedUrl = String(req.body?.feedUrl || '').trim();
    const licenseEvidence = String(req.body?.licenseEvidence || '').trim();
    if (!name || !/^https?:\/\//i.test(feedUrl) || !licenseEvidence) return res.status(400).json({ success: false, error: 'FEED_SOURCE_REQUIRES_LICENSE_AND_URL' });
    const source: FashionFeedSource = { id: `feed-${crypto.randomUUID()}`, name, feedUrl, licenseEvidence, enabled: true };
    fashionFeedSources.unshift(source);
    await saveFashionFeeds();
    res.status(201).json({ success: true, source });
  });

  app.post('/api/admin/fashion-feeds/run', requireAdminAuth, requireAdminPermission('content.gallery'), async (_req, res) => {
    await runFashionFeedIngestion();
    res.json({ success: true, sources: fashionFeedSources, items: fashionFeedItems });
  });

  app.put('/api/admin/fashion-feeds/items/:id', requireAdminAuth, requireAdminPermission('content.gallery'), async (req: AuthRequest, res) => {
    const item = fashionFeedItems.find(entry => entry.id === req.params.id);
    if (!item) return res.status(404).json({ success: false, error: 'FEED_ITEM_NOT_FOUND' });
    const status = req.body?.status;
    if (status !== 'approved' && status !== 'rejected' && status !== 'pending') return res.status(400).json({ success: false, error: 'FEED_STATUS_INVALID' });
    item.status = status;
    item.reviewedAt = new Date().toISOString();
    if (status === 'approved' && !sharedGallery.some(image => image.id === `feed-${item.id}`)) {
      sharedGallery.unshift({ id: `feed-${item.id}`, image: item.image, merchantId: 'platform', merchantName: 'RUDA Editorial', createdAt: item.createdAt, featured: false });
      sharedGallery = sharedGallery.slice(0, 500);
      await saveSharedGallery();
    }
    await saveFashionFeeds();
    res.json({ success: true, item });
  });

  app.get('/api/merchant/gallery', requireMerchantTenant, (_req, res) => {
    res.json({ success: true, images: sharedGallery });
  });

  app.post('/api/merchant/gallery', requireMerchantTenant, async (req: AuthRequest, res) => {
    try {
      const merchant = (req as any).merchant;
      const images = Array.isArray(req.body?.images) ? req.body.images : [];
      if (!images.length || images.length > 24) return res.status(400).json({ success: false, error: 'GALLERY_IMAGE_COUNT_INVALID' });
      const validImages = images.filter((image: unknown): image is string => typeof image === 'string'
        && /^data:image\/(jpeg|png|webp);base64,[a-z0-9+/=]+$/i.test(image)
        && image.length <= 2_200_000);
      if (!validImages.length || validImages.length !== images.length) {
        return res.status(400).json({ success: false, error: 'GALLERY_IMAGE_INVALID' });
      }
      const newImages = validImages.map(image => ({
        id: `gallery-${crypto.randomUUID()}`,
        image,
        merchantId: merchant.merchantId,
        merchantName: merchant.name,
        createdAt: new Date().toISOString(),
        publicationStatus: 'pending' as const,
        rightsStatus: 'pending' as const
      }));
      sharedGallery = [...newImages, ...sharedGallery].slice(0, 500);
      await saveSharedGallery();
      logAudit(merchant.name, 'merchant', 'GALLERY_UPLOAD', 'SharedGallery', newImages[0].id, '-', `${newImages.length} image(s)`);
      res.status(201).json({ success: true, images: newImages });
    } catch (error) {
      sendInternalError(res, error, 'merchant-gallery-upload');
    }
  });

  app.delete('/api/merchant/gallery/:id', requireMerchantTenant, async (req: AuthRequest, res) => {
    try {
      const merchantId = (req as any).merchant.merchantId;
      const target = sharedGallery.find(image => image.id === req.params.id);
      if (!target) return res.status(404).json({ success: false, error: 'GALLERY_IMAGE_NOT_FOUND' });
      if (target.merchantId !== merchantId) return sendAccessDenied(res, 'GALLERY_IMAGE_FORBIDDEN');
      sharedGallery = sharedGallery.filter(image => image.id !== target.id);
      await saveSharedGallery();
      res.json({ success: true, id: target.id });
    } catch (error) {
      sendInternalError(res, error, 'merchant-gallery-delete');
    }
  });

