  app.post('/api/admin/website-collector/jobs', requireAdminAuth, requireAdminPermission('content.gallery'), async (req: AuthRequest, res) => {
    const urls = Array.isArray(req.body?.urls)
      ? req.body.urls.map((value: unknown) => String(value).trim()).filter(Boolean).slice(0, 20)
      : String(req.body?.url || '').split(/\r?\n|,/).map(value => value.trim()).filter(Boolean).slice(0, 20);
    const validUrls = urls.filter(url => Boolean(normalizeCollectorUrl(url)));
    if (!validUrls.length) return res.status(400).json({ success: false, error: 'COLLECTOR_URL_REQUIRED' });
    const job: WebsiteCollectorJob = { id: `collector-job-${crypto.randomUUID()}`, urls: validUrls, status: 'queued', discovered: 0, downloaded: 0, duplicates: 0, failed: urls.length - validUrls.length, results: [], createdAt: new Date().toISOString() };
    websiteCollectorJobs.set(job.id, job);
    void runWebsiteCollector(job);
    res.status(202).json({ success: true, job });
  });

  app.get('/api/admin/website-collector/jobs/:id', requireAdminAuth, requireAdminPermission('content.gallery'), (req, res) => {
    const job = websiteCollectorJobs.get(req.params.id);
    if (!job) return res.status(404).json({ success: false, error: 'COLLECTOR_JOB_NOT_FOUND' });
    res.json({ success: true, job });
  });

  app.get('/api/admin/website-collector/history', requireAdminAuth, requireAdminPermission('content.gallery'), async (_req, res) => {
    try {
      const saved = JSON.parse(await readFile(collectorJobPath, 'utf8'));
      res.json({ success: true, jobs: Array.isArray(saved) ? saved.slice(-50).reverse() : [] });
    } catch {
      res.json({ success: true, jobs: [] });
    }
  });

  app.post('/api/admin/website-collector/schedules', requireAdminAuth, requireAdminPermission('content.gallery'), (req, res) => {
    const urls = Array.isArray(req.body?.urls) ? req.body.urls.map(String).filter((value: string) => normalizeCollectorUrl(value)).slice(0, 20) : [];
    const intervalMinutes = Math.max(15, Math.min(10080, Number(req.body?.intervalMinutes || 1440)));
    if (!urls.length) return res.status(400).json({ success: false, error: 'COLLECTOR_URL_REQUIRED' });
    const schedule = { id: `collector-schedule-${crypto.randomUUID()}`, urls, intervalMinutes, enabled: true };
    collectorSchedules.set(schedule.id, schedule);
    const timer = setInterval(() => {
      const job: WebsiteCollectorJob = { id: `collector-job-${crypto.randomUUID()}`, urls: schedule.urls, status: 'queued', discovered: 0, downloaded: 0, duplicates: 0, failed: 0, results: [], createdAt: new Date().toISOString() };
      websiteCollectorJobs.set(job.id, job);
      void runWebsiteCollector(job);
    }, intervalMinutes * 60_000);
    timer.unref();
    res.status(201).json({ success: true, schedule });
  });

  app.get('/api/admin/website-collector/jobs/:id/export', requireAdminAuth, requireAdminPermission('content.gallery'), (req, res) => {
    const job = websiteCollectorJobs.get(req.params.id);
    if (!job) return res.status(404).json({ success: false, error: 'COLLECTOR_JOB_NOT_FOUND' });
    const header = 'id,sourceUrl,pageUrl,sourceHost,width,height,bytes,qualityScore,category,colors,materials,style,trendTags,rightsStatus,createdAt';
    const rows = job.results.map(item => [item.id, item.sourceUrl, item.pageUrl, item.sourceHost, item.width, item.height, item.bytes, item.qualityScore, item.analysis.category, item.analysis.colors.join('|'), item.analysis.materials.join('|'), item.analysis.style.join('|'), item.analysis.trendTags.join('|'), item.rightsStatus, item.createdAt].map(value => `"${String(value).replaceAll('"', '""')}"`).join(','));
    res.type('text/csv').set('Content-Disposition', `attachment; filename="ruda-collector-${job.id}.csv"`).send([header, ...rows].join('\n'));
  });

  app.get('/api/admin/website-collector/similar/:id', requireAdminAuth, requireAdminPermission('content.gallery'), (req, res) => {
    const target = [...websiteCollectorJobs.values()].flatMap(job => job.results).find(item => item.id === req.params.id);
    if (!target) return res.status(404).json({ success: false, error: 'COLLECTOR_IMAGE_NOT_FOUND' });
    const matches = [...websiteCollectorJobs.values()].flatMap(job => job.results).filter(item => item.id !== target.id && phashDistance(item.phash, target.phash) <= 10).slice(0, 24);
    res.json({ success: true, images: matches });
  });

