    const imported = job.results.filter(item => selected.includes(item.id) && !sharedGallery.some(image => image.id === item.id)).map(item => ({
      id: item.id, image: item.image, merchantId: 'platform', merchantName: 'RUDA Collector',
      createdAt: item.createdAt, featured: false, title: 'RUDA Fashion Edit', caption: item.sourceUrl,
      category: 'Editorial', rightsStatus: 'pending' as const, publicationStatus: 'pending' as const
    }));
