    await saveSharedGallery();
    logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'COLLECTOR_IMPORT', 'SharedGallery', job.id, '-', `${imported.length} image(s)`);
    res.json({ success: true, images: imported });
