      const where = { merchantId: req.merchant!.merchantId, ...(req.merchant!.employeeId && !canReview ? { requesterEmployeeId: req.merchant!.employeeId } : {}) };
      const requests = await prisma.pricingApprovalRequest.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        take: 100,
        include: { requester: { select: { name: true, email: true } } }
      });
