  // POST /api/merchant/customers — create a tenant-scoped buyer relationship.
  app.post('/api/merchant/customers', requireMerchantTenant, requireEmployeePermission('sales.order.create', 'sales', 'store_manager'), async (req: AuthRequest, res) => {
    const merchantId = req.merchant!.merchantId;
    const body = req.body || {};
    const companyName = String(body.companyName || '').trim();
    const contactPerson = String(body.contactPerson || '').trim();
    const emailInput = String(body.email || '').trim().toLowerCase();
    const vatNumber = String(body.vatNumber || '').trim().toUpperCase();
    const address = String(body.address || '').trim();
    const city = String(body.city || '').trim();
    const country = String(body.country || 'Italy').trim();
    const phone = String(body.phone || '').trim();
    const businessType = String(body.businessType || 'Boutique').trim();
    const customerLevel = String(body.customerLevel || 'new_customer').trim();
    const email = emailInput || `no-email-${crypto.randomUUID()}@ruda.local`;
    const notes = typeof body.merchantNotes === 'string'
      ? body.merchantNotes.trim().slice(0, 2000)
      : typeof body.notes === 'string' ? body.notes.trim().slice(0, 2000) : null;
    const tags = Array.isArray(body.merchantTags)
      ? [...new Set<string>(body.merchantTags.map((tag: unknown) => String(tag).trim()).filter((tag: string) => Boolean(tag)))].slice(0, 30)
      : undefined;
    if (Array.isArray(body.merchantTags) && (body.merchantTags.length > 30 || body.merchantTags.some((tag: unknown) => String(tag).trim().length > 40))) {
      return res.status(400).json({ success: false, error: 'MERCHANT_CUSTOMER_TAGS_INVALID' });
    }
    const validBusinessTypes = ['Boutique', 'Retail Store', 'Online Store', 'Department Store', 'Wholesale Buyer', 'Distributor', 'Brand', 'Stylist / Atelier', 'Other'];
    const validCustomerLevels = ['good_customer', 'regular_customer', 'new_customer', 'standard_customer', 'overdue_customer'];
    if (!companyName || companyName.length > 200 || email.length > 200 || vatNumber.length > 40 ||
        address.length > 300 || city.length > 120 || !country || country.length > 120 ||
        !phone || phone.length > 60 || !validBusinessTypes.includes(businessType) || !validCustomerLevels.includes(customerLevel)) {
      return res.status(400).json({ success: false, error: 'MERCHANT_CUSTOMER_INPUT_INVALID' });
    }
    try {
      const result = await prisma.$transaction(async tx => {
        const existing = await tx.customer.findFirst({
          where: { OR: [...(emailInput ? [{ email }] : []), ...(vatNumber ? [{ vatNumber }] : [])] }
        });
        const record = existing
          ? await tx.customer.update({ where: { id: existing.id }, data: { customerLevel } })
          : await tx.customer.create({
          data: {
            id: crypto.randomUUID(),
            companyName, vatNumber, address, city, country, contactPerson, phone, email,
            businessType, customerLevel, registrationDate: new Date().toISOString().slice(0, 10),
            status: 'pending', onboardingStatus: 'document_check'
          }
        });
        const link = await tx.merchantCustomerLink.upsert({
          where: { merchantId_customerId: { merchantId, customerId: record.id } },
          create: { merchantId, customerId: record.id, notes, ...(tags ? { tags: JSON.stringify(tags) } : {}) },
          update: { notes, ...(tags ? { tags: JSON.stringify(tags) } : {}) }
        });
        return { customer: record, link };
      });
      const customer = result.customer;
      logAudit((req as any).merchant.name, 'merchant', 'CUSTOMER_CREATED', 'Customer', customer.id, '', `${customer.companyName} (${customer.email})`);
      let merchantTags: string[] = [];
      try {
        const parsed: unknown = JSON.parse(result.link.tags || '[]');
        if (Array.isArray(parsed)) merchantTags = parsed.filter((tag): tag is string => typeof tag === 'string');
      } catch {
        console.warn('[merchant-customer-create] Invalid customer tag JSON', customer.id);
      }
      res.status(201).json({
        success: true,
        customer: {
          ...customer,
          merchantNotes: result.link.notes || '',
          merchantTags,
          creditLimit: Number(customer.creditLimit),
          usedCredit: Number(customer.usedCredit),
          discountRate: Number(customer.discountRate)
        }
      });
    } catch (error) {
      sendInternalError(res, error, 'merchant-customer-create');
    }
  });

  app.put('/api/merchant/customers/:id', requireMerchantTenant, requireEmployeePermission('sales.order.create', 'sales', 'store_manager'), async (req: AuthRequest, res) => {
    const merchantId = req.merchant!.merchantId;
    const customerId = String(req.params.id);
    const body = req.body || {};
    const companyName = String(body.companyName || '').trim();
    const contactPerson = String(body.contactPerson || '').trim();
    const emailInput = String(body.email || '').trim().toLowerCase();
    const vatNumber = String(body.vatNumber || '').trim().toUpperCase();
    const address = String(body.address || '').trim();
    const city = String(body.city || '').trim();
    const country = String(body.country || 'Italy').trim();
    const phone = String(body.phone || '').trim();
    const businessType = String(body.businessType || 'Boutique').trim();
    const customerLevel = String(body.customerLevel || 'new_customer').trim();
    const email = emailInput || `no-email-${crypto.randomUUID()}@ruda.local`;
    const notes = typeof body.merchantNotes === 'string'
      ? body.merchantNotes.trim().slice(0, 2000)
      : typeof body.notes === 'string' ? body.notes.trim().slice(0, 2000) : null;
    const tags = Array.isArray(body.merchantTags)
      ? [...new Set<string>(body.merchantTags.map((tag: unknown) => String(tag).trim()).filter((tag: string) => Boolean(tag)))].slice(0, 30)
      : undefined;
    if (Array.isArray(body.merchantTags) && (body.merchantTags.length > 30 || body.merchantTags.some((tag: unknown) => String(tag).trim().length > 40))) {
      return res.status(400).json({ success: false, error: 'MERCHANT_CUSTOMER_TAGS_INVALID' });
    }
    const validBusinessTypes = ['Boutique', 'Retail Store', 'Online Store', 'Department Store', 'Wholesale Buyer', 'Distributor', 'Brand', 'Stylist / Atelier', 'Other'];
    const validCustomerLevels = ['good_customer', 'regular_customer', 'new_customer', 'standard_customer', 'overdue_customer'];
    if (!companyName || companyName.length > 200 || email.length > 200 || vatNumber.length > 40 ||
        address.length > 300 || city.length > 120 || !country || country.length > 120 ||
        !phone || phone.length > 60 || !validBusinessTypes.includes(businessType) || !validCustomerLevels.includes(customerLevel)) {
      return res.status(400).json({ success: false, error: 'MERCHANT_CUSTOMER_INPUT_INVALID' });
    }
    try {
      const link = await prisma.merchantCustomerLink.findUnique({ where: { merchantId_customerId: { merchantId, customerId } } });
      if (!link) return res.status(404).json({ success: false, error: 'MERCHANT_CUSTOMER_NOT_FOUND' });
      const conflict = await prisma.customer.findFirst({ where: { id: { not: customerId }, OR: [...(emailInput ? [{ email }] : []), ...(vatNumber ? [{ vatNumber }] : [])] }, select: { id: true } });
      if (conflict) return res.status(409).json({ success: false, error: 'CUSTOMER_EMAIL_OR_VAT_IN_USE' });
      const result = await prisma.$transaction(async tx => {
        const updated = await tx.customer.update({ where: { id: customerId }, data: { companyName, contactPerson, email, vatNumber, address, city, country, phone, businessType, customerLevel } });
        const link = await tx.merchantCustomerLink.update({
          where: { merchantId_customerId: { merchantId, customerId } },
          data: { notes, ...(tags ? { tags: JSON.stringify(tags) } : {}) }
        });
        return { customer: updated, link };
      });
      const customer = result.customer;
      logAudit(merchantId, 'merchant', 'CUSTOMER_UPDATED', 'Customer', customer.id, '', `${customer.companyName} (${customer.email})`);
      return res.json({
        success: true,
        customer: {
          ...customer,
          merchantNotes: notes || '',
          merchantTags: tags || (() => {
            try {
              const parsed: unknown = JSON.parse(result.link.tags || '[]');
              return Array.isArray(parsed) ? parsed.filter((value): value is string => typeof value === 'string') : [];
            } catch {
              return [];
            }
          })(),
          creditLimit: Number(customer.creditLimit),
          usedCredit: Number(customer.usedCredit),
          discountRate: Number(customer.discountRate)
        }
      });
    } catch (error) {
      return sendInternalError(res, error, 'merchant-customer-update');
    }
  });

  app.put('/api/merchant/customers/batch/tags', requireMerchantTenant, requireEmployeePermission('sales.order.create', 'sales', 'store_manager'), async (req: AuthRequest, res) => {
    const merchantId = req.merchant!.merchantId;
    const customerIds: string[] = Array.isArray(req.body?.customerIds)
      ? [...new Set<string>(req.body.customerIds.map((id: unknown) => String(id).trim()).filter((id): id is string => Boolean(id)))]
      : [];
    const tag = String(req.body?.tag || '').trim();
    const mode = String(req.body?.mode || '');
    if (!customerIds.length || customerIds.length > 500 || !tag || tag.length > 40 || !['add', 'remove'].includes(mode)) {
      return res.status(400).json({ success: false, error: 'CUSTOMER_BATCH_TAG_INVALID' });
    }
    try {
      const links = await prisma.merchantCustomerLink.findMany({
        where: { merchantId, customerId: { in: customerIds } },
        select: { customerId: true, tags: true }
      });
      if (links.length !== customerIds.length) {
        return res.status(404).json({ success: false, error: 'MERCHANT_CUSTOMER_SCOPE_INVALID' });
      }
      await prisma.$transaction(links.map(link => {
        let currentTags: string[] = [];
        try {
          const parsed: unknown = JSON.parse(link.tags || '[]');
          if (Array.isArray(parsed)) currentTags = parsed.filter((value): value is string => typeof value === 'string');
        } catch {
          currentTags = [];
        }
        const tags = mode === 'add'
          ? [...new Set([...currentTags, tag])].slice(0, 30)
          : currentTags.filter(currentTag => currentTag !== tag);
        return prisma.merchantCustomerLink.update({
          where: { merchantId_customerId: { merchantId, customerId: link.customerId } },
          data: { tags: JSON.stringify(tags) }
        });
      }));
      logAudit(merchantId, 'merchant', 'CUSTOMER_BATCH_TAGS_UPDATED', 'Customer', customerIds.join(','), '', `${mode}:${tag}`);
      return res.json({ success: true, customerIds });
    } catch (error) {
      return sendInternalError(res, error, 'merchant-customer-batch-tags');
    }
  });

