  // POST /api/merchant/vault-requests/:id/review (商家审批买手看货申请: Approve / Reject)
  app.put('/api/merchant/vault-requests/:id/review', requireMerchantTenant, requireEmployeePermission('pricing.approve', 'store_manager'), async (req, res) => {
    const merchantId = (req as any).merchant.merchantId;
    const requestId = req.params.id;
    const { status, notes } = req.body; // status: 'approved' | 'rejected'

    const reqItem = await prisma.vaultAccessRequest.findFirst({ where: { id: requestId, merchantId } });
    if (!reqItem) {
      return res.status(404).json({ success: false, error: 'Vault request not found or unauthorized' });
    }

    if (!['approved', 'rejected'].includes(status)) return res.status(400).json({ success: false, error: 'VAULT_STATUS_INVALID' });
    const oldStatus = reqItem.status;
    const updated = await prisma.vaultAccessRequest.update({ where: { id: requestId }, data: {
      status,
      reviewedAt: new Date().toISOString().replace('T', ' ').substring(0, 19),
      approvedBy: (req as any).merchant.contactPerson,
      expiresAt: status === 'approved' ? new Date(Date.now() + 180 * 24 * 60 * 60 * 1000).toISOString() : null,
      note: notes ? `${reqItem.note || ''} [商家回复: ${String(notes).slice(0, 500)}]` : reqItem.note
    } });

    logAudit((req as any).merchant.name, 'merchant', 'VAULT_REQUEST_REVIEW', 'VaultAccessRequest', requestId, oldStatus, status);

    res.json({ success: true, request: updated });
  });

  // GET /api/merchant/finance (商家结算与佣金对账)
  app.get('/api/merchant/finance', requireMerchantTenant, async (req, res) => {
    try {
      const merchantId = (req as any).merchant.merchantId;
      const rows = await prisma.merchantPayout.findMany({
        where: { merchantId },
        include: { allocations: { select: { orderId: true, grossAmount: true, refundAmount: true, netAmount: true, order: { select: { orderNo: true, date: true, paymentStatus: true, refundStatus: true } } } } },
        orderBy: { createdAt: 'desc' }
      });
      const payouts = rows.map(row => ({
        ...row,
        grossSales: Number(row.grossSales),
        platformFeeRate: Number(row.platformFeeRate),
        platformFeeAmount: Number(row.platformFeeAmount),
        paymentProcessingFee: Number(row.paymentProcessingFee),
        refunds: Number(row.refunds),
        netPayout: Number(row.netPayout),
        orderIds: parseStoredJson(row.orderIds, []),
        allocations: row.allocations.map(item => ({
          ...item,
          grossAmount: Number(item.grossAmount),
          refundAmount: Number(item.refundAmount),
          netAmount: Number(item.netAmount),
          order: item.order
        }))
      }));
      const totalGross = payouts.reduce((acc, p) => acc + p.grossSales, 0);
      const totalFees = payouts.reduce((acc, p) => acc + p.platformFeeAmount + p.paymentProcessingFee, 0);
      const totalNet = payouts.reduce((acc, p) => acc + p.netPayout, 0);

      res.json({
        success: true,
        summary: { totalGross, totalFees, totalNet, totalRefunds: payouts.reduce((acc, p) => acc + p.refunds, 0), commissionRate: '按商户配置', paymentFeeRate: '2%' },
        payouts
      });
    } catch (error) {
      sendInternalError(res, error, 'merchant-finance');
    }
  });

