  app.post('/api/admin/inventory/inbound', requireAdminAuth, requireAdminPermission('inventory.adjust'), async (req: AuthRequest, res) => {
    try {
      const productId = String(req.body?.productId || '');
      const skuCode = String(req.body?.sku || '');
      const location = String(req.body?.location || SINGLE_WAREHOUSE_CODE);
      const quantity = Number(req.body?.quantity);
      const referenceId = String(req.body?.referenceId || '').trim();
      if (!productId || !skuCode || location !== SINGLE_WAREHOUSE_CODE || !Number.isInteger(quantity) || quantity <= 0
        || referenceId.length < 8 || referenceId.length > 120) {
        return res.status(400).json({ success: false, error: 'INBOUND_INPUT_INVALID' });
      }
      const product = await prisma.product.findUnique({ where: { id: productId } });
      if (!product) return res.status(404).json({ success: false, error: 'PRODUCT_NOT_FOUND' });
      const locationKey = 'stockCentral';
      const skus = parseStoredJson<any[]>(product.skus, []);
      const sku = skus.find(item => item.sku === skuCode);
      if (!sku) return res.status(404).json({ success: false, error: 'SKU_NOT_FOUND' });
      const existingMovement = await prisma.inventoryMovement.findFirst({
        where: {
          referenceType: 'InventoryInbound',
          referenceId,
          movementType: 'inbound',
          variant: { is: { productId, sku: skuCode } },
          location: { is: { code: SINGLE_WAREHOUSE_CODE } }
        },
        select: { quantity: true }
      });
      if (existingMovement) {
        if (existingMovement.quantity !== quantity) return res.status(409).json({ success: false, error: 'INVENTORY_IDEMPOTENCY_KEY_REUSED' });
        return res.json({ success: true, idempotent: true, product: serializeProductRow(product), referenceId });
      }
      const updated = await prisma.$transaction(async tx => {
        await applyInventoryLedgerChanges(tx, [{
          productId, sku: skuCode, locationCode: SINGLE_WAREHOUSE_CODE,
          merchantId: product.merchantId, onHandDelta: quantity, movementType: 'inbound',
          referenceType: 'InventoryInbound', referenceId,
          operatorId: req.admin?.username, note: req.body?.note ? String(req.body.note).slice(0, 500) : null
        }]);
        sku[locationKey] = Number(sku[locationKey] || 0) + quantity;
        return tx.product.update({
          where: { id: productId },
          data: { skus: JSON.stringify(skus), inventoryVersion: { increment: 1 } }
        });
      }, { isolationLevel: Prisma.TransactionIsolationLevel.Serializable });
      res.status(201).json({ success: true, referenceId, product: serializeProductRow(updated) });
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === 'P2002') {
        return res.status(409).json({ success: false, error: 'INVENTORY_REQUEST_ALREADY_PROCESSED' });
      }
      if (error instanceof Error && ['INVENTORY_CONCURRENT_UPDATE', 'INVENTORY_LEDGER_CONCURRENT_UPDATE', 'INVENTORY_BALANCE_NOT_FOUND', 'INVENTORY_LOCATION_NOT_CONFIGURED'].includes(error.message)) {
        return res.status(409).json({ success: false, error: 'INVENTORY_CHANGED_RETRY' });
      }
      sendInternalError(res, error, 'admin-inventory-inbound');
    }
  });

