  app.post('/api/merchant/assistant/memories', requireMerchantTenant, async (req: AuthRequest, res) => {
    const content = typeof req.body?.content === 'string' ? req.body.content.trim() : '';
    if (!content) return res.status(400).json({ success: false, error: 'ASSISTANT_MEMORY_REQUIRED' });
    if (content.length > 500) return res.status(400).json({ success: false, error: 'ASSISTANT_MEMORY_TOO_LONG' });
    const safeContent = redactSupportMessage(content);
    try {
      const where = { merchantId: req.merchant!.merchantId, actorId: merchantAssistantActorId(req) };
      const [count, duplicate] = await Promise.all([
        prisma.merchantAssistantMemory.count({ where }),
        prisma.merchantAssistantMemory.findFirst({ where: { ...where, content: safeContent } })
      ]);
      if (duplicate) return res.status(409).json({ success: false, error: 'ASSISTANT_MEMORY_ALREADY_EXISTS' });
      if (count >= 25) return res.status(409).json({ success: false, error: 'ASSISTANT_MEMORY_LIMIT_REACHED' });
      const memory = await prisma.merchantAssistantMemory.create({
        data: { ...where, content: safeContent }
      });
      res.status(201).json({ success: true, memory });
    } catch (error) {
      sendInternalError(res, error, 'merchant-assistant-memory-create');
    }
  });

