  app.post(
    '/api/merchant/modagpt/brain/documents',
    requireMerchantTenant,
    requireEmployeePermission('brain.write'),
    merchantSupportMessageRateLimit,
    async (req: AuthRequest, res) => {
      if (!modaGptBrainEnabled) return res.status(503).json({ success: false, error: 'MODAGPT_BRAIN_DISABLED' });
      const body = req.body;
      const allowedFields = new Set(['title', 'sourceId', 'mimeType', 'content', 'requiredPermissions']);
      if (!isPlainRecord(body)) {
        return res.status(400).json({ success: false, error: 'MODAGPT_BRAIN_DOCUMENT_INPUT_INVALID' });
      }
      const title = typeof body.title === 'string' ? body.title : null;
      const content = typeof body.content === 'string' ? body.content : null;
      if (Object.keys(body).some(key => !allowedFields.has(key))
        || title === null
        || content === null) {
        return res.status(400).json({ success: false, error: 'MODAGPT_BRAIN_DOCUMENT_INPUT_INVALID' });
      }
      const sourceId = body.sourceId === undefined
        ? undefined
        : typeof body.sourceId === 'string' ? body.sourceId : null;
      if (sourceId === null) {
        return res.status(400).json({ success: false, error: 'MODAGPT_BRAIN_DOCUMENT_INPUT_INVALID' });
      }
      const requestedMimeType = body.mimeType === undefined
        ? undefined
        : typeof body.mimeType === 'string' ? body.mimeType : null;
      if (requestedMimeType === null) {
        return res.status(400).json({ success: false, error: 'MODAGPT_BRAIN_DOCUMENT_INPUT_INVALID' });
      }
      const requestedPermissions = body.requiredPermissions;
      let requiredPermissions: string[] | undefined;
      if (requestedPermissions !== undefined) {
        if (!Array.isArray(requestedPermissions)) {
          return res.status(400).json({ success: false, error: 'MODAGPT_BRAIN_DOCUMENT_INPUT_INVALID' });
        }
        requiredPermissions = [];
        for (const permission of requestedPermissions) {
          if (typeof permission !== 'string') {
            return res.status(400).json({ success: false, error: 'MODAGPT_BRAIN_DOCUMENT_INPUT_INVALID' });
          }
          requiredPermissions.push(permission);
        }
      }
      if (Buffer.byteLength(content, 'utf8') > 512 * 1024) {
        return res.status(400).json({ success: false, error: 'MODAGPT_BRAIN_DOCUMENT_INPUT_INVALID' });
      }
      const mimeType = requestedMimeType || 'text/plain';
      if (!['text/plain', 'text/markdown', 'text/x-markdown'].includes(mimeType)) {
        return res.status(415).json({ success: false, error: 'MODAGPT_BRAIN_DOCUMENT_MIME_UNSUPPORTED' });
      }
      const merchantId = req.merchant!.merchantId;
      try {
        const document = await modaGptBrainService.ingestTextDocument({
          tenantId: merchantId,
          merchantId,
          actorId: req.merchant!.employeeId || merchantId,
          permissions: ['brain.write'],
          scopes: ['MERCHANT']
        }, {
          sourceType: 'DOCUMENT',
          sourceId,
          title,
          mimeType,
          authorization: { requiredPermissions },
          content
        });
        return res.status(201).json({ success: true, document });
      } catch (error) {
        const code = error instanceof Error ? error.message : '';
        if (code.startsWith('MODAGPT_BRAIN_DOCUMENT_')
          || code === 'MODAGPT_BRAIN_CHUNK_INVALID'
          || code === 'MODAGPT_BRAIN_AUTHORIZATION_INVALID') {
          return res.status(400).json({ success: false, error: code });
        }
        if (code === 'MODAGPT_MERCHANT_NOT_FOUND') return res.status(404).json({ success: false, error: code });
        return sendInternalError(res, error, 'merchant-modagpt-brain-document-ingest');
      }
    }
  );

