  app.post('/api/admin/homepage-video/presign', requireAdminAuth, requireAdminPermission('settings.footer'), async (req: AuthRequest, res) => {
    const storageClient = getMediaObjectStorageClient();
    const storageBucket = getMediaObjectStorageBucket();
    if (!storageClient || !storageBucket) {
      return res.status(503).json({ success: false, error: 'OBJECT_STORAGE_NOT_CONFIGURED' });
    }
    const contentType = String(req.body?.contentType || '').toLowerCase();
    if (!['video/mp4', 'video/webm'].includes(contentType)) {
      return res.status(400).json({ success: false, error: 'VIDEO_TYPE_NOT_ALLOWED' });
    }
    const extension = contentType === 'video/webm' ? 'webm' : 'mp4';
    const key = `site/homepage/videos/${crypto.randomUUID()}.${extension}`;
    try {
      const uploadUrl = await getSignedUrl(storageClient, new PutObjectCommand({
        Bucket: storageBucket,
        Key: key,
        ContentType: contentType,
        CacheControl: 'public,max-age=31536000,immutable'
      }), { expiresIn: 900 });
      const publicBaseUrl = getMediaObjectStoragePublicBaseUrl();
      const publicUrl = publicBaseUrl
        ? `${publicBaseUrl}/${key}`
        : `${getMediaObjectStorageConfig().endpoint.replace(/\/+$/, '')}/${storageBucket}/${key}`;
      res.json({ success: true, uploadUrl, publicUrl, expiresIn: 900 });
    } catch (error) {
      sendInternalError(res, error, 'admin-homepage-video-presign');
    }
  });

