  app.put('/api/admin/settings/integrations', requireAdminAuth, requireAdminPermission('settings.integrations'), async (req: AuthRequest, res) => {
    const body = req.body || {};
    const mediaBackupInput = body.mediaBackupS3;
    let mediaBackupSettings: {
      endpoint: string;
      region: string;
      bucket: string;
      accessKeyId: string;
      secretAccessKey: string;
      enabled: boolean;
      forcePathStyle: boolean;
      prefix: string;
    } | undefined;
    if (mediaBackupInput !== undefined) {
      if (!mediaBackupInput || typeof mediaBackupInput !== 'object' || Array.isArray(mediaBackupInput)) {
        return res.status(400).json({ success: false, error: 'MEDIA_BACKUP_SETTINGS_INVALID' });
      }
      for (const key of ['endpoint', 'region', 'bucket', 'accessKeyId', 'secretAccessKey', 'prefix'] as const) {
        if (mediaBackupInput[key] !== undefined && typeof mediaBackupInput[key] !== 'string') {
          return res.status(400).json({ success: false, error: 'MEDIA_BACKUP_SETTINGS_INVALID' });
        }
      }
      if (
        (mediaBackupInput.enabled !== undefined && typeof mediaBackupInput.enabled !== 'boolean') ||
        (mediaBackupInput.forcePathStyle !== undefined && typeof mediaBackupInput.forcePathStyle !== 'boolean')
      ) {
        return res.status(400).json({ success: false, error: 'MEDIA_BACKUP_SETTINGS_INVALID' });
      }
      const current = getMediaBackupStorageConfig();
      const objectStorageInput = body.objectStorage;
      const sourceBucket = typeof objectStorageInput?.bucket === 'string' && objectStorageInput.bucket.trim()
        ? objectStorageInput.bucket.trim()
        : getObjectStorageBucket() || '';
      mediaBackupSettings = {
        endpoint: typeof mediaBackupInput.endpoint === 'string' && mediaBackupInput.endpoint.trim()
          ? mediaBackupInput.endpoint.trim()
          : current.endpoint,
        region: typeof mediaBackupInput.region === 'string' && mediaBackupInput.region.trim()
          ? mediaBackupInput.region.trim()
          : current.region,
        bucket: typeof mediaBackupInput.bucket === 'string' && mediaBackupInput.bucket.trim()
          ? mediaBackupInput.bucket.trim()
          : current.bucket,
        accessKeyId: typeof mediaBackupInput.accessKeyId === 'string' && mediaBackupInput.accessKeyId.trim()
          ? mediaBackupInput.accessKeyId.trim()
          : current.accessKeyId,
        secretAccessKey: typeof mediaBackupInput.secretAccessKey === 'string' && mediaBackupInput.secretAccessKey.trim()
          ? mediaBackupInput.secretAccessKey.trim()
          : current.secretAccessKey,
        enabled: mediaBackupInput.enabled ?? current.enabled,
        forcePathStyle: mediaBackupInput.forcePathStyle ?? current.forcePathStyle,
        prefix: typeof mediaBackupInput.prefix === 'string' && mediaBackupInput.prefix.trim()
          ? mediaBackupInput.prefix.trim().replace(/^\/+|\/+$/g, '')
          : current.prefix
      };
      if (mediaBackupSettings.endpoint) {
        try {
          const parsedEndpoint = new URL(mediaBackupSettings.endpoint);
          if (!['http:', 'https:'].includes(parsedEndpoint.protocol) || parsedEndpoint.username || parsedEndpoint.password) {
            return res.status(400).json({ success: false, error: 'MEDIA_BACKUP_ENDPOINT_INVALID' });
          }
        } catch {
          return res.status(400).json({ success: false, error: 'MEDIA_BACKUP_ENDPOINT_INVALID' });
        }
      }
      if (mediaBackupSettings.enabled && !validateMediaBackupTarget(
        sourceBucket,
        mediaBackupSettings.bucket,
        mediaBackupSettings.prefix
      )) {
        return res.status(400).json({ success: false, error: 'MEDIA_BACKUP_TARGET_INVALID' });
      }
      if (mediaBackupSettings.enabled && (
        !mediaBackupSettings.endpoint ||
        !mediaBackupSettings.accessKeyId ||
        !mediaBackupSettings.secretAccessKey
      )) {
        return res.status(400).json({ success: false, error: 'MEDIA_BACKUP_CREDENTIALS_REQUIRED' });
      }
    }
    const previousMediaBackupS3 = { ...integrationConfig.mediaBackupS3 };
    try {
      for (const key of ['google', 'wechat', 'facebook'] as const) {
        const input = body[key] || {};
        if (key === 'google') {
          if (typeof input.clientId === 'string' && input.clientId.trim()) integrationConfig.google.clientIdEncrypted = encryptSecret(input.clientId.trim());
          if (typeof input.clientSecret === 'string' && input.clientSecret.trim()) integrationConfig.google.clientSecretEncrypted = encryptSecret(input.clientSecret.trim());
        } else {
          if (typeof input.appId === 'string' && input.appId.trim()) integrationConfig[key].appIdEncrypted = encryptSecret(input.appId.trim());
          if (typeof input.appSecret === 'string' && input.appSecret.trim()) integrationConfig[key].appSecretEncrypted = encryptSecret(input.appSecret.trim());
          if (key === 'facebook' && typeof input.loginConfigId === 'string' && input.loginConfigId.trim()) {
            integrationConfig.facebook.loginConfigIdEncrypted = encryptSecret(input.loginConfigId.trim());
          }
        }
      }
      if (typeof body.sharing?.secret === 'string' && body.sharing.secret.trim()) integrationConfig.sharing.secretEncrypted = encryptSecret(body.sharing.secret.trim());
      const objectStorageInput = body.objectStorage;
      if (objectStorageInput && typeof objectStorageInput === 'object') {
        if (typeof objectStorageInput.endpoint === 'string' && objectStorageInput.endpoint.trim()) integrationConfig.objectStorage.endpointEncrypted = encryptSecret(objectStorageInput.endpoint.trim());
        if (typeof objectStorageInput.region === 'string' && objectStorageInput.region.trim()) integrationConfig.objectStorage.regionEncrypted = encryptSecret(objectStorageInput.region.trim());
        if (typeof objectStorageInput.bucket === 'string' && objectStorageInput.bucket.trim()) integrationConfig.objectStorage.bucketEncrypted = encryptSecret(objectStorageInput.bucket.trim());
        if (typeof objectStorageInput.accessKeyId === 'string' && objectStorageInput.accessKeyId.trim()) integrationConfig.objectStorage.accessKeyIdEncrypted = encryptSecret(objectStorageInput.accessKeyId.trim());
        if (typeof objectStorageInput.secretAccessKey === 'string' && objectStorageInput.secretAccessKey.trim()) integrationConfig.objectStorage.secretAccessKeyEncrypted = encryptSecret(objectStorageInput.secretAccessKey.trim());
        if (typeof objectStorageInput.publicBaseUrl === 'string' && objectStorageInput.publicBaseUrl.trim()) integrationConfig.objectStorage.publicBaseUrlEncrypted = encryptSecret(objectStorageInput.publicBaseUrl.trim());
        if (typeof objectStorageInput.forcePathStyle === 'boolean') integrationConfig.objectStorage.forcePathStyle = objectStorageInput.forcePathStyle;
        cachedObjectStorageClient = null;
      }
      if (mediaBackupSettings) {
        integrationConfig.mediaBackupS3.endpointEncrypted = encryptSecret(mediaBackupSettings.endpoint);
        integrationConfig.mediaBackupS3.regionEncrypted = encryptSecret(mediaBackupSettings.region);
        integrationConfig.mediaBackupS3.bucketEncrypted = encryptSecret(mediaBackupSettings.bucket);
        integrationConfig.mediaBackupS3.accessKeyIdEncrypted = encryptSecret(mediaBackupSettings.accessKeyId);
        integrationConfig.mediaBackupS3.secretAccessKeyEncrypted = encryptSecret(mediaBackupSettings.secretAccessKey);
        integrationConfig.mediaBackupS3.enabled = mediaBackupSettings.enabled;
        integrationConfig.mediaBackupS3.forcePathStyle = mediaBackupSettings.forcePathStyle;
        integrationConfig.mediaBackupS3.prefix = mediaBackupSettings.prefix;
        cachedMediaBackupStorageClient = null;
      }
      await saveIntegrationConfig();
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'INTEGRATION_CONFIG_UPDATED', 'IntegrationConfig', 'global', '', 'credentials updated');
      res.json({ success: true });
    } catch (error) {
      if (mediaBackupSettings) {
        integrationConfig.mediaBackupS3 = previousMediaBackupS3;
        cachedMediaBackupStorageClient = null;
      }
      sendInternalError(res, error, 'admin-integration-config-save');
    }
  });

