  app.post('/api/admin/settings/integrations/media-backup/start', requireAdminAuth, requireAdminPermission('settings.integrations'), async (req: AuthRequest, res) => {
    if (req.body?.confirm !== true) {
      return res.status(400).json({ success: false, error: 'MEDIA_BACKUP_CONFIRMATION_REQUIRED' });
    }
    try {
      const sourceBucket = getObjectStorageBucket();
      const sourceClient = getObjectStorageClient();
      const backup = getMediaBackupStorageConfig();
      const destinationClient = getMediaBackupStorageClient();
      if (!backup.enabled) return res.status(409).json({ success: false, error: 'MEDIA_BACKUP_DISABLED' });
      if (!sourceBucket || !sourceClient || !backup.bucket || !destinationClient) {
        return res.status(400).json({ success: false, error: 'MEDIA_BACKUP_NOT_CONFIGURED' });
      }
      if (!validateMediaBackupTarget(sourceBucket, backup.bucket, backup.prefix)) {
        return res.status(400).json({ success: false, error: 'MEDIA_BACKUP_TARGET_INVALID' });
      }
      await mediaBackupManager.testConnection(sourceClient, sourceBucket);
      await mediaBackupManager.testConnection(destinationClient, backup.bucket);
      const run = await mediaBackupManager.start({
        sourceClient,
        sourceBucket,
        destinationClient,
        destinationBucket: backup.bucket,
        destinationPrefix: backup.prefix
      });
      logAudit(
        req.admin?.username || 'Platform SuperAdmin',
        'admin',
        'MEDIA_BACKUP_STARTED',
        'MediaBackup',
        run.id,
        '',
        JSON.stringify({ sourceBucket: run.sourceBucket, destinationBucket: run.destinationBucket })
      );
      res.status(202).json({ success: true, run });
    } catch (error) {
      const message = error instanceof Error && /^MEDIA_BACKUP_[A-Z0-9_-]+$/.test(error.message)
        ? error.message
        : 'MEDIA_BACKUP_START_FAILED';
      console.error('[admin-media-backup-start]', message);
      res.status(message === 'MEDIA_BACKUP_ALREADY_RUNNING' ? 409 : 502).json({ success: false, error: message });
    }
  });

