  app.post('/api/admin/settings/integrations/test', requireAdminAuth, requireAdminPermission('settings.integrations'), async (req, res) => {
    const provider = String(req.body?.provider || '');
    try {
      if (provider === 'google') {
        if (!getGoogleClientId()) throw new Error('GOOGLE_LOGIN_NOT_CONFIGURED');
      } else if (provider === 'wechat') {
        const appId = configuredIntegrationValue(integrationConfig.wechat.appIdEncrypted, process.env.WECHAT_APP_ID);
        const appSecret = configuredIntegrationValue(integrationConfig.wechat.appSecretEncrypted, process.env.WECHAT_APP_SECRET);
        if (!appId || !appSecret) throw new Error('WECHAT_NOT_CONFIGURED');
        const response = await fetch(`https://api.weixin.qq.com/cgi-bin/token?grant_type=client_credential&appid=${encodeURIComponent(appId)}&secret=${encodeURIComponent(appSecret)}`);
        const data = await response.json() as { access_token?: string; errcode?: number; errmsg?: string };
        if (!response.ok || data.errcode) throw new Error(data.errmsg || 'WECHAT_PROVIDER_ERROR');
      } else if (provider === 'facebook') {
        const appId = configuredIntegrationValue(integrationConfig.facebook.appIdEncrypted, process.env.FACEBOOK_APP_ID);
        const appSecret = configuredIntegrationValue(integrationConfig.facebook.appSecretEncrypted, process.env.FACEBOOK_APP_SECRET);
        if (!appId || !appSecret) throw new Error('FACEBOOK_NOT_CONFIGURED');
        const response = await fetch(`https://graph.facebook.com/oauth/access_token?client_id=${encodeURIComponent(appId)}&client_secret=${encodeURIComponent(appSecret)}&grant_type=client_credentials`);
        if (!response.ok) throw new Error(`FACEBOOK_PROVIDER_${response.status}`);
      } else if (provider === 'sharing') {
        if (!integrationConfig.sharing.secretEncrypted && !process.env.SHARE_LINK_SECRET) throw new Error('SHARING_NOT_CONFIGURED');
      } else if (provider === 'objectStorage') {
        const storageClient = getObjectStorageClient();
        const storageBucket = getObjectStorageBucket();
        if (!storageClient || !storageBucket) throw new Error('OBJECT_STORAGE_NOT_CONFIGURED');
        await storageClient.send(new HeadBucketCommand({ Bucket: storageBucket }));
      } else if (provider === 'mediaBackup') {
        const sourceBucket = getObjectStorageBucket();
        const sourceClient = getObjectStorageClient();
        const backup = getMediaBackupStorageConfig();
        const destinationClient = getMediaBackupStorageClient();
        if (!sourceBucket || !sourceClient || !backup.bucket || !destinationClient) {
          throw new Error('MEDIA_BACKUP_NOT_CONFIGURED');
        }
        if (!validateMediaBackupTarget(sourceBucket, backup.bucket, backup.prefix)) {
          throw new Error('MEDIA_BACKUP_TARGET_INVALID');
        }
        await mediaBackupManager.testConnection(sourceClient, sourceBucket);
        await mediaBackupManager.testConnection(destinationClient, backup.bucket);
      } else {
        return res.status(400).json({ success: false, error: 'INTEGRATION_PROVIDER_REQUIRED' });
      }
      res.json({ success: true, provider });
    } catch (error) {
      res.status(502).json({ success: false, error: error instanceof Error ? error.message : 'INTEGRATION_TEST_FAILED' });
    }
  });

