  app.post('/api/admin/promotions', requireAdminAuth, async (req: AuthRequest, res) => {
    try {
      const body = req.body || {};
      const scope = String(body.scope || '');
      const merchantIds = normalizePromotionTargets(body.merchantIds ?? []);
      const categoryIds = normalizePromotionTargets(body.categoryIds ?? []);
      const productIds = normalizePromotionTargets(body.productIds ?? []);
      const startsAt = new Date(String(body.startsAt || ''));
      const expiresAt = body.expiresAt ? new Date(String(body.expiresAt)) : null;
      const code = body.code ? String(body.code).trim().toUpperCase() : null;
      if (!promotionTypes.includes(body.type) || !promotionScopes.includes(scope) || !promotionAppliesOn.includes(body.appliesOn)
        || typeof body.name !== 'string' || !body.name.trim() || body.name.trim().length > 160
        || merchantIds === null || categoryIds === null || productIds === null
        || Number.isNaN(startsAt.getTime()) || (expiresAt && Number.isNaN(expiresAt.getTime()))
        || (expiresAt && expiresAt <= startsAt) || (code && code.length > 80)) {
        return res.status(400).json({ success: false, error: 'PROMOTION_INPUT_INVALID' });
      }
      const targetError = await validatePromotionTargets(scope, merchantIds, categoryIds, productIds);
      if (targetError) return res.status(targetError === 'PROMOTION_TARGET_REQUIRED' ? 400 : 404).json({ success: false, error: targetError });
      const numberOrNull = (value: unknown) => value === null || value === undefined || value === '' ? null : Number(value);
      const percentOff = numberOrNull(body.percentOff);
      const fixedAmountOff = numberOrNull(body.fixedAmountOff);
      const minSubtotal = numberOrNull(body.minSubtotal);
      const minQty = numberOrNull(body.minQty);
      const getPercentOff = numberOrNull(body.getPercentOff);
      const buyQty = numberOrNull(body.buyQty);
      const getQty = numberOrNull(body.getQty);
      const totalUsageLimit = numberOrNull(body.totalUsageLimit);
      const tiers = normalizePromotionTiers(body.tiers ?? []);
      if ([percentOff, fixedAmountOff, minSubtotal, getPercentOff].some(value => value !== null && (!Number.isFinite(value) || value < 0))
        || (percentOff !== null && percentOff > 100) || (getPercentOff !== null && getPercentOff > 100)
        || [minQty, buyQty, getQty, totalUsageLimit].some(value => value !== null && (!Number.isInteger(value) || value <= 0))
        || tiers === null
        || !hasValidPromotionMechanics(body.type, { percentOff, fixedAmountOff, minQty, buyQty, getQty }, tiers)) {
        return res.status(400).json({ success: false, error: 'PROMOTION_VALUE_INVALID' });
      }
      const created = await prisma.promotionRule.create({
        data: {
          id: crypto.randomUUID(),
          code,
          type: body.type,
          scope,
          appliesOn: body.appliesOn,
          name: body.name.trim(),
          nameIt: typeof body.name_it === 'string' ? body.name_it.slice(0, 160) : null,
          nameZh: typeof body.name_zh === 'string' ? body.name_zh.slice(0, 160) : null,
          description: typeof body.description === 'string' ? body.description.slice(0, 4000) : null,
          minSubtotal,
          percentOff,
          fixedAmountOff,
          minQty,
          buyQty,
          getQty,
          getPercentOff,
          tiersJson: tiers.length ? JSON.stringify(tiers) : null,
          merchantIds: scope === 'merchant' ? merchantIds : [],
          categoryIds: scope === 'category' ? categoryIds : [],
          productIds: scope === 'product' ? productIds : [],
          excludeSaleItems: Boolean(body.excludeSaleItems),
          usageLimitPerConsumer: Number.isInteger(body.usageLimitPerConsumer) && body.usageLimitPerConsumer > 0 ? body.usageLimitPerConsumer : null,
          totalUsageLimit,
          startsAt,
          expiresAt,
          isActive: body.isActive !== false,
          createdByAdminId: req.admin?.username || null
        }
      });
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'PROMOTION_CREATED', 'PromotionRule', created.id, '', created.name);
      res.status(201).json({ success: true, promotion: serializeAdminPromotion(created) });
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === 'P2002') {
        return res.status(409).json({ success: false, error: 'PROMOTION_CODE_DUPLICATE' });
      }
      sendInternalError(res, error, 'admin-promotions-create');
    }
  });

  app.put('/api/admin/promotions/:id', requireAdminAuth, async (req: AuthRequest, res) => {
    try {
      const existing = await prisma.promotionRule.findUnique({ where: { id: req.params.id } });
      if (!existing) return res.status(404).json({ success: false, error: 'PROMOTION_NOT_FOUND' });
      const body = req.body || {};
      const scope = body.scope === undefined ? existing.scope : String(body.scope);
      const merchantIds = normalizePromotionTargets(body.merchantIds ?? (scope === 'merchant' ? existing.merchantIds : []));
      const categoryIds = normalizePromotionTargets(body.categoryIds ?? (scope === 'category' ? existing.categoryIds : []));
      const productIds = normalizePromotionTargets(body.productIds ?? (scope === 'product' ? existing.productIds : []));
      const nextType = body.type === undefined ? existing.type : String(body.type);
      const appliesOn = body.appliesOn === undefined ? existing.appliesOn : String(body.appliesOn);
      const name = body.name === undefined ? existing.name : String(body.name).trim();
      const startsAt = body.startsAt === undefined ? existing.startsAt : new Date(String(body.startsAt));
      const expiresAt = body.expiresAt === undefined ? existing.expiresAt : body.expiresAt ? new Date(String(body.expiresAt)) : null;
      const code = body.code === undefined ? existing.code : body.code ? String(body.code).trim().toUpperCase() : null;
      if (!promotionTypes.includes(nextType) || !promotionScopes.includes(scope) || !promotionAppliesOn.includes(appliesOn)
        || !name || name.length > 160 || merchantIds === null || categoryIds === null || productIds === null
        || Number.isNaN(startsAt.getTime()) || (expiresAt && Number.isNaN(expiresAt.getTime()))
        || (expiresAt && expiresAt <= startsAt) || (code && code.length > 80)) {
        return res.status(400).json({ success: false, error: 'PROMOTION_INPUT_INVALID' });
      }
      const targetError = await validatePromotionTargets(scope, merchantIds, categoryIds, productIds);
      if (targetError) return res.status(targetError === 'PROMOTION_TARGET_REQUIRED' ? 400 : 404).json({ success: false, error: targetError });
      const numberOrCurrent = (key: string, current: number | null) => body[key] === undefined ? current : body[key] === null || body[key] === '' ? null : Number(body[key]);
      const percentOff = numberOrCurrent('percentOff', existing.percentOff === null ? null : Number(existing.percentOff));
      const fixedAmountOff = numberOrCurrent('fixedAmountOff', existing.fixedAmountOff === null ? null : Number(existing.fixedAmountOff));
      const minSubtotal = numberOrCurrent('minSubtotal', existing.minSubtotal === null ? null : Number(existing.minSubtotal));
      const minQty = numberOrCurrent('minQty', existing.minQty);
      const getPercentOff = numberOrCurrent('getPercentOff', existing.getPercentOff === null ? null : Number(existing.getPercentOff));
      const buyQty = numberOrCurrent('buyQty', existing.buyQty);
      const getQty = numberOrCurrent('getQty', existing.getQty);
      const totalUsageLimit = numberOrCurrent('totalUsageLimit', existing.totalUsageLimit);
      const tiers = normalizePromotionTiers(body.tiers === undefined ? parseStoredJson(existing.tiersJson, []) : body.tiers);
      if ([percentOff, fixedAmountOff, minSubtotal, getPercentOff].some(value => value !== null && (!Number.isFinite(value) || value < 0))
        || (percentOff !== null && percentOff > 100) || (getPercentOff !== null && getPercentOff > 100)
        || [minQty, buyQty, getQty, totalUsageLimit].some(value => value !== null && (!Number.isInteger(value) || value <= 0))
        || (totalUsageLimit !== null && totalUsageLimit < existing.totalUsedCount)
        || tiers === null
        || !hasValidPromotionMechanics(nextType, { percentOff, fixedAmountOff, minQty, buyQty, getQty }, tiers)) {
        return res.status(400).json({ success: false, error: 'PROMOTION_VALUE_INVALID' });
      }
      const updated = await prisma.promotionRule.update({
        where: { id: existing.id },
        data: {
          code,
          type: nextType,
          scope,
          appliesOn,
          name,
          nameIt: body.name_it === undefined ? existing.nameIt : String(body.name_it).slice(0, 160),
          nameZh: body.name_zh === undefined ? existing.nameZh : String(body.name_zh).slice(0, 160),
          description: body.description === undefined ? existing.description : String(body.description).slice(0, 4000),
          minSubtotal,
          percentOff,
          fixedAmountOff,
          minQty,
          buyQty,
          getQty,
          getPercentOff,
          tiersJson: tiers.length ? JSON.stringify(tiers) : null,
          merchantIds: scope === 'merchant' ? merchantIds : [],
          categoryIds: scope === 'category' ? categoryIds : [],
          productIds: scope === 'product' ? productIds : [],
          excludeSaleItems: body.excludeSaleItems === undefined ? existing.excludeSaleItems : Boolean(body.excludeSaleItems),
          usageLimitPerConsumer: body.usageLimitPerConsumer === undefined ? existing.usageLimitPerConsumer : Number.isInteger(body.usageLimitPerConsumer) && body.usageLimitPerConsumer > 0 ? body.usageLimitPerConsumer : null,
          totalUsageLimit,
          startsAt,
          expiresAt,
          isActive: body.isActive === undefined ? existing.isActive : Boolean(body.isActive)
        }
      });
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'PROMOTION_UPDATED', 'PromotionRule', updated.id, existing.name, updated.name);
      res.json({ success: true, promotion: serializeAdminPromotion(updated) });
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === 'P2002') {
        return res.status(409).json({ success: false, error: 'PROMOTION_CODE_DUPLICATE' });
      }
      sendInternalError(res, error, 'admin-promotions-update');
    }
  });

