  app.put('/api/admin/merchants/:id/password', requireAdminAuth, requireAdminPermission('merchants.review'), async (req: AuthRequest, res) => {
    const password = typeof req.body?.password === 'string' ? req.body.password : '';
    if (password.length < 12 || password.trim().length < 12) {
      return res.status(400).json({ success: false, error: 'MERCHANT_PASSWORD_TOO_SHORT' });
    }

    try {
      const merchant = await prisma.merchant.findUnique({
        where: { id: req.params.id },
        select: { id: true, name: true, code: true, companyId: true, contactEmail: true }
      });
      if (!merchant) return res.status(404).json({ success: false, error: 'MERCHANT_NOT_FOUND' });

      const passwordHash = await bcrypt.hash(password, 12);
      const result = await prisma.$transaction(async tx => {
        const merchantAccounts = await tx.authAccount.findMany({
          where: {
            role: 'merchant',
            OR: [{ merchantId: merchant.id }, { merchantCode: merchant.code }]
          },
          select: { id: true, merchantId: true }
        });
        if (merchantAccounts.length > 1) {
          return { accountCount: 0, error: 'MERCHANT_LOGIN_ACCOUNT_CONFLICT' };
        }
        const merchantAccount = merchantAccounts[0];
        if (merchantAccount) {
          if (merchantAccount.merchantId && merchantAccount.merchantId !== merchant.id) {
            return { accountCount: 0, error: 'MERCHANT_LOGIN_ACCOUNT_CONFLICT' };
          }
          if (!merchantAccount.merchantId) {
            const accountForMerchant = await tx.authAccount.findUnique({
              where: { merchantId: merchant.id },
              select: { id: true }
            });
            if (accountForMerchant && accountForMerchant.id !== merchantAccount.id) {
              return { accountCount: 0, error: 'MERCHANT_LOGIN_ACCOUNT_CONFLICT' };
            }
          }
          await tx.authAccount.update({
            where: { id: merchantAccount.id },
            data: {
              passwordHash,
              ...(merchantAccount.merchantId ? {} : { merchantId: merchant.id })
            }
          });
        } else {
          const accountForMerchant = await tx.authAccount.findUnique({
            where: { merchantId: merchant.id },
            select: { id: true }
          });
          if (accountForMerchant) {
            return { accountCount: 0, error: 'MERCHANT_LOGIN_ACCOUNT_CONFLICT' };
          }
          const ownerEmail = merchant.contactEmail.trim().toLowerCase();
          const accountForEmail = ownerEmail ? await tx.authAccount.findFirst({
            where: { role: 'merchant', email: ownerEmail },
            select: { id: true }
          }) : null;
          if (accountForEmail) {
            return { accountCount: 0, error: 'MERCHANT_LOGIN_EMAIL_IN_USE' };
          }
          await tx.authAccount.create({
            data: {
              role: 'merchant',
              email: ownerEmail || null,
              merchantId: merchant.id,
              merchantCode: merchant.code,
              passwordHash
            }
          });
        }

        const linkedCompanies = await tx.company.findMany({
          where: { merchants: { some: { id: merchant.id } } },
          select: { id: true }
        });
        const companyIds = [...new Set([
          merchant.companyId,
          ...linkedCompanies.map(company => company.id)
        ].filter((companyId): companyId is string => Boolean(companyId)))];
        const accountScopes: Prisma.AuthAccountWhereInput[] = [
          ...companyIds.map(companyId => ({ role: 'company', companyId }))
        ];
        const accountUpdate = await tx.authAccount.updateMany({
          where: accountScopes.length > 0 ? { OR: accountScopes } : { id: '__no_company_account__' },
          data: { passwordHash }
        });
        const identityIds = [...new Set([
          merchantAccount ? (await tx.authAccount.findUnique({ where: { id: merchantAccount.id }, select: { identityId: true } }))?.identityId : null,
          ...companyIds.length > 0
            ? (await tx.authAccount.findMany({
                where: { role: 'company', companyId: { in: companyIds } },
                select: { identityId: true }
              })).map(account => account.identityId)
            : []
        ].filter((id): id is string => Boolean(id)))];
        if (identityIds.length > 0) {
          await tx.accountIdentity.updateMany({
            where: { id: { in: identityIds } },
            data: { passwordHash }
          });
        }

        return { accountCount: 1 + accountUpdate.count };
      });
      if ('error' in result) {
        return res.status(409).json({ success: false, error: result.error });
      }
      if (result.accountCount === 0) {
        return res.status(404).json({ success: false, error: 'MERCHANT_LOGIN_NOT_FOUND' });
      }

      logAudit(
        req.admin?.username || 'Platform SuperAdmin',
        'admin',
        'MERCHANT_PASSWORD_RESET',
        'Merchant',
        merchant.id,
        '',
        'Merchant owner password reset'
      );
      res.json({ success: true });
    } catch (error) {
      sendInternalError(res, error, 'admin-merchant-password-reset');
    }
  });

  app.get('/api/admin/account-identities/review', requireAdminAuth, requireAdminPermission('accounts.manage'), async (_req, res) => {
    try {
      const accounts = await prisma.authAccount.findMany({
        where: {
          role: { in: ['buyer', 'company', 'merchant'] },
          email: { not: null }
        },
        select: {
          id: true,
          role: true,
          email: true,
          identityId: true,
          emailVerifiedAt: true,
          lastLoginAt: true,
          merchantId: true,
          companyId: true,
          customerId: true
        },
        orderBy: { createdAt: 'asc' }
      });
      const groups = new Map<string, typeof accounts>();
      for (const account of accounts) {
        const email = account.email?.trim().toLowerCase();
        if (!email) continue;
        const group = groups.get(email) || [];
        group.push(account);
        groups.set(email, group);
      }
      const reviewGroups = [...groups.entries()]
        .filter(([, group]) => group.length > 1 && !(group.every(account => account.identityId) && new Set(group.map(account => account.identityId)).size === 1))
        .map(([email, group]) => ({
          email,
          accounts: group.map(({ id, role, identityId, emailVerifiedAt, lastLoginAt, merchantId, companyId, customerId }) => ({
            id, role, identityId, emailVerifiedAt, lastLoginAt, merchantId, companyId, customerId
          }))
        }));
      res.json({ success: true, reviewGroups });
    } catch (error) {
      sendInternalError(res, error, 'admin-account-identity-review');
    }
  });

  app.put('/api/admin/account-identities/link', requireAdminAuth, requireAdminPermission('accounts.manage'), async (req: AuthRequest, res) => {
    const requestedAccountIds: unknown = req.body?.accountIds;
    const accountIds: string[] = [];
    if (Array.isArray(requestedAccountIds)) {
      for (const id of requestedAccountIds) {
        if (typeof id === 'string' && id.length > 0 && !accountIds.includes(id)) {
          accountIds.push(id);
        }
      }
    }
    const password = typeof req.body?.password === 'string' ? req.body.password : '';
    if (accountIds.length < 2 || accountIds.length > 10) {
      return res.status(400).json({ success: false, error: 'ACCOUNT_IDENTITY_SELECTION_INVALID' });
    }
    if (password.length < 12 || password.trim().length < 12) {
      return res.status(400).json({ success: false, error: 'ACCOUNT_IDENTITY_PASSWORD_TOO_SHORT' });
    }

    try {
      const accounts = await prisma.authAccount.findMany({
        where: { id: { in: accountIds } },
        select: { id: true, role: true, email: true, identityId: true, phone: true, phoneVerifiedAt: true }
      });
      const normalizedEmails = [...new Set(accounts.map(account => account.email?.trim().toLowerCase()).filter(Boolean))];
      if (accounts.length !== accountIds.length ||
        accounts.some(account => !['buyer', 'company', 'merchant'].includes(account.role)) ||
        normalizedEmails.length !== 1) {
        return res.status(409).json({ success: false, error: 'ACCOUNT_IDENTITY_SELECTION_CONFLICT' });
      }
      const email = normalizedEmails[0]!;
      const allSameEmailAccounts = await prisma.authAccount.findMany({
        where: {
          role: { in: ['buyer', 'company', 'merchant'] },
          email: { equals: email, mode: 'insensitive' }
        },
        select: { id: true }
      });
      if (allSameEmailAccounts.length !== accountIds.length ||
        allSameEmailAccounts.some(account => !accountIds.includes(account.id))) {
        return res.status(409).json({ success: false, error: 'ACCOUNT_IDENTITY_SELECTION_INCOMPLETE' });
      }
      const passwordHash = await bcrypt.hash(password, 12);
      const identity = await prisma.$transaction(async tx => {
        const currentAccounts = await tx.authAccount.findMany({
          where: { id: { in: accountIds } },
          select: { id: true, role: true, email: true, identityId: true, phone: true, phoneVerifiedAt: true }
        });
        const currentEmails = [...new Set(currentAccounts.map(account => account.email?.trim().toLowerCase()).filter(Boolean))];
        const currentSameEmailAccounts = await tx.authAccount.findMany({
          where: {
            role: { in: ['buyer', 'company', 'merchant'] },
            email: { equals: email, mode: 'insensitive' }
          },
          select: { id: true }
        });
        if (currentAccounts.length !== accountIds.length ||
          currentEmails.length !== 1 ||
          currentEmails[0] !== email ||
          currentAccounts.some(account => !['buyer', 'company', 'merchant'].includes(account.role)) ||
          currentSameEmailAccounts.length !== accountIds.length ||
          currentSameEmailAccounts.some(account => !accountIds.includes(account.id))) {
          throw new Error('ACCOUNT_IDENTITY_SELECTION_INCOMPLETE');
        }
        const existing = await tx.accountIdentity.findFirst({ where: { scope: 'public', email } });
        const identityIds = [...new Set(currentAccounts.map(account => account.identityId).filter((id): id is string => Boolean(id)))];
        if (identityIds.length > 1 || (existing && identityIds.some(id => id !== existing.id))) {
          throw new Error('ACCOUNT_IDENTITY_SELECTION_CONFLICT');
        }
        if (existing) {
          const existingAccounts = await tx.authAccount.findMany({
            where: { identityId: existing.id },
            select: { id: true, email: true }
          });
          if (existingAccounts.some(account =>
            !accountIds.includes(account.id) || account.email?.trim().toLowerCase() !== email
          )) {
            throw new Error('ACCOUNT_IDENTITY_SELECTION_CONFLICT');
          }
        }
        if (currentAccounts.some(account => account.phoneVerifiedAt && !account.phone)) {
          throw new Error('ACCOUNT_IDENTITY_PHONE_CONFLICT');
        }
        const verifiedPhones = [...new Set(currentAccounts
          .filter(account => account.phoneVerifiedAt)
          .map(account => account.phone?.trim())
          .filter((phone): phone is string => Boolean(phone)))];
        if (verifiedPhones.length > 1 || (existing?.phone && !existing.phoneVerifiedAt)) {
          throw new Error('ACCOUNT_IDENTITY_PHONE_CONFLICT');
        }
        const verifiedPhone = verifiedPhones[0] || null;
        if (existing?.phone && verifiedPhone && existing.phone.trim() !== verifiedPhone) {
          throw new Error('ACCOUNT_IDENTITY_PHONE_CONFLICT');
        }
        const phone = existing?.phone?.trim() || verifiedPhone;
        const phoneVerifiedAt = existing?.phoneVerifiedAt
          || currentAccounts.find(account => account.phoneVerifiedAt)?.phoneVerifiedAt
          || null;
        if (phone) {
          const phoneOwner = await tx.accountIdentity.findUnique({
            where: { phone },
            select: { id: true }
          });
          if (phoneOwner && phoneOwner.id !== existing?.id) {
            throw new Error('ACCOUNT_IDENTITY_PHONE_CONFLICT');
          }
        }
        const shared = existing
          ? await tx.accountIdentity.update({
              where: { id: existing.id },
              data: { emailVerifiedAt: new Date(), passwordHash, phone, phoneVerifiedAt, updatedAt: new Date() }
            })
          : await tx.accountIdentity.create({
                data: { id: crypto.randomUUID(), scope: 'public', email, emailVerifiedAt: new Date(), passwordHash, phone, phoneVerifiedAt }
            });
        await tx.authAccount.updateMany({
          where: { id: { in: accountIds } },
          data: {
            identityId: shared.id,
            emailVerifiedAt: shared.emailVerifiedAt,
            passwordHash
          }
        });
        return shared;
      }, { isolationLevel: Prisma.TransactionIsolationLevel.Serializable });
      logAudit(
        req.admin?.username || 'Platform SuperAdmin',
        'admin',
        'ACCOUNT_IDENTITY_LINKED',
        'AccountIdentity',
        identity.id,
        '',
        JSON.stringify({ email, accountIds })
      );
      res.json({ success: true });
    } catch (error) {
      if (error instanceof Error && error.message === 'ACCOUNT_IDENTITY_SELECTION_CONFLICT') {
        return res.status(409).json({ success: false, error: error.message });
      }
      if (error instanceof Error && error.message === 'ACCOUNT_IDENTITY_SELECTION_INCOMPLETE') {
        return res.status(409).json({ success: false, error: error.message });
      }
      if (error instanceof Error && error.message === 'ACCOUNT_IDENTITY_PHONE_CONFLICT') {
        return res.status(409).json({ success: false, error: error.message });
      }
      sendInternalError(res, error, 'admin-account-identity-link');
    }
  });

