  app.put('/api/admin/merchant-bank-accounts/:id/review', requireAdminAuth, requireAdminPermission('finance.payouts'), async (req: AuthRequest, res) => {
    const status = req.body?.status === 'verified' ? 'verified' : req.body?.status === 'rejected' ? 'rejected' : null;
    const rejectionReason = String(req.body?.rejectionReason || '').trim();
    if (!status || (status === 'rejected' && !rejectionReason)) {
      return res.status(400).json({ success: false, error: 'BANK_ACCOUNT_REVIEW_INVALID' });
    }
    try {
      const account = await prisma.merchantBankAccount.findUnique({ where: { id: req.params.id } });
      if (!account) return res.status(404).json({ success: false, error: 'BANK_ACCOUNT_NOT_FOUND' });
      const updated = await prisma.$transaction(async tx => {
        if (status === 'verified') {
          await tx.merchantBankAccount.updateMany({
            where: { merchantId: account.merchantId, status: 'verified', id: { not: account.id } },
            data: { status: 'rejected', rejectionReason: 'SUPERSEDED_BY_NEWER_VERIFIED_ACCOUNT' }
          });
        }
        return tx.merchantBankAccount.update({
          where: { id: account.id },
          data: { status, reviewedAt: new Date(), reviewedBy: req.admin?.username || 'Platform SuperAdmin', rejectionReason: status === 'rejected' ? rejectionReason : null }
        });
      });
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'BANK_ACCOUNT_REVIEWED', 'MerchantBankAccount', updated.id, account.status, status);
      res.json({ success: true, account: { id: updated.id, status: updated.status, iban: maskIban(updated.ibanLast4), reviewedAt: updated.reviewedAt } });
    } catch (error) {
      sendInternalError(res, error, 'admin-merchant-bank-account-review');
    }
  });

  // PUT /api/admin/merchants/:id/status (平台审核商家、挂起、调整佣金率)
  app.put('/api/admin/merchants/:id/status', requireAdminAuth, requireAdminPermission('merchants.review'), async (req, res) => {
    const merchantId = req.params.id;
    const { isVerified, storefrontEnabled, platformFeeRate } = req.body;
    const adminName = (req as AuthRequest).admin?.username || 'Platform SuperAdmin';

    const merchant = await prisma.merchant.findUnique({ where: { id: merchantId } });
    if (!merchant) {
      return res.status(404).json({ success: false, error: 'Merchant not found' });
    }

    const oldStatus = merchant.isVerified;
    const nextFeeRate = platformFeeRate === undefined ? Number(merchant.platformFeeRate ?? 0.08) : Number(platformFeeRate);
    if (!Number.isFinite(nextFeeRate) || nextFeeRate < 0 || nextFeeRate > 1) {
      return res.status(400).json({ success: false, error: 'INVALID_PLATFORM_FEE_RATE' });
    }
    const updated = await prisma.merchant.update({ where: { id: merchantId }, data: {
      isVerified: typeof isVerified === 'boolean' ? isVerified : oldStatus,
      storefrontEnabled: typeof storefrontEnabled === 'boolean' ? storefrontEnabled : merchant.storefrontEnabled,
      platformFeeRate: nextFeeRate
    } });

    logAudit(adminName, 'admin', 'MERCHANT_STATUS_UPDATE', 'Merchant', merchantId, String(oldStatus), String(isVerified));
    if (updated.isVerified && !oldStatus) {
      enqueueNotification('merchant.approved', updated.contactEmail, {
        referenceId: updated.id,
        companyName: updated.name,
        storeUrl: merchantStorefrontOrigin(updated.storeSlug)
      });
    }
    res.json({ success: true, merchant: serializeMerchantRow(updated) });
  });

