  app.get('/api/admin/health', requireAdminAuth, requireAdminPermission('settings.health'), async (_req, res) => {
    const startedAt = Date.now();
    try {
      await prisma.$queryRawUnsafe('SELECT 1');
      const [
        merchants,
        customers,
        orders,
        products,
        pendingPayments,
        failedRefunds,
        failedNotifications,
        pendingPayouts,
        openReturns,
        activeTransfers
      ] = await Promise.all([
        prisma.merchant.count(),
        prisma.customer.count(),
        prisma.order.count(),
        prisma.product.count(),
        prisma.paymentTransaction.count({ where: { status: { in: ['pending', 'processing'] } } }),
        prisma.refundTransaction.count({ where: { status: 'failed' } }),
        prisma.notificationEvent.count({ where: { status: 'failed' } }),
        prisma.merchantPayout.count({ where: { status: { in: ['pending', 'processing'] } } }),
        prisma.returnRequest.count({ where: { status: { in: ['requested', 'approved'] } } }),
        prisma.stockTransfer.count({ where: { status: { in: ['requested', 'approved', 'picking', 'in_transit'] } } })
      ]);
      res.json({
        success: true,
        status: 'healthy',
        database: { status: 'connected', latencyMs: Date.now() - startedAt },
        counts: { merchants, customers, orders, products },
        risks: { pendingPayments, failedRefunds, failedNotifications, pendingPayouts, openReturns, activeTransfers },
        checkedAt: new Date().toISOString()
      });
    } catch (error) {
      console.error('[admin-health]', error instanceof Error ? error.message : error);
      res.status(503).json({
        success: false,
        status: 'degraded',
        database: { status: 'unavailable', latencyMs: Date.now() - startedAt },
        checkedAt: new Date().toISOString()
      });
    }
  });

