  // PUT /api/admin/orders/:id/status — platform order workflow control
  app.put('/api/admin/orders/:id/status', requireAdminAuth, requireAdminPermission('orders.manage'), async (req: AuthRequest, res) => {
    try {
      const { status, trackingNumber, notes } = req.body || {};
      const allowedStatuses = ['pending', 'confirmed', 'picking', 'shipped', 'delivered', 'cancelled'];
      if (!allowedStatuses.includes(status)) {
        return res.status(400).json({ success: false, error: 'ORDER_STATUS_INVALID' });
      }
      const order = await prisma.order.findUnique({ where: { id: req.params.id }, include: { items: true } });
      if (!order) return res.status(404).json({ success: false, error: 'ORDER_NOT_FOUND' });
      if (!canTransitionOrderStatus(order.status, status)) {
        return res.status(409).json({ success: false, error: 'INVALID_ORDER_TRANSITION' });
      }
      const timeline = parseStoredJson<any[]>(order.timeline, []);
      timeline.push({
        status,
        title: `平台操作：${String(status).toUpperCase()}`,
        time: new Date().toISOString(),
        completed: true,
        note: notes || undefined
      });
      const updated = await prisma.order.update({
        where: { id: order.id },
        data: {
          status,
          trackingNumber: trackingNumber || order.trackingNumber,
          notes: notes || order.notes,
          timeline: JSON.stringify(timeline)
        },
        include: { items: true }
      });
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'ORDER_STATUS_UPDATE', 'Order', order.id, order.status, status);
      res.json({ success: true, order: serializeOrderRow(updated) });
    } catch (error) {
      sendInternalError(res, error, 'admin-order-status');
    }
  });

  // GET /api/admin/appointments — persistent showroom appointments
  app.get('/api/admin/appointments', requireAdminAuth, async (req, res) => {
    try {
      const appointments = await prisma.appointment.findMany({ orderBy: { date: 'desc' }, take: 500 });
      res.json({ success: true, count: appointments.length, appointments });
    } catch (error) {
      sendInternalError(res, error, 'admin-appointments');
    }
  });

  // PUT /api/admin/appointments/:id/status — appointment workflow
  app.put('/api/admin/appointments/:id/status', requireAdminAuth, requireAdminPermission('showrooms.appointments'), async (req: AuthRequest, res) => {
    const status = req.body?.status;
    if (!['confirmed', 'pending', 'completed', 'cancelled', 'no_show'].includes(status)) {
      return res.status(400).json({ success: false, error: 'APPOINTMENT_STATUS_INVALID' });
    }
    const appointment = await prisma.appointment.findUnique({ where: { id: req.params.id } });
    if (!appointment) return res.status(404).json({ success: false, error: 'APPOINTMENT_NOT_FOUND' });
    const allowedTransitions: Record<string, string[]> = {
      pending: ['confirmed', 'cancelled'],
      confirmed: ['completed', 'cancelled', 'no_show'],
      completed: [],
      cancelled: [],
      no_show: []
    };
    if (!allowedTransitions[appointment.status]?.includes(status)) {
      return res.status(409).json({ success: false, error: 'APPOINTMENT_STATUS_TRANSITION_INVALID' });
    }
    const updated = await prisma.appointment.update({ where: { id: appointment.id }, data: { status } });
    logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'APPOINTMENT_STATUS', 'Appointment', appointment.id, appointment.status, status);
    res.json({ success: true, appointment: updated });
  });

  app.put('/api/admin/appointments/:id/reschedule', requireAdminAuth, requireAdminPermission('showrooms.appointments'), async (req: AuthRequest, res) => {
    const date = typeof req.body?.date === 'string' ? req.body.date : '';
    const time = typeof req.body?.time === 'string' ? req.body.time : '';
    const parsedDate = /^\d{4}-\d{2}-\d{2}$/.test(date) ? new Date(`${date}T00:00:00.000Z`) : null;
    if (!parsedDate || Number.isNaN(parsedDate.getTime()) || parsedDate.toISOString().slice(0, 10) !== date || !/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) {
      return res.status(400).json({ success: false, error: 'APPOINTMENT_SCHEDULE_INVALID' });
    }
    try {
      const appointment = await prisma.appointment.findUnique({ where: { id: req.params.id }, include: { showroom: true } });
      if (!appointment) return res.status(404).json({ success: false, error: 'APPOINTMENT_NOT_FOUND' });
      if (!['pending', 'confirmed'].includes(appointment.status)) {
        return res.status(409).json({ success: false, error: 'APPOINTMENT_RESCHEDULE_NOT_ALLOWED' });
      }
      const capacity = Number.parseInt(appointment.showroom.capacity, 10);
      const booked = await prisma.appointment.count({
        where: {
          id: { not: appointment.id },
          showroomId: appointment.showroomId,
          date,
          time,
          status: { notIn: ['cancelled', 'no_show'] }
        }
      });
      if (Number.isFinite(capacity) && booked >= capacity) {
        return res.status(409).json({ success: false, error: 'APPOINTMENT_SLOT_FULL' });
      }
      const updated = await prisma.appointment.update({ where: { id: appointment.id }, data: { date, time } });
      logAudit(
        req.admin?.username || 'Platform SuperAdmin',
        'admin',
        'APPOINTMENT_RESCHEDULE',
        'Appointment',
        appointment.id,
        JSON.stringify({ date: appointment.date, time: appointment.time }),
        JSON.stringify({ date, time })
      );
      res.json({ success: true, appointment: updated });
    } catch (error) {
      sendInternalError(res, error, 'admin-appointment-reschedule');
    }
  });

