  // POST /api/admin/payouts/generate — creates auditable merchant payout drafts
  // from paid, unallocated merchant child orders. Drafts cannot be disbursed
  // until finance has verified the merchant's bank account.
  app.post('/api/admin/payouts/generate', requireAdminAuth, requireAdminPermission('finance.payouts'), async (req: AuthRequest, res) => {
    const period = String(req.body?.period || '').trim();
    if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(period)) {
      return res.status(400).json({ success: false, error: 'PAYOUT_PERIOD_INVALID' });
    }
    const [year, month] = period.split('-').map(Number);
    const periodStart = new Date(Date.UTC(year, month - 1, 1));
    const periodEnd = new Date(Date.UTC(year, month, 1));
    try {
      const eligibleOrders = await prisma.order.findMany({
        where: {
          merchantId: { not: null },
          paymentStatus: { in: ['paid', 'partially_refunded', 'refunded'] },
          refundStatus: { in: ['none', 'partially_refunded', 'completed'] },
          createdAt: { gte: periodStart, lt: periodEnd },
          payoutAllocation: null
        },
        include: { merchant: { select: { id: true, name: true, platformFeeRate: true } } },
        orderBy: { createdAt: 'asc' }
      });
      const ordersByMerchant = new Map<string, typeof eligibleOrders>();
      for (const order of eligibleOrders) {
        if (!order.merchantId || !order.merchant) continue;
        const group = ordersByMerchant.get(order.merchantId) || [];
        group.push(order);
        ordersByMerchant.set(order.merchantId, group);
      }
      if (ordersByMerchant.size === 0) {
        return res.status(404).json({ success: false, error: 'NO_UNALLOCATED_PAID_ORDERS' });
      }
      const payouts = await prisma.$transaction(async tx => {
        const drafts = [];
        for (const [merchantId, orders] of ordersByMerchant) {
          const grossSales = orders.reduce((sum, order) => sum + Math.max(0, Number(order.totalAmount) - Number(order.shippingFee || 0)), 0);
          const refunds = orders.reduce((sum, order) => sum + Number(order.refundAmount || 0), 0);
          const platformFeeRate = Number(orders[0].merchant?.platformFeeRate ?? 0.08);
          const platformFeeAmount = Number((grossSales * platformFeeRate).toFixed(2));
          const paymentProcessingFee = Number((grossSales * 0.02).toFixed(2));
          const netPayout = Number(orders.reduce((sum, order) => {
            const grossAmount = Math.max(0, Number(order.totalAmount) - Number(order.shippingFee || 0));
            return sum + calculatePayoutAllocation(grossAmount, Number(order.refundAmount || 0), platformFeeRate).netAmount;
          }, 0).toFixed(2));
          const verifiedBankAccount = await tx.merchantBankAccount.findFirst({
            where: { merchantId, status: 'verified' },
            orderBy: { reviewedAt: 'desc' },
            select: { ibanLast4: true }
          });
          const payout = await tx.merchantPayout.create({
            data: {
              id: `pay-${period}-${merchantId}-${crypto.randomUUID().slice(0, 8)}`,
              merchantId,
              merchantName: orders[0].merchant!.name,
              period,
              grossSales,
              platformFeeRate,
              platformFeeAmount,
              paymentProcessingFee,
              refunds,
              netPayout,
              status: 'pending',
              bankAccount: verifiedBankAccount ? maskIban(verifiedBankAccount.ibanLast4) : 'PENDING_BANK_ACCOUNT_VERIFICATION',
              orderIds: JSON.stringify(orders.map(order => order.id)),
              allocations: {
                create: orders.map(order => {
                  const grossAmount = Math.max(0, Number(order.totalAmount) - Number(order.shippingFee || 0));
                  const refundAmount = Number(order.refundAmount || 0);
                  const allocation = calculatePayoutAllocation(grossAmount, refundAmount, platformFeeRate);
                  return { orderId: order.id, grossAmount, refundAmount, netAmount: allocation.netAmount };
                })
              }
            }
          });
          drafts.push(payout);
        }
        return drafts;
      }, { isolationLevel: Prisma.TransactionIsolationLevel.Serializable });
      logAudit(req.admin?.username || 'Platform SuperAdmin', 'admin', 'PAYOUT_DRAFTS_GENERATED', 'MerchantPayout', period, '', `${payouts.length} merchant drafts`);
      res.status(201).json({ success: true, period, count: payouts.length, payouts });
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === 'P2002') {
        return res.status(409).json({ success: false, error: 'PAYOUT_ORDERS_ALREADY_ALLOCATED' });
      }
      sendInternalError(res, error, 'admin-payout-generate');
    }
  });

